import { DataType } from '../data/Declaration';
import { AssignmentPredicate } from './AssignmentPredicate';
import { BasePLCPredicate } from './BasePLCPredicate';
import { SendMessagePredicate } from './SendMessagePredicate';
import { ToggleMemoryBitPredicate } from './ToggleMemoryBitPredicate';
import { ToggleStagePredicate } from './ToggleStagePredicate';

/**
 * Enum for all available predicate types
 */
export enum PredicateType {
    Assignment = 'Assignment',
    ToggleStage = 'ToggleStage',
    ToggleMemoryBit = 'ToggleMemoryBit',
    SendMessage = 'SendMessage',
    Contact = 'Contact',
    ContactNC = 'ContactNC',
    Coil = 'Coil',
    CoilSet = 'CoilSet',
    CoilReset = 'CoilReset',
    Timer = 'Timer',
    Counter = 'Counter',
    Compare = 'Compare',
    Math = 'Math',
    FunctionCall = 'FunctionCall',
    // Add more verb types here as they are created
}

/**
 * Metadata for a predicate type (for UI display)
 */
export interface PredicateTypeInfo {
    type: PredicateType;
    displayName: string;
    description: string;
    category?: string;
    requiresType?: DataType;  // Optional: Required declaration type for this predicate
}

/**
 * Predicate utilities including factory and type listing
 */
export class PredicateUtilities {
    /**
     * Get all available predicate types with metadata
     */
    public static getPredicateTypes(): PredicateTypeInfo[] {
        return [
            {
                type: PredicateType.Assignment,
                displayName: 'Assignment',
                description: 'Assign a value to a variable using predicates',
                category: 'Data'
            },
            {
                type: PredicateType.SendMessage,
                displayName: 'Send Message',
                description: 'Display a message to the user (info, error, or fault)',
                category: 'User Interface'
            },
            {
                type: PredicateType.ToggleStage,
                displayName: 'Toggle Stage',
                description: 'Control stage activation (turn on, turn off, or jump to)',
                category: 'Control'
            },
            {
                type: PredicateType.ToggleMemoryBit,
                displayName: 'Toggle Memory Bit',
                description: 'Toggle a memory bit between true and false',
                category: 'Data',
                requiresType: DataType.MemoryBit
            },
            // Add more predicate type info here as they are implemented
        ];
    }

    /**
     * Get predicate type info by type enum
     */
    public static getPredicateTypeInfo(type: PredicateType): PredicateTypeInfo | undefined {
        return this.getPredicateTypes().find(t => t.type === type);
    }

    /**
     * Factory method to create a predicate by type
     */
    public static createPredicate(type: PredicateType): BasePLCPredicate {
        switch (type) {
            case PredicateType.Assignment:
                return new AssignmentPredicate();

            case PredicateType.ToggleStage:
                return new ToggleStagePredicate();

            case PredicateType.ToggleMemoryBit:
                return new ToggleMemoryBitPredicate();

            case PredicateType.SendMessage:
                return new SendMessagePredicate();

            // TODO: Create other concrete predicate classes
            default:
                throw new Error(`Predicate creation not yet implemented for type: ${type}`);
        }
    }    /**
     * Factory method to create a predicate from JSON data
     * Uses the 'type' discriminator in the JSON to determine which class to instantiate
     */
    public static createPredicateFromJSON(data: any): BasePLCPredicate {
        if (!data || !data.type) {
            throw new Error('Invalid predicate JSON: missing type field');
        }

        let predicate: BasePLCPredicate;

        switch (data.type) {
            case 'AssignmentPredicate':
                predicate = new AssignmentPredicate();
                break;

            case 'ToggleStagePredicate':
                predicate = new ToggleStagePredicate();
                break;

            case 'ToggleMemoryBitPredicate':
                predicate = new ToggleMemoryBitPredicate();
                break;

            case 'SendMessagePredicate':
                predicate = new SendMessagePredicate();
                break;

            // TODO: Add other concrete predicate types
            default:
                throw new Error(`Unknown predicate type in JSON: ${data.type}`);
        }

        predicate.fromJSON(data);
        return predicate;
    }    /**
     * Get predicate types grouped by category
     */
    public static getPredicateTypesByCategory(): Map<string, PredicateTypeInfo[]> {
        const types = this.getPredicateTypes();
        const grouped = new Map<string, PredicateTypeInfo[]>();

        types.forEach(typeInfo => {
            const category = typeInfo.category || 'Other';
            if (!grouped.has(category)) {
                grouped.set(category, []);
            }
            grouped.get(category)!.push(typeInfo);
        });

        return grouped;
    }

    /**
     * Get display name for a predicate type
     */
    public static getDisplayName(type: PredicateType): string {
        const info = this.getPredicateTypeInfo(type);
        return info?.displayName || type.toString();
    }

    /**
     * Get description for a predicate type
     */
    public static getDescription(type: PredicateType): string {
        const info = this.getPredicateTypeInfo(type);
        return info?.description || '';
    }

    /**
     * Get predicate types that are compatible with a specific data type
     */
    public static getPredicateTypesForDataType(dataType: DataType): PredicateTypeInfo[] {
        return this.getPredicateTypes().filter(v =>
            !v.requiresType || v.requiresType === dataType
        );
    }
}
