import { PLCProgramType } from '../data/PLCUtilities';
import { AssignmentStatement } from './AssignmentStatement';
import { BasePLCStatement } from './BasePLCStatement';
import { InputMappingStatement } from './InputMappingStatement';
import { IOStateChangesStatement } from './IOStateChangesStatement';
import { IsChangedStatement } from './IsChangedStatement';
import { LogicStatement } from './LogicStatement';
import { ScriptStatement } from './ScriptStatement';
import { SendMessageStatement } from './SendMessageStatement';
import { StandardM9495HandlingStatement } from './StandardM9495HandlingStatement';
import { SystemUIEventsStatement } from './SystemUIEventsStatement';
import { TimerStatement } from './TimerStatement';
import { ToggleStageStatement } from './ToggleStageStatement';

/**
 * Enum for all available statement types
 */
export enum StatementType {
    Assignment = 'Assignment',
    ToggleStage = 'ToggleStage',
    SendMessage = 'SendMessage',
    Logic = 'Logic',
    Timer = 'Timer',
    IsChanged = 'IsChanged',
    Script = 'Script',
    // System-only statement types (only available in SystemDefault PLC)
    SystemKeybindings = 'SystemKeybindings',
    InputMapping = 'InputMapping',
    IOStateChanges = 'IOStateChanges',
    StandardM9495Handling = 'StandardM9495Handling',
    // Add more statement types here as they are created
    // Output = 'Output',
    // Input = 'Input',
    // Movement = 'Movement',
    // Delay = 'Delay',
    // Conditional = 'Conditional',
}

/**
 * Metadata for a statement type (for UI display)
 */
export interface StatementTypeInfo {
    type: StatementType;
    displayName: string;
    description: string;
    category?: string;
    systemOnly?: boolean;  // True if only available in SystemDefault PLC
}

/**
 * Statement utilities including factory and type listing
 */
export class StatementUtilities {
    /**
     * Get all available statement types with metadata
     * @param programType Optional program type to filter statements (System-only statements excluded for non-SystemDefault)
     */
    public static getStatementTypes(programType?: PLCProgramType): StatementTypeInfo[] {
        const allTypes: StatementTypeInfo[] = [
            // Common statement types
            {
                type: StatementType.Logic,
                displayName: 'Logic (Data + Verb)',
                description: 'Traditional ladder logic with data element and verb',
                category: 'Logic'
            },
            {
                type: StatementType.Timer,
                displayName: 'Timer',
                description: 'Timer-based logic with rising edge or falling edge detection',
                category: 'Logic'
            },
            {
                type: StatementType.IsChanged,
                displayName: 'Is Changed',
                description: 'Trigger actions when a value changes',
                category: 'Logic'
            },
            {
                type: StatementType.Assignment,
                displayName: 'Assignment',
                description: 'Assign a value to a variable or output',
                category: 'Data'
            },
            {
                type: StatementType.SendMessage,
                displayName: 'Send Message',
                description: 'Display a message to the user (info, error, or fault)',
                category: 'User Interface'
            },
            // Additional statement types
            {
                type: StatementType.ToggleStage,
                displayName: 'Toggle Stage',
                description: 'Control stage activation (turn on, turn off, or jump to)',
                category: 'Control'
            },
            {
                type: StatementType.Script,
                displayName: 'Script',
                description: 'Custom logic for one-off cases with inline data elements',
                category: 'Advanced'
            },
            // System-only statement types (no UI, only for code generation)
            {
                type: StatementType.SystemKeybindings,
                displayName: 'System UI Events',
                description: 'UI event and keybinding handling code (system only)',
                category: 'System',
                systemOnly: true
            },
            {
                type: StatementType.InputMapping,
                displayName: 'Input Mapping',
                description: 'Maps raw hardware inputs to processed memory bits with inversion (system only)',
                category: 'System',
                systemOnly: true
            },
            {
                type: StatementType.IOStateChanges,
                displayName: 'IO State Changes',
                description: 'Standard IO state change handling code (system only)',
                category: 'System',
                systemOnly: true
            },
            {
                type: StatementType.StandardM9495Handling,
                displayName: 'Standard M94/M95 Handling',
                description: 'Standard M94/M95 trigger handling code (system only)',
                category: 'System',
                systemOnly: true
            },
            // Add more statement type info here as they are created
        ];

        // Filter out system-only statements if not in SystemDefault program
        if (programType !== undefined && programType !== PLCProgramType.SystemDefault) {
            return allTypes.filter(t => !t.systemOnly);
        }

        return allTypes;
    }

    /**
     * Get statement type info by type enum
     */
    public static getStatementTypeInfo(type: StatementType): StatementTypeInfo | undefined {
        return this.getStatementTypes().find(t => t.type === type);
    }

    /**
     * Factory method to create a statement by type
     */
    public static createStatement(type: StatementType): BasePLCStatement {
        switch (type) {
            case StatementType.Assignment:
                return new AssignmentStatement();

            case StatementType.ToggleStage:
                return new ToggleStageStatement();

            case StatementType.SendMessage:
                return new SendMessageStatement();

            case StatementType.Logic:
                return new LogicStatement();

            case StatementType.Timer:
                return new TimerStatement();

            case StatementType.IsChanged:
                return new IsChangedStatement();

            case StatementType.Script:
                return new ScriptStatement();

            case StatementType.SystemKeybindings:
                return new SystemUIEventsStatement();

            case StatementType.InputMapping:
                return new InputMappingStatement();

            case StatementType.IOStateChanges:
                return new IOStateChangesStatement();

            case StatementType.StandardM9495Handling:
                return new StandardM9495HandlingStatement();

            // Add more statement types here as they are created
            default:
                throw new Error(`Unknown statement type: ${type}`);
        }
    }

    /**
     * Factory method to create a statement from JSON data
     * Uses the 'type' discriminator in the JSON to determine which class to instantiate
     */
    public static createStatementFromJSON(data: any): BasePLCStatement {
        if (!data || !data.type) {
            throw new Error('Invalid statement JSON: missing type field');
        }

        let statement: BasePLCStatement;

        switch (data.type) {
            case 'AssignmentStatement':
                statement = new AssignmentStatement();
                break;

            case 'ToggleStageStatement':
                statement = new ToggleStageStatement();
                break;

            case 'SendMessageStatement':
                statement = new SendMessageStatement();
                break;

            case 'LogicStatement':
                statement = new LogicStatement();
                break;

            case 'TimerStatement':
                statement = new TimerStatement();
                break;

            case 'IsChangedStatement':
                statement = new IsChangedStatement();
                break;

            case 'ScriptStatement':
                statement = new ScriptStatement();
                break;

            case 'SystemUIEventsStatement':
            case 'SystemKeybindingsStatement': // Legacy support
                statement = new SystemUIEventsStatement();
                break;

            case 'InputMappingStatement':
                statement = new InputMappingStatement();
                break;

            case 'IOStateChangesStatement':
                statement = new IOStateChangesStatement();
                break;

            case 'StandardM9495HandlingStatement':
                statement = new StandardM9495HandlingStatement();
                break;

            // Add more statement types here as they are created
            default:
                throw new Error(`Unknown statement type in JSON: ${data.type}`);
        }

        // Call fromJSON to deserialize the statement data
        // This is safe because the parent chain will be resolved lazily via getters
        statement.fromJSON(data);
        return statement;
    }

    /**
     * Get statement types grouped by category
     */
    public static getStatementTypesByCategory(): Map<string, StatementTypeInfo[]> {
        const types = this.getStatementTypes();
        const grouped = new Map<string, StatementTypeInfo[]>();

        types.forEach(typeInfo => {
            const category = typeInfo.category || 'Other';
            if (!grouped.has(category)) {
                grouped.set(category, []);
            }
            grouped.get(category)!.push(typeInfo);
        });

        return grouped;
    }

    /**
     * Get display name for a statement type
     */
    public static getDisplayName(type: StatementType): string {
        const info = this.getStatementTypeInfo(type);
        return info?.displayName || type.toString();
    }

    /**
     * Get description for a statement type
     */
    public static getDescription(type: StatementType): string {
        const info = this.getStatementTypeInfo(type);
        return info?.description || '';
    }
}
