import { Box, Button, ButtonGroup, TextField } from '@mui/material';
import React from 'react';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { DataElement } from '../data/DataElement';
import { Declaration } from '../data/Declaration';
import { PLCRenderMode, PLCValidationIssue } from '../data/IPLCElement';
import { PLCProgramType, PLCSerializationHelper, PLCUtilities } from '../data/PLCUtilities';
import { BasePLCPredicate } from './BasePLCPredicate';

/**
 * Message level for SendMessage predicate
 */
export enum MessageLevel {
    Fault = 'fault',
    Error = 'error',
    Info = 'info'
}

/**
 * Message mode for SendMessage predicate
 */
export enum MessageMode {
    Sync = 'sync',
    Async = 'async'
}

/**
 * SendMessage predicate - displays a message to the user
 */
export class SendMessagePredicate extends BasePLCPredicate {
    private _level: MessageLevel = MessageLevel.Info;
    private _mode: MessageMode = MessageMode.Async;
    private _messageText: string = '';

    /**
     * Get the message level
     */
    public get level(): MessageLevel {
        return this._level;
    }

    /**
     * Set the message level
     */
    public set level(value: MessageLevel) {
        this._level = value;
        StateManager.propertyChanged(this, 'level');
    }

    /**
     * Get the message mode (sync/async)
     */
    public get mode(): MessageMode {
        return this._mode;
    }

    /**
     * Set the message mode (sync/async)
     */
    public set mode(value: MessageMode) {
        this._mode = value;
        StateManager.propertyChanged(this, 'mode');
    }

    /**
     * Get the message text
     */
    public get messageText(): string {
        return this._messageText;
    }

    /**
     * Set the message text
     */
    public set messageText(value: string) {
        this._messageText = value;
        StateManager.propertyChanged(this, 'messageText');
    }

    /**
     * Get a short, single-line description for display in tree views
     * Example: "Send message 'Ready'"
     * @returns A human-readable summary of the message action
     */
    public getShortDescription(): string {
        const msg = this._messageText || '(no message)';
        const truncated = msg.length > 30 ? msg.substring(0, 30) + '...' : msg;
        return `Send message "${truncated}"`;
    }

    /**
     * Get all data elements used by this predicate
     */
    /**
     * Get the inline comment for this predicate based on the message
     */
    public getComment(): string {
        // If there's a manual comment, use that
        const manualComment = super.getComment();
        if (manualComment) {
            return manualComment;
        }

        // Otherwise, use the message text itself as the comment
        if (this._messageText) {
            return `Display message: "${this._messageText}"`;
        }

        return '';
    }

    public getDataElements(): DataElement[] {
        return [];
    }

    /**
     * Render the predicate to JSX
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        return <SendMessagePredicateRenderer predicate={this} renderMode={mode} />;
    }

    /**
     * Get declarations that are used/referenced by this predicate
     */
    public getUsedDeclarations(): Declaration[] {
        // Return all message word variables for this level (base + stack)
        const declarations: Declaration[] = [];
        let baseDeclarationName: string;

        switch (this._level) {
            case MessageLevel.Fault:
                baseDeclarationName = 'MSG_FAULT';
                break;
            case MessageLevel.Error:
                baseDeclarationName = 'MSG_ERROR';
                break;
            case MessageLevel.Info:
            default:
                baseDeclarationName = 'MSG_INFO';
                break;
        }

        // Add base message variable
        const baseDecl = PLCUtilities.lookupDeclarationSafe(`${baseDeclarationName}_W`);
        if (baseDecl) {
            declarations.push(baseDecl);
        }

        // Add stack message variables (1-4)
        for (let i = 1; i <= 4; i++) {
            const stackDecl = PLCUtilities.lookupDeclarationSafe(`${baseDeclarationName}_${i}_W`);
            if (stackDecl) {
                declarations.push(stackDecl);
            }
        }

        // Add global message control variables
        const toQueueDecl = PLCUtilities.lookupDeclarationSafe('MSG_TO_QUEUE_W');
        if (toQueueDecl) {
            declarations.push(toQueueDecl);
        }

        const queuedDecl = PLCUtilities.lookupDeclarationSafe('MSG_QUEUED_M');
        if (queuedDecl) {
            declarations.push(queuedDecl);
        }

        return declarations;
    }

    /**
     * Get declarations that are added/defined by this predicate
     */
    public getAddedDeclarations(): Declaration[] {
        // No per-predicate variables - use global MSG_TO_QUEUE_W and MSG_QUEUED_M
        return [];
    }

    /**
     * Get the PLC logic code for this predicate
     */
    public getPLCLogic(): string[] {
        if (!this._messageText || this._messageText.trim() === '') {
            return ['; Send Message: No message text'];
        }

        // Use PLCUtilities to register message (avoids circular dependency with PLCProgram)
        const messageNumber = PLCUtilities.registerMessage(this._messageText);

        // Calculate word value using formula: (messageNumber * 256) + modeOffset
        // Mode offset: 1 for SYNC, 2 for ASYNC
        // Examples:
        //   Message 1, SYNC:  (1 * 256) + 1 = 257
        //   Message 1, ASYNC: (1 * 256) + 2 = 258
        //   Message 2, ASYNC: (2 * 256) + 2 = 514
        const isSync = this._mode === MessageMode.Sync;
        const modeOffset = isSync ? 1 : 2;
        const wordValue = (messageNumber * 256) + modeOffset;

        // Determine which word variable to use based on level
        let wordVariable: string;
        switch (this._level) {
            case MessageLevel.Fault:
                wordVariable = 'MSG_FAULT_W';
                break;
            case MessageLevel.Error:
                wordVariable = 'MSG_ERROR_W';
                break;
            case MessageLevel.Info:
            default:
                wordVariable = 'MSG_INFO_W';
                break;
        }

        // Set the message value and flag that a message is ready to queue
        // The actual queue assignment happens in getSecondaryPLCLogic()
        return [`${wordVariable} = ${wordValue}`];
    }

    /**
     * Get pre-PLC logic (reset the global control variables)
     */
    public getPrePLCLogic(): string[] {
        // Reset the global message control variables at the start of each scan
        return [
            '; Send Message predicate - reset global control variables',
            'IF 1==1 THEN MSG_TO_QUEUE_W = 0',
            'IF 1==1 THEN RST MSG_QUEUED_M',
            ''
        ];
    }

    /**
     * Get secondary PLC logic (assign message to first empty slot in queue)
     */
    public getSecondaryPLCLogic(): string[] {
        if (!this._messageText || this._messageText.trim() === '') {
            return [];
        }

        // Determine base variable name and get message word variable based on level
        let baseVariable: string;
        let msgWordVariable: string;
        switch (this._level) {
            case MessageLevel.Fault:
                baseVariable = 'MSG_FAULT';
                msgWordVariable = 'MSG_FAULT_W';
                break;
            case MessageLevel.Error:
                baseVariable = 'MSG_ERROR';
                msgWordVariable = 'MSG_ERROR_W';
                break;
            case MessageLevel.Info:
            default:
                baseVariable = 'MSG_INFO';
                msgWordVariable = 'MSG_INFO_W';
                break;
        }

        const code: string[] = [];
        code.push('');
        code.push('; Send Message predicate - assign to first empty slot');

        // Check base message variable first - if it's zero (empty), assign the queued message to it
        code.push(`IF MSG_TO_QUEUE_W != 0 && ${baseVariable}_W == 0 THEN ${baseVariable}_W = ${msgWordVariable}, SET MSG_QUEUED_M`);

        // Get configured message queue depth from ConfigurationData (default 3, range 1-5)
        const queueDepth = ConfigurationData.Instance.messageQueueDepth;

        // Check stack slots 1-4, but only up to (queueDepth - 1) slots
        // Depth 1 = base only (no stack), Depth 2 = base + 1 stack, etc.
        const stackSlotsToGenerate = Math.max(0, queueDepth - 1);
        for (let i = 1; i <= Math.min(stackSlotsToGenerate, 4); i++) {
            code.push(`IF MSG_TO_QUEUE_W != 0 && !MSG_QUEUED_M && ${baseVariable}_${i}_W == 0 THEN ${baseVariable}_${i}_W = ${msgWordVariable}, SET MSG_QUEUED_M`);
        }

        code.push('');
        code.push('; Reset global control variables after processing');
        code.push('IF MSG_TO_QUEUE_W != 0 THEN MSG_TO_QUEUE_W = 0');
        code.push('IF MSG_QUEUED_M THEN RST MSG_QUEUED_M');

        return code;
    }

    /**
     * Get validation issues for this predicate
     */
    public getValidationIssues(): PLCValidationIssue[] {
        const issues: PLCValidationIssue[] = [];

        if (!this._messageText || this._messageText.trim() === '') {
            issues.push(new PLCValidationIssue(this, 'Message text is required'));
        }

        // Check if there are multiple SendMessage predicates in the same predicate group
        // Since we use global MSG_TO_QUEUE_W and MSG_QUEUED_M, only one SendMessage can execute per scan
        const parent = this.getParentElement();
        if (parent && 'predicates' in parent) {
            // Count SendMessage predicates in this predicate group
            const predicates = (parent as any).predicates || [];
            const sendMessageCount = predicates.filter((p: any) => p instanceof SendMessagePredicate).length;

            if (sendMessageCount > 1) {
                issues.push(new PLCValidationIssue(
                    this,
                    'Only one Send Message predicate allowed per statement (uses shared global variables MSG_TO_QUEUE_W and MSG_QUEUED_M)',
                ));
            }
        }

        return issues;
    }

    /**
     * Validate the predicate
     */
    public validate(): string | undefined {
        if (!this._messageText || this._messageText.trim() === '') {
            return 'Message text is required';
        }
        return undefined;
    }

    /**
     * Clone the predicate
     */
    public clone(): SendMessagePredicate {
        const cloned = new SendMessagePredicate();
        cloned.level = this._level;
        cloned.mode = this._mode;
        cloned.messageText = this._messageText;
        return cloned;
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        return {
            type: 'SendMessagePredicate',
            ...PLCSerializationHelper.getStorageData(this)
        };
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        if (!data) return;
        DataUtilities.loadStorageData(this, data);
    }
}

/**
 * Functional component for rendering SendMessagePredicate
 */
function SendMessagePredicateRenderer({ predicate, renderMode }: { predicate: SendMessagePredicate; renderMode?: PLCRenderMode }) {
    const isDisabled = renderMode === PLCRenderMode.Disabled;
    const isReadOnly = renderMode === PLCRenderMode.ReadOnly || isDisabled;
    const colors = ConfigurationDataColors.Instance;
    const effectiveRenderMode = renderMode || PLCRenderMode.Edit;

    // Check if this predicate should be disabled:
    // 1. If renderMode is Disabled (parent condition is disabled), OR
    // 2. If predicate itself is disabled due to unavailable declarations
    const targetProgramType = predicate.plcSource?.getProgramType() || PLCProgramType.System;
    const isPredicateDisabled = effectiveRenderMode === PLCRenderMode.Disabled || predicate.isDisabled(PLCRenderMode.Edit, targetProgramType);
    const disabledStyle = isPredicateDisabled ? {
        opacity: 0.5,
        textDecoration: 'line-through',
        color: colors.mutedTextColor
    } : {};

    return (
        <ObserveState
            key="send-message-predicate-render"
            profilerName="SendMessagePredicate-render"
            listenTo={predicate}
            properties={['level', 'mode', 'messageText']}

            control={() => {
                // Calculate text field width based on content
                const textLength = predicate.messageText.length;
                const calculatedWidth = Math.max(300, Math.min(800, textLength * 8 + 100));

                return (
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, flex: 1, ...disabledStyle }}>
                        {/* Message Mode */}
                        <span>Display:</span>
                        <ButtonGroup size="small" disabled={isReadOnly}>
                            <Button
                                variant={predicate.mode === MessageMode.Sync ? 'contained' : 'outlined'}
                                onClick={() => !isReadOnly && (predicate.mode = MessageMode.Sync)}
                                sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '12px',
                                    minWidth: 'auto',
                                    px: 1.5,
                                    py: 0.5,
                                    textTransform: 'uppercase',
                                    backgroundColor: predicate.mode === MessageMode.Sync ? colors.mutedTextColor : undefined,
                                    color: predicate.mode === MessageMode.Sync ? colors.lightTextColor : undefined,
                                    border: predicate.mode === MessageMode.Sync ? 'none' : `1px solid ${colors.mutedTextColor}`,
                                    '&:hover': {
                                        opacity: 0.9,
                                    }
                                }}
                            >
                                SYNC
                            </Button>
                            <Button
                                variant={predicate.mode === MessageMode.Async ? 'contained' : 'outlined'}
                                onClick={() => !isReadOnly && (predicate.mode = MessageMode.Async)}
                                sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '12px',
                                    minWidth: 'auto',
                                    px: 1.5,
                                    py: 0.5,
                                    textTransform: 'uppercase',
                                    backgroundColor: predicate.mode === MessageMode.Async ? colors.mutedTextColor : undefined,
                                    color: predicate.mode === MessageMode.Async ? colors.lightTextColor : undefined,
                                    border: predicate.mode === MessageMode.Async ? 'none' : `1px solid ${colors.mutedTextColor}`,
                                    '&:hover': {
                                        opacity: 0.9,
                                    }
                                }}
                            >
                                ASYNC
                            </Button>
                        </ButtonGroup>

                        {/* Message Level */}
                        <ButtonGroup
                            size="small"
                            disabled={isReadOnly}
                        >
                            <Button
                                variant={predicate.level === MessageLevel.Info ? 'contained' : 'outlined'}
                                onClick={() => !isReadOnly && (predicate.level = MessageLevel.Info)}
                                sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '12px',
                                    minWidth: 'auto',
                                    px: 1.5,
                                    py: 0.5,
                                    textTransform: 'uppercase',
                                    backgroundColor: predicate.level === MessageLevel.Info ? colors.successColor : undefined,
                                    color: predicate.level === MessageLevel.Info ? colors.lightTextColor : undefined,
                                    border: predicate.level === MessageLevel.Info ? 'none' : `1px solid ${colors.mutedTextColor}`,
                                    '&:hover': {
                                        opacity: 0.9,
                                    }
                                }}
                            >
                                INFO
                            </Button>
                            <Button
                                variant={predicate.level === MessageLevel.Error ? 'contained' : 'outlined'}
                                onClick={() => !isReadOnly && (predicate.level = MessageLevel.Error)}
                                sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '12px',
                                    minWidth: 'auto',
                                    px: 1.5,
                                    py: 0.5,
                                    textTransform: 'uppercase',
                                    backgroundColor: predicate.level === MessageLevel.Error ? colors.warningColor : undefined,
                                    color: predicate.level === MessageLevel.Error ? colors.lightTextColor : undefined,
                                    border: predicate.level === MessageLevel.Error ? 'none' : `1px solid ${colors.mutedTextColor}`,
                                    '&:hover': {
                                        opacity: 0.9,
                                    }
                                }}
                            >
                                ERROR
                            </Button>
                            <Button
                                variant={predicate.level === MessageLevel.Fault ? 'contained' : 'outlined'}
                                onClick={() => !isReadOnly && (predicate.level = MessageLevel.Fault)}
                                sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '12px',
                                    minWidth: 'auto',
                                    px: 1.5,
                                    py: 0.5,
                                    textTransform: 'uppercase',
                                    backgroundColor: predicate.level === MessageLevel.Fault ? colors.errorColor : undefined,
                                    color: predicate.level === MessageLevel.Fault ? colors.lightTextColor : undefined,
                                    border: predicate.level === MessageLevel.Fault ? 'none' : `1px solid ${colors.mutedTextColor}`,
                                    '&:hover': {
                                        opacity: 0.9,
                                    }
                                }}
                            >
                                FAULT
                            </Button>
                        </ButtonGroup>

                        {/* Message Label and Text Field */}
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <span>Message:</span>
                            <TextField
                                value={predicate.messageText}
                                onChange={(e) => !isReadOnly && (predicate.messageText = e.target.value)}
                                placeholder="Enter message text..."
                                variant="filled"
                                size="small"
                                disabled={isReadOnly}
                                sx={{
                                    width: `${calculatedWidth}px`,
                                    transition: 'width 0.2s ease',
                                    '& .MuiFilledInput-root': {
                                        paddingTop: '2px',
                                        paddingBottom: '2px'
                                    },
                                    '& .MuiFilledInput-input': {
                                        paddingTop: '4px',
                                        paddingBottom: '4px'
                                    }
                                }}
                            />
                        </Box>
                    </Box>
                );
            }}
        />
    );
}
