import { SingletonRegistry } from '../../utils/SingletonRegistry';
import { StateManager } from '../../utils/statemanager/StateManager';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { DataFileConstants } from '../DataFileConstants';
import { Material } from './Material';
import { SaveableDataBase } from './SaveableDataBase';

/**
 * Material type enum
 * Direct conversion from C# MaterialType enum
 */
export enum MaterialType {
  Wood = 'Wood',
  Metal = 'Metal',
  Plastic = 'Plastic',
  Composite = 'Composite',
  Other = 'Other'
}

/**
 * Grain direction enum
 * Direct conversion from C# GrainDirection enum
 */
export enum GrainDirection {
  X = 'X',
  Y = 'Y'
}

/**
 * Material library class
 * Direct conversion from C# MaterialLibrary class
 * Implemented as singleton pattern
 */
export class MaterialLibrary extends SaveableDataBase {
  /**
   * Filename for saving/loading material library data
   */
  protected get filename(): string {
    return DataFileConstants.MATERIALS;
  }
  public materials: Material[];

  private constructor() {
    super();

    // Register this singleton - will throw if a duplicate is created
    SingletonRegistry.MaterialLibrary = this;

    this.materials = [];

    // Note: setupAutoSave() will be called after instance creation to avoid constructor issues
  }

  /**
   * Serialize to JSON - handle materials array explicitly
   */
  public toJSON(): any {
    const baseData = DataUtilities.getStorageData(this, ['materials']); // Exclude materials from auto-processing

    // Handle materials array explicitly with proper serialization
    return {
      ...baseData,
      materials: this.materials.map(material => material.toJSON())
    };
  }

  /**
   * Load from JSON - handle materials array explicitly using fromJSON
   */
  public fromJSON(data: any): void {
    // Load basic properties
    DataUtilities.loadStorageData(this, data, ['materials']); // Exclude materials from auto-processing

    // Handle materials array explicitly
    if (data.materials && Array.isArray(data.materials)) {
      this.materials = data.materials.map((materialData: any) => {
        const material = new Material();
        material.fromJSON(materialData);
        return material;
      });
    }
  }

  /**
   * Add a material to the library
   */
  public addMaterial(material: Material): void {
    this.materials.push(material);
    StateManager.propertyChanged(this, 'materials');
  }

  /**
   * Remove a material from the library
   */
  public removeMaterial(materialName: string): void {
    const index = this.materials.findIndex(material => material.name === materialName);
    if (index !== -1) {
      this.materials.splice(index, 1);
      StateManager.propertyChanged(this, 'materials');
    }
  }

  /**
   * Update a material in the library
   */
  public updateMaterial(materialName: string, updatedMaterial: Material): void {
    const index = this.materials.findIndex(material => material.name === materialName);
    if (index !== -1) {
      this.materials[index] = updatedMaterial;
      StateManager.propertyChanged(this, 'materials');
    }
  }

  /**
   * Update the entire materials array from loaded data
   * This preserves existing material objects where possible by updating their properties
   * instead of replacing the entire array
   */
  public updateFromLoadedData(loadedMaterials: any[]): void {
    if (!Array.isArray(loadedMaterials)) return;

    // Clear existing materials
    this.materials.length = 0;

    // Add loaded materials
    for (const materialData of loadedMaterials) {
      const material = new Material();
      if (materialData.name !== undefined) material.name = materialData.name;
      if (materialData.type !== undefined) material.type = materialData.type;
      if (materialData.xLength !== undefined) material.xLength = materialData.xLength;
      if (materialData.yLength !== undefined) material.yLength = materialData.yLength;
      if (materialData.height !== undefined) material.height = materialData.height;
      if (materialData.grainDirection !== undefined) material.grainDirection = materialData.grainDirection;
      if (materialData.materialColor !== undefined) material.materialColor = materialData.materialColor;

      this.materials.push(material);
    }

    StateManager.propertyChanged(this, 'materials');
  }

  /**
   * Get the singleton instance
   */
  public static get Instance(): MaterialLibrary {
    if (!SingletonRegistry.MaterialLibrary) {
      const instance = new MaterialLibrary();
      // Setup auto-save after instance is fully created
      instance.setupAutoSave();
    }
    return SingletonRegistry.MaterialLibrary!;
  }
}

// Export MaterialColors for convenience
export { MaterialColors } from './MaterialColors';
export type { MaterialColorDefinition } from './MaterialColors';

