import React from 'react';
import { CNCPoint } from '../../data/CNCPoint';
import { CoordinateType } from '../../data/Common/CoordinateType';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineStateData } from '../../data/MachineStateData';
import { Machine, MovementCoordinateType } from '../../machine/Machine';
import { CollisionAction, CollisionDetection, CollisionResult } from '../CollisionDetection';
import { CollisionModalManager } from '../CollisionModalManager';
import { LogCategory, Logger } from '../Logger';
import { StateManager } from '../statemanager/StateManager';
import { ActionBus, IAction } from './ActionBus';
import { combineCoordinates, createTargetPosition, getMoveDelayTime, MoveType, resolveCoordinates } from './MoveActionUtils';
import { NotificationList } from '../NotificationList';

// Re-export MoveType for backwards compatibility
export { MoveType } from './MoveActionUtils';

export class MoveAction implements IAction {
    public type = 'Move';
    public id: string = `move-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`; // Unique ID
    public singleAction = true; // Only one move action allowed in queue at a time
    public x: number; // Always resolved in constructor
    public y: number; // Always resolved in constructor
    public z: number; // Always resolved in constructor
    public a?: number; // A-axis can remain optional
    public startingPoint: CNCPoint;
    public moveType: MoveType;
    public noDelay: boolean = false;
    public _timeoutId?: number; // Made public for combining logic
    public _startTime: number = Date.now(); // Made public for combining logic

    // Collision handling
    public bypassCollisionDetection: boolean = false;
    public isShowingCollisionWarning: boolean = false; // Track if this action is showing collision UI
    public isExecutingAfterCollision: boolean = false; // Track if we're executing after collision confirmation
    private isCheckingCollision: boolean = false; // Track if we're currently checking for collisions

    constructor(coordinateType: CoordinateType, x?: number, y?: number, z?: number, a?: number, moveType: MoveType = MoveType.Coordinates, bypassCollisionDetection: boolean = false, noDelay: boolean = false) {
        // Capture the starting point (current machine position) when the action is created
        this.startingPoint = ConfigurationState.Instance.currentMachinePoint;
        this.moveType = moveType;
        this.noDelay = noDelay;
        this.bypassCollisionDetection = bypassCollisionDetection;        // Get the base position for resolving undefined coordinates
        // Use proposed spindle position if it exists (for chained moves), otherwise current machine position
        const basePos = ConfigurationState.Instance.proposedSpindlePosition || ConfigurationState.Instance.currentMachinePoint;

        // Use extracted utility function to resolve coordinates
        const resolved = resolveCoordinates(coordinateType, x, y, z, a, basePos);
        this.x = resolved.x;
        this.y = resolved.y;
        this.z = resolved.z;
        this.a = resolved.a;
    } canCombine(other: IAction): boolean {
        if (!(other instanceof MoveAction)) {
            return false; // Cannot combine with non-MoveAction
        }
        return true; // Can combine with other MoveActions
    }

    combineWith(other: IAction): IAction {
        if (other instanceof MoveAction) {
            // Cancel this existing action's timeout to prevent it from executing
            if (this._timeoutId) {
                clearTimeout(this._timeoutId);
                this._timeoutId = undefined;
            }

            // Clear collision warning flag since we're combining with new action
            this.isShowingCollisionWarning = false;

            // Use extracted utility function to combine coordinates
            const combined = combineCoordinates(this, other);

            // Create the combined action with MachineZero coordinates
            const combinedAction = new MoveAction(
                CoordinateType.MachineZero,
                combined.x,
                combined.y,
                combined.z,
                combined.a,
                other.moveType, // Use the new action's move type
                this.bypassCollisionDetection || other.bypassCollisionDetection, // Bypass if either action bypasses
                other.noDelay // Use the new action's no delay setting
            );

            // Preserve the original starting point from this existing action
            combinedAction.startingPoint = this.startingPoint;

            // Reset the start time to now so the timer restarts at 2 seconds
            // This gives the user a fresh countdown when they click the jog button again
            const now = Date.now();
            combinedAction._startTime = now;

            // Update the spindle drag position to the new target immediately
            // This allows subsequent jog operations to build on the combined target
            const newTarget = createTargetPosition(combined.x, combined.y, combined.z);

            ConfigurationState.Instance.proposedSpindlePosition = newTarget;

            return combinedAction;
        }
        throw new Error('Cannot combine with non-MoveAction');
    }

    /**
     * Get the delay time for this move type
     */
    public getDelayTime(): number {
        return getMoveDelayTime(this.moveType, ConfigurationData.Instance);
    }

    /**
     * Cancel this move action
     */
    cancel(): void {
        // Clear collision warning flag
        this.isShowingCollisionWarning = false;

        // Clear timeout if it exists
        if (this._timeoutId) {
            clearTimeout(this._timeoutId);
            this._timeoutId = undefined;
        }

        // Clear the proposed spindle position since the action is being canceled
        ConfigurationState.Instance.proposedSpindlePosition = null;

        // Remove this action from the action bus
        ActionBus.Instance.completeAction(this);
    }

    /**
     * Execute the move action
     * Three possible paths:
     * 1. Bypass collision -> delay (optional) -> performActualMove
     * 2. Collision detected -> show dialog -> user confirms -> delay (optional) -> performActualMove
     * 3. No collision -> delay (optional) -> performActualMove
     */
    async execute(): Promise<void> {
        // Get the target position first
        const targetPosition = this.getTargetPosition();

        // Skip collision detection if bypassing is enabled via constructor flag
        if (this.bypassCollisionDetection) {
            await this.executeWithDelay(targetPosition);
            return;
        }

        // Set flag to prevent UI from showing while we check for collisions
        this.isCheckingCollision = true;
        StateManager.propertyChanged(ActionBus.Instance, 'actions');
        this.updateNotificationUI();

        // Check for collisions before executing the move
        const currentPosition = ConfigurationState.Instance.currentMachinePoint;
        const collisionInputs = await CollisionDetection.createInputsFromMachineState(MachineStateData.Instance);
        const collisionResult = CollisionDetection.checkMoveCollision(currentPosition, targetPosition, collisionInputs);

        // Clear the checking flag
        this.isCheckingCollision = false;
        StateManager.propertyChanged(ActionBus.Instance, 'actions');
        this.updateNotificationUI();

        if (collisionResult.hasCollision) {
            // Get collision options for the UI
            const options = CollisionDetection.getCollisionOptions(collisionResult);

            // Set the collision warning flag now that we know there's a collision
            this.isShowingCollisionWarning = true;

            // Trigger a property change to force UI update (hide countdown, show collision modal)
            StateManager.propertyChanged(ActionBus.Instance, 'actions');
            this.updateNotificationUI();

            // Show collision warning UI and DO NOT execute the move
            // The move will only execute when user responds with their choice
            await this.showCollisionWarning(collisionResult, options, targetPosition);
            return; // STOP HERE - don't execute until user responds
        }

        // No collision detected, proceed with normal execution
        await this.executeWithDelay(targetPosition);
    }

    /**
     * Execute the move with optional delay (handles the delay countdown UI)
     */
    private async executeWithDelay(targetPosition: CNCPoint): Promise<void> {
        const delayTime = this.getDelayTime();

        // Set the proposed spindle position to show intermediate position during move
        ConfigurationState.Instance.proposedSpindlePosition = targetPosition;

        // Check safe mode overrides for delay
        const configState = ConfigurationState.Instance;
        const shouldSkipDelay = this.noDelay || configState.delayOff;

        // Skip delay if noDelay is enabled or delay override is active
        if (delayTime > 0 && !shouldSkipDelay) {
            // Set up delayed execution - action should already be in ActionBus if needed
            this._timeoutId = window.setTimeout(async () => {
                await this.performActualMove(targetPosition);
                // Remove from action bus when complete
                ActionBus.Instance.completeAction(this);

                // Force cleanup any stale actions after a delay
                setTimeout(() => {
                    ActionBus.Instance.forceCleanup();
                }, 200);
            }, delayTime);
        } else {
            // Execute immediately if no delay or noDelay is enabled
            await this.performActualMove(targetPosition);
            // Remove from action bus when complete
            ActionBus.Instance.completeAction(this);

            // Force cleanup any stale actions after a delay
            setTimeout(() => {
                ActionBus.Instance.forceCleanup();
            }, 200);
        }
    }

    /**
     * Perform the actual move via IMachineInterface
     * This is the ONLY method that should call the machine interface MoveTo
     * IMachineInterface implementations clear proposedSpindlePosition after move completes
     */
    private async performActualMove(targetPosition: CNCPoint): Promise<void> {
        try {
            // Call the machine interface to perform the actual move
            // - Simulator: SimulatorCNCMovement.MoveTo() will update currentMachinePoint and clear proposedSpindlePosition
            // - Centroid: CentroidCNCMovement.MoveTo() will call the API and clear proposedSpindlePosition
            //   (currentMachinePoint updated via SignalR DRO events)
            const machine = Machine.getInstance();
            await machine.movement.MoveTo(targetPosition, MovementCoordinateType.WorkZero);

            // SAFETY: Clear proposed spindle position after move completes
            // (Machine interface implementations should do this, but ensure it's cleared)
            ConfigurationState.Instance.proposedSpindlePosition = null;

        } catch (error) {
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to execute move:', error);
            // Clear proposed position on error as well
            ConfigurationState.Instance.proposedSpindlePosition = null;
        }
    }

    /**
     * Show collision warning UI and handle user response
     */
    private async showCollisionWarning(collisionResult: CollisionResult, options: Array<{
        action: CollisionAction;
        label: string;
        description: string;
        point?: CNCPoint;
    }>, targetPosition: CNCPoint): Promise<void> {
        // Set flag to prevent renderUI from showing countdown
        this.isShowingCollisionWarning = true;
        StateManager.propertyChanged(ActionBus.Instance, 'actions');
        this.updateNotificationUI();

        // IMPORTANT: Cancel any pending execution timeout
        if (this._timeoutId) {
            clearTimeout(this._timeoutId);
            this._timeoutId = undefined;
        }

        // Create collision inputs for debug information
        const machineState = MachineStateData.Instance;
        const collisionInputs = await CollisionDetection.createInputsFromMachineState(machineState);

        // Show the collision warning modal using the modal manager
        CollisionModalManager.Instance.showCollisionWarning(
            collisionResult,
            options,
            (action: CollisionAction, safePosition?: CNCPoint) => {
                this.handleCollisionResponse(action, safePosition);
            },
            targetPosition,
            this.startingPoint,
            collisionInputs
        );
    }

    /**
     * Handle user's collision warning response
     * After user confirms, we proceed with the delay and move
     */
    public async handleCollisionResponse(action: CollisionAction, safePosition?: CNCPoint): Promise<void> {
        // Safety check - if not showing collision warning, ignore this call
        if (!this.isShowingCollisionWarning) {
            return;
        }

        // Get the target position for this action
        const targetPosition = this.getTargetPosition();

        switch (action) {
            case CollisionAction.Cancel:
                this.cancel();
                break;

            case CollisionAction.Proceed:
                // User chose to proceed despite collision - continue with this action but bypass collision
                this.bypassCollisionDetection = true;
                this.isShowingCollisionWarning = false;
                this.isExecutingAfterCollision = true;
                StateManager.propertyChanged(ActionBus.Instance, 'actions');
                this.updateNotificationUI();
                // Execute immediately - user has already confirmed, no need for additional delay
                await this.performActualMove(targetPosition);
                ActionBus.Instance.completeAction(this);
                break;

            case CollisionAction.MoveSafe:
                // Move to the safe position instead
                if (safePosition) {
                    this.isShowingCollisionWarning = false;
                    this.isExecutingAfterCollision = true;
                    StateManager.propertyChanged(ActionBus.Instance, 'actions');
                    this.updateNotificationUI();
                    // Execute immediately - user has already confirmed, no need for additional delay
                    await this.performActualMove(safePosition);
                    ActionBus.Instance.completeAction(this);
                } else {
                    this.cancel(); // Fallback if no safe position available
                }
                break;
        }
    }

    /**
     * Execute the move immediately without delay (used by Move Now button)
     */
    public async executeImmediate(targetPosition?: CNCPoint): Promise<void> {
        // Use provided target or calculate it
        const finalTarget = targetPosition || this.getTargetPosition();

        // Call the single method that performs the actual move
        await this.performActualMove(finalTarget);
    }

    /**
     * Get the notification UI for this action
     * Called by ActionBus to add the UI to NotificationList
     */
    public getNotificationUI(): React.ReactNode {
        // Import MoveActionUI dynamically to avoid circular dependency
        const { MoveActionUI } = require('../../components/Common/MoveActionUI');
        return <MoveActionUI action={this} />;
    }

    /**
     * Update the notification UI in NotificationList
     * Called whenever action state changes to refresh the UI
     */
    private updateNotificationUI(): void {
        const ui = this.getNotificationUI();
        NotificationList.Instance.add(this.id, ui, 0);
    }

    /**
     * Get the target position that this action will move to
     */
    getTargetPosition(): CNCPoint {
        // Use extracted utility function to create target position
        return createTargetPosition(this.x, this.y, this.z, this.a);
    }

    /**
     * Create a MoveAction from a CNCPoint
     */
    static fromCNCPoint(point: CNCPoint, moveType: MoveType = MoveType.Coordinates, bypassCollisionDetection: boolean = false, noDelay: boolean = false): MoveAction {
        return new MoveAction(
            point.coordinateType,
            point.x,
            point.y,
            point.z,
            undefined,
            moveType,
            bypassCollisionDetection,
            noDelay
        );
    }

    /**
     * Create a MoveAction that moves only specific axes
     */
    static moveAxis(coordinateType: CoordinateType, axes: { x?: number; y?: number; z?: number; a?: number }, moveType: MoveType = MoveType.Coordinates): MoveAction {
        return new MoveAction(
            coordinateType,
            axes.x,
            axes.y,
            axes.z,
            axes.a,
            moveType
        );
    }


}
