import { GpsFixed as WorkZeroIcon } from '@mui/icons-material';
import { Box, Typography } from '@mui/material';
import React from 'react';
import { SetWorkZeroDialog } from '../../components/Common/SetWorkZeroDialog';
import { ConfigurationState } from '../../data/ConfigurationState';
import { ModalManager } from '../ModalManager';
import { IUserAction } from './IUserAction';

export class GoToWorkZeroUserAction implements IUserAction {
    public readonly id = 'go_to_work_zero';
    public readonly category = 'Machine Actions';
    public readonly isDefaultHomeAction = false;

    public isAvailable(): boolean {
        // GoTo Work Zero is available when machine is homed
        return ConfigurationState.Instance.isHomed;
    }

    public renderButton(asLink: boolean): React.ReactNode {
        if (asLink) {
            return (
                <React.Fragment>
                    <WorkZeroIcon sx={{ fontSize: 18, color: 'primary.main' }} />
                    <Typography variant="body2" sx={{ color: 'inherit', fontWeight: 500 }}>
                        GoTo Work Zero
                    </Typography>
                </React.Fragment>
            );
        } else {
            return (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <WorkZeroIcon />
                    <Typography>GoTo Work Zero</Typography>
                </Box>
            );
        }
    }

    public async run(): Promise<void> {
        const modalId = 'set-work-zero-dialog';

        // Show the SetWorkZeroDialog using ModalManager
        ModalManager.Instance.showModal({
            id: modalId,
            render: () => (
                <SetWorkZeroDialog
                    onClose={() => ModalManager.Instance.closeModal(modalId)}
                />
            )
        });
    }
}
