import { Box, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { DataElement } from '../data/DataElement';
import { Declaration } from '../data/Declaration';
import { PLCRenderMode } from '../data/IPLCElement';
import { PLCProgram } from '../data/PLCProgram';
import { PLCProgramType } from '../data/PLCUtilities';
import { BasePLCStatement } from './BasePLCStatement';

/**
 * Input Mapping Statement
 * System-only statement with no UI that outputs input mapping code
 * Maps raw hardware inputs to processed memory bits with optional inversion
 * Only available in SystemDefault PLC programs
 */
export class InputMappingStatement extends BasePLCStatement {
    /**
     * Get a short, single-line description for display in tree views
     * @returns A human-readable summary
     */
    public getShortDescription(): string {
        return 'Map hardware inputs';
    }

    /**
     * Validate the statement
     */
    public validate(): string | undefined {
        return undefined; // Always valid
    }

    /**
     * Render the statement (informational display only, no editable properties)
     */
    public render(mode?: PLCRenderMode): any {
        const config = ConfigurationData.Instance;
        const colors = ConfigurationDataColors.Instance;

        return React.createElement(Box, {
            sx: {
                padding: 2,
                backgroundColor: ConfigurationDataColors.Instance.selectionColor, // Light blue background for system-only statements
                border: `1px solid ${colors.borderColor}`,
                borderRadius: 1,
                opacity: this._enabled ? 1 : 0.5
            }
        }, [
            React.createElement(Typography, {
                key: 'title',
                variant: 'subtitle2',
                sx: { color: colors.primaryColor, fontWeight: 'bold' }
            }, 'Input Mapping'),
            React.createElement(Typography, {
                key: 'description',
                variant: 'body2',
                sx: { marginTop: 0.5 }
            }, 'Maps raw hardware inputs to processed memory bits with inversion (system only)')
        ]);
    }

    /**
     * Get declarations used by this statement
     */
    public getUsedDeclarations(): Declaration[] {
        return [];
    }

    /**
     * Get declarations added by this statement
     */
    public getAddedDeclarations(): Declaration[] {
        // Validate that this statement has a valid plcSource
        if (!this.plcSource) {
            throw new Error('InputMappingStatement: plcSource is not set. Statement must be added to a program before calling getAddedDeclarations()');
        }

        // CRITICAL: InputMappingStatement should ONLY be used in SystemDefault program
        const myProgramType = this.plcSource.getProgramType();
        if (myProgramType !== PLCProgramType.SystemDefault) {
            throw new Error(`InputMappingStatement can only be used in SystemDefault program, but found in ${myProgramType} program`);
        }

        return [];
    }

    /**
     * Get PLC logic code
     * Generates input mapping code for all defined inputs with inversion support
     */
    public getPLCLogic(availableDeclarations: string[]): string[] {
        if (!this._enabled) {
            return [];
        }

        const lines: string[] = [];

        // Get the System PLC program to access user-defined inputs
        const program = PLCProgram.Instance(PLCProgramType.System);
        const inputs = program.inputs;

        if (inputs.length === 0) {
            return [
                '; Input Mapping - Standard handling',
                '; (No inputs defined)'
            ];
        }

        lines.push('; Input Mapping - Standard handling');

        for (const input of inputs) {
            const inputName = input.centroidName;

            // Add _RAW suffix to get hardware input name (ESTOPOK_I -> ESTOPOK_I_RAW)
            // Memory bit keeps original name (ESTOPOK_I)
            const hwName = `${inputName}_RAW`;

            // Generate the IF statement based on inversion
            if (input.isInverted) {
                // Inverted: IF NOT hardware input THEN set memory bit
                lines.push(`IF (!${hwName}) THEN (${inputName}) ; Inverted`);
            } else {
                // Normal: IF hardware input THEN set memory bit
                lines.push(`IF ${hwName} THEN (${inputName})`);
            }
        }

        lines.push('; End Input Mapping');

        return lines;
    }

    /**
     * Get validation issues
     */
    public getValidationIssues(): any[] {
        return [];
    }

    /**
     * Get all data elements (none for this statement)
     */
    public getDataElements(): DataElement[] {
        return [];
    }

    /**
     * Clone the statement
     */
    public clone(): InputMappingStatement {
        const cloned = new InputMappingStatement();
        cloned._comment = this._comment;
        cloned._enabled = this._enabled;
        return cloned;
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        return {
            type: 'InputMappingStatement',
            ...DataUtilities.getStorageData(this, ['_parentElement', '_plcSource'])
        };
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data, ['_parentElement', '_plcSource']);
    }
}
