import { TouchOffTarget } from "../../../machine/ICNCSystem";
import { IMachineCallback } from "../../../machine/IMachineCallback";
import { Wizard } from "../../Wizard/Wizard";
import { WizardManager } from "../../Wizard/WizardManager";
import { SelectMethodStep } from "./steps/SelectMethodStep";
import { OffsetType } from "./steps/SelectOffsetTypeStep";
import { SelectTargetStep } from "./steps/SelectTargetStep";

export enum TouchOffMethod {
    Manual = 'manual',
    TouchPlate = 'touchplate'
}

export interface TouchOffWizardState {
    target?: TouchOffTarget;  // Optional - undefined when showing target selection step
    method?: TouchOffMethod;
    offsetType?: OffsetType;
    alsoSetWorkZero?: boolean;  // For spoilboard and material top - also set work zero
}

export class TouchOffWizard extends Wizard<TouchOffWizardState> {
    constructor(target?: TouchOffTarget, callback?: IMachineCallback) {
        // Initialize state - target is undefined if not provided (will show selection step)
        const initialState: TouchOffWizardState = {
            target: target,
            method: undefined
        };

        // Call super with temporary null for firstStep
        super(
            null as any, // Temporary - will be set below
            initialState,
            true, // canClose
            false, // clickAwayClose - don't allow accidental closure during operation
            '80%', // width
            '85%'  // height
        );

        // Set callback on wizard instance (WizardManager expects this)
        this.callback = callback;

        // Create the first step - if target not provided, show selection
        const firstStep = target !== undefined
            ? new SelectMethodStep(this, null)
            : new SelectTargetStep(this, null);
        this.firstStep = firstStep;
        this.currentStep = firstStep;
    }

    static showForMaterialTop(callback?: IMachineCallback): TouchOffWizard {
        const wizard = new TouchOffWizard(TouchOffTarget.MaterialTop, callback);
        WizardManager.Instance.start(wizard);
        return wizard;
    }

    static showForMaterialTopAndWorkZero(callback?: IMachineCallback): TouchOffWizard {
        const wizard = new TouchOffWizard(TouchOffTarget.MaterialTopAndWorkZero, callback);
        WizardManager.Instance.start(wizard);
        return wizard;
    }

    static showForSpoilboard(callback?: IMachineCallback): TouchOffWizard {
        const wizard = new TouchOffWizard(TouchOffTarget.SpoilBoard, callback);
        WizardManager.Instance.start(wizard);
        return wizard;
    }

    static showForSpoilboardAndWorkZero(callback?: IMachineCallback): TouchOffWizard {
        const wizard = new TouchOffWizard(TouchOffTarget.SpoilBoardAndWorkZero, callback);
        WizardManager.Instance.start(wizard);
        return wizard;
    }

    static showForMachineBed(callback?: IMachineCallback): TouchOffWizard {
        const wizard = new TouchOffWizard(TouchOffTarget.MachineBed, callback);
        WizardManager.Instance.start(wizard);
        return wizard;
    }

    static showForWorkZero(callback?: IMachineCallback): TouchOffWizard {
        const wizard = new TouchOffWizard(TouchOffTarget.WorkZero, callback);
        WizardManager.Instance.start(wizard);
        return wizard;
    }

    /**
     * Show wizard with target selection page
     */
    static show(callback?: IMachineCallback): TouchOffWizard {
        const wizard = new TouchOffWizard(undefined, callback); // No target - will show selection
        WizardManager.Instance.start(wizard);
        return wizard;
    }
}
