import { Add as AddIcon, Delete as DeleteIcon, Edit as EditIcon } from '@mui/icons-material';
import { Box, Button, Chip, IconButton, Paper, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Typography } from '@mui/material';
import { useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { SymbolNameWithUsageTooltip } from '../components/SymbolNameWithUsageTooltip';
import { PLCProgram } from '../data/PLCProgram';
import { PLCProgramType } from '../data/PLCUtilities';
import { UITrigger } from '../data/ui/UITrigger';
import { UITriggerDialog } from './UITriggerDialog';

interface UITriggersTabProps {
    programType: PLCProgramType;
}

/**
 * UI Triggers Tab - Configuration for skin events in the PLC editor
 */
export function UITriggersTab({ programType }: UITriggersTabProps): React.ReactElement {
    const [dialogOpen, setDialogOpen] = useState(false);
    const [editingTrigger, setEditingTrigger] = useState<UITrigger | null>(null);
    const colors = ConfigurationDataColors.Instance;

    // Get the correct program based on the passed programType
    const program = PLCProgram.Instance(programType);

    const handleAdd = () => {
        setEditingTrigger(null);
        setDialogOpen(true);
    };

    const handleEdit = (trigger: UITrigger) => {
        setEditingTrigger(trigger);
        setDialogOpen(true);
    };

    const handleDelete = (trigger: UITrigger) => {
        program.removeUITrigger(trigger);
    };

    const handleDialogClose = () => {
        setDialogOpen(false);
        setEditingTrigger(null);
    };

    const handleDialogSave = (trigger: UITrigger) => {
        if (editingTrigger) {
            program.updateUITrigger(editingTrigger, trigger);
        } else {
            program.addUITrigger(trigger);
        }
        handleDialogClose();
    };

    return (
        <ObserveState
            key="ui-triggers-tab"
            listenTo={program}
            properties={['uiTriggers']}
            control={() => (
                <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', gap: 2 }}>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <Typography variant="h5">
                            UI Triggers Configuration
                        </Typography>
                        <Button
                            variant="contained"
                            startIcon={<AddIcon />}
                            onClick={handleAdd}
                            sx={{
                                backgroundColor: colors.primaryColor,
                                '&:hover': {
                                    backgroundColor: colors.primaryColor,
                                    opacity: 0.9,
                                },
                            }}
                        >
                            Add UI Trigger
                        </Button>
                    </Box>

                    <Typography variant="body2" color="textSecondary">
                        Configure UI triggers (skin events) to trigger PLC actions from the user interface.
                        Event numbers must be unique across System and SystemDefault programs.
                    </Typography>

                    <TableContainer component={Paper} sx={{ flex: 1 }}>
                        <Table stickyHeader>
                            <TableHead>
                                <TableRow>
                                    <TableCell sx={{ fontWeight: 600 }}>Event #</TableCell>
                                    <TableCell sx={{ fontWeight: 600 }}>Event Name</TableCell>
                                    <TableCell sx={{ fontWeight: 600 }}>States</TableCell>
                                    <TableCell sx={{ fontWeight: 600 }}>Description</TableCell>
                                    <TableCell sx={{ fontWeight: 600 }} align="right">Actions</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {program.uiTriggers.length === 0 ? (
                                    <TableRow>
                                        <TableCell colSpan={5} align="center" sx={{ py: 4 }}>
                                            <Typography variant="body2" color="textSecondary">
                                                No UI triggers configured. Click "Add UI Trigger" to create one.
                                            </Typography>
                                        </TableCell>
                                    </TableRow>
                                ) : (
                                    [...program.uiTriggers].sort((a, b) => a.eventNumber - b.eventNumber).map((trigger) => (
                                        <TableRow key={trigger.eventNumber} hover>
                                            <TableCell>
                                                <Chip
                                                    label={trigger.eventNumber}
                                                    size="small"
                                                    sx={{
                                                        backgroundColor: colors.primaryColor,
                                                        color: colors.lightTextColor,
                                                        fontWeight: 600,
                                                    }}
                                                />
                                            </TableCell>
                                            <TableCell>
                                                <SymbolNameWithUsageTooltip
                                                    centroidName={trigger.eventName}
                                                    programType={programType}
                                                >
                                                    <Typography variant="body2" sx={{ fontWeight: 500 }}>
                                                        {trigger.eventName}
                                                    </Typography>
                                                </SymbolNameWithUsageTooltip>
                                            </TableCell>
                                            <TableCell>
                                                <Box sx={{ display: 'flex', gap: 1 }}>
                                                    <Chip label={trigger.pressedText} size="small" variant="outlined" />
                                                    <Chip label={trigger.notPressedText} size="small" variant="outlined" />
                                                </Box>
                                            </TableCell>
                                            <TableCell>
                                                <Typography variant="body2" color="textSecondary">
                                                    {trigger.description || '—'}
                                                </Typography>
                                            </TableCell>
                                            <TableCell align="right">
                                                <IconButton
                                                    size="small"
                                                    onClick={() => handleEdit(trigger)}
                                                    sx={{ mr: 1 }}
                                                >
                                                    <EditIcon fontSize="small" />
                                                </IconButton>
                                                <IconButton
                                                    size="small"
                                                    onClick={() => handleDelete(trigger)}
                                                    color="error"
                                                >
                                                    <DeleteIcon fontSize="small" />
                                                </IconButton>
                                            </TableCell>
                                        </TableRow>
                                    ))
                                )}
                            </TableBody>
                        </Table>
                    </TableContainer>

                    <UITriggerDialog
                        open={dialogOpen}
                        trigger={editingTrigger}
                        onClose={handleDialogClose}
                        onSave={handleDialogSave}
                        programType={programType}
                    />
                </Box>
            )}
        />
    );
}
