import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item for verifying manual tool change location configuration.
 * This requires manual confirmation as we cannot programmatically verify
 * if the tool change location is safe and accessible.
 */
export class ManualToolChangeChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Manual Tool Change Location',
            'Configure the location where the machine moves for manual tool changes'
        );
    }

    public needsManualConfirmation(): boolean {
        // User must manually confirm they've configured a safe tool change location
        return true;
    }

    public completionCheck(): boolean {
        // We cannot automatically determine if the location is safe
        // The user must manually verify and confirm
        return true;
    }

    public clone(): SetupChecklistItem {
        const cloned = new ManualToolChangeChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
