import React from 'react';
import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { Job } from '../../../data/Job';
import { MachineData } from '../../../data/Machine/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { ActionBus } from '../../../utils/actions/ActionBus';
import { MoveAction, MoveType } from '../../../utils/actions/MoveAction';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { GridBox } from './GridBox';

export interface MaterialProps {
  simulatorView: SimulatorView;
  machineState: MachineStateData;
  machineData: MachineData;
  job?: Job; // Optional job - can be null, only use what's passed in
}

export const Material: React.FC<MaterialProps> = ({
  simulatorView,
  machineState,
  machineData,
  job // Optional job override
}) => {
  // Get configuration colors

  // State for tracking which sphere is hovered
  const [hoveredSphere, setHoveredSphere] = React.useState<number | null>(null);

  // Build dynamic listen array to handle null material cases
  const listenToArray = [
    { object: simulatorView, properties: ['material'] },
    { object: machineState, properties: ['currentWorkZero'] }, // Only listen to currentWorkZero since we use passed-in job
    { object: ConfigurationDataColors.Instance, properties: ['materialTransparency', 'defaultMaterialColor', 'materialColor'] }
  ];

  // Add material object to listening if it exists
  if (job?.material) {
    listenToArray.push({
      object: job.material,
      properties: ['xLength', 'yLength', 'height', 'materialColor', 'materialType']
    });
  }

  return (
    <ObserveMultiProperties
      listenTo={listenToArray}
      control={() => {
        const colors = ConfigurationDataColors.Instance;

        // Only render if job exists with valid material
        if (!job ||
          !job.material ||
          job.material.xLength <= 0 ||
          job.material.yLength <= 0 ||
          job.material.height <= 0) {
          return null;
        }

        const material = job.material;

        // Material is now observed by the outer ObserveMultiProperties
        const materialWidth = material.xLength;
        const materialLength = material.yLength;
        const materialHeight = material.height;

        // Use CoordinateUtil for consistent positioning with clamps and other components
        const materialBox = CoordinateUtil.getMaterialBox(machineState);

        // Convert material box to simulator coordinates for rendering
        const materialPositionSim = CoordinateUtil.toSimulator(
          new CNCPoint(
            materialBox.origin.x + materialWidth / 2,
            materialBox.origin.y + materialLength / 2,
            materialBox.origin.z + materialHeight / 2,
            CoordinateType.MachineZero
          )
        );

        // Target sphere positions: corners, edges, center
        // Z position for spheres (top surface of material)
        const sphereZSim = CoordinateUtil.toSimulator(
          new CNCPoint(0, 0, materialBox.origin.z + materialHeight, CoordinateType.MachineZero)
        ).z;

        // Convert material box corners to simulator coordinates
        const materialOriginSim = CoordinateUtil.toSimulator(materialBox.origin);
        const materialMaxSim = CoordinateUtil.toSimulator(
          new CNCPoint(
            materialBox.origin.x + materialWidth,
            materialBox.origin.y + materialLength,
            materialBox.origin.z,
            CoordinateType.MachineZero
          )
        );

        // Define CNCPoint positions for corners, edges, center (using consistent coordinates)
        const spherePositions = [
          // Corners
          new CNCPoint(materialOriginSim.x, materialOriginSim.y, sphereZSim, CoordinateType.Simulator), // Front Left
          new CNCPoint(materialMaxSim.x, materialOriginSim.y, sphereZSim, CoordinateType.Simulator), // Front Right
          new CNCPoint(materialOriginSim.x, materialMaxSim.y, sphereZSim, CoordinateType.Simulator), // Back Left
          new CNCPoint(materialMaxSim.x, materialMaxSim.y, sphereZSim, CoordinateType.Simulator), // Back Right
          // Edges
          new CNCPoint(materialOriginSim.x + materialWidth / 2, materialOriginSim.y, sphereZSim, CoordinateType.Simulator), // Front Center
          new CNCPoint(materialOriginSim.x + materialWidth / 2, materialMaxSim.y, sphereZSim, CoordinateType.Simulator), // Back Center
          new CNCPoint(materialOriginSim.x, materialOriginSim.y + materialLength / 2, sphereZSim, CoordinateType.Simulator), // Left Center
          new CNCPoint(materialMaxSim.x, materialOriginSim.y + materialLength / 2, sphereZSim, CoordinateType.Simulator), // Right Center
          // Center
          new CNCPoint(materialOriginSim.x + materialWidth / 2, materialOriginSim.y + materialLength / 2, sphereZSim, CoordinateType.Simulator), // Center
        ];

        // Handler to move machine to target sphere location
        const handleTargetClick = (spherePosition: CNCPoint) => {
          // Convert sphere position (Simulator coords) to WorkZeroWithOffsets
          const targetInWorkZero = CoordinateUtil.toWorkZeroWithOffsets(spherePosition);
          // Keep current Z position unchanged - get current Z in WorkZeroWithOffsets
          const currentPosInWorkZero = CoordinateUtil.toWorkZeroWithOffsets(ConfigurationState.Instance.currentMachinePoint);
          // Create and execute move action - move tool tip to sphere X,Y position
          const moveAction = new MoveAction(CoordinateType.WorkZeroWithOffsets, targetInWorkZero.x, targetInWorkZero.y, currentPosInWorkZero.z, undefined, MoveType.Coordinates);
          ActionBus.Instance.addAction(moveAction);
        };

        return (
          <>
            <GridBox
              position={[materialPositionSim.x, materialPositionSim.y, materialPositionSim.z]}
              size={[materialWidth, materialLength, materialHeight]}
              color={ConfigurationDataColors.toThreeJsColor(material.materialColor || colors.materialColor)}
              viewStyle={simulatorView.material}
              opacity={simulatorView.material === ViewStyle.SemiTransparent ? colors.materialTransparency : 1}
              gridSpacing={1} // 1" x 1" grid
            />
            {spherePositions.map((pos, idx) => {
              // Convert to simulator coordinates
              const sim = CoordinateUtil.toSimulator(pos);
              const isHovered = hoveredSphere === idx;
              return (
                <mesh
                  key={idx}
                  position={[sim.x, sim.y, sim.z]}
                  onClick={() => handleTargetClick(pos)}
                  onPointerOver={() => setHoveredSphere(idx)}
                  onPointerOut={() => setHoveredSphere(null)}
                  castShadow
                  receiveShadow
                >
                  <sphereGeometry args={[ConfigurationData.Instance.targetSphereSize, 16, 16]} />
                  <meshStandardMaterial
                    color={ConfigurationDataColors.toThreeJsColor(isHovered ? colors.highlightColor : colors.mutedTextColor)}
                    transparent={true}
                    opacity={isHovered ? 1.0 : 0.0}
                  />
                </mesh>
              );
            })}
          </>
        );
      }}
    />
  );
};
