import { StateManager } from '../utils/statemanager/StateManager';

/**
 * State management for G-code preview dialog
 * Prevents issues with useEffect and ensures consistent state handling
 */
export class GCodePreviewState {
    private static _instance: GCodePreviewState;

    private _lastRequestTitle: string = '';
    private _elapsedSeconds: number = 0;
    private _timerInterval: NodeJS.Timeout | null = null;

    private constructor() {
        // Private constructor for singleton
    }

    public static get Instance(): GCodePreviewState {
        if (!GCodePreviewState._instance) {
            GCodePreviewState._instance = new GCodePreviewState();
        }
        return GCodePreviewState._instance;
    }

    public get lastRequestTitle(): string {
        return this._lastRequestTitle;
    }

    public get elapsedSeconds(): number {
        return this._elapsedSeconds;
    }

    /**
     * Check if a request is new (different from last processed)
     */
    public isNewRequest(title: string): boolean {
        return title !== this._lastRequestTitle;
    }

    /**
     * Mark a request as started
     */
    public markRequestStarted(title: string): void {
        this._lastRequestTitle = title;
        StateManager.propertyChanged(this, 'lastRequestTitle');
    }

    /**
     * Start the elapsed time timer
     */
    public startTimer(): void {
        // Clear any existing timer
        this.stopTimer();
        
        // Reset elapsed seconds
        this._elapsedSeconds = 0;
        StateManager.propertyChanged(this, 'elapsedSeconds');
        
        // Start new timer
        this._timerInterval = setInterval(() => {
            this._elapsedSeconds++;
            StateManager.propertyChanged(this, 'elapsedSeconds');
        }, 1000);
    }

    /**
     * Stop the elapsed time timer
     */
    public stopTimer(): void {
        if (this._timerInterval) {
            clearInterval(this._timerInterval);
            this._timerInterval = null;
        }
    }

    /**
     * Reset state when dialog closes
     */
    public reset(): void {
        this._lastRequestTitle = '';
        this._elapsedSeconds = 0;
        this.stopTimer();
        StateManager.propertyChanged(this, 'lastRequestTitle');
        StateManager.propertyChanged(this, 'elapsedSeconds');
    }
}
