import { MyLocation as AutoMoveIcon, PanTool as ManualIcon } from '@mui/icons-material';
import { Box, Card, CardActionArea, CardContent, Grid, Typography } from '@mui/material';
import React from 'react';
import { CNCPoint } from '../../../../data/CNCPoint';
import { CoordinateType } from '../../../../data/Common/CoordinateType';
import { Tool } from '../../../../data/Common/Tool';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { MachineData } from '../../../../data/Machine/MachineData';
import { MovementCoordinateType } from '../../../../machine/ICNCMovement';
import { CoordinateUtil } from '../../../../utils/CoordinateUtil';
import { MachineInterfaceManager } from '../../../../utils/MachineInterfaceManager';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { WizardStep } from '../../../Wizard/WizardStep';
import { ToolMeasurementMethod, ToolMeasurementWizard } from '../ToolMeasurementWizard';
import { ManualJogStep } from './ManualJogStep';
import { ManualPositioningStep } from './ManualPositioningStep';
import { SelectTouchplateOrManualStep } from './SelectTouchplateOrManualStep';

/**
 * Step to move to the measurement position
 */
export class MoveToPositionStep extends WizardStep {
    private tool: Tool;
    private method: ToolMeasurementMethod;

    constructor(wizard: ToolMeasurementWizard, tool: Tool, previousStep: WizardStep | null, method: ToolMeasurementMethod) {
        super(wizard, previousStep);
        this.tool = tool;
        this.method = method;
    }

    getTitle(): string {
        return `Move to ${this.getPositionName()}`;
    }

    private getPositionName(): string {
        switch (this.method) {
            case ToolMeasurementMethod.ManualFixedPoint:
                return 'Fixed Tool Measurement Point';
            case ToolMeasurementMethod.ManualSpoilboard:
                return 'Spoilboard Tool Measurement Point';
            case ToolMeasurementMethod.ManualMachineBed:
                return 'Machine Bed Tool Measurement Point';
            default:
                return 'Measurement Position';
        }
    }

    nextStep(): WizardStep | null {
        const machineData = MachineData.Instance;

        if (machineData.hasMovableTouchPlate) {
            return new SelectTouchplateOrManualStep(this.wizard as ToolMeasurementWizard, this.tool, this, this.method);
        } else {
            return new ManualJogStep(this.wizard as ToolMeasurementWizard, this.tool, this, this.method);
        }
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return <MoveToPositionStepComponent step={this} />;
    }
}

interface MoveToPositionStepComponentProps {
    step: MoveToPositionStep;
}

function MoveToPositionStepComponent({ step }: MoveToPositionStepComponentProps) {
    const wizard = step.wizard as ToolMeasurementWizard;
    const colors = ConfigurationDataColors.Instance;

    const handleAutoMove = async () => {
        // Get the machine interface and machine data
        const machine = MachineInterfaceManager.Instance.getMachineInterface();
        const machineData = MachineData.Instance;

        // Determine measurement position based on the method
        let measurementPoint: CNCPoint;
        switch (step['method']) {
            case ToolMeasurementMethod.ManualFixedPoint:
                measurementPoint = new CNCPoint(
                    machineData.fixedToolMeasurementPoint.x,
                    machineData.fixedToolMeasurementPoint.y,
                    CoordinateUtil.getZMax(CoordinateType.MachineZero),
                    CoordinateType.MachineZero
                );
                break;
            case ToolMeasurementMethod.ManualSpoilboard:
                measurementPoint = new CNCPoint(
                    machineData.spoilboardToolMeasurementPoint.x,
                    machineData.spoilboardToolMeasurementPoint.y,
                    CoordinateUtil.getZMax(CoordinateType.MachineZero),
                    CoordinateType.MachineZero
                );
                break;
            case ToolMeasurementMethod.ManualMachineBed:
                measurementPoint = new CNCPoint(
                    machineData.machineBedToolMeasurementPoint.x,
                    machineData.machineBedToolMeasurementPoint.y,
                    CoordinateUtil.getZMax(CoordinateType.MachineZero),
                    CoordinateType.MachineZero
                );
                break;
            default:
                measurementPoint = new CNCPoint(
                    machineData.fixedToolMeasurementPoint.x,
                    machineData.fixedToolMeasurementPoint.y,
                    CoordinateUtil.getZMax(CoordinateType.MachineZero),
                    CoordinateType.MachineZero
                );
        }

        // Move to the measurement position (X/Y at measurement point, Z at max)
        await machine.movement.MoveTo(measurementPoint, MovementCoordinateType.Machine, 200);

        // Advance to next step (Z jog step)
        wizard.advanceToNextStep();
    };

    const handleManualPosition = () => {
        const nextStep = new ManualPositioningStep(wizard, step['tool'], step, step['method']);
        wizard.currentStep = nextStep;
        StateManager.propertyChanged(wizard, 'currentStep');
    };

    return (
        <Box sx={{ p: 3 }}>
            <Typography variant="body1" sx={{ mb: 3, color: 'text.secondary' }}>
                Choose how to position the tool at the {step['getPositionName']()}:
            </Typography>

            <Grid container spacing={3}>
                <Grid item xs={12} sm={6}>
                    <Card
                        sx={{
                            height: '100%',
                            border: `2px solid ${colors.borderColor}`,
                            transition: 'all 0.2s ease-in-out',
                            '&:hover': {
                                boxShadow: 3,
                                borderColor: colors.primaryColor
                            }
                        }}
                    >
                        <CardActionArea
                            onClick={handleAutoMove}
                            sx={{ height: '100%', p: 3 }}
                        >
                            <CardContent sx={{ textAlign: 'center' }}>
                                <AutoMoveIcon sx={{ fontSize: 80, color: colors.primaryColor, mb: 2 }} />
                                <Typography variant="h5" gutterBottom>
                                    Move to Position
                                </Typography>
                                <Typography variant="body2" color="text.secondary">
                                    Automatically move to the configured position
                                </Typography>
                            </CardContent>
                        </CardActionArea>
                    </Card>
                </Grid>

                <Grid item xs={12} sm={6}>
                    <Card
                        sx={{
                            height: '100%',
                            border: `2px solid ${colors.borderColor}`,
                            transition: 'all 0.2s ease-in-out',
                            '&:hover': {
                                boxShadow: 3,
                                borderColor: colors.secondaryColor
                            }
                        }}
                    >
                        <CardActionArea
                            onClick={handleManualPosition}
                            sx={{ height: '100%', p: 3 }}
                        >
                            <CardContent sx={{ textAlign: 'center' }}>
                                <ManualIcon sx={{ fontSize: 80, color: colors.secondaryColor, mb: 2 }} />
                                <Typography variant="h5" gutterBottom>
                                    Manually Position
                                </Typography>
                                <Typography variant="body2" color="text.secondary">
                                    Use jog controls to position the machine
                                </Typography>
                            </CardContent>
                        </CardActionArea>
                    </Card>
                </Grid>
            </Grid>
        </Box>
    );
}
