import { Close as CloseIcon } from '@mui/icons-material';
import { Box, IconButton, Paper, Typography } from '@mui/material';
import React, { useCallback, useRef, useState } from 'react';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';

export interface FloatingWindowProps {
    title: string;
    children: React.ReactNode;
    onClose: () => void;
    defaultPosition?: { x: number; y: number };
    width?: number | string;
    minWidth?: number;
    maxWidth?: number;
    defaultHeight?: number | string;
    minHeight?: number;
    maxHeight?: number;
}

/**
 * Draggable and resizable floating window component
 * Can be moved around the screen, resized by dragging edges/corners, and closed
 */
export function FloatingWindow({
    title,
    children,
    onClose,
    defaultPosition = { x: 100, y: 100 },
    width = 400,
    minWidth = 300,
    maxWidth = 800,
    defaultHeight = 'auto',
    minHeight = 200,
    maxHeight = 900
}: FloatingWindowProps) {
    const colors = ConfigurationDataColors.Instance;
    const [position, setPosition] = useState(defaultPosition);
    const [size, setSize] = useState({
        width: typeof width === 'number' ? width : parseInt(width) || 400,
        height: typeof defaultHeight === 'number' ? defaultHeight : parseInt(defaultHeight) || 600
    });
    const [isDragging, setIsDragging] = useState(false);
    const [isResizing, setIsResizing] = useState(false);
    const [resizeDirection, setResizeDirection] = useState<string>('');
    const dragStartRef = useRef<{ x: number; y: number } | null>(null);
    const resizeStartRef = useRef<{ x: number; y: number; width: number; height: number; startX: number; startY: number } | null>(null);

    const handleMouseDown = (e: React.MouseEvent) => {
        // Only start drag if clicking on the header (not buttons)
        if ((e.target as HTMLElement).closest('button')) {
            return;
        }

        setIsDragging(true);
        dragStartRef.current = {
            x: e.clientX - position.x,
            y: e.clientY - position.y
        };
    };

    const handleMouseMove = useCallback((e: MouseEvent) => {
        if (!isDragging || !dragStartRef.current) return;

        const newX = e.clientX - dragStartRef.current.x;
        const newY = e.clientY - dragStartRef.current.y;

        // Keep window within viewport bounds
        const maxX = window.innerWidth - 200; // Leave some space to grab it
        const maxY = window.innerHeight - 100;

        setPosition({
            x: Math.max(0, Math.min(newX, maxX)),
            y: Math.max(0, Math.min(newY, maxY))
        });
    }, [isDragging]);

    const handleMouseUp = () => {
        setIsDragging(false);
        setIsResizing(false);
        setResizeDirection('');
        dragStartRef.current = null;
        resizeStartRef.current = null;
    };

    const handleResizeMouseDown = (e: React.MouseEvent, direction: string) => {
        e.preventDefault();
        e.stopPropagation();

        setIsResizing(true);
        setResizeDirection(direction);
        resizeStartRef.current = {
            x: e.clientX,
            y: e.clientY,
            width: size.width,
            height: size.height,
            startX: position.x,
            startY: position.y
        };
    };

    const handleResizeMouseMove = useCallback((e: MouseEvent) => {
        if (!isResizing || !resizeStartRef.current) return;

        const deltaX = e.clientX - resizeStartRef.current.x;
        const deltaY = e.clientY - resizeStartRef.current.y;

        let newWidth = size.width;
        let newHeight = size.height;
        let newX = position.x;
        let newY = position.y;

        // Handle horizontal resizing
        if (resizeDirection.includes('e')) {
            newWidth = Math.max(minWidth, Math.min(maxWidth, resizeStartRef.current.width + deltaX));
        } else if (resizeDirection.includes('w')) {
            const potentialWidth = resizeStartRef.current.width - deltaX;
            if (potentialWidth >= minWidth && potentialWidth <= maxWidth) {
                newWidth = potentialWidth;
                newX = resizeStartRef.current.startX + deltaX;
            }
        }

        // Handle vertical resizing
        if (resizeDirection.includes('s')) {
            newHeight = Math.max(minHeight, Math.min(maxHeight, resizeStartRef.current.height + deltaY));
        } else if (resizeDirection.includes('n')) {
            const potentialHeight = resizeStartRef.current.height - deltaY;
            if (potentialHeight >= minHeight && potentialHeight <= maxHeight) {
                newHeight = potentialHeight;
                newY = resizeStartRef.current.startY + deltaY;
            }
        }

        setSize({ width: newWidth, height: newHeight });
        setPosition({ x: newX, y: newY });
    }, [isResizing, resizeDirection, size, position, minWidth, maxWidth, minHeight, maxHeight]);

    React.useEffect(() => {
        if (isDragging) {
            document.addEventListener('mousemove', handleMouseMove);
            document.addEventListener('mouseup', handleMouseUp);
            return () => {
                document.removeEventListener('mousemove', handleMouseMove);
                document.removeEventListener('mouseup', handleMouseUp);
            };
        }
    }, [isDragging, handleMouseMove]);

    React.useEffect(() => {
        if (isResizing) {
            document.addEventListener('mousemove', handleResizeMouseMove);
            document.addEventListener('mouseup', handleMouseUp);
            return () => {
                document.removeEventListener('mousemove', handleResizeMouseMove);
                document.removeEventListener('mouseup', handleMouseUp);
            };
        }
    }, [isResizing, handleResizeMouseMove]);

    return (
        <Paper
            elevation={8}
            sx={{
                position: 'fixed',
                left: position.x,
                top: position.y,
                width: size.width,
                height: size.height,
                minWidth,
                maxWidth,
                minHeight,
                maxHeight,
                zIndex: 1500, // Above wizards
                display: 'flex',
                flexDirection: 'column',
                backgroundColor: colors.lightBackgroundColor,
                borderColor: colors.borderColor,
                cursor: isDragging ? 'grabbing' : 'default'
            }}
        >
            {/* Resize Handles */}
            {/* Top edge */}
            <Box
                onMouseDown={(e) => handleResizeMouseDown(e, 'n')}
                sx={{
                    position: 'absolute',
                    top: 0,
                    left: 8,
                    right: 8,
                    height: '8px',
                    cursor: 'ns-resize',
                    zIndex: 10
                }}
            />
            {/* Bottom edge */}
            <Box
                onMouseDown={(e) => handleResizeMouseDown(e, 's')}
                sx={{
                    position: 'absolute',
                    bottom: 0,
                    left: 8,
                    right: 8,
                    height: '8px',
                    cursor: 'ns-resize',
                    zIndex: 10
                }}
            />
            {/* Left edge */}
            <Box
                onMouseDown={(e) => handleResizeMouseDown(e, 'w')}
                sx={{
                    position: 'absolute',
                    left: 0,
                    top: 8,
                    bottom: 8,
                    width: '8px',
                    cursor: 'ew-resize',
                    zIndex: 10
                }}
            />
            {/* Right edge */}
            <Box
                onMouseDown={(e) => handleResizeMouseDown(e, 'e')}
                sx={{
                    position: 'absolute',
                    right: 0,
                    top: 8,
                    bottom: 8,
                    width: '8px',
                    cursor: 'ew-resize',
                    zIndex: 10
                }}
            />
            {/* Top-left corner */}
            <Box
                onMouseDown={(e) => handleResizeMouseDown(e, 'nw')}
                sx={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    width: '16px',
                    height: '16px',
                    cursor: 'nwse-resize',
                    zIndex: 11
                }}
            />
            {/* Top-right corner */}
            <Box
                onMouseDown={(e) => handleResizeMouseDown(e, 'ne')}
                sx={{
                    position: 'absolute',
                    top: 0,
                    right: 0,
                    width: '16px',
                    height: '16px',
                    cursor: 'nesw-resize',
                    zIndex: 11
                }}
            />
            {/* Bottom-left corner */}
            <Box
                onMouseDown={(e) => handleResizeMouseDown(e, 'sw')}
                sx={{
                    position: 'absolute',
                    bottom: 0,
                    left: 0,
                    width: '16px',
                    height: '16px',
                    cursor: 'nesw-resize',
                    zIndex: 11
                }}
            />
            {/* Bottom-right corner */}
            <Box
                onMouseDown={(e) => handleResizeMouseDown(e, 'se')}
                sx={{
                    position: 'absolute',
                    bottom: 0,
                    right: 0,
                    width: '16px',
                    height: '16px',
                    cursor: 'nwse-resize',
                    zIndex: 11
                }}
            />
            {/* Header */}
            <Box
                onMouseDown={handleMouseDown}
                sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    p: 1.5,
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor,
                    cursor: isDragging ? 'grabbing' : 'grab',
                    userSelect: 'none'
                }}
            >
                <Typography variant="h6" sx={{ fontSize: '1rem', fontWeight: 'bold' }}>
                    {title}
                </Typography>
                <IconButton
                    size="small"
                    onClick={onClose}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon fontSize="small" />
                </IconButton>
            </Box>

            {/* Content */}
            <Box
                sx={{
                    flex: 1,
                    overflow: 'auto',
                    p: 2
                }}
            >
                {children}
            </Box>
        </Paper>
    );
}
