import React, { ReactNode } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { ActionBus } from '../../utils/actions/ActionBus';
import { MoveAction, MoveType } from '../../utils/actions/MoveAction';
import { ObserveState } from '../../utils/statemanager/ObserveState';

interface MoveActionUIProps {
    action: MoveAction;
}

/**
 * UI Component that displays countdown timer and controls for a MoveAction
 * This component is rendered by ActionNotificationArea based on action state
 */
export function MoveActionUI({ action }: MoveActionUIProps): ReactNode {
    // Don't show UI if this action is showing collision warning
    if (action.isShowingCollisionWarning) {
        return null; // Modal manager handles collision UI
    }

    // Don't show UI if executing after collision confirmation
    if (action.isExecutingAfterCollision) {
        return null;
    }

    // Check safe mode overrides for delay UI
    const configState = ConfigurationState.Instance;
    const shouldSkipDelayUI = action.noDelay || configState.delayOff;

    // Don't show countdown UI if noDelay is enabled or delay override is active
    if (shouldSkipDelayUI) {
        return null;
    }

    // Show normal move UI countdown
    const delayTime = action.getDelayTime();
    if (delayTime <= 0) {
        return null; // No UI if no delay
    }

    return (
        <MoveActionCountdown
            key={action.id}
            action={action}
            delayTime={delayTime}
            startTime={action._startTime}
        />
    );
}

// Internal countdown component
interface MoveActionCountdownProps {
    action: MoveAction;
    delayTime: number;
    startTime: number;
}

function MoveActionCountdown({ action, delayTime, startTime }: MoveActionCountdownProps): ReactNode {
    // Don't use useState for timeRemaining - calculate it directly each render
    const [, forceUpdate] = React.useReducer(x => x + 1, 0);
    const [isPaused, setIsPaused] = React.useState(false);
    const [remainingTimeWhenPaused, setRemainingTimeWhenPaused] = React.useState<number | null>(null);

    // Get the current configuration delay for this move type
    const getCurrentConfigDelay = () => {
        const config = ConfigurationData.Instance;
        switch (action.moveType) {
            case MoveType.Simulator:
                return config.simulatorMoveDelay;
            case MoveType.JogPad:
                return config.jogPadMoveDelay;
            case MoveType.Coordinates:
                return config.coordinateMoveDelay;
            case MoveType.MDI:
                return config.mdiToolDelay;
            default:
                return config.coordinateMoveDelay;
        }
    };

    const [adjustedDelayTime, setAdjustedDelayTime] = React.useState(getCurrentConfigDelay());

    // Calculate remaining time based on current props and pause state
    const now = Date.now();
    let elapsed: number;
    let timeRemaining: number;

    if (isPaused && remainingTimeWhenPaused !== null) {
        // Use the saved remaining time when paused
        timeRemaining = remainingTimeWhenPaused;
        elapsed = adjustedDelayTime - timeRemaining;
    } else {
        // Normal time calculation
        elapsed = now - startTime;
        timeRemaining = Math.max(0, adjustedDelayTime - elapsed);
    }

    // Use refs to store stable values that won't trigger effect re-runs
    const delayTimeRef = React.useRef(adjustedDelayTime);
    const startTimeRef = React.useRef(startTime);

    // Update refs when values change
    React.useEffect(() => {
        delayTimeRef.current = adjustedDelayTime;
        startTimeRef.current = startTime;
    }, [adjustedDelayTime, startTime]);

    // Handle move now button
    const handleMoveNow = React.useCallback(() => {
        // Clear existing timeout
        if (action._timeoutId) {
            clearTimeout(action._timeoutId);
            action._timeoutId = undefined;
        }

        // Execute immediately
        action.executeImmediate();
        ActionBus.Instance.completeAction(action);
    }, [action]);

    React.useEffect(() => {
        const interval = setInterval(() => {
            if (!isPaused) {
                const currentTimeRemaining = Math.max(0, adjustedDelayTime - (Date.now() - startTime));

                // Check if time has expired and execute the action
                if (currentTimeRemaining <= 0) {
                    handleMoveNow();
                } else {
                    forceUpdate(); // Force component to re-render and recalculate timeRemaining
                }
            }
        }, 100); // Update every 100ms for smooth countdown

        return () => {
            clearInterval(interval);
        };
    }, [action.id, isPaused, adjustedDelayTime, startTime, handleMoveNow]); // Reset interval when these change

    // Handle mouse enter/leave for pause functionality
    const handleMouseEnter = () => {
        if (!isPaused) {
            // Clear the existing timeout to actually pause the action
            if (action._timeoutId) {
                clearTimeout(action._timeoutId);
                action._timeoutId = undefined;
            }

            // Calculate and save remaining time when pausing
            const currentRemaining = Math.max(0, adjustedDelayTime - (Date.now() - startTime));
            setRemainingTimeWhenPaused(currentRemaining);
            setIsPaused(true);
        }
    };

    const handleMouseLeave = () => {
        if (isPaused && remainingTimeWhenPaused !== null) {
            // Resume the action with the remaining time
            if (remainingTimeWhenPaused > 0) {
                // Update start time to account for the pause
                action._startTime = Date.now() - (adjustedDelayTime - remainingTimeWhenPaused);

                // Restart the timeout with remaining time
                action._timeoutId = window.setTimeout(() => {
                    handleMoveNow();
                }, remainingTimeWhenPaused);
            }

            setIsPaused(false);
            setRemainingTimeWhenPaused(null);
        }
    };

    // Handle delay adjustment - this updates the configuration for this move type
    const handleDelayChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const newDelaySeconds = parseInt(event.target.value);
        const newDelay = newDelaySeconds * 1000; // Convert seconds to milliseconds

        // Update the configuration setting for this move type
        const config = ConfigurationData.Instance;
        switch (action.moveType) {
            case MoveType.Simulator:
                config.simulatorMoveDelay = newDelay;
                break;
            case MoveType.JogPad:
                config.jogPadMoveDelay = newDelay;
                break;
            case MoveType.Coordinates:
                config.coordinateMoveDelay = newDelay;
                break;
            case MoveType.MDI:
                config.mdiToolDelay = newDelay;
                break;
        }

        // Update the current action's adjusted delay time for UI display
        setAdjustedDelayTime(newDelay);

        // Clear existing timeout
        if (action._timeoutId) {
            clearTimeout(action._timeoutId);
            action._timeoutId = undefined;
        }

        if (newDelay > 0) {
            if (isPaused) {
                // If paused, just update the remaining time
                setRemainingTimeWhenPaused(newDelay);
            } else {
                // If not paused, restart with new timing
                const currentElapsed = Date.now() - startTime;
                const newTimeRemaining = Math.max(0, newDelay - currentElapsed);

                if (newTimeRemaining > 0) {
                    // Update start time to match new delay
                    action._startTime = Date.now() - (newDelay - newTimeRemaining);

                    action._timeoutId = window.setTimeout(() => {
                        handleMoveNow();
                    }, newTimeRemaining);
                } else {
                    handleMoveNow(); // Execute immediately if no time remaining
                }
            }
        }
    };

    const progressPercent = Math.max(0, (timeRemaining / adjustedDelayTime) * 100);
    const secondsRemaining = Math.ceil(timeRemaining / 1000);
    const delaySeconds = Math.round(adjustedDelayTime / 1000);

    // Get a display name for the move type
    const getMoveTypeName = () => {
        switch (action.moveType) {
            case MoveType.Simulator:
                return 'Simulator';
            case MoveType.JogPad:
                return 'Jog Pad';
            case MoveType.Coordinates:
                return 'Coordinates';
            case MoveType.MDI:
                return 'MDI';
            default:
                return 'Move';
        }
    };

    // Don't show UI if delay is set to 0
    if (adjustedDelayTime <= 0) {
        handleMoveNow(); // Execute immediately
        return null;
    }

    return (
        <ObserveState
            key="move-action-countdown-theme"
            listenTo={ConfigurationDataColors.Instance}
            properties={['darkOverlay', 'modalBackdrop', 'lightTextColor', 'warningColor', 'lightOverlay', 'successColor', 'errorColor']}
            control={() => (
                <div
                    onMouseEnter={handleMouseEnter}
                    onMouseLeave={handleMouseLeave}
                    style={{
                        backgroundColor: isPaused
                            ? ConfigurationDataColors.Instance.darkOverlay
                            : ConfigurationDataColors.Instance.modalBackdrop,
                        color: ConfigurationDataColors.Instance.lightTextColor,
                        padding: '12px 16px',
                        borderRadius: '8px',
                        minWidth: '250px',
                        fontFamily: 'Arial, sans-serif',
                        border: isPaused
                            ? `2px solid ${ConfigurationDataColors.Instance.warningColor}`
                            : 'none'
                    }}
                >
                    <div style={{ fontSize: '14px', fontWeight: 'bold', marginBottom: '8px' }}>
                        {`Move Command Executing...${isPaused ? ' (PAUSED)' : ''}`}
                    </div>

                    <div style={{ fontSize: '12px', marginBottom: '8px' }}>
                        {`${secondsRemaining} seconds remaining`}
                    </div>

                    <div
                        style={{
                            width: '100%',
                            height: '4px',
                            backgroundColor: ConfigurationDataColors.Instance.lightOverlay,
                            borderRadius: '2px',
                            marginBottom: '8px',
                            overflow: 'hidden'
                        }}
                    >
                        <div
                            style={{
                                width: `${progressPercent}%`,
                                height: '100%',
                                backgroundColor: isPaused
                                    ? ConfigurationDataColors.Instance.warningColor
                                    : ConfigurationDataColors.Instance.successColor,
                                transition: isPaused ? 'none' : 'width 0.1s ease'
                            }}
                        />
                    </div>

                    <div style={{ marginBottom: '8px' }}>
                        <label style={{ fontSize: '11px', display: 'block', marginBottom: '4px' }}>
                            {`${getMoveTypeName()} Delay: ${delaySeconds}s`}
                        </label>
                        <input
                            type="range"
                            min="0"
                            max="20"
                            value={delaySeconds.toString()}
                            onChange={handleDelayChange}
                            style={{
                                width: '100%',
                                height: '4px',
                                background: ConfigurationDataColors.Instance.lightOverlay,
                                outline: 'none',
                                borderRadius: '2px'
                            }}
                        />
                    </div>

                    <div style={{ display: 'flex', gap: '8px' }}>
                        <button
                            onClick={handleMoveNow}
                            style={{
                                backgroundColor: ConfigurationDataColors.Instance.successColor,
                                color: ConfigurationDataColors.Instance.lightTextColor,
                                border: 'none',
                                padding: '4px 8px',
                                borderRadius: '4px',
                                fontSize: '12px',
                                cursor: 'pointer',
                                flex: 1
                            }}
                        >
                            Move Now
                        </button>

                        <button
                            onClick={() => action.cancel()}
                            style={{
                                backgroundColor: ConfigurationDataColors.Instance.errorColor,
                                color: ConfigurationDataColors.Instance.lightTextColor,
                                border: 'none',
                                padding: '4px 8px',
                                borderRadius: '4px',
                                fontSize: '12px',
                                cursor: 'pointer',
                                flex: 1
                            }}
                        >
                            Cancel
                        </button>
                    </div>
                </div>
            )}
        />
    );
}
