import { Close as CloseIcon } from '@mui/icons-material';
import { Box, Button, Dialog, DialogActions, DialogContent, DialogTitle, IconButton, TextField } from '@mui/material';
import { useEffect, useState } from 'react';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { GCodeEditor } from './GCodeEditor';

export interface GCodeEditorDialogProps {
    open: boolean;
    gcode: string;
    jobName?: string;
    onSave: (gcode: string, jobName: string) => void;
    onCancel: () => void;
}

export function GCodeEditorDialog({ open, gcode, jobName = '', onSave, onCancel }: GCodeEditorDialogProps) {
    const colors = ConfigurationDataColors.Instance;
    const [editedGCode, setEditedGCode] = useState(gcode);
    const [editedJobName, setEditedJobName] = useState(jobName);

    // Generate default name with timestamp
    const generateDefaultName = () => {
        const now = new Date();
        const timestamp = now.toISOString().replace(/[:.]/g, '-').slice(0, -5); // Format: 2026-02-07T15-30-45
        return `custom_job_${timestamp}`;
    };

    // Update local state when props change
    useEffect(() => {
        if (open) {
            setEditedGCode(gcode);
            setEditedJobName(jobName || generateDefaultName());
        }
    }, [open, gcode, jobName]);

    const handleSave = () => {
        const finalJobName = editedJobName.trim() || generateDefaultName();
        onSave(editedGCode, finalJobName);
    };

    const handleCancel = () => {
        setEditedGCode(gcode); // Reset to original
        setEditedJobName(jobName);
        onCancel();
    };

    return (
        <Dialog
            open={open}
            onClose={handleCancel}
            maxWidth="lg"
            fullWidth
        >
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3
            }}>
                Edit G-code
                <IconButton
                    onClick={handleCancel}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>
            <DialogContent>
                <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 2 }}>
                    <TextField
                        label="Job Name"
                        fullWidth
                        value={editedJobName}
                        onChange={(e) => setEditedJobName(e.target.value)}
                        variant="outlined"
                        placeholder="Enter a name for this job"
                        helperText="A unique name will be generated if left empty"
                    />
                    <GCodeEditor
                        value={editedGCode}
                        onChange={setEditedGCode}
                        minRows={20}
                        maxRows={25}
                    />
                </Box>
            </DialogContent>
            <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
                <Button onClick={handleCancel}>
                    Cancel
                </Button>
                <Button
                    variant="contained"
                    onClick={handleSave}
                    sx={{
                        backgroundColor: colors.primaryColor,
                        '&:hover': {
                            backgroundColor: colors.primaryColor,
                            opacity: 0.9
                        }
                    }}
                >
                    Save
                </Button>
            </DialogActions>
        </Dialog>
    );
}
