import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item for Simulator configuration
 * Requires manual confirmation that simulator is properly configured
 */
export class SimulatorChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Simulator Configuration',
            'Confirm simulator settings and views are properly configured'
        );
    }

    public needsManualConfirmation(): boolean {
        return true; // Requires manual confirmation
    }

    public completionCheck(): boolean {
        // Always requires manual confirmation
        return true;
    }

    public clone(): SimulatorChecklistItem {
        const cloned = new SimulatorChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
