import { Settings as SettingsIcon, Tune as TuneIcon } from '@mui/icons-material';
import {
    Box,
    Button,
    Checkbox,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    FormControl,
    FormControlLabel,
    Grid,
    IconButton,
    InputLabel,
    MenuItem,
    Paper,
    Select,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    TextField,
    Tooltip,
    Typography
} from '@mui/material';
import React, { useState } from 'react';
import { SetupChecklistIndicator } from '../../../../components/Common/SetupChecklistIndicator';
import { AxisCalibrationWizard } from '../../../../components/wizards/axis/AxisCalibrationWizard';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { AxisConfig } from '../../../../data/Machine/AxisConfig';
import { AxisType } from '../../../../data/Machine/AxisType';
import { MachineData } from '../../../../data/Machine/MachineData';
import { StepFrequency, getStepFrequencyLabel } from '../../../../data/Machine/StepFrequency';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';

interface AdvancedSettingsDialogProps {
    open: boolean;
    onClose: () => void;
    axisConfig: AxisConfig | null;
}

function AdvancedSettingsDialog({ open, onClose, axisConfig }: AdvancedSettingsDialogProps): React.ReactElement {
    if (!axisConfig) return <></>;

    return (
        <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
            <DialogTitle>Advanced Settings - Axis {axisConfig.axisNumber}</DialogTitle>
            <DialogContent>
                <ObserveState
                    key={`axis-advanced-${axisConfig.axisNumber}`}
                    listenTo={axisConfig}
                    properties={[
                        'stepSignalInverted',
                        'directionSignalInverted',
                        'enableSignalInverted'
                    ]}
                    control={() => (
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, pt: 2 }}>
                            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                Speed settings have been moved to Configuration Settings → Feed Rate Speeds section.
                            </Typography>

                            <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1 }}>
                                Signal Inversions
                            </Typography>

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={axisConfig.stepSignalInverted}
                                        onChange={(e) => (axisConfig.stepSignalInverted = e.target.checked)}
                                    />
                                }
                                label="Step Signal Inverted"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={axisConfig.directionSignalInverted}
                                        onChange={(e) => (axisConfig.directionSignalInverted = e.target.checked)}
                                    />
                                }
                                label="Direction Signal Inverted"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={axisConfig.enableSignalInverted}
                                        onChange={(e) => (axisConfig.enableSignalInverted = e.target.checked)}
                                    />
                                }
                                label="Enable Signal Inverted"
                            />
                        </Box>
                    )}
                />
            </DialogContent>
            <DialogActions>
                <Button onClick={onClose}>Close</Button>
            </DialogActions>
        </Dialog>
    );
}

/**
 * Axis Setup Tab - Axis configuration settings
 */
export function AxisSetupTab(): React.ReactElement {
    const [advancedDialogOpen, setAdvancedDialogOpen] = useState(false);
    const [selectedAxis, setSelectedAxis] = useState<AxisConfig | null>(null);
    const machineData = MachineData.Instance;
    const config = ConfigurationData.Instance;
    const colors = ConfigurationDataColors.Instance;

    const handleAdvancedClick = (axisConfig: AxisConfig) => {
        setSelectedAxis(axisConfig);
        setAdvancedDialogOpen(true);
    };

    const handleCalibrateAxis = (axisType: AxisType) => {
        AxisCalibrationWizard.show(axisType);
    };

    return (
        <Box sx={{ p: 3 }}>
            <Box sx={{ mb: 3 }}>
                <Typography variant="h5" gutterBottom>
                    Axis Configuration
                </Typography>
                <Typography variant="body2" color="text.secondary">
                    Configure the 6 machine axes. Click the settings icon for advanced options.
                </Typography>
            </Box>

            {/* Axis Checklist Indicators */}
            <Grid container spacing={3} sx={{ mb: 3 }}>
                <Grid item xs={12}>
                    <SetupChecklistIndicator name="Axis Configuration" />
                </Grid>
                <Grid item xs={12}>
                    <SetupChecklistIndicator name="Axis Calibration" />
                </Grid>
            </Grid>

            <Paper sx={{ p: 3, mb: 3 }}>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                    Settings that apply to all axes.
                </Typography>
                <ObserveState
                    key="axis-global-settings"
                    listenTo={machineData}
                    properties={['stepFrequency', 'driveFaultDelay']}
                    control={() => (
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                            <Box sx={{ display: 'flex', gap: 3 }}>
                                <FormControl sx={{ flex: 1 }}>
                                    <InputLabel id="step-frequency-label">Step Frequency</InputLabel>
                                    <Select
                                        labelId="step-frequency-label"
                                        label="Step Frequency"
                                        value={machineData.stepFrequency}
                                        onChange={(e) => (machineData.stepFrequency = e.target.value as StepFrequency)}
                                    >
                                        {Object.values(StepFrequency)
                                            .filter((v) => typeof v === 'number')
                                            .map((freq) => (
                                                <MenuItem key={freq} value={freq}>
                                                    {getStepFrequencyLabel(freq as StepFrequency)}
                                                </MenuItem>
                                            ))}
                                    </Select>
                                </FormControl>

                                <TextField
                                    label="Drive Fault Delay"
                                    type="number"
                                    value={machineData.driveFaultDelay}
                                    onChange={(e) => (machineData.driveFaultDelay = parseInt(e.target.value))}
                                    sx={{ flex: 1 }}
                                    helperText="Delay in milliseconds before drive fault is triggered"
                                    inputProps={{ min: 0, step: 10 }}
                                />
                            </Box>
                        </Box>
                    )}
                />
            </Paper>

            <ObserveState
                key="axis-setup-table"
                listenTo={machineData}
                properties={['axisConfigurations']}
                control={() => (
                    <TableContainer component={Paper}>
                        <Table size="small">
                            <TableHead>
                                <TableRow sx={{ backgroundColor: colors.primaryColor }}>
                                    <TableCell sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>Axis #</TableCell>
                                    <TableCell sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>Type</TableCell>
                                    <TableCell sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>Steps/Rev</TableCell>
                                    <TableCell sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>Turns Ratio</TableCell>
                                    <TableCell sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>Lash Comp</TableCell>
                                    <TableCell sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>Accel/Decel</TableCell>
                                    <TableCell sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>Reversed</TableCell>
                                    <TableCell sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>Advanced</TableCell>
                                    <TableCell sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>Calibrate</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {machineData.axisConfigurations.map((axisConfig) => {
                                    // Check if this axis should show configuration fields
                                    const isConfigurable = axisConfig.axisType !== AxisType.Unset &&
                                        axisConfig.axisType !== AxisType.XSlave &&
                                        axisConfig.axisType !== AxisType.YSlave;

                                    return (
                                        <TableRow key={axisConfig.axisNumber}>
                                            <TableCell>{axisConfig.axisNumber}</TableCell>
                                            <TableCell>
                                                <ObserveState
                                                    key={`axis-type-${axisConfig.axisNumber}`}
                                                    listenTo={axisConfig}
                                                    properties={['axisType']}
                                                    control={() => {
                                                        // Get list of axis types already in use by other axes
                                                        const usedTypes = machineData.axisConfigurations
                                                            .filter(ac => ac.axisNumber !== axisConfig.axisNumber)
                                                            .map(ac => ac.axisType);

                                                        return (
                                                            <FormControl size="small" fullWidth>
                                                                <Select
                                                                    value={axisConfig.axisType}
                                                                    onChange={(e) => (axisConfig.axisType = e.target.value as AxisType)}
                                                                >
                                                                    {Object.values(AxisType).map((type) => {
                                                                        const isUsed = usedTypes.includes(type);
                                                                        const isCurrentSelection = axisConfig.axisType === type;
                                                                        // Show if: it's Unset, it's the current selection, or it's not used
                                                                        if (type === AxisType.Unset || isCurrentSelection || !isUsed) {
                                                                            return (
                                                                                <MenuItem key={type} value={type}>
                                                                                    {type}
                                                                                </MenuItem>
                                                                            );
                                                                        }
                                                                        return null;
                                                                    })}
                                                                </Select>
                                                            </FormControl>
                                                        );
                                                    }}
                                                />
                                            </TableCell>
                                            {!isConfigurable ? (
                                                <>
                                                    <TableCell colSpan={4} sx={{ textAlign: 'center', fontStyle: 'italic', color: 'text.secondary' }}>
                                                        Configuration not available for this axis type
                                                    </TableCell>
                                                    {/* Slave axes still need direction reversal */}
                                                    <TableCell>
                                                        <ObserveState
                                                            key={`axis-reversed-${axisConfig.axisNumber}`}
                                                            listenTo={axisConfig}
                                                            properties={['directionReversal']}
                                                            control={() => (
                                                                <Checkbox
                                                                    checked={axisConfig.directionReversal}
                                                                    onChange={(e) => (axisConfig.directionReversal = e.target.checked)}
                                                                />
                                                            )}
                                                        />
                                                    </TableCell>
                                                    <TableCell />
                                                    <TableCell />
                                                </>
                                            ) : (
                                                <>
                                                    <TableCell>
                                                        <ObserveState
                                                            key={`axis-steps-${axisConfig.axisNumber}`}
                                                            listenTo={axisConfig}
                                                            properties={['stepsPerRevolution']}
                                                            control={() => (
                                                                <TextField
                                                                    type="number"
                                                                    value={axisConfig.stepsPerRevolution}
                                                                    onChange={(e) => (axisConfig.stepsPerRevolution = parseInt(e.target.value))}
                                                                    size="small"
                                                                    sx={{ width: 100 }}
                                                                />
                                                            )}
                                                        />
                                                    </TableCell>
                                                    <TableCell>
                                                        <ObserveState
                                                            key={`axis-turns-${axisConfig.axisNumber}`}
                                                            listenTo={axisConfig}
                                                            properties={['overallTurnsRatio']}
                                                            control={() => (
                                                                <TextField
                                                                    type="number"
                                                                    value={axisConfig.overallTurnsRatio}
                                                                    onChange={(e) => (axisConfig.overallTurnsRatio = parseFloat(e.target.value))}
                                                                    size="small"
                                                                    sx={{ width: 100 }}
                                                                />
                                                            )}
                                                        />
                                                    </TableCell>
                                                    <TableCell>
                                                        <ObserveState
                                                            key={`axis-lash-${axisConfig.axisNumber}`}
                                                            listenTo={axisConfig}
                                                            properties={['lashCompensation']}
                                                            control={() => (
                                                                <TextField
                                                                    type="number"
                                                                    value={axisConfig.lashCompensation}
                                                                    onChange={(e) => (axisConfig.lashCompensation = parseFloat(e.target.value))}
                                                                    size="small"
                                                                    sx={{ width: 100 }}
                                                                />
                                                            )}
                                                        />
                                                    </TableCell>
                                                    <TableCell>
                                                        <ObserveState
                                                            key={`axis-accel-${axisConfig.axisNumber}`}
                                                            listenTo={axisConfig}
                                                            properties={['accelDecel']}
                                                            control={() => (
                                                                <TextField
                                                                    type="number"
                                                                    value={axisConfig.accelDecel}
                                                                    onChange={(e) => (axisConfig.accelDecel = parseFloat(e.target.value))}
                                                                    size="small"
                                                                    sx={{ width: 100 }}
                                                                />
                                                            )}
                                                        />
                                                    </TableCell>
                                                    <TableCell>
                                                        <ObserveState
                                                            key={`axis-reversed-${axisConfig.axisNumber}`}
                                                            listenTo={axisConfig}
                                                            properties={['directionReversal']}
                                                            control={() => (
                                                                <Checkbox
                                                                    checked={axisConfig.directionReversal}
                                                                    onChange={(e) => (axisConfig.directionReversal = e.target.checked)}
                                                                />
                                                            )}
                                                        />
                                                    </TableCell>
                                                    <TableCell>
                                                        <Tooltip title="Advanced Settings">
                                                            <IconButton
                                                                size="small"
                                                                onClick={() => handleAdvancedClick(axisConfig)}
                                                            >
                                                                <SettingsIcon fontSize="small" />
                                                            </IconButton>
                                                        </Tooltip>
                                                    </TableCell>
                                                    <TableCell>
                                                        {/* Only show calibrate button for X, Y, Z axes */}
                                                        {(axisConfig.axisType === AxisType.X ||
                                                            axisConfig.axisType === AxisType.Y ||
                                                            axisConfig.axisType === AxisType.Z) && (
                                                                <Tooltip title={`Calibrate ${axisConfig.axisType} Axis`}>
                                                                    <Button
                                                                        size="small"
                                                                        variant="outlined"
                                                                        startIcon={<TuneIcon />}
                                                                        onClick={() => handleCalibrateAxis(axisConfig.axisType)}
                                                                        sx={{
                                                                            fontSize: '0.75rem',
                                                                            py: 0.5,
                                                                            px: 1,
                                                                            minWidth: 'auto'
                                                                        }}
                                                                    >
                                                                        Calibrate
                                                                    </Button>
                                                                </Tooltip>
                                                            )}
                                                    </TableCell>
                                                </>
                                            )}
                                        </TableRow>
                                    );
                                })}
                            </TableBody>
                        </Table>
                    </TableContainer>
                )}
            />

            <AdvancedSettingsDialog
                open={advancedDialogOpen}
                onClose={() => setAdvancedDialogOpen(false)}
                axisConfig={selectedAxis}
            />
        </Box>
    );
}
