import { IStorable } from '../../common/IStorable';
import { PWMConfiguration } from '../../services/src/models/PWMConfiguration';
import { StateManager } from '../../utils/statemanager';
import { DataUtilities } from '../../utils/storage/DataUtilities';

/**
 * Laser PWM configuration class
 * Wraps PWM configuration for local state management and persistence
 * Maps to/from API PWMConfiguration interface
 * All values are nullable - null means not set/not configured
 */
export class LaserPWMConfig implements IStorable {
    // PWM output assignment
    private _outputNumber: number | null = null;

    // PWM basic parameters
    private _pwmEnabled: boolean | null = false;
    private _frequency: number | null = 1000; // Hz - default 1000Hz
    private _sCommandRange1000: boolean | null = true; // true = 0-1000, false = 0-100

    // Power management
    private _floor: number | null = 10; // Minimum power percentage
    private _onlyApplyFloorDuringVelocityMoves: boolean | null = false;

    // Output control
    private _inverseOutput: boolean | null = false;
    private _laserCoolingFanDelayTimer: number | null = 0; // Seconds

    // Advanced (not shown in basic UI)
    private _velocityScaling: number | null = null;

    // Getters and setters with StateManager integration
    public get outputNumber(): number | null {
        return this._outputNumber;
    }
    public set outputNumber(value: number | null) {
        this._outputNumber = value;
        StateManager.propertyChanged(this, 'outputNumber');
    }

    public get pwmEnabled(): boolean | null {
        return this._pwmEnabled;
    }
    public set pwmEnabled(value: boolean | null) {
        this._pwmEnabled = value;
        StateManager.propertyChanged(this, 'pwmEnabled');
    }

    public get frequency(): number | null {
        return this._frequency;
    }
    public set frequency(value: number | null) {
        this._frequency = value;
        StateManager.propertyChanged(this, 'frequency');
    }

    public get sCommandRange1000(): boolean | null {
        return this._sCommandRange1000;
    }
    public set sCommandRange1000(value: boolean | null) {
        this._sCommandRange1000 = value;
        StateManager.propertyChanged(this, 'sCommandRange1000');
    }

    public get floor(): number | null {
        return this._floor;
    }
    public set floor(value: number | null) {
        this._floor = value;
        StateManager.propertyChanged(this, 'floor');
    }

    public get onlyApplyFloorDuringVelocityMoves(): boolean | null {
        return this._onlyApplyFloorDuringVelocityMoves;
    }
    public set onlyApplyFloorDuringVelocityMoves(value: boolean | null) {
        this._onlyApplyFloorDuringVelocityMoves = value;
        StateManager.propertyChanged(this, 'onlyApplyFloorDuringVelocityMoves');
    }

    public get inverseOutput(): boolean | null {
        return this._inverseOutput;
    }
    public set inverseOutput(value: boolean | null) {
        this._inverseOutput = value;
        StateManager.propertyChanged(this, 'inverseOutput');
    }

    public get laserCoolingFanDelayTimer(): number | null {
        return this._laserCoolingFanDelayTimer;
    }
    public set laserCoolingFanDelayTimer(value: number | null) {
        this._laserCoolingFanDelayTimer = value;
        StateManager.propertyChanged(this, 'laserCoolingFanDelayTimer');
    }

    public get velocityScaling(): number | null {
        return this._velocityScaling;
    }
    public set velocityScaling(value: number | null) {
        this._velocityScaling = value;
        StateManager.propertyChanged(this, 'velocityScaling');
    }

    /**
     * Convert to API PWMConfiguration interface
     */
    public toAPIConfiguration(): PWMConfiguration {
        return {
            outputNumber: this._outputNumber ?? undefined,
            frequency: this._frequency,
            sCommandRange1000: this._sCommandRange1000,
            floor: this._floor,
            onlyApplyFloorDuringVelocityMoves: this._onlyApplyFloorDuringVelocityMoves,
            inverseOutput: this._inverseOutput,
            laserCoolingFanDelayTimer: this._laserCoolingFanDelayTimer,
            velocityScaling: this._velocityScaling
        };
    }

    /**
     * Load from API PWMConfiguration interface
     */
    public fromAPIConfiguration(config: PWMConfiguration): void {
        this._outputNumber = config.outputNumber ?? null;
        this._frequency = config.frequency ?? 1000;
        this._sCommandRange1000 = config.sCommandRange1000 ?? true;
        this._floor = config.floor ?? 0;
        this._onlyApplyFloorDuringVelocityMoves = config.onlyApplyFloorDuringVelocityMoves ?? false;
        this._inverseOutput = config.inverseOutput ?? false;
        this._laserCoolingFanDelayTimer = config.laserCoolingFanDelayTimer ?? 0;
        this._velocityScaling = config.velocityScaling ?? null;

        // Notify all properties changed
        StateManager.propertyChanged(this, 'outputNumber');
        StateManager.propertyChanged(this, 'frequency');
        StateManager.propertyChanged(this, 'sCommandRange1000');
        StateManager.propertyChanged(this, 'floor');
        StateManager.propertyChanged(this, 'onlyApplyFloorDuringVelocityMoves');
        StateManager.propertyChanged(this, 'inverseOutput');
        StateManager.propertyChanged(this, 'laserCoolingFanDelayTimer');
        StateManager.propertyChanged(this, 'velocityScaling');
    }

    // IStorable implementation for local persistence
    public toJSON(): object {
        return DataUtilities.getStorageData(this);
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}
