import { Category as MaterialIcon } from '@mui/icons-material';
import { Box, Typography } from '@mui/material';
import React from 'react';
import { MaterialEditor } from '../../components/Views/MaterialEditor';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineStateData } from '../../data/MachineStateData';
import { ModalManager } from '../ModalManager';
import { IUserAction } from './IUserAction';

export class EditMaterialUserAction implements IUserAction {
    public readonly id = 'home_page_edit_material';
    public readonly category = 'Machine Actions';

    public isAvailable(): boolean {
        const config = ConfigurationState.Instance;
        return config.isHomed && !config.isJobRunning;
    }

    public renderButton(asLink: boolean): React.ReactNode {
        if (asLink) {
            return (
                <React.Fragment>
                    <MaterialIcon sx={{ fontSize: 18, color: 'primary.main' }} />
                    <Typography variant="body2" sx={{ color: 'inherit', fontWeight: 500 }}>
                        Edit Material
                    </Typography>
                </React.Fragment>
            );
        } else {
            return (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <MaterialIcon />
                    <Typography>Edit Material</Typography>
                </Box>
            );
        }
    }

    public run(): void {
        const modalId = 'material-editor-dialog';
        const machineState = MachineStateData.Instance;
        ModalManager.Instance.showModal({
            id: modalId,
            render: () => (
                <MaterialEditor
                    open
                    onClose={() => ModalManager.Instance.closeModal(modalId)}
                    machineState={machineState}
                />
            )
        });
    }
}
