import React from 'react';
import { IStorable } from '../../../common/IStorable';
import { DataElement } from '../data/DataElement';
import { DataElementButton } from '../data/DataElementButton';
import { Declaration } from '../data/Declaration';
import { IPLCElement, PLCRenderMode } from '../data/IPLCElement';
import { IPLCSource, PLCProgramType, PLCUtilities } from '../data/PLCUtilities';

/**
 * Type of script piece
 */
export enum ScriptPieceType {
    Text = 'Text',
    NewLine = 'NewLine',
    DataElement = 'DataElement'
}

/**
 * Base class for script pieces
 * Script pieces can be text, newlines, or data element references
 */
export abstract class ScriptPiece implements IStorable {
    private _id: string;
    private _type: ScriptPieceType;

    constructor(type: ScriptPieceType) {
        this._id = `piece_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
        this._type = type;
    }

    public get id(): string {
        return this._id;
    }

    public get type(): ScriptPieceType {
        return this._type;
    }

    /**
     * Get the text representation of this piece
     */
    public abstract getText(): string;

    /**
     * Render this piece as a React node
     * @param mode Rendering mode (Edit, ReadOnly, or Disabled)
     * @param targetProgramType The program type context for rendering
     */
    public abstract render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode;

    /**
     * Clone this piece
     */
    public abstract clone(): ScriptPiece;

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        return {
            id: this._id,
            type: this._type
        };
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        if (data.id !== undefined) this._id = data.id;
        if (data.type !== undefined) this._type = data.type;
    }

    /**
     * Factory method to create a script piece from JSON data
     */
    public static fromJSONFactory(data: any): ScriptPiece | undefined {
        if (!data || !data.type) return undefined;

        switch (data.type as ScriptPieceType) {
            case ScriptPieceType.Text:
                const textPiece = new TextPiece('');
                textPiece.fromJSON(data);
                return textPiece;
            case ScriptPieceType.NewLine:
                const newLinePiece = new NewLinePiece();
                newLinePiece.fromJSON(data);
                return newLinePiece;
            case ScriptPieceType.DataElement:
                const dataElementPiece = new DataElementPiece();
                dataElementPiece.fromJSON(data);
                return dataElementPiece;
            default:
                return undefined;
        }
    }
}

/**
 * Text piece - represents plain text content
 */
export class TextPiece extends ScriptPiece {
    private _text: string;

    constructor(text: string = '') {
        super(ScriptPieceType.Text);
        this._text = text;
    }

    public get text(): string {
        return this._text;
    }

    public set text(value: string) {
        this._text = value;
    }

    public getText(): string {
        return this._text;
    }

    public isDisabled(mode: PLCRenderMode, targetProgramType: PLCProgramType): boolean {
        return false;  // Text pieces are never disabled
    }

    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        return <span>{this._text}</span>;
    }

    public clone(): TextPiece {
        const cloned = new TextPiece(this._text);
        return cloned;
    }

    public toJSON(): object {
        return {
            ...super.toJSON(),
            text: this._text
        };
    }

    public fromJSON(data: any): void {
        super.fromJSON(data);
        if (data.text !== undefined) this._text = data.text;
    }
}

/**
 * New line piece - represents a line break
 */
export class NewLinePiece extends ScriptPiece {
    constructor() {
        super(ScriptPieceType.NewLine);
    }

    public getText(): string {
        return '\n';
    }

    public isDisabled(mode: PLCRenderMode, targetProgramType: PLCProgramType): boolean {
        return false;  // New line pieces are never disabled
    }

    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        return <br />;
    }

    public clone(): NewLinePiece {
        return new NewLinePiece();
    }

    public toJSON(): object {
        return super.toJSON();
    }

    public fromJSON(data: any): void {
        super.fromJSON(data);
    }
}

/**
 * Data element piece - represents a reference to a data element/declaration
 * Implements IPLCElement for proper parent chain management
 */
export class DataElementPiece extends ScriptPiece implements IPLCElement {
    private _dataElement: DataElement;
    private _parentElement?: IPLCElement;
    private _plcSource?: IPLCSource;

    constructor() {
        super(ScriptPieceType.DataElement);
        this._dataElement = new DataElement();
        // Set this DataElementPiece as the parent of the DataElement
        this._dataElement.setParentElement(this);

        // Set up cache invalidation listener
        PLCUtilities.setupCacheInvalidationListener(this);
    }

    public get plcSource(): IPLCSource | undefined {
        const resolved = PLCUtilities.resolvePLCSource(this, false);
        return resolved !== null ? resolved : undefined;
    }

    public get dataElement(): DataElement {
        return this._dataElement;
    }

    public set declaration(value: Declaration | undefined) {
        this._dataElement.declaration = value;
        // Don't set declarationName when setting declaration object
        // DataElement.toJSON only serializes declaration if declarationName is NOT set
        // this prevents duplicate serialization
    }

    public get declaration(): Declaration | undefined {
        return this._dataElement.declaration;
    }

    public get declarationName(): string {
        // Use effectiveName which returns declaration.name if declaration exists,
        // or declarationName if it's a reference
        return this._dataElement.effectiveName || '';
    }

    public set declarationName(value: string) {
        this._dataElement.declarationName = value;
    }

    /**
     * IPLCElement implementation
     */
    public getElementType(): 'other' {
        return 'other';
    }

    public preRenderReset(): void {
        // Default: no-op
        this._dataElement.preRenderReset();
    }

    public getElementId(): string {
        return this.id;
    }

    public getParentElement(): IPLCElement | undefined {
        return this._parentElement;
    }

    public setParentElement(parent: IPLCElement | undefined): void {
        this._parentElement = parent;
        // Clear cached plcSource - will be resolved on next access
        this._plcSource = undefined;
    }

    public getUsedDeclarations(): Declaration[] {
        // Delegate to DataElement's getUsedDeclarations which does proper runtime lookup
        return this._dataElement.getUsedDeclarations();
    }

    public getAddedDeclarations(): Declaration[] {
        return [];
    }

    public getPLCLogic(availableDeclarations: string[]): string[] {
        return [];
    }

    public getDataElements(): any[] {
        return [this._dataElement];
    }

    public getValidationIssues(): any[] {
        return [];
    }

    public shouldOutput(outputType: any, availableDeclarations?: string[]): any {
        return 'output'; // OutputState.Output
    }

    public getText(): string {
        return this._dataElement.effectiveName || '[pick variable]';
    }

    public isDisabled(mode: PLCRenderMode, targetProgramType: PLCProgramType): boolean {
        return this._dataElement.isDisabled(mode, targetProgramType);
    }

    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        return (
            <span style={{ display: 'inline-block', margin: '0 2px' }}>
                <DataElementButton
                    dataElement={this._dataElement}
                    renderMode={mode}
                />
            </span>
        );
    }

    public clone(): DataElementPiece {
        const cloned = new DataElementPiece();
        cloned._dataElement.declarationName = this._dataElement.declarationName;
        cloned._dataElement.declaration = this._dataElement.declaration;
        cloned.setParentElement(this._parentElement);
        return cloned;
    }

    public toJSON(): object {
        return {
            ...super.toJSON(),
            dataElement: this._dataElement.toJSON()
        };
    }

    public fromJSON(data: any): void {
        super.fromJSON(data);
        // Support both new format (dataElement) and old format (declarationName) for backward compatibility
        if (data.dataElement) {
            this._dataElement.fromJSON(data.dataElement);
            // Restore parent chain
            this._dataElement.setParentElement(this);
        } else if (data.declarationName !== undefined) {
            // Backward compatibility: old format only stored declarationName
            this._dataElement.declarationName = data.declarationName;
        }
    }
}
