import CloseIcon from '@mui/icons-material/Close';
import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    Paper,
    Typography
} from '@mui/material';
import React from 'react';
import { LogicStatement } from '../../centroid/plc/statements/LogicStatement';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { StateManager } from '../../utils/statemanager/StateManager';

interface LogicStructureDialogProps {
    open: boolean;
    onClose: () => void;
    statement: LogicStatement;
}

export function LogicStructureDialog({ open, onClose, statement }: LogicStructureDialogProps) {
    const colors = ConfigurationDataColors.Instance;

    // Local state for all toggles
    const [hasElse, setHasElse] = React.useState(statement.hasElse);
    const [hasNestedIf, setHasNestedIf] = React.useState(statement.hasNestedIf);
    const [hasNestedIfElse, setHasNestedIfElse] = React.useState(statement.hasNestedIfElse);
    const [hasNestedElse, setHasNestedElse] = React.useState(statement.hasNestedElse);
    const [hasNestedElseElse, setHasNestedElseElse] = React.useState(statement.hasNestedElseElse);
    const [hideSimpleActions, setHideSimpleActions] = React.useState(statement.hideSimpleActions);
    const [hideElseActions, setHideElseActions] = React.useState(statement.hideElseActions);

    const handleApply = () => {
        // Update statement with all configuration
        statement.hasElse = hasElse;
        statement.hasNestedIf = hasNestedIf;
        statement.hasNestedIfElse = hasNestedIfElse;
        statement.hasNestedElse = hasNestedElse;
        statement.hasNestedElseElse = hasNestedElseElse;
        statement.hideSimpleActions = hideSimpleActions;
        statement.hideElseActions = hideElseActions;

        // Notify state manager of changes
        StateManager.propertyChanged(statement, 'hasElse');
        StateManager.propertyChanged(statement, 'hasNestedIf');
        StateManager.propertyChanged(statement, 'hasNestedIfElse');
        StateManager.propertyChanged(statement, 'hasNestedElse');
        StateManager.propertyChanged(statement, 'hasNestedElseElse');
        StateManager.propertyChanged(statement, 'hideSimpleActions');
        StateManager.propertyChanged(statement, 'hideElseActions');

        onClose();
    };

    const handleCancel = () => {
        // Reset to original values
        setHasElse(statement.hasElse);
        setHasNestedIf(statement.hasNestedIf);
        setHasNestedIfElse(statement.hasNestedIfElse);
        setHasNestedElse(statement.hasNestedElse);
        setHasNestedElseElse(statement.hasNestedElseElse);
        setHideSimpleActions(statement.hideSimpleActions);
        setHideElseActions(statement.hideElseActions);
        onClose();
    };

    // Render pseudo-code structure with clickable links for configuration
    const renderPseudoCode = () => {
        const enabledStyle = {
            color: colors.darkTextColor,
            fontWeight: 'bold',
            fontFamily: 'monospace',
            fontSize: '14px',
            padding: '4px 8px',
            backgroundColor: colors.primaryColor + '20',
            borderRadius: '4px',
            marginBottom: '4px',
            display: 'flex',
            alignItems: 'center',
            gap: 1
        };

        const disabledStyle = {
            color: colors.mutedTextColor,
            fontWeight: 'normal',
            fontFamily: 'monospace',
            fontSize: '14px',
            padding: '4px 8px',
            marginBottom: '4px',
            display: 'flex',
            alignItems: 'center',
            gap: 1
        };

        const strikethrough = {
            textDecoration: 'line-through'
        };

        const linkStyle = {
            color: colors.primaryColor,
            textDecoration: 'none !important',
            cursor: 'pointer',
            fontSize: '11px',
            fontFamily: 'sans-serif',
            fontWeight: 'bold',
            border: `1px solid ${colors.primaryColor}`,
            padding: '2px 6px',
            borderRadius: '3px',
            backgroundColor: colors.lightOverlay,
            '&:hover': {
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor
            }
        };

        return (
            <Paper sx={{
                p: 2,
                backgroundColor: colors.lightBackgroundColor,
                border: `1px solid ${colors.borderColor}`,
                fontFamily: 'monospace'
            }}>
                <Box sx={enabledStyle}>
                    <span>IF (condition)</span>
                </Box>

                {/* Simple THEN Actions */}
                <Box sx={{ ...(!hideSimpleActions ? enabledStyle : disabledStyle), ml: 2 }}>
                    <span style={hideSimpleActions ? strikethrough : undefined}>THEN [actions]</span>
                    {hasNestedIf && (
                        <Typography
                            component="span"
                            onClick={() => setHideSimpleActions(!hideSimpleActions)}
                            sx={linkStyle}
                        >
                            [{hideSimpleActions ? 'show' : 'hide'}]
                        </Typography>
                    )}
                </Box>

                {/* Nested IF */}
                <Box sx={{ ...(hasNestedIf ? enabledStyle : disabledStyle), ml: 2 }}>
                    <span style={!hasNestedIf ? strikethrough : undefined}>IF (nested-condition)</span>
                    <Typography
                        component="span"
                        onClick={() => {
                            setHasNestedIf(!hasNestedIf);
                            if (hasNestedIf) {
                                setHasNestedIfElse(false);
                                setHideSimpleActions(false);
                            }
                        }}
                        sx={linkStyle}
                    >
                        [{hasNestedIf ? 'hide' : 'show'}]
                    </Typography>
                </Box>

                <Box sx={{ ...(hasNestedIf ? enabledStyle : disabledStyle), ml: 4 }}>
                    <span style={!hasNestedIf ? strikethrough : undefined}>THEN [nested-actions]</span>
                </Box>

                {/* Nested IF ELSE */}
                <Box sx={{ ...(hasNestedIf && hasNestedIfElse ? enabledStyle : disabledStyle), ml: 2 }}>
                    <span style={!(hasNestedIf && hasNestedIfElse) ? strikethrough : undefined}>ELSE [nested-else-actions]</span>
                    {hasNestedIf && (
                        <Typography
                            component="span"
                            onClick={() => setHasNestedIfElse(!hasNestedIfElse)}
                            sx={linkStyle}
                        >
                            [{hasNestedIfElse ? 'hide' : 'show'}]
                        </Typography>
                    )}
                </Box>

                {/* Main ELSE */}
                <Box sx={{ ...(hasElse ? enabledStyle : disabledStyle), mt: 1 }}>
                    <span style={!hasElse ? strikethrough : undefined}>ELSE</span>
                    <Typography
                        component="span"
                        onClick={() => {
                            setHasElse(!hasElse);
                            if (hasElse) {
                                setHasNestedElse(false);
                                setHasNestedElseElse(false);
                                setHideElseActions(false);
                            }
                        }}
                        sx={linkStyle}
                    >
                        [{hasElse ? 'hide' : 'show'}]
                    </Typography>
                </Box>

                {/* Simple ELSE Actions */}
                {hasElse && (
                    <Box sx={{ ...(!hideElseActions ? enabledStyle : disabledStyle), ml: 2 }}>
                        <span style={hideElseActions ? strikethrough : undefined}>[else-actions]</span>
                        {hasNestedElse && (
                            <Typography
                                component="span"
                                onClick={() => setHideElseActions(!hideElseActions)}
                                sx={linkStyle}
                            >
                                [{hideElseActions ? 'show' : 'hide'}]
                            </Typography>
                        )}
                    </Box>
                )}

                {/* Nested ELSE IF */}
                {hasElse && (
                    <Box sx={{ ...(hasNestedElse ? enabledStyle : disabledStyle), ml: 2 }}>
                        <span style={!hasNestedElse ? strikethrough : undefined}>IF (nested-else-condition)</span>
                        <Typography
                            component="span"
                            onClick={() => {
                                setHasNestedElse(!hasNestedElse);
                                if (hasNestedElse) {
                                    setHasNestedElseElse(false);
                                    setHideElseActions(false);
                                }
                            }}
                            sx={linkStyle}
                        >
                            [{hasNestedElse ? 'hide' : 'show'}]
                        </Typography>
                    </Box>
                )}

                {hasElse && hasNestedElse && (
                    <Box sx={{ ...enabledStyle, ml: 4 }}>
                        <span>THEN [nested-else-actions]</span>
                    </Box>
                )}

                {/* Nested ELSE ELSE */}
                {hasElse && (
                    <Box sx={{ ...(hasNestedElse && hasNestedElseElse ? enabledStyle : disabledStyle), ml: 2 }}>
                        <span style={!(hasNestedElse && hasNestedElseElse) ? strikethrough : undefined}>ELSE [nested-else-else-actions]</span>
                        {hasNestedElse && (
                            <Typography
                                component="span"
                                onClick={() => setHasNestedElseElse(!hasNestedElseElse)}
                                sx={linkStyle}
                            >
                                [{hasNestedElseElse ? 'hide' : 'show'}]
                            </Typography>
                        )}
                    </Box>
                )}
            </Paper>
        );
    };

    return (
        <Dialog open={open} onClose={handleCancel} maxWidth="md" fullWidth>
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3
            }}>
                Configure IF Statement Structure
                <IconButton
                    onClick={handleCancel}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>

            <DialogContent>
                <Box sx={{ mt: 3 }}>
                    <Typography variant="body1" sx={{ mb: 2, color: colors.darkTextColor }}>
                        Click links in the structure below to configure sections. Links appear only when relevant.
                    </Typography>
                    {renderPseudoCode()}
                </Box>
            </DialogContent>

            <DialogActions sx={{
                p: 2,
                gap: 1,
                justifyContent: 'flex-end',
                borderTop: `1px solid ${colors.borderColor}`
            }}>
                <Button onClick={handleCancel} variant="outlined">
                    Cancel
                </Button>
                <Button onClick={handleApply} variant="contained">
                    Apply
                </Button>
            </DialogActions>
        </Dialog>
    );
}
