import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Spindle Configuration Checklist Item
 * Manually confirmed by the user after verifying spindle settings
 */
export class SpindleConfigurationChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Spindle Configuration',
            'Verify spindle is configured correctly'
        );
    }

    /**
     * This item requires manual confirmation by the user
     */
    public needsManualConfirmation(): boolean {
        return true;
    }

    /**
     * No automated check — always passes; completion requires manual confirm
     */
    public completionCheck(): boolean {
        return true;
    }

    public clone(): SpindleConfigurationChecklistItem {
        const cloned = new SpindleConfigurationChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
