import { CNCPoint } from '../data/CNCPoint';
import { CoordinateType } from '../data/Common/CoordinateType';
import { ConfigurationData } from '../data/ConfigurationData';
import { ConfigurationState } from '../data/ConfigurationState';
import { UserMessageQueue } from '../data/UserMessageQueue';
import { GCodeExecutionCallback } from '../machine/ICNCProgram';
import { CoordinateUtil } from '../utils/CoordinateUtil';
import { LogCategory, Logger } from '../utils/Logger';
import { SignalRManager } from '../utils/SignalRManager';

/**
 * Parsed G-code command with movement information
 */
interface ParsedGCodeCommand {
    lineNumber: number;
    originalLine: string;
    command: string; // G0, G1, G2, G3, M3, M5, etc.
    x?: number;
    y?: number;
    z?: number;
    feedRate?: number; // F parameter
    spindleSpeed?: number; // S parameter
    i?: number; // Arc center offset X (G2/G3)
    j?: number; // Arc center offset Y (G2/G3)
    isRapid?: boolean; // G0 rapid move
    isLinear?: boolean; // G1 linear move
    isArc?: boolean; // G2/G3 arc move
    isSpindleOn?: boolean; // M3/M4
    isSpindleOff?: boolean; // M5
    isError?: boolean; // Detected error in code
    errorMessage?: string;
}

/**
 * G-Code Simulator
 * Simulates basic G-code execution for testing without actual hardware
 */
export class GCodeSimulator {
    private currentFeedRate: number = 100; // inches/minute default
    private currentSpindleSpeed: number = 0;
    private spindleOn: boolean = false;
    private isRunning: boolean = false;
    private shouldStop: boolean = false;
    private isAbsoluteMode: boolean = true; // G90 (absolute) vs G91 (incremental)
    private isMachineCoordinates: boolean = false; // G53 (machine) vs G54 (work with offsets)
    private lastGCommand: string = 'G0'; // Track last movement command for modal operation

    /**
     * Reset execution state to initial values
     * Called at the start of each run to ensure clean state
     */
    private resetExecutionState(): void {
        this.currentFeedRate = 100; // inches/minute default
        this.currentSpindleSpeed = 0;
        this.spindleOn = false;
        this.isAbsoluteMode = true; // G90 default
        this.isMachineCoordinates = false; // G54 default (work coordinates)
        this.lastGCommand = 'G0'; // Reset to rapid positioning
    }

    /**
     * Parse a single line of G-code
     */
    private parseLine(line: string, lineNumber: number): ParsedGCodeCommand | null {
        // Remove N-code line numbers (e.g., "N0001 ", "N100 ")
        const trimmed = line.trim().toUpperCase().replace(/^N\d+\s*/i, '');

        // Skip empty lines and comments
        if (!trimmed || trimmed.startsWith('(') || trimmed.startsWith(';')) {
            return null;
        }

        const command: ParsedGCodeCommand = {
            lineNumber,
            originalLine: line,
            command: '',
        };

        // Extract ALL G/M commands on the line (not just the first)
        const allCommandMatches = trimmed.matchAll(/([GM]\d+)/g);
        const commands: string[] = [];
        for (const match of allCommandMatches) {
            commands.push(match[1]);
        }

        // Determine the primary command (movement or spindle)
        // Priority: G0/G1/G2/G3 (movement) > M3/M4/M5 (spindle) > G90/G91/G53/G54 (modes)
        let movementCommand = commands.find(cmd => ['G0', 'G1', 'G2', 'G3'].includes(cmd));
        let spindleCommand = commands.find(cmd => ['M3', 'M4', 'M5'].includes(cmd));

        // Update lastGCommand if movement command found
        if (movementCommand) {
            this.lastGCommand = movementCommand;
        }

        // Set primary command (movement takes priority, fall back to lastGCommand for modal operation)
        command.command = movementCommand || spindleCommand || commands[0] || this.lastGCommand;

        // Parse coordinates - handle both space-separated and concatenated (e.g., "X1.0" or "X 1.0")
        const xMatch = trimmed.match(/X\s*([-+]?\d*\.?\d+)/);
        const yMatch = trimmed.match(/Y\s*([-+]?\d*\.?\d+)/);
        const zMatch = trimmed.match(/Z\s*([-+]?\d*\.?\d+)/);
        const fMatch = trimmed.match(/F\s*([-+]?\d*\.?\d+)/);
        const sMatch = trimmed.match(/S\s*([-+]?\d*\.?\d+)/);
        const iMatch = trimmed.match(/I\s*([-+]?\d*\.?\d+)/);
        const jMatch = trimmed.match(/J\s*([-+]?\d*\.?\d+)/);

        if (xMatch) command.x = parseFloat(xMatch[1]);
        if (yMatch) command.y = parseFloat(yMatch[1]);
        if (zMatch) command.z = parseFloat(zMatch[1]);
        if (fMatch) command.feedRate = parseFloat(fMatch[1]);
        if (sMatch) command.spindleSpeed = parseFloat(sMatch[1]);
        if (iMatch) command.i = parseFloat(iMatch[1]);
        if (jMatch) command.j = parseFloat(jMatch[1]);

        // Classify movement type
        if (command.command === 'G0') {
            command.isRapid = true;
        } else if (command.command === 'G1') {
            command.isLinear = true;
        } else if (command.command === 'G2' || command.command === 'G3') {
            command.isArc = true;
        }

        // Spindle commands
        if (command.command === 'M3' || command.command === 'M4') {
            command.isSpindleOn = true;
        } else if (command.command === 'M5') {
            command.isSpindleOff = true;
        }

        // Check for common errors
        if (command.isArc && (command.i === undefined && command.j === undefined)) {
            command.isError = true;
            command.errorMessage = 'Arc command (G2/G3) missing I or J parameter';
        }

        return command;
    }

    /**
     * Calculate distance between two 3D points
     */
    private calculateDistance(x1: number, y1: number, z1: number, x2: number, y2: number, z2: number): number {
        const dx = x2 - x1;
        const dy = y2 - y1;
        const dz = z2 - z1;
        return Math.sqrt(dx * dx + dy * dy + dz * dz);
    }

    /**
     * Interpolate position between two points
     * @param start Start position
     * @param end End position
     * @param fraction Interpolation fraction (0 to 1)
     */
    private interpolate(start: number, end: number, fraction: number): number {
        return start + (end - start) * fraction;
    }

    /**
     * Simulate movement from current position to target position
     * Moves in 0.5 second increments
     */
    private async simulateMovement(
        target: CNCPoint,
        feedRate: number,
        isRapid: boolean
    ): Promise<void> {
        const config = ConfigurationData.Instance;

        // Convert target to MachineZero for internal tracking/interpolation
        const targetMachineZero = CoordinateUtil.toMachineZero(target);
        const targetX = targetMachineZero.x;
        const targetY = targetMachineZero.y;
        const targetZ = targetMachineZero.z;

        const startX = ConfigurationState.Instance.currentMachinePoint.x;
        const startY = ConfigurationState.Instance.currentMachinePoint.y;
        const startZ = ConfigurationState.Instance.currentMachinePoint.z;

        // Calculate distance
        const distance = this.calculateDistance(startX, startY, startZ, targetX, targetY, targetZ);

        // Use max speed from configuration for rapid moves, otherwise use feed rate
        const effectiveFeedRate = isRapid ? config.maxSpeedXY : feedRate;

        // Calculate time in minutes
        const timeMinutes = distance / effectiveFeedRate;
        const timeSeconds = timeMinutes * 60;
        const timeMilliseconds = timeSeconds * 1000;

        // For smooth position updates, emit DRO events every 100ms (10 updates per second)
        // But don't create more steps than necessary for short moves
        const updateInterval = 100; // milliseconds between position updates
        const steps = Math.max(1, Math.floor(timeMilliseconds / updateInterval));
        const actualStepTime = timeMilliseconds / steps;

        // Move in increments
        for (let i = 1; i <= steps; i++) {
            if (this.shouldStop) {
                break;
            }

            const fraction = i / steps;

            // Calculate interpolated position
            const newX = this.interpolate(startX, targetX, fraction);
            const newY = this.interpolate(startY, targetY, fraction);
            const newZ = this.interpolate(startZ, targetZ, fraction);

            // Create CNCPoint in MachineZero for DRO event
            const currentPoint = new CNCPoint(newX, newY, newZ, CoordinateType.MachineZero);
            this.emitDROEvent(currentPoint);

            // Wait for calculated step time (unless it's the last step)
            if (i < steps) {
                await new Promise(resolve => setTimeout(resolve, actualStepTime));
            }
        }

        // Ensure final position is exact by emitting final DRO event
        // SignalRPositionUpdater will handle updating currentMachinePoint
        const finalPoint = new CNCPoint(targetX, targetY, targetZ, CoordinateType.MachineZero);
        this.emitDROEvent(finalPoint);
    }

    /**
     * Simulate arc movement (simplified - treats as series of linear moves)
     */
    private async simulateArc(
        target: CNCPoint,
        i: number,
        j: number,
        feedRate: number,
        isClockwise: boolean
    ): Promise<void> {
        // For simplicity, approximate arc with 10 linear segments

        // Convert target to MachineZero for calculations
        const targetMachineZero = CoordinateUtil.toMachineZero(target);
        const targetX = targetMachineZero.x;
        const targetY = targetMachineZero.y;
        const targetZ = targetMachineZero.z;

        const startX = ConfigurationState.Instance.currentMachinePoint.x;
        const startY = ConfigurationState.Instance.currentMachinePoint.y;
        const startZ = ConfigurationState.Instance.currentMachinePoint.z;

        // Calculate arc center
        const centerX = startX + i;
        const centerY = startY + j;

        // Number of segments to approximate the arc
        const segments = 10;

        // Calculate angles
        const startAngle = Math.atan2(startY - centerY, startX - centerX);
        const endAngle = Math.atan2(targetY - centerY, targetX - centerX);

        let totalAngle = endAngle - startAngle;
        if (isClockwise && totalAngle > 0) totalAngle -= 2 * Math.PI;
        if (!isClockwise && totalAngle < 0) totalAngle += 2 * Math.PI;

        const radius = Math.sqrt(i * i + j * j);

        // Move through arc segments
        for (let seg = 1; seg <= segments; seg++) {
            if (this.shouldStop) {
                break;
            }

            const fraction = seg / segments;
            const currentAngle = startAngle + totalAngle * fraction;

            const segX = centerX + radius * Math.cos(currentAngle);
            const segY = centerY + radius * Math.sin(currentAngle);
            const segZ = this.interpolate(startZ, targetZ, fraction);

            const segmentPoint = new CNCPoint(segX, segY, segZ, CoordinateType.MachineZero);
            await this.simulateMovement(segmentPoint, feedRate, false);
        }
    }

    /**
     * Execute a parsed G-code command
     */
    private async executeCommand(command: ParsedGCodeCommand, callback?: GCodeExecutionCallback, jobId?: string): Promise<void> {
        // Check for errors
        if (command.isError) {
            Logger.Instance.logError(LogCategory.System, `G-code error at line ${command.lineNumber}: ${command.errorMessage}`);
            UserMessageQueue.Instance.addMessage(`❌ ${command.errorMessage}`);
            if (callback && jobId) {
                callback.onError(jobId, command.errorMessage || 'Unknown error');
            }
            this.shouldStop = true;
            return;
        }

        // Update feed rate if specified
        if (command.feedRate !== undefined) {
            this.currentFeedRate = command.feedRate;
        }

        // Spindle commands
        if (command.isSpindleOn) {
            this.spindleOn = true;
            if (command.spindleSpeed !== undefined) {
                this.currentSpindleSpeed = command.spindleSpeed;
            }
            const message = `Spindle ON at ${this.currentSpindleSpeed} RPM`;
            UserMessageQueue.Instance.addMessage(`🔄 ${message}`);
            this.emitMessageEvent(message, 0, 'Info');
            await new Promise(resolve => setTimeout(resolve, 500)); // Spindle spin-up delay
        }

        if (command.isSpindleOff) {
            this.spindleOn = false;
            const message = 'Spindle OFF';
            UserMessageQueue.Instance.addMessage(`⏸ ${message}`);
            this.emitMessageEvent(message, 0, 'Info');
            await new Promise(resolve => setTimeout(resolve, 300)); // Spindle spin-down delay
        }

        // Update coordinate modes
        if (command.command === 'G90') {
            this.isAbsoluteMode = true;
        } else if (command.command === 'G91') {
            this.isAbsoluteMode = false;
        }

        // G54 is modal - it sets the coordinate system for all subsequent moves
        if (command.command === 'G54') {
            this.isMachineCoordinates = false;
        }

        // Movement commands
        const hasMovement = command.x !== undefined || command.y !== undefined || command.z !== undefined;

        if (hasMovement) {
            // G53 is NON-MODAL - it only applies to the current line, then reverts
            // Check if G53 is anywhere on THIS command line (not just the primary command)
            const isG53OnThisLine = command.originalLine.toUpperCase().includes('G53');

            // Determine coordinate type: G53 on this line = machine coords, otherwise use modal state
            const coordType = isG53OnThisLine ? CoordinateType.MachineZero :
                (this.isMachineCoordinates ? CoordinateType.MachineZero : CoordinateType.WorkZeroWithOffsets);

            // Get current position in the TARGET coordinate system
            // Always explicitly convert - never assume the point is already in the right system
            const currentInTargetSystem = coordType === CoordinateType.MachineZero
                ? CoordinateUtil.toMachineZero(ConfigurationState.Instance.currentMachinePoint)
                : CoordinateUtil.toWorkZeroWithOffsets(ConfigurationState.Instance.currentMachinePoint);

            // Create target point in the appropriate coordinate system
            // Use current position IN THAT COORDINATE SYSTEM for any unspecified axes
            const targetPoint = new CNCPoint(
                command.x !== undefined ? command.x : currentInTargetSystem.x,
                command.y !== undefined ? command.y : currentInTargetSystem.y,
                command.z !== undefined ? command.z : currentInTargetSystem.z,
                coordType
            );

            if (command.isRapid || command.isLinear) {
                // Linear movement (G0 or G1)
                await this.simulateMovement(
                    targetPoint,
                    this.currentFeedRate,
                    command.isRapid || false
                );
            } else if (command.isArc && command.i !== undefined && command.j !== undefined) {
                // Arc movement (G2 or G3)
                const isClockwise = command.command === 'G2';
                await this.simulateArc(
                    targetPoint,
                    command.i,
                    command.j,
                    this.currentFeedRate,
                    isClockwise
                );
            }
        }
    }

    /**
     * Run G-code simulation
     */
    public async runGCode(
        gcode: string[],
        startImmediately: boolean = true,
        callback?: GCodeExecutionCallback
    ): Promise<void> {
        if (!startImmediately) {
            return; // Just load without executing
        }

        // Reset execution state for fresh run
        this.resetExecutionState();

        this.isRunning = true;
        this.shouldStop = false;
        const jobId = `sim-job-${Date.now()}`;

        try {
            const startTime = Date.now();

            // Emit job started event
            this.emitJobStartedEvent(jobId, gcode);

            // Parse all G-code lines
            const commands: ParsedGCodeCommand[] = [];
            for (let i = 0; i < gcode.length; i++) {
                const parsed = this.parseLine(gcode[i], i);
                if (parsed) {
                    commands.push(parsed);
                }
            }

            // Execute commands
            for (let i = 0; i < commands.length; i++) {
                if (this.shouldStop) {
                    break;
                }

                const command = commands[i];
                const isLastStep = i === commands.length - 1;

                // Emit events and callback BEFORE executing the line
                // so UI shows which line is about to run

                // Emit step execution event
                this.emitStepExecutionEvent(jobId, command.lineNumber + 1, command.originalLine, gcode.length, isLastStep);

                // Emit job info event (shows filename and line number like real system)
                this.emitJobInfoEvent(jobId, command.lineNumber + 1);

                // Callback: line execution (called BEFORE line starts)
                // Send 1-based line number to match backend behavior
                if (callback) {
                    callback.onExecuteLine(jobId, command.lineNumber + 1, command.originalLine, gcode.length, isLastStep);
                }

                // Now execute the command
                await this.executeCommand(command, callback, jobId);

                if (this.shouldStop) {
                    break;
                }
            }

            // Calculate duration
            const endTime = Date.now();
            const durationMs = endTime - startTime;
            const durationSeconds = (durationMs / 1000).toFixed(1);
            const duration = `${durationSeconds}s`;

            // Emit job completed event
            if (this.shouldStop) {
                this.emitJobCompletedEvent(jobId, false, 'Stopped by user', commands.length, duration);
                this.emitMessageEvent('Job stopped by user', 0, 'Warning');
            } else {
                this.emitJobCompletedEvent(jobId, true, undefined, commands.length, duration);
                this.emitMessageEvent(`Job completed successfully in ${duration}`, 0, 'Info');
            }

            // Callback: completion
            if (callback) {
                if (this.shouldStop) {
                    callback.onComplete(jobId, false, 'Stopped by user', commands.length, duration);
                } else {
                    callback.onComplete(jobId, true, undefined, commands.length, duration);
                }
            }

            if (!this.shouldStop) {
                UserMessageQueue.Instance.addMessage(`✓ G-code simulation completed (${commands.length} commands in ${duration})`);
            }

        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'G-code simulation error:', error);
            const errorMessage = error instanceof Error ? error.message : 'Unknown error';

            // Emit error events
            this.emitJobCompletedEvent(jobId, false, errorMessage, 0, '0s');
            this.emitMessageEvent(`Simulation error: ${errorMessage}`, 999, 'Error');

            if (callback) {
                callback.onError(jobId, errorMessage);
                callback.onComplete(jobId, false, errorMessage, 0, '0s');
            }

            UserMessageQueue.Instance.addMessage(`❌ G-code simulation failed: ${errorMessage}`);
        } finally {
            this.isRunning = false;
            this.shouldStop = false;
        }
    }

    /**
     * Stop the current simulation
     */
    public stop(): void {
        this.shouldStop = true;
    }

    /**
     * Check if simulation is running
     */
    public isSimulationRunning(): boolean {
        return this.isRunning;
    }

    /**
     * Emit simulated SignalR events for message display
     */
    private emitJobStartedEvent(jobId: string, gcode: string[]): void {
        const manager = SignalRManager.Instance;
        manager.emitLocalEvent({
            eventType: 'JobStartedEvent',
            timestamp: new Date().toISOString(),
            data: {
                timestamp: new Date().toISOString(),
                messageType: 'JobStartedEvent',
                message: 'Job started in simulator mode',
                jobId,
                gCodeLines: gcode,
                totalLines: gcode.length,
                isStepRunMode: false,
            },
        });
    }

    private emitJobCompletedEvent(jobId: string, success: boolean, errorMessage: string | undefined, linesExecuted: number, duration: string): void {
        const manager = SignalRManager.Instance;
        manager.emitLocalEvent({
            eventType: 'JobCompletedEvent',
            timestamp: new Date().toISOString(),
            data: {
                timestamp: new Date().toISOString(),
                messageType: 'JobCompletedEvent',
                message: success ? 'Job completed successfully' : 'Job failed',
                jobId,
                success,
                errorMessage,
                duration,
                linesExecuted,
            },
        });
    }

    private emitStepExecutionEvent(jobId: string, lineNumber: number, currentLine: string, totalLines: number, isLastStep: boolean): void {
        const manager = SignalRManager.Instance;
        manager.emitLocalEvent({
            eventType: 'StepExecutionEvent',
            timestamp: new Date().toISOString(),
            data: {
                timestamp: new Date().toISOString(),
                messageType: 'StepExecutionEvent',
                message: `Executing line ${lineNumber}`,
                jobId,
                lineNumber,
                currentLine,
                totalLines,
                isLastStep,
                status: 'Executing',
            },
        });
    }

    private emitJobInfoEvent(jobId: string, lineNumber: number): void {
        const manager = SignalRManager.Instance;
        manager.emitLocalEvent({
            eventType: 'JobInfoEvent',
            timestamp: new Date().toISOString(),
            data: {
                timestamp: new Date().toISOString(),
                messageType: 'JobInfoEvent',
                message: `Line ${lineNumber}`,
                lineNumber,
                stackLevel: 0,
                jobName: 'Simulator Job',
            },
        });
    }

    private emitDROEvent(point: CNCPoint): void {
        // DRO events should be in MachineHome coordinates (like the real Centroid backend)
        // Convert the point to MachineHome regardless of its current coordinate type
        const machineHomePoint = CoordinateUtil.toMachineHome(point);

        const manager = SignalRManager.Instance;
        manager.emitLocalEvent({
            eventType: 'DROEvent',
            timestamp: new Date().toISOString(),
            data: {
                timestamp: new Date().toISOString(),
                messageType: 'DROEvent',
                message: `X: ${machineHomePoint.x.toFixed(3)}, Y: ${machineHomePoint.y.toFixed(3)}, Z: ${machineHomePoint.z.toFixed(3)}`,
                axis1: machineHomePoint.x,
                axis2: machineHomePoint.y,
                axis3: machineHomePoint.z,
                axis4: 0,
                axis5: 0,
                axis6: 0,
                axis7: 0,
                axis8: 0,
            },
        });
    }

    private emitMessageEvent(message: string, eventCode: number, severity: 'Info' | 'Warning' | 'Error' = 'Info'): void {
        const manager = SignalRManager.Instance;
        manager.emitLocalEvent({
            eventType: 'MessageEvent',
            timestamp: new Date().toISOString(),
            data: {
                timestamp: new Date().toISOString(),
                messageType: 'MessageEvent',
                message,
                eventCode,
                eventType: severity,
            },
        });
    }
}
