import { Box, Typography } from '@mui/material';
import { useState } from 'react';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineStateData } from '../../data/MachineStateData';
import { CoordinateOperations } from '../../utils/CoordinateOperations';
import { ObserveMultiProperties } from '../../utils/statemanager/ObserveMultiProperties';

export function CoordinatesDisplay() {
    const [colors] = useState(() => ConfigurationDataColors.Instance);

    return (
        <ObserveMultiProperties
            key="coordinates-display-observer"
            listenTo={[
                {
                    object: MachineStateData.Instance,
                    properties: ['currentWorkZero', 'currentToolOffsets', 'currentToolNumber', 'currentFixtureNumber']
                },
                {
                    object: ConfigurationState.Instance,
                    properties: ['isHomed', 'currentMachinePoint']
                }
            ]}
            control={() => {
                const machineState = MachineStateData.Instance;
                const fixtureNumber = machineState.currentFixtureNumber || 'None';
                const isCustom = machineState.isWorkZeroCustom();
                const displayText = isCustom ? 'Custom' : fixtureNumber;
                const isHomed = ConfigurationState.Instance.isHomed;

                // If machine is not homed, show message instead of coordinates
                if (!isHomed) {
                    return (
                        <Box sx={{
                            height: '100%',
                            overflow: 'auto',
                            p: 2,
                            display: 'flex',
                            flexDirection: 'column',
                            alignItems: 'center',
                            justifyContent: 'center',
                            textAlign: 'center'
                        }}>
                            <Typography variant="h6" sx={{ mb: 2, fontWeight: 'bold' }}>
                                Coordinates
                            </Typography>
                            <Box sx={{
                                p: 3,
                                borderRadius: 1,
                                backgroundColor: colors.lightBackgroundColor,
                                border: `2px solid ${colors.warningColor}`,
                                maxWidth: 400
                            }}>
                                <Typography variant="body1" sx={{ mb: 1, fontWeight: 'bold', color: colors.warningColor }}>
                                    Machine Not Homed
                                </Typography>
                                <Typography variant="body2" color="text.secondary">
                                    Coordinates are not available until the machine has been homed.
                                    Please home the machine to view position information.
                                </Typography>
                            </Box>
                        </Box>
                    );
                }

                // Use CoordinateOperations to get display values - no conversions here
                const workZeroX = CoordinateOperations.getWorkZeroCoordinate('X');
                const workZeroY = CoordinateOperations.getWorkZeroCoordinate('Y');
                const workZeroZ = CoordinateOperations.getWorkZeroCoordinate('Z');

                const workWithOffsetsX = CoordinateOperations.getWorkCoordinate('X');
                const workWithOffsetsY = CoordinateOperations.getWorkCoordinate('Y');
                const workWithOffsetsZ = CoordinateOperations.getWorkCoordinate('Z');

                const machineX = CoordinateOperations.getMachineCoordinate('X');
                const machineY = CoordinateOperations.getMachineCoordinate('Y');
                const machineZ = CoordinateOperations.getMachineCoordinate('Z');

                const machineHomeX = CoordinateOperations.getMachineHomeCoordinate('X');
                const machineHomeY = CoordinateOperations.getMachineHomeCoordinate('Y');
                const machineHomeZ = CoordinateOperations.getMachineHomeCoordinate('Z');

                const fixtureX = CoordinateOperations.getFixtureCoordinate('X');
                const fixtureY = CoordinateOperations.getFixtureCoordinate('Y');
                const fixtureZ = CoordinateOperations.getFixtureCoordinate('Z');

                const formatCoord = (value: number) => value.toFixed(3);

                const coordinateSectionStyle = {
                    mb: 2,
                    p: 1.5,
                    borderRadius: 1,
                    backgroundColor: colors.lightBackgroundColor,
                    border: `1px solid ${colors.borderColor}`
                };

                const coordinateRowStyle = {
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    mb: 0.5
                };

                return (
                    <Box sx={{ height: '100%', overflow: 'auto', p: 2 }}>
                        <Typography variant="h6" sx={{ mb: 2, fontWeight: 'bold' }}>
                            Coordinates
                        </Typography>

                        {/* Work Zero (Spindle Position) */}
                        <Box sx={coordinateSectionStyle}>
                            <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, color: colors.primaryColor }}>
                                Work Zero (Spindle)
                            </Typography>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">X:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(workZeroX)}
                                </Typography>
                            </Box>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">Y:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(workZeroY)}
                                </Typography>
                            </Box>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">Z:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(workZeroZ)}
                                </Typography>
                            </Box>
                        </Box>

                        {/* Work Zero With Offsets (Tool Tip) */}
                        <Box sx={coordinateSectionStyle}>
                            <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, color: colors.primaryColor }}>
                                Work Zero With Offsets (Tool Tip)
                            </Typography>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">X:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(workWithOffsetsX)}
                                </Typography>
                            </Box>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">Y:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(workWithOffsetsY)}
                                </Typography>
                            </Box>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">Z:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(workWithOffsetsZ)}
                                </Typography>
                            </Box>
                        </Box>

                        {/* Machine Zero */}
                        <Box sx={coordinateSectionStyle}>
                            <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, color: colors.primaryColor }}>
                                Machine Zero
                            </Typography>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">X:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(machineX)}
                                </Typography>
                            </Box>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">Y:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(machineY)}
                                </Typography>
                            </Box>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">Z:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(machineZ)}
                                </Typography>
                            </Box>
                        </Box>

                        {/* Machine Home */}
                        <Box sx={coordinateSectionStyle}>
                            <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, color: colors.primaryColor }}>
                                Machine Home
                            </Typography>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">X:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(machineHomeX)}
                                </Typography>
                            </Box>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">Y:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(machineHomeY)}
                                </Typography>
                            </Box>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">Z:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(machineHomeZ)}
                                </Typography>
                            </Box>
                        </Box>

                        {/* From Current Fixture */}
                        <Box sx={coordinateSectionStyle}>
                            <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, color: colors.primaryColor }}>
                                From Current Fixture
                                {!isCustom && (
                                    <Typography component="span" variant="caption" sx={{ ml: 1, color: colors.darkTextColor }}>
                                        ({displayText})
                                    </Typography>
                                )}
                            </Typography>
                            {!isCustom ? (
                                <>
                                    <Box sx={coordinateRowStyle}>
                                        <Typography variant="body2">X:</Typography>
                                        <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                            {formatCoord(fixtureX)}
                                        </Typography>
                                    </Box>
                                    <Box sx={coordinateRowStyle}>
                                        <Typography variant="body2">Y:</Typography>
                                        <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                            {formatCoord(fixtureY)}
                                        </Typography>
                                    </Box>
                                    <Box sx={coordinateRowStyle}>
                                        <Typography variant="body2">Z:</Typography>
                                        <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                            {formatCoord(fixtureZ)}
                                        </Typography>
                                    </Box>
                                </>
                            ) : (
                                <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic' }}>
                                    No fixture selected
                                </Typography>
                            )}
                        </Box>
                    </Box>
                );
            }}
        />
    );
}
