import { ManualToolChangeDialog } from '../components/Common/ManualToolChangeDialog';
import { ModalManager } from './ModalManager';

/**
 * Helper to show manual tool change dialog and wait for user confirmation
 * Separated into .tsx file to use JSX syntax per coding guidelines
 */
export class ManualToolChangeHelper {
    /**
     * Show manual tool load dialog and return a promise that resolves when user confirms
     */
    static async showDialog(toolNumber: number, toolName: string): Promise<void> {
        return new Promise<void>((resolve, reject) => {
            const modalId = `manual-tool-change-${toolNumber}`;
            let dialogResolved = false;

            const modal = {
                id: modalId,
                render: () => (
                    <ManualToolChangeDialog
                        open={true}
                        toolNumber={toolNumber}
                        toolName={toolName}
                        onConfirm={() => {
                            if (!dialogResolved) {
                                dialogResolved = true;
                                ModalManager.Instance.closeModal(modalId);
                                resolve();
                            }
                        }}
                        onCancel={() => {
                            if (!dialogResolved) {
                                dialogResolved = true;
                                ModalManager.Instance.closeModal(modalId);
                                reject(new Error('Manual tool change cancelled by user'));
                            }
                        }}
                    />
                ),
            };

            ModalManager.Instance.showModal(modal);
        });
    }

    /**
     * Show combined manual tool change dialog (remove one, install another)
     */
    static async showCombinedDialog(fromToolNumber: number, fromToolName: string, toToolNumber: number, toToolName: string): Promise<void> {
        return new Promise<void>((resolve, reject) => {
            const modalId = `manual-tool-change-${fromToolNumber}-to-${toToolNumber}`;
            let dialogResolved = false;

            const modal = {
                id: modalId,
                render: () => (
                    <ManualToolChangeDialog
                        open={true}
                        toolNumber={toToolNumber}
                        toolName={toToolName}
                        fromToolNumber={fromToolNumber}
                        mode="change"
                        onConfirm={() => {
                            if (!dialogResolved) {
                                dialogResolved = true;
                                ModalManager.Instance.closeModal(modalId);
                                resolve();
                            }
                        }}
                        onCancel={() => {
                            if (!dialogResolved) {
                                dialogResolved = true;
                                ModalManager.Instance.closeModal(modalId);
                                reject(new Error('Manual tool change cancelled by user'));
                            }
                        }}
                    />
                ),
            };

            ModalManager.Instance.showModal(modal);
        });
    }

    /**
     * Show manual tool drop dialog and return a promise that resolves when user confirms
     */
    static async showDropDialog(toolNumber: number, toolName: string): Promise<void> {
        return new Promise<void>((resolve, reject) => {
            const modalId = `manual-tool-drop-${toolNumber}`;
            let dialogResolved = false;

            const modal = {
                id: modalId,
                render: () => (
                    <ManualToolChangeDialog
                        open={true}
                        toolNumber={toolNumber}
                        toolName={toolName}
                        mode="drop"
                        onConfirm={() => {
                            if (!dialogResolved) {
                                dialogResolved = true;
                                ModalManager.Instance.closeModal(modalId);
                                resolve();
                            }
                        }}
                        onCancel={() => {
                            if (!dialogResolved) {
                                dialogResolved = true;
                                ModalManager.Instance.closeModal(modalId);
                                reject(new Error('Manual tool drop cancelled by user'));
                            }
                        }}
                    />
                ),
            };

            ModalManager.Instance.showModal(modal);
        });
    }
}
