import {
  Box,
  ListItem,
  Typography
} from '@mui/material';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { InputWithState } from '../../data/IOStateData';
import { ObserveState } from '../../utils/statemanager/ObserveState';

interface InputItemProps {
  input: InputWithState;
}

export function InputItem({ input }: InputItemProps) {
  return (
    <ObserveState
      key={`input-item-${input.number}`}
      listenTo={input}
      properties={['isActive', 'isInverted']}
      control={() => {
        const colors = ConfigurationDataColors.Instance;
        const displayIsActive = input.displayState;
        const displayText = displayIsActive ? input.activeText : input.inactiveText;
        const activeColor = colors.primaryColor;

        return (
          <ListItem
            sx={{
              py: 0.75,
              px: 1.5,
              borderBottom: `1px solid ${colors.borderColor}`,
              minHeight: 48,
              display: 'flex',
              alignItems: 'center'
            }}
          >
            <Box sx={{
              display: 'flex',
              alignItems: 'center',
              width: '100%',
              gap: 1
            }}>
              {/* Input Number in Solid Box */}
              <Box
                sx={{
                  width: 28,
                  height: 24,
                  backgroundColor: displayIsActive ? activeColor : colors.errorColor,
                  color: colors.lightTextColor,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  borderRadius: 1,
                  fontSize: '0.75rem',
                  fontWeight: 'bold',
                  flexShrink: 0
                }}
              >
                {input.number}
              </Box>

              {/* Input Name */}
              <Box sx={{ flex: 1, minWidth: 0 }}>
                <Typography
                  variant="body2"
                  sx={{
                    fontSize: '0.8rem',
                    fontWeight: 500,
                    color: colors.darkTextColor,
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap'
                  }}
                >
                  {input.name}
                </Typography>
                {input.centroidName && (
                  <Typography
                    variant="caption"
                    sx={{
                      fontSize: '0.65rem',
                      color: colors.mutedTextColor,
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                      fontStyle: 'italic'
                    }}
                  >
                    {input.centroidName}
                  </Typography>
                )}
              </Box>

              {/* Active/Inactive Status Text */}
              <Box sx={{
                minWidth: 80,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'flex-end'
              }}>
                <Typography
                  variant="caption"
                  sx={{
                    fontSize: '0.7rem',
                    fontWeight: displayIsActive ? 'bold' : 'normal',
                    color: displayIsActive ? activeColor : colors.errorColor,
                    textAlign: 'right'
                  }}
                >
                  {displayText}
                </Typography>
              </Box>
            </Box>
          </ListItem>
        );
      }}
    />
  );
}
