import {
    Box,
    Button,
    Chip,
    Divider,
    FormControl,
    FormControlLabel,
    Grid,
    InputLabel,
    MenuItem,
    Select,
    Switch,
    TextField,
    ToggleButton,
    ToggleButtonGroup,
    Typography
} from '@mui/material';
import React from 'react';
import { CutterType, Tool, ToolMeasurementMode } from '../../data/Common/Tool';
import { ToolLibrary } from '../../data/Common/ToolLibrary';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { MachineData } from '../../data/Machine/MachineData';
import { MachineStateData } from '../../data/MachineStateData';
import { MachineInterfaceManager } from '../../utils/MachineInterfaceManager';
import { ObserveMultiState } from '../../utils/statemanager/ObserveMultiState';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { ToolViewer } from '../MachineViewer/ToolViewer';
import { NumberInput } from './NumberInput';
import { OffsetEditor } from './OffsetEditor';

interface ToolEditorFormProps {
    tool: Tool | null;
    library: ToolLibrary;
    onToolChange?: (tool: Tool) => void;
    initialToolNumber?: number | null;
    showToolViewer?: boolean;
    disabled?: boolean;
    isNewTool?: boolean;  // True when creating a new tool, false when editing existing
}

export function ToolEditorForm({
    tool,
    library,
    onToolChange,
    initialToolNumber,
    showToolViewer = true,
    disabled = false,
    isNewTool = false
}: ToolEditorFormProps) {
    const colors = ConfigurationDataColors.Instance;

    // Work directly with the tool object reference - critical for ObserveState to detect updates
    // For new tools, parent should pass a new Tool() instance
    if (!tool) {
        throw new Error('ToolEditorForm requires a tool object (use new Tool() for new tools)');
    }

    // Set initial tool number if provided
    React.useEffect(() => {
        if (initialToolNumber !== undefined && tool.toolNumber === null) {
            tool.toolNumber = initialToolNumber;
        }
    }, [initialToolNumber, tool]);

    // Compute validation errors on each render - no state needed
    const getToolNumberValidation = () => {
        if (tool.toolNumber === null) {
            return { error: '', warning: '', conflictingTool: null };
        }

        const existingTool = library.tools.find((existingTool, index) => {
            if (!isNewTool && library.tools[index] === tool) {
                return false;
            }
            return existingTool.toolNumber === tool.toolNumber;
        });

        if (existingTool) {
            return {
                error: '',
                warning: `Warning: Tool number ${tool.toolNumber} is assigned to "${existingTool.displayName}". Saving will unassign that tool.`,
                conflictingTool: existingTool
            };
        }

        return { error: '', warning: '', conflictingTool: null };
    };

    const getCuttingLengthError = () => {
        if (tool.cuttingLength > Math.abs(tool.lengthBelowHolder)) {
            return 'Cutting length must be <= length below holder';
        }
        return '';
    };

    const getVBitAngleError = () => {
        if (tool.cutterType === CutterType.VBit) {
            if (tool.vCuttingEdgeAngle <= 0 || tool.vCuttingEdgeAngle >= 180) {
                return 'Angle must be between 0 and 180 degrees';
            }
        }
        return '';
    };

    const toolNumberValidation = getToolNumberValidation();
    const cuttingLengthError = getCuttingLengthError();
    const vBitAngleError = getVBitAngleError();

    // Centralized update function - no validation needed, just update the tool
    const updateFormData = (updates: Partial<Tool>) => {
        // Update the tool directly using its setters (which trigger StateManager)
        Object.keys(updates).forEach(key => {
            const value = (updates as any)[key];
            if (key in tool) {
                (tool as any)[key] = value;
            }
        });

        // Notify parent of changes (tool object was modified in place)
        if (onToolChange) {
            onToolChange(tool);
        }
    };

    return (
        <Grid container spacing={3} sx={{ minHeight: '500px' }}>
            {/* Left side - Form */}
            <Grid item xs={12} md={showToolViewer ? 7 : 12}>
                <Grid container spacing={2}>
                    {/* Row 1 - Tool Name with edit/generate link */}
                    <Grid item xs={12}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <TextField
                                fullWidth
                                label="Tool Name"
                                value={tool.allowCustomName ? tool.toolName : tool.getAutoGeneratedName()}
                                onChange={(e) => updateFormData({ toolName: e.target.value })}
                                InputProps={{
                                    readOnly: !tool.allowCustomName || tool.systemLocked || disabled,
                                }}
                                disabled={tool.systemLocked || disabled}
                            />
                            <Button
                                variant="text"
                                size="small"
                                onClick={() => updateFormData({ allowCustomName: !tool.allowCustomName })}
                                disabled={tool.systemLocked || disabled}
                                sx={{ minWidth: 'auto', whiteSpace: 'nowrap' }}
                            >
                                {tool.allowCustomName ? 'Generate' : 'Edit'}
                            </Button>
                        </Box>
                    </Grid>

                    {/* Row 2 - Tool Number and Cutter Type */}
                    <Grid item xs={12} md={6}>
                        <NumberInput
                            fullWidth
                            label="Tool Number"
                            value={tool.toolNumber ?? 0}
                            onChange={(value) => updateFormData({ toolNumber: value === 0 ? null : value })}
                            error={!!toolNumberValidation.error}
                            helperText={toolNumberValidation.error || toolNumberValidation.warning}
                            disabled={tool.systemLocked || disabled}
                            min={1}
                            precision={0}
                            sx={{
                                '& .MuiFormHelperText-root': {
                                    color: toolNumberValidation.warning && !toolNumberValidation.error ? 'warning.main' : undefined
                                }
                            }}
                        />
                    </Grid>

                    <Grid item xs={12} md={6}>
                        <FormControl fullWidth disabled={tool.systemLocked || disabled}>
                            <InputLabel>Cutter Type</InputLabel>
                            <Select
                                value={tool.cutterType}
                                onChange={(e) => updateFormData({ cutterType: e.target.value as CutterType })}
                            >
                                <MenuItem value={CutterType.FlatEndMill}>Flat End Mill</MenuItem>
                                <MenuItem value={CutterType.BallEndMill}>Ball End Mill</MenuItem>
                                <MenuItem value={CutterType.VBit}>V-Bit</MenuItem>
                            </Select>
                        </FormControl>
                    </Grid>

                    {/* Divider line */}
                    <Grid item xs={12}>
                        <Divider />
                    </Grid>

                    {/* Row 3 - Shank Width and Length Below Tool Holder */}
                    <Grid item xs={12} md={6}>
                        <NumberInput
                            fullWidth
                            label="Shank Width *"
                            value={tool.shankWidth}
                            onChange={(value) => updateFormData({ shankWidth: value })}
                            precision={3}
                            disabled={tool.systemLocked || disabled}
                            error={tool.shankWidth <= 0}
                            helperText={tool.shankWidth <= 0 ? 'Required' : undefined}
                        />
                    </Grid>

                    <Grid item xs={12} md={6}>
                        <NumberInput
                            fullWidth
                            label="Length Below Tool Holder *"
                            value={Math.abs(tool.lengthBelowHolder)}
                            onChange={(value) => updateFormData({ lengthBelowHolder: -Math.abs(value) })}
                            precision={3}
                            disabled={tool.systemLocked || disabled}
                            error={Math.abs(tool.lengthBelowHolder) <= 0}
                            helperText={Math.abs(tool.lengthBelowHolder) <= 0 ? 'Required' : undefined}
                        />
                    </Grid>

                    {/* Row 4 - Different layouts based on cutter type */}
                    {/* For Flat End Mill, Ball End Mill, Surfacing */}
                    {(tool.cutterType === CutterType.FlatEndMill ||
                        tool.cutterType === CutterType.BallEndMill ||
                        tool.cutterType === CutterType.Surfacing) && (
                            <>
                                <Grid item xs={12} md={6}>
                                    <NumberInput
                                        fullWidth
                                        label="Cutter Diameter *"
                                        value={tool.cuttingDiameter}
                                        onChange={(value) => updateFormData({ cuttingDiameter: value })}
                                        precision={3}
                                        disabled={tool.systemLocked || disabled}
                                        error={tool.cuttingDiameter <= 0}
                                        helperText={tool.cuttingDiameter <= 0 ? 'Required' : undefined}
                                    />
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <NumberInput
                                        fullWidth
                                        label="Cutter Length *"
                                        value={tool.cuttingLength}
                                        onChange={(value) => updateFormData({ cuttingLength: value })}
                                        precision={3}
                                        error={!!cuttingLengthError || tool.cuttingLength <= 0}
                                        helperText={cuttingLengthError || (tool.cuttingLength <= 0 ? 'Required' : undefined)}
                                        disabled={tool.systemLocked || disabled}
                                    />
                                </Grid>
                            </>
                        )}

                    {/* For V-Bit */}
                    {tool.cutterType === CutterType.VBit && (
                        <>
                            <Grid item xs={12} md={6}>
                                <NumberInput
                                    fullWidth
                                    label="Cutter Diameter *"
                                    value={tool.cuttingDiameter}
                                    onChange={(value) => updateFormData({ cuttingDiameter: value })}
                                    precision={3}
                                    disabled={tool.systemLocked || disabled}
                                    error={tool.cuttingDiameter <= 0}
                                    helperText={tool.cuttingDiameter <= 0 ? 'Required' : undefined}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NumberInput
                                    fullWidth
                                    label="V-Bit Angle *"
                                    value={tool.vCuttingEdgeAngle}
                                    onChange={(value) => updateFormData({ vCuttingEdgeAngle: value })}
                                    precision={1}
                                    error={!!vBitAngleError}
                                    helperText={vBitAngleError}
                                    disabled={tool.systemLocked || disabled}
                                />
                            </Grid>
                        </>
                    )}

                    {/* System Locked - conditional display based on system configuration mode */}
                    <Grid item xs={12}>
                        <ObserveState
                            key="tool-editor-system-locked"
                            listenTo={ConfigurationData.Instance}
                            properties={['systemConfigurationUnlocked']}
                            control={() => {
                                const config = ConfigurationData.Instance;

                                // If system is unlocked, show toggle for system locked
                                if (config.systemConfigurationUnlocked && !disabled) {
                                    return (
                                        <FormControlLabel
                                            control={
                                                <Switch
                                                    checked={tool.systemLocked}
                                                    onChange={(e) => updateFormData({ systemLocked: e.target.checked })}
                                                />
                                            }
                                            label="System Locked"
                                        />
                                    );
                                }

                                // If system is locked and tool is locked, show chip indicator
                                if (tool.systemLocked) {
                                    return (
                                        <Chip
                                            label="System Locked"
                                            color="primary"
                                            variant="outlined"
                                            size="small"
                                        />
                                    );
                                }

                                // If system is locked but tool is not locked, show nothing
                                return null;
                            }}
                        />
                    </Grid>

                    {/* Measured Length and Tool Measurement section */}
                    <Grid item xs={12}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <Typography variant="subtitle2" gutterBottom sx={{ mb: 0 }}>Tool Measurement</Typography>
                            <ObserveState
                                key="measurement-status-chip"
                                listenTo={tool}
                                properties={['measuredLength', 'lastMeasuredSessionNumber']}
                                control={() => {
                                    const isMeasured = !tool.needsMeasurement(MachineStateData.Instance.sessionNumber);
                                    return (
                                        <Chip
                                            label={isMeasured ? 'Measured' : 'Not Measured'}
                                            color={isMeasured ? 'success' : 'default'}
                                            size="small"
                                            variant={isMeasured ? 'filled' : 'outlined'}
                                        />
                                    );
                                }}
                            />
                        </Box>
                    </Grid>

                    <Grid item xs={12} md={6}>
                        <ObserveState
                            key="measured-length-field"
                            listenTo={tool}
                            properties={['measuredLength']}
                            control={() => (
                                <NumberInput
                                    fullWidth
                                    label="Measured Length"
                                    value={Math.abs(tool.measuredLength || 0)}
                                    onChange={(value) => updateFormData({ measuredLength: -Math.abs(value) })}
                                    precision={3}
                                    disabled={true}
                                />
                            )}
                        />
                    </Grid>

                    <Grid item xs={12} md={6}>
                        <ObserveMultiState
                            key="measure-tool-button"
                            listenTo={[
                                { obj: MachineStateData.Instance, properties: ['currentToolNumber', 'sessionNumber'] },
                                { obj: tool, properties: ['measuredLength', 'lastMeasuredSessionNumber'] }
                            ]}
                            control={() => {
                                const machineState = MachineStateData.Instance;
                                const isCurrentTool = tool.toolNumber === machineState.currentToolNumber;
                                const isMeasured = !tool.needsMeasurement(machineState.sessionNumber);

                                if (disabled) {
                                    return null;
                                }

                                if (!isCurrentTool) {
                                    // Tool is not loaded - show Load Tool button if tool has a valid number
                                    if (tool.toolNumber === null) {
                                        return (
                                            <Box sx={{ display: 'flex', alignItems: 'center', height: '100%' }}>
                                                <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', width: '100%' }}>
                                                    Assign a tool number to load this tool
                                                </Typography>
                                            </Box>
                                        );
                                    }

                                    return (
                                        <Box sx={{ display: 'flex', alignItems: 'center', height: '100%' }}>
                                            <Button
                                                variant="outlined"
                                                color="primary"
                                                onClick={async () => {
                                                    const machine = MachineInterfaceManager.Instance.getMachineInterface();
                                                    if (machine?.system) {
                                                        await machine.system.changeTool(tool.toolNumber!);
                                                    }
                                                }}
                                                disabled={tool.systemLocked}
                                                fullWidth
                                                sx={{ height: '56px' }}
                                            >
                                                Load Tool
                                            </Button>
                                        </Box>
                                    );
                                }

                                return (
                                    <Box sx={{ display: 'flex', alignItems: 'center', height: '100%' }}>
                                        <Button
                                            variant={isMeasured ? "outlined" : "contained"}
                                            color="primary"
                                            onClick={async () => {
                                                const machine = MachineInterfaceManager.Instance.getMachineInterface();
                                                if (machine?.system) {
                                                    await machine.system.measureCurrentTool();
                                                }
                                            }}
                                            disabled={tool.systemLocked}
                                            fullWidth
                                            sx={{ height: '56px' }}
                                        >
                                            {isMeasured ? 'Re-measure Tool' : 'Measure Tool'}
                                        </Button>
                                    </Box>
                                );
                            }}
                        />
                    </Grid>

                    {/* Tool Measurement Mode - Only show if fixed touch plate is available */}
                    <ObserveState
                        key="tool-measurement-mode"
                        listenTo={MachineData.Instance}
                        properties={['hasFixedTouchPlate']}
                        control={() => {
                            const machineData = MachineData.Instance;
                            if (!machineData.hasFixedTouchPlate || disabled) {
                                // No fixed touch plate - measurement is always manual
                                return null;
                            }

                            return (
                                <Grid item xs={12}>
                                    <Typography variant="subtitle2" gutterBottom>
                                        Measurement Mode
                                    </Typography>
                                    <ToggleButtonGroup
                                        value={tool.measurementMode}
                                        exclusive
                                        onChange={(_, newValue) => {
                                            if (newValue !== null) {
                                                updateFormData({ measurementMode: newValue });
                                            }
                                        }}
                                        disabled={tool.systemLocked}
                                        fullWidth
                                        sx={{ mt: 1 }}
                                    >
                                        <ToggleButton
                                            value={ToolMeasurementMode.AutoMeasure}
                                            sx={{
                                                '&.Mui-selected': {
                                                    backgroundColor: colors.primaryColor,
                                                    color: colors.lightTextColor,
                                                    '&:hover': {
                                                        backgroundColor: colors.primaryColor,
                                                        filter: 'brightness(0.9)'
                                                    }
                                                }
                                            }}
                                        >
                                            Auto Measure
                                        </ToggleButton>
                                        <ToggleButton
                                            value={ToolMeasurementMode.AutoMeasureConfirm}
                                            sx={{
                                                '&.Mui-selected': {
                                                    backgroundColor: colors.primaryColor,
                                                    color: colors.lightTextColor,
                                                    '&:hover': {
                                                        backgroundColor: colors.primaryColor,
                                                        filter: 'brightness(0.9)'
                                                    }
                                                }
                                            }}
                                        >
                                            Auto Measure (Confirm)
                                        </ToggleButton>
                                        <ToggleButton
                                            value={ToolMeasurementMode.ManualMeasure}
                                            sx={{
                                                '&.Mui-selected': {
                                                    backgroundColor: colors.primaryColor,
                                                    color: colors.lightTextColor,
                                                    '&:hover': {
                                                        backgroundColor: colors.primaryColor,
                                                        filter: 'brightness(0.9)'
                                                    }
                                                }
                                            }}
                                        >
                                            Manual Measure
                                        </ToggleButton>
                                    </ToggleButtonGroup>
                                    <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                                        {tool.measurementMode === ToolMeasurementMode.AutoMeasure && "Tool will be measured automatically during tool changes"}
                                        {tool.measurementMode === ToolMeasurementMode.AutoMeasureConfirm && "Tool measurement requires user confirmation during tool changes"}
                                        {tool.measurementMode === ToolMeasurementMode.ManualMeasure && "Tool measurement must be done manually"}
                                    </Typography>
                                </Grid>
                            );
                        }}
                    />

                    {/* Tool Offsets section */}
                    <Grid item xs={12}>
                        <Typography variant="subtitle2" gutterBottom>Tool Offsets</Typography>
                    </Grid>

                    <Grid item xs={12}>
                        <OffsetEditor
                            offset={tool.toolOffset}
                            onOffsetChange={(newOffset) => {
                                tool.toolOffset.setValues(newOffset.x, newOffset.y, newOffset.z);
                                updateFormData({});
                            }}
                            disabled={tool.systemLocked || disabled}
                            xLabel="X Offset"
                            yLabel="Y Offset"
                            zLabel="Z Offset"
                        />
                    </Grid>
                </Grid>
            </Grid>

            {/* Right side - 3D Preview */}
            {showToolViewer && (
                <Grid item xs={12} md={5}>
                    <Box sx={{
                        height: '100%',
                        minHeight: '400px',
                        border: 1,
                        borderColor: 'divider',
                        borderRadius: 1,
                        p: 2
                    }}>
                        <Typography variant="h6" gutterBottom>
                            Tool Preview
                        </Typography>
                        {/* Show preview only if tool has valid dimensions */}
                        {Math.abs(tool.lengthBelowHolder) > 0 &&
                            ((tool.cutterType === CutterType.VBit && tool.cuttingDiameter > 0) ||
                                (tool.cutterType !== CutterType.VBit && tool.cuttingLength > 0)) &&
                            tool.cuttingDiameter > 0 ? (
                            <ToolViewer
                                tool={tool}
                                width="100%"
                                height="350px"
                                showGrid={true}
                                enableControls={true}
                            />
                        ) : (
                            <Box sx={{
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                height: '350px',
                                backgroundColor: 'grey.100',
                                borderRadius: 1
                            }}>
                                <Typography variant="body2" color="text.secondary">
                                    Enter tool dimensions to see preview
                                </Typography>
                            </Box>
                        )}
                    </Box>
                </Grid>
            )}
        </Grid>
    );
}
