import { Warning as WarningIcon } from '@mui/icons-material';
import { Alert, AlertTitle, Button } from '@mui/material';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { Machine } from '../../machine/Machine';
import { LogCategory, Logger } from '../../utils/Logger';

/**
 * Notification component displayed when machine requires a reset
 * Shows warning and provides reset button
 */
export function ResetRequiredNotification() {
    const colors = ConfigurationDataColors.Instance;

    const handleReset = async () => {
        try {
            // Call machine reset
            const machine = Machine.getInstance();
            await machine.system.Reset();

            // Clear the requiresReset flag (setter notifies observers)
            ConfigurationState.Instance.requiresReset = false;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to reset machine:', error);
        }
    };

    return (
        <Alert
            severity="warning"
            icon={<WarningIcon />}
            sx={{
                minWidth: 300,
                maxWidth: 400,
                backgroundColor: colors.warningColor,
                color: colors.lightTextColor,
                '& .MuiAlert-icon': {
                    color: colors.lightTextColor
                },
                boxShadow: 3
            }}
            action={
                <Button
                    color="inherit"
                    size="small"
                    onClick={handleReset}
                    sx={{
                        backgroundColor: `${colors.lightTextColor}33`,
                        '&:hover': {
                            backgroundColor: `${colors.lightTextColor}4D`
                        }
                    }}
                >
                    RESET
                </Button>
            }
        >
            <AlertTitle sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>
                Machine Reset Required
            </AlertTitle>
            The machine is in a restricted state and requires a reset before operations can continue.
        </Alert>
    );
}
