import { Cancel as CancelIcon } from '@mui/icons-material';
import {
    Box,
    Button,
    CircularProgress,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    LinearProgress,
    Typography
} from '@mui/material';
import { ConfigurationDataColors } from '../data/ConfigurationDataColors';
import { ConfigurationState } from '../data/ConfigurationState';
import { LogCategory, Logger } from '../utils/Logger';
import { ObserveState } from '../utils/statemanager/ObserveState';

/**
 * LongRunningOperationDialog displays during long-running system operations
 * Shows progress message and allows user to cancel the operation
 * Used for operations like load tool, drop tool, measure tool, home machine, etc.
 * 
 * Supports two modes:
 * 1. Simulator mode (duration provided): Shows countdown progress bar and auto-completes
 * 2. Real operation mode (no duration): Shows spinner until explicitly completed
 */

// Track active timer and progress outside component for imperative management
let activeTimer: NodeJS.Timeout | null = null;
let currentProgress = 0;
let forceUpdateCounter = 0;

function startSimulatorTimer(operation: any) {
    // Clear any existing timer
    if (activeTimer) {
        clearTimeout(activeTimer);
        activeTimer = null;
    }

    const startTime = Date.now();
    currentProgress = 0;

    const updateProgress = () => {
        const elapsed = Date.now() - startTime;
        currentProgress = Math.min((elapsed / operation.duration!) * 100, 100);

        // Trigger re-render by modifying state (force update via property change)
        forceUpdateCounter++;
        ConfigurationState.Instance.updateLongRunningOperationMessage(operation.message);

        if (elapsed >= operation.duration!) {
            // Duration complete - call onComplete
            if (activeTimer) {
                clearTimeout(activeTimer);
                activeTimer = null;
            }
            operation.complete();
        } else {
            // Continue updating progress
            activeTimer = setTimeout(updateProgress, 50) as any;
        }
    };

    updateProgress();
}

function stopSimulatorTimer() {
    if (activeTimer) {
        clearTimeout(activeTimer);
        activeTimer = null;
    }
    currentProgress = 0;
}

export function LongRunningOperationDialog() {
    const handleCancel = async () => {
        try {
            // Clear any active timer
            stopSimulatorTimer();

            // Call cancelLongRunningOperation which invokes the onCancel callback
            // Callback handles CancelCycle, closing dialog, and error propagation
            await ConfigurationState.Instance.cancelLongRunningOperation();
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to cancel operation:', error);
        }
    };

    return (
        <ObserveState
            key="long-running-operation-dialog-observer"
            listenTo={ConfigurationState.Instance}
            properties={['longRunningOperation']}
            control={() => {
                const operation = ConfigurationState.Instance.longRunningOperation;
                const colors = ConfigurationDataColors.Instance;

                // Manage timer based on operation state
                if (operation && operation.duration && !activeTimer) {
                    // Start timer for simulator mode
                    startSimulatorTimer(operation);
                } else if (!operation) {
                    // Clear timer when operation completes
                    stopSimulatorTimer();
                }

                if (!operation) {
                    return null;
                }

                return (
                    <Dialog
                        open={true}
                        maxWidth="sm"
                        fullWidth
                        disableEscapeKeyDown
                        slotProps={{
                            backdrop: {
                                style: { zIndex: 1999 }
                            }
                        }}
                        PaperProps={{
                            style: { zIndex: 2000 }
                        }}
                        sx={{
                            zIndex: 2000
                        }}
                    >
                        <DialogTitle sx={{
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'space-between',
                            backgroundColor: colors.primaryColor,
                            color: colors.lightTextColor,
                            py: 2,
                            px: 3
                        }}>
                            {operation.title}
                        </DialogTitle>

                        <DialogContent>
                            <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3 }}>
                                {operation.duration ? (
                                    // Simulator mode - show progress bar
                                    <Box sx={{ width: '100%' }}>
                                        <LinearProgress
                                            variant="determinate"
                                            value={currentProgress}
                                            sx={{
                                                height: 8,
                                                borderRadius: 4,
                                                backgroundColor: `${colors.primaryColor}20`,
                                                '& .MuiLinearProgress-bar': {
                                                    backgroundColor: colors.primaryColor
                                                }
                                            }}
                                        />
                                    </Box>
                                ) : (
                                    // Real operation mode - show spinner
                                    <CircularProgress
                                        size={60}
                                        sx={{ color: colors.primaryColor }}
                                    />
                                )}

                                <Typography variant="body1" align="center">
                                    {operation.message}
                                </Typography>
                            </Box>
                        </DialogContent>

                        <DialogActions sx={{
                            p: 2,
                            justifyContent: 'center',
                            borderTop: `1px solid ${colors.borderColor}`
                        }}>
                            <Button
                                onClick={handleCancel}
                                variant="outlined"
                                color="error"
                                startIcon={<CancelIcon />}
                            >
                                Cancel Operation
                            </Button>
                        </DialogActions>
                    </Dialog>
                );
            }}
        />
    );
}
