import { PLCProgram, PLCProgramSystem } from '../centroid/plc/data/PLCProgram';
import { PLCProgramType } from '../centroid/plc/data/PLCUtilities';
import { ConfigurationData } from '../data/ConfigurationData';
import { AxisType } from '../data/Machine/AxisType';
import { HomingDirection } from '../data/Machine/HomingDirection';
import { MachineData } from '../data/Machine/MachineData';
import { MachineStateData } from '../data/MachineStateData';
import { PLCInputName } from '../data/PLCIONames';
import type { AxisConfiguration } from '../machine/Machine';
import { CoordinateUtil } from './CoordinateUtil';

/**
 * Utility class for mapping between MachineData internal representations
 * and machine API configuration formats
 */
export class MachineConfigurationMapper {
  /**
   * Convert soft limits from MachineZero coordinates to MachineHome travel limits
   * Returns plus and minus travel limits for a specific axis
   * 
   * @param axisType The type of axis (X, Y, Z, A, etc.)
   * @returns Object containing plusLimit and minusLimit, or null values if not applicable
   */
  public static async getSoftLimitsForAxis(
    axisType: AxisType
  ): Promise<{ plusLimit: number | null; minusLimit: number | null }> {
    // Use existing CoordinateUtil method to get soft limits box
    const softLimitsBox = await CoordinateUtil.getSoftLimitsBox(MachineStateData.Instance);

    // The box already has all 8 corner points computed
    // Convert the relevant corners to MachineHome coordinates
    const originMH = CoordinateUtil.toMachineHome(softLimitsBox.origin);
    const farCornerMH = CoordinateUtil.toMachineHome(softLimitsBox.boxPoints.rearRightUpper);

    // Extract travel limits for the specific axis
    // In MachineHome coordinates, home is at 0,0,0 and travel is typically negative
    switch (axisType) {
      case AxisType.X:
      case AxisType.XSlave:
        return {
          plusLimit: Math.max(originMH.x, farCornerMH.x),  // Positive travel from home
          minusLimit: Math.min(originMH.x, farCornerMH.x)  // Negative travel from home
        };

      case AxisType.Y:
      case AxisType.YSlave:
        return {
          plusLimit: Math.max(originMH.y, farCornerMH.y),
          minusLimit: Math.min(originMH.y, farCornerMH.y)
        };

      case AxisType.Z:
        return {
          plusLimit: Math.max(originMH.z, farCornerMH.z),
          minusLimit: Math.min(originMH.z, farCornerMH.z)
        };

      case AxisType.A:
        // Rotary axis - no soft limits by default
        return { plusLimit: null, minusLimit: null };

      case AxisType.Unset:
      default:
        return { plusLimit: null, minusLimit: null };
    }
  }

  /**
   * Map AxisType enum to API axis label string
   * 
   * @param axisType The internal AxisType enum value
   * @returns API-compatible axis label (X, Y, Z, A) or null for unset
   */
  public static mapAxisTypeToLabel(axisType: AxisType): string | null {
    switch (axisType) {
      case AxisType.X:
        return 'X';
      case AxisType.Y:
        return 'Y';
      case AxisType.Z:
        return 'Z';
      case AxisType.A:
        return 'A';
      case AxisType.XSlave:
      case AxisType.YSlave:
        // CNC12 requires label 'N' (No Motor) on a paired slave axis.
        // Leaving a real label (X/Y) causes CNC12 to treat it as an
        // independent axis and ignore the masterAxis pairing parameter.
        return 'N';
      case AxisType.Unset:
      default:
        // Unset slots are sent as 'Unset' so the backend can distinguish them
        // from real 'N' (No Motor / slave) slots and skip them explicitly.
        return 'Unset';
    }
  }

  /**
   * Check if an axis type represents a rotary axis
   * 
   * @param axisType The axis type to check
   * @returns True if the axis is rotary (A-axis)
   */
  public static isRotaryAxis(axisType: AxisType): boolean {
    return axisType === AxisType.A;
  }

  /**
   * Get the limit input configuration for an axis based on PLC inputs and homing direction
   * 
   * Logic:
   * - If homing in positive direction with home/limit switch → assign to positiveLimitInput
   * - If also have separate limit switch → assign to negativeLimitInput
   * - If homing in negative direction with home/limit switch → assign to negativeLimitInput
   * - If also have separate limit switch → assign to positiveLimitInput
   * 
   * @param axisType The axis type
   * @param homingDirection The homing direction for this axis
   * @returns Object with positiveLimitInput and negativeLimitInput numbers (1-based, or 0 for none)
   */
  private static getAxisLimitInputs(
    axisType: AxisType,
    homingDirection: HomingDirection
  ): { positiveLimitInput: number | undefined; negativeLimitInput: number | undefined; homingDirectionPositive: boolean | undefined } {
    const systemPLC = PLCProgram.Instance(PLCProgramType.System) as PLCProgramSystem;

    // Determine the centroid names for this axis type
    let homeLimitInputName: PLCInputName | null = null;
    let limitInputName: PLCInputName | null = null;

    switch (axisType) {
      case AxisType.X:
        homeLimitInputName = PLCInputName.XAxisHomeLimitOk;
        limitInputName = PLCInputName.XAxisLimitOk;
        break;
      case AxisType.Y:
        homeLimitInputName = PLCInputName.YAxisHomeLimitOk;
        limitInputName = PLCInputName.YAxisLimitOk;
        break;
      case AxisType.Z:
        homeLimitInputName = PLCInputName.ZAxisHomeLimitOk;
        limitInputName = PLCInputName.ZAxisLimitOk;
        break;
      case AxisType.A:
        homeLimitInputName = PLCInputName.AAxisHomeLimitOk;
        limitInputName = PLCInputName.AAxisLimitOk;
        break;
      default:
        // No limit inputs for other axis types
        return { positiveLimitInput: undefined, negativeLimitInput: undefined, homingDirectionPositive: undefined };
    }

    // Find the PLC inputs by centroid name
    const homeLimitInput = systemPLC.inputs.find((input: any) => input.centroidName === homeLimitInputName);
    const limitInput = systemPLC.inputs.find((input: any) => input.centroidName === limitInputName);

    // Get the input numbers (0 if not assigned)
    const homeLimitNumber = homeLimitInput?.number ?? 0;
    const limitNumber = limitInput?.number ?? 0;

    // Determine homing direction positive flag
    const homingDirectionPositive = homingDirection === HomingDirection.Positive ? true :
      homingDirection === HomingDirection.Negative ? false :
        undefined;

    // Apply the logic based on homing direction
    if (homingDirection === HomingDirection.Positive) {
      // Homing in positive direction
      // Home/limit switch goes to positive input
      // Separate limit switch goes to negative input
      return {
        positiveLimitInput: homeLimitNumber > 0 ? homeLimitNumber : undefined,
        negativeLimitInput: limitNumber > 0 ? limitNumber : undefined,
        homingDirectionPositive
      };
    } else if (homingDirection === HomingDirection.Negative) {
      // Homing in negative direction
      // Home/limit switch goes to negative input
      // Separate limit switch goes to positive input
      return {
        positiveLimitInput: limitNumber > 0 ? limitNumber : undefined,
        negativeLimitInput: homeLimitNumber > 0 ? homeLimitNumber : undefined,
        homingDirectionPositive
      };
    } else {
      // No homing direction specified - no inputs assigned
      return { positiveLimitInput: undefined, negativeLimitInput: undefined, homingDirectionPositive: undefined };
    }
  }

  /**
   * Convert MachineData AxisConfig to API AxisConfiguration format
   * 
   * @param axis The internal AxisConfig object
   * @param axisNumber The 1-based axis number (1-6)
   * @param machineData Optional MachineData instance (defaults to singleton)
   * @returns AxisConfiguration object ready for API submission
   */
  public static async convertAxisToAPIFormat(
    axis: any,
    axisNumber: number,
    machineData: MachineData = MachineData.Instance
  ): Promise<AxisConfiguration> {
    // Map axis type to label
    const label = MachineConfigurationMapper.mapAxisTypeToLabel(axis.axisType);

    // Get travel limits for this axis
    const travelLimits = await MachineConfigurationMapper.getSoftLimitsForAxis(
      axis.axisType
    );

    // Get global speed settings from ConfigurationData
    const configData = ConfigurationData.Instance;
    const isZAxis = axis.axisType === AxisType.Z;
    const slowJogRate = isZAxis ? configData.slowJogZ : configData.slowJogXY;
    const fastJogRate = isZAxis ? configData.fastJogZPlus : configData.fastJogXY;
    const fastJogPlusDirection = isZAxis ? configData.fastJogZPlus : configData.fastJogXY;
    const fastJogMinusDirection = isZAxis ? configData.fastJogZMinus : configData.fastJogXY;
    const maxRate = isZAxis ? configData.maxSpeedZ : configData.maxSpeedXY;

    // Map all axis configuration properties
    const apiConfig = {
      axisNumber: axisNumber,
      axisType: label,
      stepsPerRevolution: axis.stepsPerRevolution,
      overallTurnsRatio: axis.overallTurnsRatio,
      lashCompensation: axis.lashCompensation,
      maxRate: maxRate,
      accelDecel: axis.accelDecel,
      directionReversal: axis.directionReversal,
      slowJogRate: slowJogRate,
      fastJogRate: fastJogRate,
      fastJogPlusDirection: fastJogPlusDirection,
      fastJogMinusDirection: fastJogMinusDirection,
      homingFeedrate: axis.homingFeedrate,
      stepSignalInverted: axis.stepSignalInverted,
      directionSignalInverted: axis.directionSignalInverted,
      enableSignalInverted: axis.enableSignalInverted,
      // Travel limits from soft limits converted to MachineHome coordinates
      plusTravelLimit: travelLimits.plusLimit,
      minusTravelLimit: travelLimits.minusLimit,
      // Limit switches - explicitly set to null (not used)
      positiveLimitInput: null,
      negativeLimitInput: null,
      homingDirectionPositive: null,
      // Axis type flags
      isRotary: MachineConfigurationMapper.isRotaryAxis(axis.axisType),
      // Optional fields - not currently used
      rotaryWrapAround: undefined,
      cAxisEnabled: undefined,
      preventDivideBy360: undefined,
      hideFromDRO: undefined,
      parallelToX: undefined,
      parallelToY: undefined,
    };


    return apiConfig;
  }

  /**
   * Convert all configured axes from MachineData to API format
   * Skips axes with AxisType.Unset
   *
   * For slave axes (XSlave / YSlave) the motion parameters are overwritten with
   * the master axis values after conversion — matching the CNC12 pairing behaviour
   * where SetCountsPerTurn, SetScrewPitch, SetLashComp, and SetAccelTime are all
   * written identically on both the master and the slave.  The slave keeps its own
   * directionReversal (independently flippable) and signal-inversion flags.  CNC12
   * identifies the paired relationship via the slave's axisType label 'N' (No Motor)
   * and masterAxisName set to the master's axis label (e.g. 'X' or 'Y').
   *
   * @param machineData Optional MachineData instance (defaults to singleton)
   * @returns Array of AxisConfiguration objects
   */
  public static async convertAllAxesToAPIFormat(
    machineData: MachineData = MachineData.Instance
  ): Promise<AxisConfiguration[]> {
    const apiConfigs: AxisConfiguration[] = [];

    // Always send all 6 axis slots explicitly so the backend never runs its
    // "unused axis" fallback loop, which would overwrite pairing on slot 4+.
    // Unset axes are sent as axisType 'N' (No Motor) — identical to what the
    // backend's fallback would write, but now we control the order.
    for (let i = 0; i < machineData.axisConfigurations.length; i++) {
      const axis = machineData.axisConfigurations[i];

      const isSlave =
        axis.axisType === AxisType.XSlave || axis.axisType === AxisType.YSlave;

      // Convert to API format using the real AxisConfig instance so all
      // prototype getters (axisType, directionReversal, etc.) work correctly.
      // Spreading a class instance only copies underscore-prefixed own properties
      // and loses the getters, so we always pass `axis` directly here.
      const apiConfig = await MachineConfigurationMapper.convertAxisToAPIFormat(
        axis,
        i + 1,
        machineData
      );

      if (isSlave) {
        // Paired axes must mirror the master's motion parameters.
        // Look up the master axis (X for XSlave, Y for YSlave).
        const masterAxisType =
          axis.axisType === AxisType.XSlave ? AxisType.X : AxisType.Y;
        const masterAxis = machineData.axisConfigurations.find(
          (a) => a.axisType === masterAxisType
        );

        if (masterAxis) {
          // Overwrite motion parameters with master's values.
          // The slave keeps its own directionReversal and signal-inversion flags
          // (already set correctly by convertAxisToAPIFormat above).
          apiConfig.stepsPerRevolution = masterAxis.stepsPerRevolution;
          apiConfig.overallTurnsRatio = masterAxis.overallTurnsRatio;
          apiConfig.lashCompensation = masterAxis.lashCompensation;
          apiConfig.accelDecel = masterAxis.accelDecel;

          // Tell the backend which axis this slave is paired to.
          // The backend deserialises this as masterAxisName (camelCase).
          apiConfig.masterAxisName = MachineConfigurationMapper.mapAxisTypeToLabel(masterAxis.axisType);
        }
      }

      apiConfigs.push(apiConfig);
    }

    return apiConfigs;
  }
}
