import { Box, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { Declaration } from './Declaration';
import { IPLCSource, PLCUtilities } from './PLCUtilities';

/**
 * Utility class for building consistent declaration tooltips
 * Used across DataElement, InitializeOneShotStatement, and other components
 * that display declaration information
 */
export class DeclarationTooltipBuilder {
    /**
     * Build tooltip content for a declaration with usage information
     * @param declaration The declaration to build tooltip for (or undefined)
     * @param program The PLC program to search for usages
     * @param isEmpty Whether the value is empty/unpicked
     * @param emptyMessage Optional custom message for empty state
     * @returns React node for tooltip content
     */
    public static buildTooltip(
        declaration: Declaration | undefined,
        program: IPLCSource | undefined,
        isEmpty: boolean,
        emptyMessage?: string
    ): React.ReactNode {
        const colors = ConfigurationDataColors.Instance;
        if (!declaration) {
            if (isEmpty) {
                return (
                    <Typography variant="caption" sx={{ color: colors.lightTextColor }}>
                        {emptyMessage || 'Click to select a data element'}
                    </Typography>
                );
            } else {
                return (
                    <Typography variant="caption" sx={{ color: ConfigurationDataColors.Instance.errorColor }}>
                        Declaration not found
                    </Typography>
                );
            }
        }

        // Get usage information
        let usages: Array<{ stageName: string; blockName: string; isWritten: boolean }> = [];
        if (program) {
            usages = PLCUtilities.getDeclarationUsages(program, declaration.name);
        }

        const writes = usages.filter(u => u.isWritten);
        const reads = usages.filter(u => !u.isWritten);

        return (
            <Box sx={{ p: 1 }}>
                <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, color: colors.lightTextColor }}>
                    {declaration.name}
                </Typography>

                <Box sx={{ display: 'grid', gridTemplateColumns: 'auto 1fr', gap: 0.5, mb: 1 }}>
                    <Typography variant="caption" sx={{ color: colors.mutedTextColor, fontWeight: 'bold' }}>Type:</Typography>
                    <Typography variant="caption" sx={{ color: colors.lightTextColor }}>{declaration.dataType}</Typography>

                    {declaration.visibility && (
                        <>
                            <Typography variant="caption" sx={{ color: colors.mutedTextColor, fontWeight: 'bold' }}>Visibility:</Typography>
                            <Typography variant="caption" sx={{ color: colors.lightTextColor }}>{declaration.visibility}</Typography>
                        </>
                    )}

                    {declaration.readOnly && (
                        <>
                            <Typography variant="caption" sx={{ color: colors.mutedTextColor, fontWeight: 'bold' }}>Access:</Typography>
                            <Typography variant="caption" sx={{ color: ConfigurationDataColors.Instance.errorColor }}>Read Only</Typography>
                        </>
                    )}

                    {declaration.isSystem && (
                        <>
                            <Typography variant="caption" sx={{ color: colors.mutedTextColor, fontWeight: 'bold' }}>Source:</Typography>
                            <Typography variant="caption" sx={{ color: ConfigurationDataColors.Instance.infoColor }}>System</Typography>
                        </>
                    )}
                </Box>

                {declaration.category && declaration.category.length > 0 && (
                    <Box sx={{ mb: 1 }}>
                        <Typography variant="caption" sx={{ color: colors.mutedTextColor, fontWeight: 'bold' }}>Category:</Typography>
                        <Typography variant="caption" sx={{ color: colors.lightTextColor, ml: 0.5 }}>
                            {declaration.category.join(' › ')}
                        </Typography>
                    </Box>
                )}

                {declaration.description && (
                    <Box sx={{ mb: 1, p: 0.5, bgcolor: colors.lightOverlay, borderRadius: 0.5 }}>
                        <Typography variant="caption" sx={{ color: colors.lightTextColor, fontStyle: 'italic' }}>
                            {declaration.description}
                        </Typography>
                    </Box>
                )}

                {usages.length > 0 ? (
                    <Box sx={{ mt: 1.5, pt: 1, borderTop: `1px solid ${colors.lightOverlay}` }}>
                        <Typography variant="caption" sx={{ color: colors.mutedTextColor, fontWeight: 'bold', display: 'block', mb: 0.5 }}>
                            Usage: {usages.length} location(s)
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 2, mb: 1 }}>
                            {writes.length > 0 && (
                                <Typography variant="caption" sx={{ color: ConfigurationDataColors.Instance.warningColor }}>
                                    ✍ Written: {writes.length}
                                </Typography>
                            )}
                            {reads.length > 0 && (
                                <Typography variant="caption" sx={{ color: ConfigurationDataColors.Instance.successColor }}>
                                    👁 Read: {reads.length}
                                </Typography>
                            )}
                        </Box>

                        <Box sx={{ mt: 1 }}>
                            <Typography variant="caption" sx={{ color: colors.mutedTextColor, fontWeight: 'bold', display: 'block', mb: 0.5 }}>
                                Locations:
                            </Typography>
                            {usages.map((usage, idx) => (
                                <Box key={idx} sx={{ ml: 1, mb: 0.25 }}>
                                    <Typography variant="caption" sx={{ color: colors.lightTextColor }}>
                                        {usage.stageName} › {usage.blockName}:{' '}
                                        <span style={{ color: usage.isWritten ? ConfigurationDataColors.Instance.warningColor : ConfigurationDataColors.Instance.successColor }}>
                                            {usage.isWritten ? 'Write' : 'Read'}
                                        </span>
                                    </Typography>
                                </Box>
                            ))}
                        </Box>
                    </Box>
                ) : (
                    <Box sx={{ mt: 1.5, pt: 1, borderTop: `1px solid ${colors.lightOverlay}` }}>
                        <Typography variant="caption" sx={{ color: ConfigurationDataColors.Instance.warningColor, fontStyle: 'italic' }}>
                            Not used in logic
                        </Typography>
                    </Box>
                )}
            </Box>
        );
    }

    /**
     * Get common tooltip styling props for Material-UI Tooltip component
     * Ensures consistent appearance across all tooltips
     */
    public static getTooltipProps() {
        const colors = ConfigurationDataColors.Instance;
        return {
            componentsProps: {
                tooltip: {
                    sx: {
                        bgcolor: colors.darkBackgroundColor,
                        maxWidth: 400,
                        border: `1px solid ${colors.lightOverlay}`,
                        boxShadow: `0 4px 20px ${colors.shadowColor}`,
                    }
                },
                arrow: {
                    sx: {
                        color: colors.darkBackgroundColor,
                    }
                }
            }
        };
    }
}
