
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';
import type { IMachineInterface } from './IMachineInterface';

// Import and re-export types from the generated services
import type {
  AvailableParametersResponse,
  AxisConfiguration,
  CheckpointInfo,
  CheckpointSaveRequest,
  CompleteMachineConfiguration,
  ConfigurationDataRequest,
  DataItem,
  DirectoryInfoResponse,
  DriveInfoResponse,
  GlobalSystemConfiguration,
  ParameterSetRequest,
  ParameterValue,
  ProbeConfiguration,
  PWMConfiguration,
  RunGCodeResponse,
  SecondSpindleConfiguration,
  SpindleConfiguration,
  StepFrequencyRequest,
  SystemHardwareInfo,
  SystemStatus,
  ToolTouchOffConfiguration,
  TouchPlateConfiguration
} from '../services/src/models';

import { MovementCoordinateType } from './ICNCMovement';
import { IOEvent } from './IOEvent';
import { JogDirection } from './JogDirection';
import { JogSpeed } from './JogSpeed';
import { MoveDirection } from './MoveDirection';
import { MoveStrategy } from './MoveStrategy';
import { MoveType } from './MoveType';

// Re-export IMachineInterface for backward compatibility
export type { IMachineInterface } from './IMachineInterface';

// Re-export enums for convenience
export { IOEvent, JogDirection, JogSpeed, MoveDirection, MovementCoordinateType, MoveStrategy, MoveType };

// Export all types for use in other modules
export type {
  AvailableParametersResponse,
  AxisConfiguration,
  CheckpointInfo,
  CheckpointSaveRequest,
  CompleteMachineConfiguration,
  ConfigurationDataRequest,
  DataItem,
  DirectoryInfoResponse,
  DriveInfoResponse,
  GlobalSystemConfiguration,
  ParameterSetRequest,
  ParameterValue,
  ProbeConfiguration,
  PWMConfiguration,
  RunGCodeResponse,
  SecondSpindleConfiguration,
  SpindleConfiguration,
  StepFrequencyRequest,
  SystemHardwareInfo,
  SystemStatus,
  ToolTouchOffConfiguration,
  TouchPlateConfiguration
};


/**
 * Root-level machine interface implementation
 */
export class Machine {
  private static _instance: IMachineInterface;

  private constructor() { }

  /**
   * Static method to get the machine interface instance
   */
  public static getInstance(): IMachineInterface {
    if (!Machine._instance) {
      Machine._instance = MachineInterfaceManager.Instance.getMachineInterface();
    }
    return Machine._instance;
  }

}
