import { Grid, Typography } from '@mui/material';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';

export function GantrySection() {
    const machine = MachineData.Instance;

    return (
        <Grid container spacing={3}>
            {/* Main Gantry Dimensions */}
            <Grid item xs={12}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                    Main Gantry Bar
                </Typography>
            </Grid>
            <Grid item xs={12}>
                <ObserveState
                    key="gantry-height"
                    listenTo={machine}
                    properties={['gantryHeight']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Gantry Height"
                            value={machine.gantryHeight}
                            onChange={(value) => machine.gantryHeight = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="gantry-bar-width"
                    listenTo={machine}
                    properties={['gantryBarWidth']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Gantry Bar Width"
                            value={machine.gantryBarWidth}
                            onChange={(value) => machine.gantryBarWidth = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="gantry-bar-height"
                    listenTo={machine}
                    properties={['gantryBarHeight']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Gantry Bar Height"
                            value={machine.gantryBarHeight}
                            onChange={(value) => machine.gantryBarHeight = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            {/* Support Posts */}
            <Grid item xs={12}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom sx={{ mt: 2 }}>
                    Support Posts
                </Typography>
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="gantry-support-width"
                    listenTo={machine}
                    properties={['gantrySupportWidth']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Post Width"
                            value={machine.gantrySupportWidth}
                            onChange={(value) => machine.gantrySupportWidth = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            {/* Extensions */}
            <Grid item xs={12}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom sx={{ mt: 2 }}>
                    Gantry Bar Extensions
                </Typography>
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="gantry-extension-left"
                    listenTo={machine}
                    properties={['gantryExtensionLeft']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Extension Left"
                            value={machine.gantryExtensionLeft}
                            onChange={(value) => machine.gantryExtensionLeft = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="gantry-extension-right"
                    listenTo={machine}
                    properties={['gantryExtensionRight']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Extension Right"
                            value={machine.gantryExtensionRight}
                            onChange={(value) => machine.gantryExtensionRight = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
        </Grid>
    );
}
