import { CNCPoint } from '../../data/CNCPoint';
import { CoordinateType } from '../../data/Common/CoordinateType';
import { CoordinateUtil } from '../CoordinateUtil';
import { ConfigurationData } from '../../data/ConfigurationData';

export enum MoveType {
    MDI,
    JogPad,
    Simulator,
    Coordinates
}

/**
 * Resolves undefined coordinates by filling them with base position values
 * and converts coordinates to MachineZero if needed
 */
export function resolveCoordinates(
    coordinateType: CoordinateType,
    x: number | undefined,
    y: number | undefined,
    z: number | undefined,
    a: number | undefined,
    basePosition: CNCPoint
): { x: number; y: number; z: number; a?: number } {
    if (coordinateType !== CoordinateType.MachineZero) {
        // If input is not already MachineZero, create a CNCPoint to handle conversion
        const inputPoint = new CNCPoint(
            x ?? basePosition.x, 
            y ?? basePosition.y, 
            z ?? basePosition.z, 
            coordinateType
        );
        const machinePoint = CoordinateUtil.toMachineZero(inputPoint);
        
        return {
            x: x !== undefined ? machinePoint.x : basePosition.x,
            y: y !== undefined ? machinePoint.y : basePosition.y,
            z: z !== undefined ? machinePoint.z : basePosition.z,
            a: a // A-axis doesn't need coordinate conversion (rotational axis)
        };
    } else {
        // Values are already MachineZero - resolve undefined coordinates with base position
        return {
            x: x ?? basePosition.x,
            y: y ?? basePosition.y,
            z: z ?? basePosition.z,
            a: a
        };
    }
}

/**
 * Gets the delay time for a specific move type
 */
export function getMoveDelayTime(moveType: MoveType, config: ConfigurationData): number {
    switch (moveType) {
        case MoveType.Simulator:
            return config.simulatorMoveDelay;
        case MoveType.JogPad:
            return config.jogPadMoveDelay;
        case MoveType.Coordinates:
            return config.coordinateMoveDelay;
        case MoveType.MDI:
            return config.mdiToolDelay;
        default:
            return config.coordinateMoveDelay;
    }
}

/**
 * Combines coordinates from two move actions, with the newer action taking precedence
 */
export function combineCoordinates(
    existingAction: { x: number; y: number; z: number; a?: number },
    newAction: { x: number; y: number; z: number; a?: number }
): { x: number; y: number; z: number; a?: number } {
    return {
        x: newAction.x, // Use the NEW action's resolved X
        y: newAction.y, // Use the NEW action's resolved Y  
        z: newAction.z, // Use the NEW action's resolved Z
        a: newAction.a  // Use the NEW action's A
    };
}

/**
 * Determines if a coordinate should be filled with base position value
 */
export function shouldFillCoordinate(value: number | undefined): boolean {
    return value === undefined;
}

/**
 * Creates a target position CNCPoint from resolved coordinates
 */
export function createTargetPosition(x: number, y: number, z: number, a?: number): CNCPoint {
    return new CNCPoint(x, y, z, CoordinateType.MachineZero);
}
