import { Download as DownloadIcon } from '@mui/icons-material';
import { Box, Button, Paper, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Typography } from '@mui/material';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { Declaration } from '../data/Declaration';
import { SystemDeclarationsDefaults } from '../data/SystemDeclarationsDefaults';

/**
 * Tab showing all system default declarations with their mappings
 * with export to CSV functionality
 */
export function DefaultMappingsTab() {
    const colors = ConfigurationDataColors.Instance;

    // Get all system declarations from defaults
    const allDeclarations = SystemDeclarationsDefaults.getDefaultDeclarations();

    // Group declarations by full category path (a/b/c)
    const declarationsByCategory = new Map<string, Declaration[]>();
    for (const decl of allDeclarations) {
        const categoryKey = decl.category.length > 0 ? decl.category.join(' > ') : 'Uncategorized';
        if (!declarationsByCategory.has(categoryKey)) {
            declarationsByCategory.set(categoryKey, []);
        }
        declarationsByCategory.get(categoryKey)!.push(decl);
    }

    // Sort categories alphabetically
    const sortedCategories = Array.from(declarationsByCategory.keys()).sort();

    const handleExportCSV = () => {
        try {
            // Create CSV header
            const headers = ['Name', 'Display Name', 'Type', 'Category', 'Mapped To', 'Read Only', 'Is System', 'Description'];
            const csvRows = [headers.join(',')];

            // Add data rows
            for (const decl of allDeclarations) {
                const row = [
                    escapeCSV(decl.name),
                    escapeCSV(decl.displayName || ''),
                    escapeCSV(decl.dataType),
                    escapeCSV(decl.category.join('; ')),
                    escapeCSV(decl.mappedToLocation || ''),
                    decl.readOnly ? 'Yes' : 'No',
                    decl.isSystem ? 'Yes' : 'No',
                    escapeCSV(decl.description || '')
                ];
                csvRows.push(row.join(','));
            }

            // Create CSV content
            const csvContent = csvRows.join('\n');

            // Create blob and download
            const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
            const link = document.createElement('a');
            const url = URL.createObjectURL(blob);
            link.setAttribute('href', url);
            link.setAttribute('download', `system_declarations_${new Date().toISOString().split('T')[0]}.csv`);
            link.style.visibility = 'hidden';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);

        } catch (error) {
            UserMessageQueue.Instance.addMessage('❌ Failed to export CSV');
        }
    };

    // Helper function to escape CSV values
    const escapeCSV = (value: string): string => {
        if (!value) return '';
        // Escape quotes and wrap in quotes if contains comma, quote, or newline
        const stringValue = String(value);
        if (stringValue.includes(',') || stringValue.includes('"') || stringValue.includes('\n')) {
            return `"${stringValue.replace(/"/g, '""')}"`;
        }
        return stringValue;
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
            {/* Header */}
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Box>
                    <Typography variant="h5" gutterBottom>
                        System Default Declarations
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                        All system declarations with their mappings to Centroid variables
                    </Typography>
                </Box>
                <Button
                    variant="contained"
                    startIcon={<DownloadIcon />}
                    onClick={handleExportCSV}
                    sx={{
                        backgroundColor: colors.primaryColor,
                        '&:hover': {
                            backgroundColor: colors.primaryColor,
                            opacity: 0.9
                        }
                    }}
                >
                    Export CSV
                </Button>
            </Box>

            {/* Table */}
            <TableContainer component={Paper} sx={{ flex: 1, overflow: 'auto' }}>
                <Table stickyHeader size="small">
                    <TableHead>
                        <TableRow>
                            <TableCell sx={{ fontWeight: 'bold', backgroundColor: colors.lightBackgroundColor, width: '180px' }}>Name</TableCell>
                            <TableCell sx={{ fontWeight: 'bold', backgroundColor: colors.lightBackgroundColor }}>Display Name</TableCell>
                            <TableCell sx={{ fontWeight: 'bold', backgroundColor: colors.lightBackgroundColor }}>Type</TableCell>
                            <TableCell sx={{ fontWeight: 'bold', backgroundColor: colors.lightBackgroundColor }}>Category</TableCell>
                            <TableCell sx={{ fontWeight: 'bold', backgroundColor: colors.lightBackgroundColor, width: '100px' }}>Mapped To</TableCell>
                            <TableCell sx={{ fontWeight: 'bold', backgroundColor: colors.lightBackgroundColor }}>Is System</TableCell>
                            <TableCell sx={{ fontWeight: 'bold', backgroundColor: colors.lightBackgroundColor }}>Read Only</TableCell>
                            <TableCell sx={{ fontWeight: 'bold', backgroundColor: colors.lightBackgroundColor }}>Description</TableCell>
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {sortedCategories.map((category) => {
                            const declarations = declarationsByCategory.get(category)!;
                            return (
                                <>
                                    {/* Category Header Row */}
                                    <TableRow key={`category-${category}`}>
                                        <TableCell
                                            colSpan={8}
                                            sx={{
                                                backgroundColor: colors.primaryColor,
                                                color: colors.lightTextColor,
                                                fontWeight: 'bold',
                                                fontSize: '0.95rem',
                                                py: 1
                                            }}
                                        >
                                            {category} ({declarations.length})
                                        </TableCell>
                                    </TableRow>
                                    {/* Declaration Rows */}
                                    {declarations.map((decl: Declaration, index: number) => (
                                        <TableRow
                                            key={`${category}-${decl.name}-${index}`}
                                            sx={{ '&:hover': { backgroundColor: `${colors.darkTextColor}0A` } }}
                                        >
                                            <TableCell sx={{ fontFamily: 'monospace', fontSize: '0.8rem' }}>{decl.name}</TableCell>
                                            <TableCell>{decl.displayName}</TableCell>
                                            <TableCell>{decl.dataType}</TableCell>
                                            <TableCell sx={{ fontSize: '0.8rem' }}>{decl.category.join(' > ')}</TableCell>
                                            <TableCell sx={{ fontFamily: 'monospace', color: colors.primaryColor, fontSize: '0.8rem' }}>
                                                {decl.mappedToLocation || '-'}
                                            </TableCell>
                                            <TableCell>{decl.isSystem ? 'Yes' : 'No'}</TableCell>
                                            <TableCell>{decl.readOnly ? 'Yes' : 'No'}</TableCell>
                                            <TableCell sx={{ fontSize: '0.875rem', color: 'text.secondary' }}>
                                                {decl.description}
                                            </TableCell>
                                        </TableRow>
                                    ))}
                                </>
                            );
                        })}
                    </TableBody>
                </Table>
            </TableContainer>
        </Box>
    );
}
