import { CheckCircle, RadioButtonUnchecked } from '@mui/icons-material';
import { Box, Button, Chip, Typography } from '@mui/material';
import { SetupChecklistLibrary } from '../../data/Checklist/SetupChecklistLibrary';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ObserveState } from '../../utils/statemanager/ObserveState';

export interface SetupChecklistIndicatorProps {
    /**
     * Name of the checklist item to display
     */
    name: string;
}

/**
 * Setup Checklist Indicator Component
 * Displays the status of a specific checklist item with completion button
 * Can be embedded in accordion sections throughout the setup pages
 */
export function SetupChecklistIndicator({ name }: SetupChecklistIndicatorProps) {
    const library = SetupChecklistLibrary.Instance;
    const item = library.getItemByName(name);

    // If item doesn't exist, don't render anything
    if (!item) {
        return null;
    }

    return (
        <ObserveState
            key={`setup-checklist-indicator-${name}`}
            listenTo={item}
            properties={['manuallyConfirmed']}
            control={() => {
                const colors = ConfigurationDataColors.Instance;

                const isCompleted = item.isCompleted();
                const needsManual = item.needsManualConfirmation();
                const checkPassed = item.completionCheck();
                const canAutoComplete = !isCompleted && checkPassed && needsManual && !item.manuallyConfirmed;
                const canReset = needsManual && item.manuallyConfirmed;

                const completedColor = colors.successColor;
                const incompleteColor = colors.errorColor;

                return (
                    <Box
                        sx={{
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'space-between',
                            p: 1.5,
                            borderRadius: 1,
                            backgroundColor: 'transparent',
                            border: `1px solid ${isCompleted ? completedColor : incompleteColor}`,
                            borderLeft: `6px solid ${isCompleted ? completedColor : incompleteColor}`,
                        }}
                    >
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, flex: 1 }}>
                            {isCompleted ? (
                                <CheckCircle
                                    sx={{
                                        color: completedColor,
                                        fontSize: '1.5rem',
                                    }}
                                />
                            ) : (
                                <RadioButtonUnchecked
                                    sx={{
                                        color: incompleteColor,
                                        fontSize: '1.5rem',
                                    }}
                                />
                            )}

                            <Box sx={{ flex: 1 }}>
                                <Typography
                                    variant="body2"
                                    sx={{
                                        fontWeight: 500,
                                        color: isCompleted ? 'text.secondary' : 'text.primary',
                                    }}
                                >
                                    {item.name}
                                </Typography>

                                {item.description && (
                                    <Typography
                                        variant="caption"
                                        color="text.secondary"
                                        sx={{ display: 'block', mt: 0.25 }}
                                    >
                                        {item.description}
                                    </Typography>
                                )}

                                <Box sx={{ display: 'flex', gap: 0.5, mt: 0.5 }}>
                                    {isCompleted ? (
                                        <Chip
                                            label="Configured"
                                            size="small"
                                            sx={{
                                                height: 18,
                                                fontSize: '0.65rem',
                                                backgroundColor: completedColor,
                                                color: colors.lightTextColor,
                                            }}
                                        />
                                    ) : (
                                        <Chip
                                            label="Not Configured"
                                            size="small"
                                            sx={{
                                                height: 18,
                                                fontSize: '0.65rem',
                                                backgroundColor: incompleteColor,
                                                color: colors.lightTextColor,
                                            }}
                                        />
                                    )}

                                    {!checkPassed && (
                                        <Chip
                                            label="Check Failed"
                                            size="small"
                                            variant="outlined"
                                            color="error"
                                            sx={{ height: 18, fontSize: '0.65rem' }}
                                        />
                                    )}
                                </Box>
                            </Box>
                        </Box>

                        <Box sx={{ display: 'flex', gap: 1 }}>
                            {canAutoComplete && (
                                <Button
                                    variant="contained"
                                    size="small"
                                    onClick={() => library.confirmItem(item)}
                                    sx={{
                                        fontSize: '0.75rem',
                                        backgroundColor: colors.primaryColor,
                                        '&:hover': {
                                            backgroundColor: colors.primaryColor,
                                            opacity: 0.9,
                                        },
                                    }}
                                >
                                    Complete
                                </Button>
                            )}

                            {canReset && (
                                <Button
                                    variant="outlined"
                                    size="small"
                                    onClick={() => library.resetItem(item)}
                                    sx={{
                                        fontSize: '0.75rem',
                                    }}
                                >
                                    Reset
                                </Button>
                            )}
                        </Box>
                    </Box>
                );
            }}
        />
    );
}
