import {
    Grid,
    Paper,
    Typography
} from '@mui/material';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';

export function CollisionDetectionSection() {
    const config = ConfigurationData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12}>

                <Paper sx={{ p: 3 }}>
                    <Typography variant="h6" gutterBottom>Safe Distance Settings</Typography>

                    <ObserveState
                        key="safe-xy-distance"
                        listenTo={config}
                        properties={['safeXYDistance']}
                        control={() => (
                            <NumberInput
                                fullWidth
                                label="Safe XY Distance (inches)"
                                value={config.safeXYDistance}
                                onChange={(value) => config.safeXYDistance = value}
                                margin="normal"
                                precision={1}
                                min={0}
                            />
                        )}
                    />

                    <ObserveState
                        key="safe-z-distance"
                        listenTo={config}
                        properties={['safeZDistance']}
                        control={() => (
                            <NumberInput
                                fullWidth
                                label="Safe Z Distance (inches)"
                                value={config.safeZDistance}
                                onChange={(value) => config.safeZDistance = value}
                                margin="normal"
                                precision={1}
                                min={0}
                            />
                        )}
                    />
                </Paper>
            </Grid>
        </Grid>
    );
}
