import { CheckCircle as SuccessIcon, FiberManualRecord as ActiveIcon, RadioButtonUnchecked as IncompleteIcon } from '@mui/icons-material';
import { Alert, Box, Button, Checkbox, FormControlLabel, Grid, Paper, Typography } from '@mui/material';
import React, { useState } from 'react';
import { Tool } from '../../../../data/Common/Tool';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { IOStateData } from '../../../../data/IOStateData';
import { PLCInputName } from '../../../../data/PLCIONames';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { WizardStep } from '../../../Wizard/WizardStep';
import { ToolMeasurementMethod, ToolMeasurementWizard } from '../ToolMeasurementWizard';
import { TriggerMeasureStep } from './TriggerMeasureStep';

/**
 * Step to confirm touchplate is working and positioned correctly
 */
export class ConfirmTouchplateStep extends WizardStep {
    private tool: Tool;
    private method: ToolMeasurementMethod;

    constructor(wizard: ToolMeasurementWizard, tool: Tool, previousStep: WizardStep | null, method: ToolMeasurementMethod) {
        super(wizard, previousStep);
        this.tool = tool;
        this.method = method;
    }

    getTitle(): string {
        return 'Confirm Touchplate';
    }

    nextStep(): WizardStep | null {
        return new TriggerMeasureStep(this.wizard as ToolMeasurementWizard, this.tool, this, this.method);
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return <ConfirmTouchplateStepComponent step={this} />;
    }
}

interface ConfirmTouchplateStepComponentProps {
    step: ConfirmTouchplateStep;
}

function ConfirmTouchplateStepComponent({ step }: ConfirmTouchplateStepComponentProps) {
    const wizard = step.wizard as ToolMeasurementWizard;
    const colors = ConfigurationDataColors.Instance;
    const [isPositioned, setIsPositioned] = useState(false);
    const [skipCheck, setSkipCheck] = useState(false);
    const [initialState, setInitialState] = useState<boolean | null>(null);
    const [stateChanged, setStateChanged] = useState(false);
    
    // Get the touchplate input once
    const touchPlateInput = IOStateData.Instance.getInputByName(PLCInputName.MaterialToolTouchPlate);

    const handleContinue = () => {
        wizard.advanceToNextStep();
    };

    // If no input configured, skip check automatically
    if (!touchPlateInput) {
        return (
            <Box sx={{ p: 4, display: 'flex', flexDirection: 'column', gap: 3, height: '100%', maxWidth: 800, mx: 'auto' }}>
                <Alert severity="warning">
                    <Typography variant="body2">
                        Touchplate input not configured. Skipping verification.
                    </Typography>
                </Alert>
                <Box sx={{ flex: 1 }} />
                <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 2, pt: 2, borderTop: `1px solid ${colors.borderColor}` }}>
                    <Button variant="outlined" onClick={() => wizard.goToPreviousStep()}>
                        BACK
                    </Button>
                    <Button variant="contained" onClick={handleContinue} sx={{ backgroundColor: colors.primaryColor }}>
                        MEASURE
                    </Button>
                </Box>
            </Box>
        );
    }

    return (
        <ObserveState
            key="touchplate-input-observer"
            listenTo={touchPlateInput}
            properties={['isActive']}
            control={() => {
                const isActive = touchPlateInput.isActive;

                // Record initial state on first render
                if (initialState === null) {
                    setInitialState(isActive);
                }

                // Detect state change from initial state
                if (initialState !== null && isActive !== initialState && !stateChanged) {
                    setStateChanged(true);
                }

                return (
                    <Box sx={{ p: 4, display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
                        <Typography variant="body1" color="text.secondary">
                            Before measuring, let's verify the touchplate is working correctly.
                        </Typography>

                        <Grid container spacing={3} sx={{ flex: 1 }}>
                            {/* Step 1: Touchplate Status */}
                            <Grid item xs={12} md={6}>
                                <Paper elevation={2} sx={{ p: 3, height: '100%', border: `2px solid ${skipCheck || stateChanged ? colors.successColor : colors.borderColor}` }}>
                                    <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 2, mb: 2 }}>
                                        <SuccessIcon 
                                            sx={{ 
                                                fontSize: 48, 
                                                color: (skipCheck || stateChanged) ? colors.successColor : colors.borderColor,
                                                opacity: (skipCheck || stateChanged) ? 1 : 0.3,
                                                mt: -0.5
                                            }} 
                                        />
                                        <Box sx={{ flex: 1 }}>
                                            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1 }}>
                                                <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
                                                    Step 1: Touchplate Status
                                                </Typography>
                                                <FormControlLabel
                                                    control={
                                                        <Checkbox
                                                            checked={skipCheck}
                                                            onChange={(e) => setSkipCheck(e.target.checked)}
                                                            sx={{
                                                                color: colors.borderColor,
                                                                '&.Mui-checked': {
                                                                    color: colors.primaryColor
                                                                }
                                                            }}
                                                        />
                                                    }
                                                    label={
                                                        <Typography variant="body2" color="text.secondary">
                                                            Skip
                                                        </Typography>
                                                    }
                                                />
                                            </Box>

                                            {skipCheck ? (
                                                        <Alert severity="warning">
                                                    <Typography variant="body2" fontWeight="bold">
                                                        Touchplate verification skipped
                                                    </Typography>
                                                </Alert>
                                            ) : (
                                                        <>
                                                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                                {initialState === null 
                                                    ? 'Detecting initial state...' 
                                                    : initialState 
                                                        ? 'Release the touchplate to verify it\'s working'
                                                        : 'Trigger the touchplate to verify it\'s working'
                                                }
                                            </Typography>
                                            
                                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
                                                <Typography variant="body2" fontWeight="bold">
                                                    Real-time Status:
                                                </Typography>
                                                <ActiveIcon 
                                                    sx={{ 
                                                        fontSize: 20, 
                                                        color: isActive ? colors.successColor : colors.borderColor,
                                                        animation: isActive ? 'pulse 1.5s ease-in-out infinite' : 'none',
                                                        '@keyframes pulse': {
                                                            '0%, 100%': { opacity: 1 },
                                                            '50%': { opacity: 0.5 }
                                                        }
                                                    }} 
                                                />
                                                <Typography variant="body2">
                                                    {isActive ? 'ACTIVE' : 'INACTIVE'}
                                                </Typography>
                                            </Box>
                                            
                                            {stateChanged ? (
                                                <Alert severity="success" icon={<SuccessIcon />}>
                                                    <Typography variant="body2" fontWeight="bold">
                                                        Touchplate state changed - working correctly!
                                                    </Typography>
                                                </Alert>
                                            ) : (
                                                <Alert severity="info">
                                                    <Typography variant="body2">
                                                        {initialState === null 
                                                            ? 'Waiting for initial state...'
                                                            : `Initial state: ${initialState ? 'ACTIVE' : 'INACTIVE'} - Waiting for change`
                                                        }
                                                    </Typography>
                                                        </Alert>
                                                    )}
                                                </>
                                            )}
                                        </Box>
                                    </Box>
                                </Paper>
                            </Grid>

                            {/* Step 2: Position Confirmation */}
                            <Grid item xs={12} md={6}>
                                <Paper elevation={2} sx={{ p: 3, height: '100%', border: `2px solid ${isPositioned ? colors.successColor : colors.borderColor}` }}>
                                    <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 2, mb: 2 }}>
                                        <SuccessIcon 
                                            sx={{ 
                                                fontSize: 48, 
                                                color: isPositioned ? colors.successColor : colors.borderColor,
                                                opacity: isPositioned ? 1 : 0.3,
                                                mt: -0.5
                                            }} 
                                        />
                                        <Box sx={{ flex: 1 }}>
                                            <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>
                                                Step 2: Confirm Position
                                            </Typography>
                                            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                                Ensure the touchplate is properly positioned under the tool before measuring
                                            </Typography>
                                            
                                            <FormControlLabel
                                                control={
                                                    <Checkbox
                                                        checked={isPositioned}
                                                        onChange={(e) => setIsPositioned(e.target.checked)}
                                                        sx={{
                                                            color: colors.borderColor,
                                                            '&.Mui-checked': {
                                                                color: colors.primaryColor
                                                            }
                                                        }}
                                                    />
                                                }
                                                label={
                                                    <Typography variant="body2" fontWeight="bold">
                                                        Touchplate is properly positioned
                                                    </Typography>
                                                }
                                            />
                                        </Box>
                                    </Box>
                                </Paper>
                            </Grid>
                        </Grid>

                        <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 2, pt: 2, borderTop: `1px solid ${colors.borderColor}` }}>
                            <Button
                                variant="outlined"
                                onClick={() => wizard.goToPreviousStep()}
                                sx={{
                                    borderColor: colors.borderColor,
                                    color: colors.darkTextColor
                                }}
                            >
                                BACK
                            </Button>
                            <Button
                                variant="contained"
                                onClick={handleContinue}
                                disabled={!((skipCheck || stateChanged) && isPositioned)}
                                sx={{ 
                                    backgroundColor: colors.primaryColor,
                                    color: colors.lightTextColor,
                                    '&:hover': {
                                        backgroundColor: colors.primaryColor,
                                        opacity: 0.9
                                    }
                                }}
                            >
                                MEASURE
                            </Button>
                        </Box>
                    </Box>
                );
            }}
        />
    );
}
