import {
  Alert,
  Box,
  CircularProgress,
  Paper,
  Typography
} from '@mui/material';
import { AppStateData } from '../data/AppStateData';
import { ConfigurationData } from '../data/ConfigurationData';
import { ConfigurationDataColors } from '../data/ConfigurationDataColors';
import { ObserveState } from '../utils/statemanager/ObserveState';

/**
 * LoadingSplashScreen displays while the application is initializing data
 * Shows loading spinner, progress messages, and error states if initialization fails
 */
export function LoadingSplashScreen() {
  const config = ConfigurationData.Instance;

  return (
    <ObserveState
      listenTo={AppStateData.Instance}
      properties={['isLoading', 'loadingMessage', 'initializationError']}
      control={() => {
        const appState = AppStateData.Instance;
        const colors = ConfigurationDataColors.Instance;

        return (
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              height: '100vh',
              backgroundColor: colors.lightBackgroundColor,
              padding: 3
            }}
          >
            <Paper
              elevation={8}
              sx={{
                padding: 6,
                borderRadius: 4,
                textAlign: 'center',
                maxWidth: 500,
                width: '100%',
                backgroundColor: colors.darkBackgroundColor,
                color: colors.lightTextColor
              }}
            >
              {/* App Title */}
              <Typography
                variant="h3"
                component="h1"
                gutterBottom
                sx={{
                  color: colors.primaryColor,
                  fontWeight: 'bold',
                  marginBottom: 3
                }}
              >
                HavenCNC
              </Typography>

              {/* Loading State */}
              {appState.isLoading && !appState.initializationError && (
                <>
                  <CircularProgress
                    size={60}
                    sx={{
                      color: colors.primaryColor,
                      marginBottom: 3
                    }}
                  />
                  <Typography
                    variant="h6"
                    sx={{
                      color: colors.lightTextColor,
                      marginBottom: 1
                    }}
                  >
                    {appState.loadingMessage}
                  </Typography>
                  <Typography
                    variant="body2"
                    sx={{
                      color: colors.mutedTextColor
                    }}
                  >
                    Initializing configuration and machine data...
                  </Typography>
                </>
              )}

              {/* Error State */}
              {appState.initializationError && (
                <Alert
                  severity="error"
                  sx={{
                    marginTop: 2,
                    backgroundColor: colors.errorColor + '20',
                    color: colors.lightTextColor,
                    '& .MuiAlert-icon': {
                      color: colors.errorColor
                    }
                  }}
                >
                  <Typography variant="h6" gutterBottom>
                    Initialization Failed
                  </Typography>
                  <Typography variant="body2">
                    {appState.initializationError}
                  </Typography>
                  <Typography variant="body2" sx={{ marginTop: 1, fontStyle: 'italic' }}>
                    The application will continue with default settings.
                  </Typography>
                </Alert>
              )}

              {/* Success State (brief display before main UI loads) */}
              {!appState.isLoading && !appState.initializationError && appState.isInitialized && (
                <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                  <Typography
                    variant="h6"
                    sx={{
                      color: colors.successColor,
                      marginBottom: 2
                    }}
                  >
                    ✓ Initialization Complete
                  </Typography>
                  <Typography
                    variant="body2"
                    sx={{
                      color: colors.mutedTextColor
                    }}
                  >
                    Loading main interface...
                  </Typography>
                </Box>
              )}
            </Paper>

            {/* Version Info */}
            <Typography
              variant="caption"
              sx={{
                color: colors.mutedTextColor,
                marginTop: 3,
                textAlign: 'center'
              }}
            >
              CNC Machine Control Interface
              <br />
              React/TypeScript with Three.js Visualization
            </Typography>
          </Box>
        );
      }}
    />
  );
}
