import { Tool } from "../../../data/Common/Tool";
import { MachineData } from "../../../data/Machine/MachineData";
import { IMachineCallback } from "../../../machine/IMachineCallback";
import { Wizard } from "../../Wizard/Wizard";
import { WizardManager } from "../../Wizard/WizardManager";
import { MoveToPositionStep } from "./steps/MoveToPositionStep";
import { SelectMethodStep } from "./steps/SelectMethodStep";

export enum ToolMeasurementMethod {
    AutoFixedTouchPlate = 'auto-fixed',
    ManualFixedPoint = 'manual-fixed',
    ManualSpoilboard = 'manual-spoilboard',
    ManualMachineBed = 'manual-machine-bed'
}

export interface ToolMeasurementWizardState {
    tool: Tool;
}

export class ToolMeasurementWizard extends Wizard<ToolMeasurementWizardState> {
    constructor(tool: Tool, callback?: IMachineCallback) {
        const initialState: ToolMeasurementWizardState = {
            tool
        };

        super(
            null as any, // Temporary - will be set below
            initialState,
            true, // canClose
            false, // clickAwayClose - don't allow accidental closure during operation
            '80%', // width
            '85%'  // height
        );

        // Set callback on wizard instance (WizardManager expects this)
        this.callback = callback;

        // Check if only one measurement method is configured
        const machineData = MachineData.Instance;
        const availableMethods: ToolMeasurementMethod[] = [];

        if (machineData.hasFixedTouchPlate) {
            availableMethods.push(ToolMeasurementMethod.AutoFixedTouchPlate);
        }
        if (machineData.fixedToolMeasurementPointEnabled) {
            availableMethods.push(ToolMeasurementMethod.ManualFixedPoint);
        }
        if (machineData.spoilboardToolMeasurementPointEnabled) {
            availableMethods.push(ToolMeasurementMethod.ManualSpoilboard);
        }
        if (machineData.machineBedToolMeasurementPointEnabled) {
            availableMethods.push(ToolMeasurementMethod.ManualMachineBed);
        }

        // If only one method is available, skip selection step and go directly to it
        let firstStep;
        if (availableMethods.length === 1) {
            const method = availableMethods[0];
            if (method === ToolMeasurementMethod.AutoFixedTouchPlate) {
                // TODO: Create auto measurement step when implemented
                // For now, fall back to selection step
                firstStep = new SelectMethodStep(this, tool, null);
            } else {
                // Skip to move-to-position step for manual methods
                firstStep = new MoveToPositionStep(this, tool, null, method);
            }
        } else {
            // Multiple or zero methods - show selection step
            firstStep = new SelectMethodStep(this, tool, null);
        }

        this.firstStep = firstStep;
        this.currentStep = firstStep;
    }

    /**
     * Show the tool measurement wizard for a specific tool
     */
    static show(tool: Tool, callback?: IMachineCallback): void {
        const wizard = new ToolMeasurementWizard(tool, callback);
        WizardManager.Instance.start(wizard);
    }
}
