import { LogCategory, Logger } from './Logger';

/**
 * Summary statistics for a profiled operation
 */
export interface ProfileSummary {
    name: string;
    count: number;
    minTime: number;
    maxTime: number;
    totalTime: number;
    averageTime: number;
}

/**
 * Hierarchical profile node with children
 */
export interface ProfileNode {
    name: string;
    count: number;
    minTime: number;
    maxTime: number;
    totalTime: number;
    averageTime: number;
    children: Map<string, ProfileNode>;
}

/**
 * Active capture tracking
 */
interface ActiveCapture {
    name: string;
    startTime: number;
    parent: ActiveCapture | null;
}

/**
 * Performance profiler with flat and hierarchical tracking
 * Tracks execution time of operations with support for nested profiling
 */
export class Profiler {
    private static _instance: Profiler;

    private _enabled: boolean = false;
    private _outputInterval: number = 0; // milliseconds, 0 = no output
    private _lastOutputTime: number = 0;

    // Flat data structure: name -> summary
    private _flatSummaries: Map<string, ProfileSummary> = new Map();

    // Hierarchical data structure: root nodes
    private _hierarchyRoots: Map<string, ProfileNode> = new Map();

    // Stack of currently active captures
    private _currentCapture: ActiveCapture | null = null;

    private constructor() {
        // Private constructor for singleton
    }

    public static get Instance(): Profiler {
        if (!Profiler._instance) {
            Profiler._instance = new Profiler();
        }
        return Profiler._instance;
    }

    /**
     * Enable or disable profiling
     */
    public get enabled(): boolean {
        return this._enabled;
    }

    public set enabled(value: boolean) {
        this._enabled = value;
        if (!value) {
            // Clear active captures when disabling
            this._currentCapture = null;
        }
    }

    /**
     * Set output interval in milliseconds
     * Set to 0 to disable automatic output
     */
    public get outputInterval(): number {
        return this._outputInterval;
    }

    public set outputInterval(value: number) {
        this._outputInterval = Math.max(0, value);
    }

    /**
     * Start capturing a profiled operation
     * @param name Name of the operation
     */
    public captureStart(name: string): void {
        if (!this._enabled) {
            return;
        }

        const capture: ActiveCapture = {
            name,
            startTime: performance.now(),
            parent: this._currentCapture
        };

        this._currentCapture = capture;
    }

    /**
     * End capturing a profiled operation
     * @param name Name of the operation (must match the current capture)
     */
    public captureEnd(name: string): void {
        if (!this._enabled || !this._currentCapture) {
            return;
        }

        // Verify name matches current capture
        if (this._currentCapture.name !== name) {
            Logger.Instance.logError(
                LogCategory.System,
                `Profiler: captureEnd('${name}') does not match current capture '${this._currentCapture.name}'`
            );
            return;
        }

        const endTime = performance.now();
        const duration = endTime - this._currentCapture.startTime;

        // Update flat summary
        this._updateFlatSummary(name, duration);

        // Update hierarchical summary
        this._updateHierarchySummary(name, duration, this._currentCapture.parent);

        // Pop to parent capture
        this._currentCapture = this._currentCapture.parent;

        // Check if we should output
        this._checkAutoOutput();
    }

    /**
     * Update flat summary with a new measurement
     */
    private _updateFlatSummary(name: string, duration: number): void {
        let summary = this._flatSummaries.get(name);

        if (!summary) {
            summary = {
                name,
                count: 0,
                minTime: Number.MAX_VALUE,
                maxTime: 0,
                totalTime: 0,
                averageTime: 0
            };
            this._flatSummaries.set(name, summary);
        }

        summary.count++;
        summary.minTime = Math.min(summary.minTime, duration);
        summary.maxTime = Math.max(summary.maxTime, duration);
        summary.totalTime += duration;
        summary.averageTime = summary.totalTime / summary.count;
    }

    /**
     * Update hierarchical summary with a new measurement
     */
    private _updateHierarchySummary(name: string, duration: number, parent: ActiveCapture | null): void {
        let targetMap: Map<string, ProfileNode>;

        if (parent === null) {
            // Root level
            targetMap = this._hierarchyRoots;
        } else {
            // Find or create parent node in hierarchy
            const parentNode = this._findOrCreateHierarchyPath(parent);
            targetMap = parentNode.children;
        }

        let node = targetMap.get(name);

        if (!node) {
            node = {
                name,
                count: 0,
                minTime: Number.MAX_VALUE,
                maxTime: 0,
                totalTime: 0,
                averageTime: 0,
                children: new Map()
            };
            targetMap.set(name, node);
        }

        node.count++;
        node.minTime = Math.min(node.minTime, duration);
        node.maxTime = Math.max(node.maxTime, duration);
        node.totalTime += duration;
        node.averageTime = node.totalTime / node.count;
    }

    /**
     * Find or create a node in the hierarchy for the given capture path
     */
    private _findOrCreateHierarchyPath(capture: ActiveCapture): ProfileNode {
        // Build path from root to this capture
        const path: string[] = [];
        let current: ActiveCapture | null = capture;
        while (current !== null) {
            path.unshift(current.name);
            current = current.parent;
        }

        // Navigate/create path in hierarchy
        let currentMap = this._hierarchyRoots;
        let currentNode: ProfileNode | undefined;

        for (const name of path) {
            currentNode = currentMap.get(name);
            if (!currentNode) {
                currentNode = {
                    name,
                    count: 0,
                    minTime: Number.MAX_VALUE,
                    maxTime: 0,
                    totalTime: 0,
                    averageTime: 0,
                    children: new Map()
                };
                currentMap.set(name, currentNode);
            }
            currentMap = currentNode.children;
        }

        return currentNode!;
    }

    /**
     * Check if we should auto-output based on interval
     */
    private _checkAutoOutput(): void {
        if (this._outputInterval <= 0) {
            return;
        }

        const now = performance.now();
        if (now - this._lastOutputTime >= this._outputInterval) {
            this.logOutput();
            this._lastOutputTime = now;
        }
    }

    /**
     * Clear all profiling data
     */
    public clear(): void {
        this._flatSummaries.clear();
        this._hierarchyRoots.clear();
        this._currentCapture = null;
        this._lastOutputTime = 0;
    }

    /**
     * Get flat summaries
     */
    public get flatSummaries(): Map<string, ProfileSummary> {
        return this._flatSummaries;
    }

    /**
     * Get hierarchical summaries
     */
    public get hierarchyRoots(): Map<string, ProfileNode> {
        return this._hierarchyRoots;
    }

    /**
     * Get flat summaries as array
     */
    public getFlatSummaries(): ProfileSummary[] {
        return Array.from(this._flatSummaries.values());
    }

    /**
     * Get hierarchical summaries as array
     */
    public getHierarchyRoots(): ProfileNode[] {
        return Array.from(this._hierarchyRoots.values());
    }

    /**
     * Log current profiling data to console
     */
    public logOutput(): void {
        if (this._flatSummaries.size === 0) {
            Logger.Instance.log(LogCategory.System, 'Profiler: No data collected');
            return;
        }

        Logger.Instance.log(LogCategory.System, '=== Profiler Flat Summary ===');
        const flatSorted = Array.from(this._flatSummaries.values())
            .sort((a, b) => b.totalTime - a.totalTime);

        for (const summary of flatSorted) {
            Logger.Instance.log(
                LogCategory.System,
                `  ${summary.name}: count=${summary.count}, ` +
                `min=${summary.minTime.toFixed(2)}ms, ` +
                `max=${summary.maxTime.toFixed(2)}ms, ` +
                `avg=${summary.averageTime.toFixed(2)}ms, ` +
                `total=${summary.totalTime.toFixed(2)}ms`
            );
        }

        Logger.Instance.log(LogCategory.System, '=== Profiler Hierarchy ===');
        this._logHierarchy(this._hierarchyRoots, 0);
    }

    /**
     * Recursively log hierarchy
     */
    private _logHierarchy(nodes: Map<string, ProfileNode>, indent: number): void {
        const indentStr = '  '.repeat(indent);

        for (const node of nodes.values()) {
            Logger.Instance.log(
                LogCategory.System,
                `${indentStr}${node.name}: count=${node.count}, ` +
                `min=${node.minTime.toFixed(2)}ms, ` +
                `max=${node.maxTime.toFixed(2)}ms, ` +
                `avg=${node.averageTime.toFixed(2)}ms, ` +
                `total=${node.totalTime.toFixed(2)}ms`
            );

            if (node.children.size > 0) {
                this._logHierarchy(node.children, indent + 1);
            }
        }
    }

    /**
     * Get current capture stack depth (for debugging)
     */
    public getCurrentDepth(): number {
        let depth = 0;
        let current = this._currentCapture;
        while (current !== null) {
            depth++;
            current = current.parent;
        }
        return depth;
    }
}
