import { Tooltip } from '@mui/material';
import { ReactNode } from 'react';
import { DeclarationTooltipBuilder } from '../data/DeclarationTooltipBuilder';
import { PLCProgram } from '../data/PLCProgram';
import { PLCProgramType, PLCUtilities } from '../data/PLCUtilities';

interface SymbolNameWithUsageTooltipProps {
    /** The centroid name of the symbol (input/output/trigger/etc.) */
    centroidName: string;
    /** The program type context (System or SystemDefault) */
    programType: PLCProgramType;
    /** The content to wrap with the tooltip (e.g., Typography displaying the name) */
    children: ReactNode;
}

/**
 * Wrapper component that shows declaration usage information when hovering over symbol names
 * Uses the existing DeclarationTooltipBuilder system for consistent tooltip appearance
 * Used in InputsTab, OutputsTab, UITriggersTab, M94M95TriggersTab to show usage on hover
 */
export function SymbolNameWithUsageTooltip({
    centroidName,
    programType,
    children
}: SymbolNameWithUsageTooltipProps) {
    // Get the program with correct context (System vs SystemDefault)
    const program = PLCProgram.Instance(programType);

    // Find the declaration for this symbol name
    const declaration = PLCUtilities.getDeclarationByName(program, centroidName);

    // Build tooltip content using the shared utility (shows usage, type, visibility, category, etc.)
    const tooltipContent = DeclarationTooltipBuilder.buildTooltip(
        declaration,
        program,
        false // isEmpty - we know it exists since it's in the tab
    );

    return (
        <Tooltip
            title={tooltipContent}
            placement="top"
            arrow
            {...DeclarationTooltipBuilder.getTooltipProps()}
            disableInteractive
        >
            <span style={{ cursor: 'help' }}>
                {children}
            </span>
        </Tooltip>
    );
}
