import { Button, FormControlLabel, Grid, Switch, Typography } from '@mui/material';
import { ConfigurationState } from '../../../../data/ConfigurationState';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';
import { SetupChecklistIndicator } from '../../../Common/SetupChecklistIndicator';

export function MachineBedToolMeasurementSection() {
    const machine = MachineData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12}>
                <ObserveState
                    key="machine-bed-tool-measurement-enabled"
                    listenTo={machine}
                    properties={['machineBedToolMeasurementPointEnabled']}
                    control={() => (
                        <FormControlLabel
                            control={
                                <Switch
                                    checked={machine.machineBedToolMeasurementPointEnabled}
                                    onChange={(e) => machine.machineBedToolMeasurementPointEnabled = e.target.checked}
                                />
                            }
                            label="Enable Machine Bed Tool Measurement Point"
                        />
                    )}
                />
            </Grid>

            <ObserveState
                key="machine-bed-tool-measurement-config"
                listenTo={machine}
                properties={['machineBedToolMeasurementPointEnabled']}
                control={() => {
                    if (!machine.machineBedToolMeasurementPointEnabled) {
                        return null;
                    }
                    return (
                        <>
                            <Grid item xs={12}>
                                <SetupChecklistIndicator name="Machine Bed Tool Measurement Position" />
                            </Grid>

                            <Grid item xs={12}>
                                <ObserveState
                                    key="machine-bed-tool-measurement-x"
                                    listenTo={machine}
                                    properties={['machineBedToolMeasurementPointX']}
                                    control={() => (
                                        <>
                                            <NumberInput
                                                label="X Position"
                                                value={machine.machineBedToolMeasurementPointX}
                                                onChange={(value) => machine.machineBedToolMeasurementPointX = value}
                                                margin="normal"
                                                precision={3}
                                                sx={{ width: '150px' }}
                                            />
                                            <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }}>
                                                X coordinate from Machine Zero
                                            </Typography>
                                        </>
                                    )}
                                />
                            </Grid>

                            <Grid item xs={12}>
                                <ObserveState
                                    key="machine-bed-tool-measurement-y"
                                    listenTo={machine}
                                    properties={['machineBedToolMeasurementPointY']}
                                    control={() => (
                                        <>
                                            <NumberInput
                                                label="Y Position"
                                                value={machine.machineBedToolMeasurementPointY}
                                                onChange={(value) => machine.machineBedToolMeasurementPointY = value}
                                                margin="normal"
                                                precision={3}
                                                sx={{ width: '150px' }}
                                            />
                                            <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }}>
                                                Y coordinate from Machine Zero
                                            </Typography>
                                        </>
                                    )}
                                />
                            </Grid>

                            <Grid item xs={12}>
                                <Button
                                    variant="outlined"
                                    onClick={() => {
                                        const currentPos = ConfigurationState.Instance.currentMachinePoint;
                                        machine.machineBedToolMeasurementPointX = currentPos.x;
                                        machine.machineBedToolMeasurementPointY = currentPos.y;
                                    }}
                                >
                                    Capture Current X/Y Position
                                </Button>
                            </Grid>
                        </>
                    );
                }}
            />
        </Grid>
    );
}
