import AddIcon from '@mui/icons-material/Add';
import {
    Box,
    Button,
    Link,
    Menu,
    MenuItem,
    Typography
} from '@mui/material';
import { useEffect, useRef, useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { TooltipManager } from '../../../utils/TooltipManager';
import { PLCRenderMode } from '../data/IPLCElement';
import { PLCProgramType } from '../data/PLCUtilities';
import { BasePLCPredicate } from '../predicates/BasePLCPredicate';
import { PredicateType, PredicateUtilities } from '../predicates/PredicateUtilities';
import { IsChangedStatement } from '../statements/IsChangedStatement';
import { ConditionGroupEditor } from './ConditionGroupEditor';
import { IsChangedStructureDialog } from './IsChangedStructureDialog';

interface IsChangedStatementEditorProps {
    statement: IsChangedStatement;
    onChanged?: () => void;
    renderMode?: PLCRenderMode;
    targetProgramType: PLCProgramType;
}

/**
 * IsChangedStatementEditor - UI component for editing IsChanged statements
 * Code-like minimal UI: if ( [conditions] ) then { [actions] }
 */
export function IsChangedStatementEditor(props: IsChangedStatementEditorProps) {
    const { statement: logicStatement, onChanged, renderMode = PLCRenderMode.Edit, targetProgramType } = props;
    const [addPredicateMenuAnchor, setAddPredicateMenuAnchor] = useState<null | HTMLElement>(null);
    const [addElsePredicateMenuAnchor, setAddElsePredicateMenuAnchor] = useState<null | HTMLElement>(null);
    const [structureDialogOpen, setStructureDialogOpen] = useState(false);
    const anchorRef = useRef<HTMLElement | null>(null);
    const menuCloseTimeoutRef = useRef<NodeJS.Timeout | null>(null);
    const colors = ConfigurationDataColors.Instance;

    const isDisabled = renderMode === PLCRenderMode.Disabled || logicStatement.isDisabled(renderMode, targetProgramType);
    const isEditable = renderMode === PLCRenderMode.Edit;

    // Cleanup timeout on unmount
    useEffect(() => {
        return () => {
            if (menuCloseTimeoutRef.current) {
                clearTimeout(menuCloseTimeoutRef.current);
            }
        };
    }, []);

    const scheduleMenuClose = (setMenuAnchor: (anchor: null | HTMLElement) => void) => {
        // Clear any existing timeout
        if (menuCloseTimeoutRef.current) {
            clearTimeout(menuCloseTimeoutRef.current);
        }
        // Schedule close after delay
        menuCloseTimeoutRef.current = setTimeout(() => {
            setMenuAnchor(null);
        }, 300);
    };

    const cancelMenuClose = () => {
        if (menuCloseTimeoutRef.current) {
            clearTimeout(menuCloseTimeoutRef.current);
            menuCloseTimeoutRef.current = null;
        }
    };

    const handleConditionChanged = () => {
        onChanged?.();
    };

    const handleAddPredicate = (predicateType: PredicateType) => {
        console.log('[IsChangedStatementEditor] handleAddPredicate called with:', predicateType);
        // Create predicate based on type
        let newPredicate: BasePLCPredicate | null = null;

        // Get predicate type info to determine if it can be created
        const predicateTypes = PredicateUtilities.getPredicateTypes();
        const typeInfo = predicateTypes.find(pt => pt.type === predicateType);

        if (typeInfo) {
            // Use PredicateUtilities factory to create the predicate
            try {
                newPredicate = PredicateUtilities.createPredicate(predicateType);
                console.log('[IsChangedStatementEditor] Created predicate:', newPredicate);
            } catch (error) {
                console.warn(`Predicate type ${predicateType} not yet implemented for creation:`, error);
            }
        }

        if (newPredicate) {
            console.log('[IsChangedStatementEditor] Adding rising edge predicate');
            logicStatement.addRisingEdgePredicate(newPredicate);
            onChanged?.();
        } else {
            console.warn('[IsChangedStatementEditor] Failed to create predicate for type:', predicateType);
        }

        setAddPredicateMenuAnchor(null);
    };

    const handleRemovePredicate = (predicate: BasePLCPredicate) => {
        logicStatement.removeRisingEdgePredicate(predicate);
        onChanged?.();
    };

    const handleAddElsePredicate = (predicateType: PredicateType) => {
        // Create predicate based on type
        let newPredicate: BasePLCPredicate | null = null;

        // Get predicate type info to determine if it can be created
        const predicateTypes = PredicateUtilities.getPredicateTypes();
        const typeInfo = predicateTypes.find(pt => pt.type === predicateType);

        if (typeInfo) {
            // Use PredicateUtilities factory to create the predicate
            try {
                newPredicate = PredicateUtilities.createPredicate(predicateType);
            } catch (error) {
                console.warn(`Predicate type ${predicateType} not yet implemented for creation:`, error);
            }
        }

        if (newPredicate) {
            logicStatement.addFallingEdgePredicate(newPredicate);
            onChanged?.();
        }

        setAddElsePredicateMenuAnchor(null);
    };

    const handleRemoveElsePredicate = (predicate: BasePLCPredicate) => {
        logicStatement.removeFallingEdgePredicate(predicate);
        onChanged?.();
    };

    // Get available predicate types for the menu
    const availablePredicateTypes = PredicateUtilities.getPredicateTypes();

    // Style for disabled mode - strikethrough text and reduced opacity
    // Use textDecorationLine which is harder to override than textDecoration
    const containerStyle = isDisabled ? {
        opacity: 0.6,
        textDecorationLine: 'line-through',
        '& *, & *::before, & *::after': {
            textDecorationLine: 'line-through !important',
            textDecoration: 'line-through !important'
        }
    } : {};

    // Determine if condition is disabled
    const isConditionDisabled = logicStatement.conditionGroup?.isDisabled(PLCRenderMode.Edit, targetProgramType) ?? false;

    // Helper to check if all predicates in an array are disabled
    const areAllPredicatesDisabled = (predicates: BasePLCPredicate[]): boolean => {
        if (predicates.length === 0) return false;
        return predicates.every(p => p.isDisabled(PLCRenderMode.Edit, targetProgramType));
    };

    return (
        <ObserveState
            key="logic-statement-editor"
            listenTo={logicStatement}
            properties={['conditionGroup', 'risingEdgePredicates', 'fallingEdgePredicates', 'hideRisingEdgeActions', 'hideFallingEdgeActions', 'skipInitial']}
            control={() => (
                <Box sx={{ fontFamily: 'monospace', fontSize: '14px', py: 1, ...containerStyle }}>
                    {/* when [condition group] changes (on every change/after initialization): */}
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Typography sx={{
                            color: colors.primaryColor,
                            fontWeight: 'bold',
                            fontFamily: 'monospace',
                            textDecoration: isConditionDisabled ? 'line-through' : 'none'
                        }}>
                            when
                        </Typography>
                        <ConditionGroupEditor
                            conditionGroup={logicStatement.conditionGroup}
                            onChanged={handleConditionChanged}
                            isRoot={false}
                            renderMode={isConditionDisabled ? PLCRenderMode.Disabled : renderMode}
                            targetProgramType={targetProgramType}
                        />
                        <Typography sx={{
                            color: colors.primaryColor,
                            fontWeight: 'bold',
                            fontFamily: 'monospace',
                            textDecoration: isConditionDisabled ? 'line-through' : 'none'
                        }}>
                            changes
                        </Typography>
                        <Typography
                            sx={{
                                color: colors.mutedTextColor,
                                fontFamily: 'monospace',
                                fontSize: '14px',
                                fontStyle: 'italic',
                                textDecoration: isEditable && !isConditionDisabled ? 'underline' : isConditionDisabled ? 'line-through' : 'none',
                                cursor: isEditable && !isConditionDisabled ? 'pointer' : 'default',
                                '&:hover': isEditable && !isConditionDisabled ? { color: colors.primaryColor } : {}
                            }}
                            onClick={() => {
                                if (isEditable && !isConditionDisabled) {
                                    logicStatement.skipInitial = !logicStatement.skipInitial;
                                    onChanged?.();
                                }
                            }}
                        >
                            ({logicStatement.skipInitial ? 'after initialization' : 'on every change'})
                        </Typography>
                        {isEditable && (
                            <Link
                                component="button"
                                onClick={() => setStructureDialogOpen(true)}
                                sx={{
                                    color: colors.primaryColor,
                                    ml: 1,
                                    textDecoration: 'none',
                                    fontFamily: 'monospace',
                                    fontSize: '14px',
                                    cursor: 'pointer',
                                    '&:hover': {
                                        textDecoration: 'underline'
                                    }
                                }}
                                title="Configure IsChanged structure"
                            >
                                edit branches
                            </Link>
                        )}
                    </Box>

                    {/* to set (true) - green */}
                    {!logicStatement.hideRisingEdgeActions && (
                        <Box sx={{ display: 'flex', alignItems: 'stretch', gap: 1, mt: 1, ml: 2 }}>
                            <Typography sx={{
                                color: ConfigurationDataColors.Instance.successColor,
                                fontWeight: 'bold',
                                fontFamily: 'monospace',
                                mt: 0.5,
                                width: '200px',
                                textDecoration: (isConditionDisabled || areAllPredicatesDisabled(logicStatement.risingEdgePredicates)) ? 'line-through' : 'none'
                            }}>
                                to set (true)
                            </Typography>
                            <Box sx={{ display: 'inline-flex', alignItems: 'stretch', borderTop: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}`, borderBottom: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}` }}>
                                <Box sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '24px',
                                    mr: 0.5,
                                    width: '10px',
                                    borderLeft: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                    display: 'flex',
                                    flexDirection: 'column',
                                    alignItems: 'center',
                                    justifyContent: 'center'
                                }}></Box>
                                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, py: 0.5 }}
                                >
                                    {logicStatement.risingEdgePredicates.length === 0 ? (
                                        isEditable && (
                                            <Button
                                                size="small"
                                                startIcon={<AddIcon />}
                                                onClick={(e) => setAddPredicateMenuAnchor(e.currentTarget)}
                                                sx={{
                                                    color: colors.primaryColor,
                                                    textTransform: 'none',
                                                    '&:hover': { backgroundColor: `${colors.primaryColor}20` }
                                                }}
                                            >
                                                add action
                                            </Button>
                                        )
                                    ) : (
                                        <Box>
                                            {logicStatement.risingEdgePredicates.map((predicate, index) => (
                                                <Box
                                                    key={index}
                                                    onMouseDown={(e) => {
                                                        // Hide tooltip when clicking on interactive elements
                                                        const target = e.target as HTMLElement;
                                                        if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.closest('button')) {
                                                            TooltipManager.Instance.hideTooltip();
                                                        }
                                                    }}
                                                    onMouseEnter={(e) => {
                                                        if (isEditable) {
                                                            anchorRef.current = e.currentTarget;
                                                            const rect = e.currentTarget.getBoundingClientRect();
                                                            const predicateTypeName = predicate.constructor.name.replace('Predicate', '');
                                                            TooltipManager.Instance.showTooltip(
                                                                <Box sx={{
                                                                    display: 'flex',
                                                                    flexDirection: 'column',
                                                                    minWidth: 150,
                                                                    bgcolor: 'background.paper',
                                                                    borderRadius: 1,
                                                                    boxShadow: 2,
                                                                    border: `1px solid ${colors.borderColor}`
                                                                }}>
                                                                    <MenuItem
                                                                        onClick={() => {
                                                                            console.log('[IsChangedStatementEditor] Add Action clicked for rising edge, anchorRef.current:', anchorRef.current);
                                                                            if (anchorRef.current) {
                                                                                setAddPredicateMenuAnchor(anchorRef.current);
                                                                                console.log('[IsChangedStatementEditor] Opening rising edge predicate menu');
                                                                                TooltipManager.Instance.hideTooltip();
                                                                            } else {
                                                                                console.warn('[IsChangedStatementEditor] anchorRef.current is null, cannot open menu');
                                                                            }
                                                                        }}
                                                                        sx={{
                                                                            py: 1,
                                                                            px: 2,
                                                                            fontSize: '14px',
                                                                            '&:hover': { backgroundColor: `${colors.primaryColor}20` }
                                                                        }}
                                                                    >
                                                                        Add Action
                                                                    </MenuItem>
                                                                    <MenuItem
                                                                        onClick={() => {
                                                                            handleRemovePredicate(predicate);
                                                                            TooltipManager.Instance.hideTooltip();
                                                                        }}
                                                                        sx={{
                                                                            py: 1,
                                                                            px: 2,
                                                                            fontSize: '14px',
                                                                            color: 'error.main',
                                                                            '&:hover': {
                                                                                backgroundColor: 'error.main',
                                                                                color: colors.lightTextColor
                                                                            }
                                                                        }}
                                                                    >
                                                                        Delete {predicateTypeName}
                                                                    </MenuItem>
                                                                </Box>,
                                                                { top: rect.top, left: rect.right + 5 }
                                                            );
                                                        }
                                                    }}
                                                    onMouseLeave={() => {
                                                        if (isEditable) {
                                                            TooltipManager.Instance.hideTooltipWithDelay(300);
                                                        }
                                                    }}
                                                    sx={{
                                                        mb: 0.5,
                                                        '&:hover': isEditable ? {
                                                            backgroundColor: `${colors.primaryColor}10`,
                                                            borderRadius: 1
                                                        } : {}
                                                    }}
                                                >
                                                    {predicate.render(isDisabled ? PLCRenderMode.Disabled : renderMode, targetProgramType)}
                                                </Box>
                                            ))}
                                        </Box>
                                    )}
                                </Box>
                                <Box sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '24px',
                                    ml: 0.5,
                                    width: '10px',
                                    borderRight: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                    display: 'flex',
                                    flexDirection: 'column',
                                    alignItems: 'center',
                                    justifyContent: 'center'
                                }}></Box>
                            </Box>
                        </Box>
                    )}

                    {/* to reset (false) - red */}
                    {!logicStatement.hideFallingEdgeActions && (
                        <Box sx={{ display: 'flex', alignItems: 'stretch', gap: 1, mt: 1, ml: 2 }}>
                            <Typography sx={{
                                color: ConfigurationDataColors.Instance.errorColor,
                                fontWeight: 'bold',
                                fontFamily: 'monospace',
                                mt: 0.5,
                                width: '200px',
                                textDecoration: (isConditionDisabled || areAllPredicatesDisabled(logicStatement.fallingEdgePredicates)) ? 'line-through' : 'none'
                            }}>
                                to reset (false)
                            </Typography>
                            <Box sx={{ display: 'inline-flex', alignItems: 'stretch', borderTop: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}`, borderBottom: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}` }}>
                                <Box sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '24px',
                                    mr: 0.5,
                                    width: '10px',
                                    borderLeft: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                    display: 'flex',
                                    flexDirection: 'column',
                                    alignItems: 'center',
                                    justifyContent: 'center'
                                }}></Box>
                                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, py: 0.5 }}>
                                    {logicStatement.fallingEdgePredicates.length === 0 ? (
                                        <Button
                                            size="small"
                                            onClick={(e) => setAddElsePredicateMenuAnchor(e.currentTarget)}
                                            sx={{
                                                color: colors.mutedTextColor,
                                                fontStyle: 'italic',
                                                fontSize: '14px',
                                                textTransform: 'none',
                                                minHeight: '28px',
                                                '&:hover': {
                                                    color: colors.primaryColor,
                                                    backgroundColor: `${colors.primaryColor}10`
                                                }
                                            }}
                                        >
                                            click to add action
                                        </Button>
                                    ) : (
                                        <Box>
                                            {logicStatement.fallingEdgePredicates.map((predicate, index) => (
                                                <Box
                                                    key={index}
                                                    onMouseDown={(e) => {
                                                        // Hide tooltip when clicking on interactive elements
                                                        const target = e.target as HTMLElement;
                                                        if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.closest('button')) {
                                                            TooltipManager.Instance.hideTooltip();
                                                        }
                                                    }}
                                                    onMouseEnter={(e) => {
                                                        if (isEditable) {
                                                            anchorRef.current = e.currentTarget;
                                                            const rect = e.currentTarget.getBoundingClientRect();
                                                            const predicateTypeName = predicate.constructor.name.replace('Predicate', '');
                                                            TooltipManager.Instance.showTooltip(
                                                                <Box sx={{
                                                                    display: 'flex',
                                                                    flexDirection: 'column',
                                                                    minWidth: 150,
                                                                    bgcolor: 'background.paper',
                                                                    borderRadius: 1,
                                                                    boxShadow: 2,
                                                                    border: `1px solid ${colors.borderColor}`
                                                                }}>
                                                                    <MenuItem
                                                                        onClick={() => {
                                                                            if (anchorRef.current) {
                                                                                setAddElsePredicateMenuAnchor(anchorRef.current);
                                                                                TooltipManager.Instance.hideTooltip();
                                                                            }
                                                                        }}
                                                                        sx={{
                                                                            py: 1,
                                                                            px: 2,
                                                                            fontSize: '14px',
                                                                            '&:hover': { backgroundColor: `${colors.primaryColor}20` }
                                                                        }}
                                                                    >
                                                                        Add Action
                                                                    </MenuItem>
                                                                    <MenuItem
                                                                        onClick={() => {
                                                                            handleRemoveElsePredicate(predicate);
                                                                            TooltipManager.Instance.hideTooltip();
                                                                        }}
                                                                        sx={{
                                                                            py: 1,
                                                                            px: 2,
                                                                            fontSize: '14px',
                                                                            color: 'error.main',
                                                                            '&:hover': {
                                                                                backgroundColor: 'error.main',
                                                                                color: colors.lightTextColor
                                                                            }
                                                                        }}
                                                                    >
                                                                        Delete {predicateTypeName}
                                                                    </MenuItem>
                                                                </Box>,
                                                                { top: rect.top, left: rect.right + 5 }
                                                            );
                                                        }
                                                    }}
                                                    onMouseLeave={() => {
                                                        if (isEditable) {
                                                            TooltipManager.Instance.hideTooltipWithDelay(300);
                                                        }
                                                    }}
                                                    sx={{
                                                        mb: 0.5,
                                                        '&:hover': isEditable ? {
                                                            backgroundColor: `${colors.primaryColor}10`,
                                                            borderRadius: 1
                                                        } : {}
                                                    }}
                                                >
                                                    {predicate.render(isDisabled ? PLCRenderMode.Disabled : renderMode, targetProgramType)}
                                                </Box>
                                            ))}
                                        </Box>
                                    )}
                                </Box>
                                <Box sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '24px',
                                    ml: 0.5,
                                    width: '10px',
                                    borderRight: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                    display: 'flex',
                                    flexDirection: 'column',
                                    alignItems: 'center',
                                    justifyContent: 'center'
                                }}></Box>
                            </Box>
                        </Box>
                    )}

                    {/* Add Action Menu */}
                    <Menu
                        anchorEl={addPredicateMenuAnchor}
                        open={Boolean(addPredicateMenuAnchor)}
                        onClose={() => {
                            setAddPredicateMenuAnchor(null);
                        }}
                        slotProps={{
                            paper: {
                                onMouseEnter: cancelMenuClose,
                                onMouseLeave: () => scheduleMenuClose(setAddPredicateMenuAnchor)
                            }
                        }}
                        anchorOrigin={{
                            vertical: 'bottom',
                            horizontal: 'left',
                        }}
                        transformOrigin={{
                            vertical: 'top',
                            horizontal: 'left',
                        }}
                    >
                        {availablePredicateTypes.map((typeInfo) => (
                            <MenuItem
                                key={typeInfo.type}
                                onClick={() => handleAddPredicate(typeInfo.type)}
                            >
                                <Box>
                                    <Typography variant="body2">{typeInfo.displayName}</Typography>
                                    {typeInfo.description && (
                                        <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                                            {typeInfo.description}
                                        </Typography>
                                    )}
                                </Box>
                            </MenuItem>
                        ))}
                    </Menu>

                    {/* Add Else Action Menu */}
                    <Menu
                        anchorEl={addElsePredicateMenuAnchor}
                        open={Boolean(addElsePredicateMenuAnchor)}
                        onClose={() => {
                            setAddElsePredicateMenuAnchor(null);
                        }}
                        slotProps={{
                            paper: {
                                onMouseEnter: cancelMenuClose,
                                onMouseLeave: () => scheduleMenuClose(setAddElsePredicateMenuAnchor)
                            }
                        }}
                        anchorOrigin={{
                            vertical: 'bottom',
                            horizontal: 'left',
                        }}
                        transformOrigin={{
                            vertical: 'top',
                            horizontal: 'left',
                        }}
                    >
                        {availablePredicateTypes.map((typeInfo) => (
                            <MenuItem
                                key={typeInfo.type}
                                onClick={() => handleAddElsePredicate(typeInfo.type)}
                            >
                                <Box>
                                    <Typography variant="body2">{typeInfo.displayName}</Typography>
                                    {typeInfo.description && (
                                        <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                                            {typeInfo.description}
                                        </Typography>
                                    )}
                                </Box>
                            </MenuItem>
                        ))}
                    </Menu>

                    {/* Structure Dialog */}
                    <IsChangedStructureDialog
                        isChanged={logicStatement}
                        open={structureDialogOpen}
                        onClose={() => setStructureDialogOpen(false)}
                    />
                </Box>
            )}
        />
    );
}
