import { CentroidMachineInterface } from '../centroid/CentroidMachineInterface';
import { SimulatorMachineInterface } from '../simulator/SimulatorMachineInterface';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';

/**
 * Register machine interface factories.
 * Must be called before MachineInterfaceManager.initialize().
 */
MachineInterfaceManager.registerFactory('simulator', () => new SimulatorMachineInterface());
MachineInterfaceManager.registerFactory('centroid', () => new CentroidMachineInterface());
