import { StateManager } from '../../utils/statemanager/StateManager';
import { MachineData } from '../Machine/MachineData';
import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * ATC Setup Checklist Item
 * Manual checklist item that requires confirmation that the ATC is properly configured.
 * Only appears when the machine has ATC enabled.
 */
export class ATCSetupChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'ATC Setup',
            'Confirm ATC configuration including tool holder count and positions'
        );

        // Listen for changes to hasATC to trigger re-evaluation
        const machine = MachineData.Instance;
        StateManager.addObserver(machine, () => {
            StateManager.propertyChanged(this, 'manuallyConfirmed');
        }, ['hasATC']);
    }

    /**
     * Only include this item when ATC is enabled
     */
    public shouldInclude(): boolean {
        return MachineData.Instance.hasATC;
    }

    /**
     * This is a manual checklist item - requires user confirmation
     */
    public needsManualConfirmation(): boolean {
        return true;
    }

    /**
     * Validation check: Returns true if ATC is disabled (N/A) or if enabled and configured
     */
    public completionCheck(): boolean {
        const machine = MachineData.Instance;

        // If ATC is disabled, this item is N/A (considered complete)
        if (!machine.hasATC) {
            return true;
        }

        // If ATC is enabled, this is a manual confirmation item
        // The actual validation is manual - user must confirm setup is complete
        return true;
    }

    public clone(): ATCSetupChecklistItem {
        const cloned = new ATCSetupChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
