import { ChevronLeft, ChevronRight } from '@mui/icons-material';
import { Box, Theme, Typography } from '@mui/material';
import { createTheme } from '@mui/material/styles';
import { Component } from 'react';
import { PLCEditorApp } from '../../centroid/plc/editor/PLCEditorApp';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { ObserveMultiProperties } from '../../utils/statemanager/ObserveMultiProperties';
import { JogControlsWindow } from '../Common/JogControlsWindow';
import { ViewerWindow } from '../Common/ViewerWindow';
import { ActionsPanel } from './ActionsPanel';
import { ControlPanel } from './ControlPanel';
import { InputOutputDrawer } from './InputOutputDrawer';
import { MillingWorkflowState } from '../../data/MillingWorkflowState';
import { LeftNavigation } from './LeftNavigation';
import { LogViewerDrawer } from './LogViewerDrawer';
import { MainContent } from './MainContent';
import { RightSidebar } from './RightSidebar';
import { SignalRMessagesDrawer } from './SignalRMessagesDrawer';

const DRAWER_WIDTH = 100;
const CONTROL_PANEL_WIDTH = 700; // Width of the drawer
const MAIN_CONTENT_WIDTH = 1200; // Main content constrained to 1200px

interface HavenCNCLayoutProps {
  isFullscreen?: boolean;
  onToggleFullscreen?: () => void;
}

type DrawerType = 'control' | 'actions' | 'logs' | 'io' | 'signalr' | null;

interface HavenCNCLayoutState {
  selectedView: string;
  activeDrawer: DrawerType;
  drawerOpen: boolean;
  isPLCEditorOpen: boolean;
}

export class HavenCNCLayout extends Component<HavenCNCLayoutProps, HavenCNCLayoutState> {
  private theme: Theme;

  constructor(props: HavenCNCLayoutProps) {
    super(props);
    this.theme = createTheme();
    const initialView = 'home';
    this.state = {
      selectedView: initialView,
      activeDrawer: this.getDefaultDrawerForView(initialView),
      drawerOpen: this.shouldDrawerBeOpen(initialView),
      isPLCEditorOpen: false
    };
  }

  // Determine default drawer type for a view
  getDefaultDrawerForView = (view: string): DrawerType => {
    switch (view) {
      case 'home':
      case 'viewer':
        return 'control'; // Control panel should be open for home/viewer
      case 'settings':
      case 'milling':
      case 'turning':
        return null; // All other views start with drawers closed
      default:
        return null; // Default to no drawer for any other views
    }
  };

  // Determine if drawer should be open based on the view
  shouldDrawerBeOpen = (view: string): boolean => {
    // All drawers start closed
    return false;
  };

  handleViewChange = (view: string) => {
    // Special case: if view is 'plc', open the PLC editor modal
    if (view === 'plc') {
      this.setState({
        isPLCEditorOpen: true
      });
      return;
    }

    // Special case: if view is 'actions', open the actions panel
    if (view === 'actions') {
      this.setState({
        activeDrawer: 'actions',
        drawerOpen: true
      });
      return;
    }

    // Special case: if navigating to milling, reset the workflow
    if (view === 'milling') {
      MillingWorkflowState.Instance.reset();
    }

    const defaultDrawer = this.getDefaultDrawerForView(view);
    const shouldOpen = this.shouldDrawerBeOpen(view);

    this.setState({
      selectedView: view,
      activeDrawer: defaultDrawer,
      drawerOpen: shouldOpen
    });
  };

  toggleDrawer = (drawerType?: DrawerType) => {
    const { activeDrawer, drawerOpen } = this.state;

    if (drawerType) {
      // If a specific drawer type is requested
      if (activeDrawer === drawerType && drawerOpen) {
        // Close if same drawer is already open
        this.setState({ drawerOpen: false });
      } else {
        // Open the requested drawer
        this.setState({ activeDrawer: drawerType, drawerOpen: true });
      }
    } else {
      // Just toggle the current drawer
      this.setState({ drawerOpen: !drawerOpen });
    }
  };

  toggleJogWindow = () => {
    const configState = ConfigurationState.Instance;
    configState.isJogWindowOpen = !configState.isJogWindowOpen;
  };

  toggleViewerWindow = () => {
    const configState = ConfigurationState.Instance;
    configState.isViewerWindowOpen = !configState.isViewerWindowOpen;
  };

  closePLCEditor = () => {
    this.setState({ isPLCEditorOpen: false });
  };

  createTheme = () => {
    const colors = ConfigurationDataColors.Instance;
    return createTheme({
      palette: {
        primary: {
          main: colors.primaryColor
        },
        secondary: {
          main: colors.secondaryColor
        }
      }
    });
  };

  render() {
    const { selectedView, drawerOpen, activeDrawer, isPLCEditorOpen } = this.state;

    return (
      <ObserveMultiProperties
        key="haven-cnc-layout"
        listenTo={[
          { object: ConfigurationData.Instance, properties: ['systemConfigurationUnlocked'] },
          { object: ConfigurationDataColors.Instance, properties: ['primaryColor', 'secondaryColor'] },
          { object: ConfigurationState.Instance, properties: ['isJogWindowOpen', 'isViewerWindowOpen'] }
        ]}
        control={() => {
          const config = ConfigurationData.Instance;
          const configState = ConfigurationState.Instance;
          const transparentColor = `${ConfigurationDataColors.Instance.lightTextColor}00`;

          // Create the Material-UI theme with the current colors
          this.theme = this.createTheme();

          // Show drawer selector for all views - users can access control panel and actions from any view
          const showDrawerSelector = true; // Always show selector for all views

          return (
            <Box sx={{ display: 'flex', width: '100%', height: '100%', overflow: 'hidden' }}>
              {/* Left Navigation */}
              <Box sx={{
                width: DRAWER_WIDTH,
                flexShrink: 0,
                backgroundColor: this.theme.palette.background.paper,
                borderRight: `1px solid ${this.theme.palette.divider}`,
                height: '100%',
              }}>
                <LeftNavigation
                  selectedView={selectedView}
                  onViewChange={this.handleViewChange}
                  onJogClick={this.toggleJogWindow}
                  onViewerClick={this.toggleViewerWindow}
                />
              </Box>

              {/* Main Content Area with Drawers - Constrained to 1200px */}
              <Box sx={{ width: MAIN_CONTENT_WIDTH, maxWidth: MAIN_CONTENT_WIDTH, flexShrink: 0, position: 'relative', minWidth: 0, height: '100%' }}>
                {/* Main Content */}
                <Box
                  component="main"
                  sx={{
                    width: drawerOpen ? `calc(100% - 48px)` : `calc(100% - 48px)`, // Always account for toggle bar
                    height: '100%',
                  }}
                >
                  <MainContent selectedView={selectedView} onViewChange={this.handleViewChange} />
                </Box>

                {/* Backdrop - Click to close drawer */}
                {showDrawerSelector && drawerOpen && activeDrawer !== null && (
                  <Box
                    sx={{
                      position: 'absolute',
                      top: 0,
                      left: 0,
                      right: 0,
                      bottom: 0,
                      backgroundColor: ConfigurationDataColors.Instance.shadowColor,
                      zIndex: this.theme.zIndex.drawer,
                      transition: 'opacity 0.3s ease',
                    }}
                    onClick={() => this.setState({ drawerOpen: false })}
                  />
                )}

                {/* Right Panel (Control or Actions) - Absolute overlay */}
                {showDrawerSelector && drawerOpen && activeDrawer !== null && (
                  <Box
                    sx={{
                      position: 'absolute',
                      right: 48,
                      top: 0,
                      height: '100%',
                      width: CONTROL_PANEL_WIDTH,
                      backgroundColor: this.theme.palette.background.paper,
                      borderLeft: `1px solid ${this.theme.palette.divider}`,
                      overflow: 'visible',
                      zIndex: this.theme.zIndex.drawer + 1,
                      boxShadow: `-4px 0 8px ${ConfigurationDataColors.Instance.shadowColor}`,
                      transition: 'right 0.3s ease',
                    }}
                  >
                    {activeDrawer === 'control' ? (
                      <ControlPanel onViewChange={this.handleViewChange} />
                    ) : activeDrawer === 'logs' ? (
                      <LogViewerDrawer onViewChange={this.handleViewChange} />
                    ) : activeDrawer === 'io' ? (
                      <InputOutputDrawer onViewChange={this.handleViewChange} />
                    ) : activeDrawer === 'signalr' ? (
                      <SignalRMessagesDrawer onViewChange={this.handleViewChange} />
                    ) : (
                      <ActionsPanel onViewChange={this.handleViewChange} />
                    )}
                  </Box>
                )}

                {/* Toggle Bar - Always visible on right edge of main content */}
                {showDrawerSelector && (
                  <Box
                    sx={{
                      position: 'absolute',
                      right: 0,
                      top: 0,
                      width: '48px',
                      height: '100%',
                      backgroundColor: ConfigurationDataColors.Instance.lightTextColor,
                      border: `1px solid ${this.theme.palette.divider}`,
                      display: 'flex',
                      flexDirection: 'column',
                      alignItems: 'center',
                      justifyContent: 'flex-start',
                      zIndex: this.theme.zIndex.drawer + 2,
                      paddingTop: '16px',
                      gap: '16px',
                      overflow: 'hidden',
                    }}
                  >
                    {/* Control Panel Option */}
                    <Box
                      sx={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        cursor: 'pointer',
                        padding: '8px 4px',
                        borderRadius: '4px',
                        backgroundColor: activeDrawer === 'control' && drawerOpen ? ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.2') :
                          activeDrawer === 'control' ? ConfigurationDataColors.Instance.hoverColor : transparentColor,
                        border: activeDrawer === 'control' ? `1px solid ${this.theme.palette.primary.main}` : `1px solid ${transparentColor}`,
                        minHeight: '60px',
                        width: '40px',
                        '&:hover': {
                          backgroundColor: activeDrawer === 'control' ? ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.15') : ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.05'),
                        },
                      }}
                      onClick={() => this.toggleDrawer('control')}
                    >
                      {activeDrawer === 'control' && drawerOpen ? (
                        <ChevronRight sx={{
                          color: this.theme.palette.primary.main,
                          fontSize: '20px',
                          marginBottom: '4px',
                        }} />
                      ) : (
                        <ChevronLeft sx={{
                          color: activeDrawer === 'control' ? this.theme.palette.primary.main : this.theme.palette.text.secondary,
                          fontSize: '20px',
                          marginBottom: '4px',
                        }} />
                      )}
                      <Typography
                        sx={{
                          color: activeDrawer === 'control' ? this.theme.palette.primary.main : this.theme.palette.text.primary,
                          fontSize: '12px',
                          fontWeight: 'bold',
                          writingMode: 'vertical-rl',
                          textOrientation: 'mixed',
                          userSelect: 'none',
                          letterSpacing: '0.5px',
                          textAlign: 'center',
                        }}
                      >
                        COORDINATES
                      </Typography>
                    </Box>

                    {/* Actions Panel Option */}
                    <Box
                      sx={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        cursor: 'pointer',
                        padding: '8px 4px',
                        borderRadius: '4px',
                        backgroundColor: activeDrawer === 'actions' && drawerOpen ? ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.2') :
                          activeDrawer === 'actions' ? ConfigurationDataColors.Instance.hoverColor : transparentColor,
                        border: activeDrawer === 'actions' ? `1px solid ${this.theme.palette.primary.main}` : `1px solid ${transparentColor}`,
                        minHeight: '60px',
                        width: '40px',
                        '&:hover': {
                          backgroundColor: activeDrawer === 'actions' ? ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.15') : ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.05'),
                        },
                      }}
                      onClick={() => this.toggleDrawer('actions')}
                    >
                      {activeDrawer === 'actions' && drawerOpen ? (
                        <ChevronRight sx={{
                          color: this.theme.palette.primary.main,
                          fontSize: '20px',
                          marginBottom: '4px',
                        }} />
                      ) : (
                        <ChevronLeft sx={{
                          color: activeDrawer === 'actions' ? this.theme.palette.primary.main : this.theme.palette.text.secondary,
                          fontSize: '20px',
                          marginBottom: '4px',
                        }} />
                      )}
                      <Typography
                        sx={{
                          color: activeDrawer === 'actions' ? this.theme.palette.primary.main : this.theme.palette.text.primary,
                          fontSize: '12px',
                          fontWeight: 'bold',
                          writingMode: 'vertical-rl',
                          textOrientation: 'mixed',
                          userSelect: 'none',
                          letterSpacing: '0.5px',
                          textAlign: 'center',
                        }}
                      >
                        ACTIONS
                      </Typography>
                    </Box>

                    {/* Log Viewer Option */}
                    <Box
                      sx={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        cursor: 'pointer',
                        padding: '8px 4px',
                        borderRadius: '4px',
                        backgroundColor: activeDrawer === 'logs' && drawerOpen ? ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.2') :
                          activeDrawer === 'logs' ? ConfigurationDataColors.Instance.hoverColor : transparentColor,
                        border: activeDrawer === 'logs' ? `1px solid ${this.theme.palette.primary.main}` : `1px solid ${transparentColor}`,
                        minHeight: '60px',
                        width: '40px',
                        '&:hover': {
                          backgroundColor: activeDrawer === 'logs' ? ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.15') : ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.05'),
                        },
                      }}
                      onClick={() => this.toggleDrawer('logs')}
                    >
                      {activeDrawer === 'logs' && drawerOpen ? (
                        <ChevronRight sx={{
                          color: this.theme.palette.primary.main,
                          fontSize: '20px',
                          marginBottom: '4px',
                        }} />
                      ) : (
                        <ChevronLeft sx={{
                          color: activeDrawer === 'logs' ? this.theme.palette.primary.main : this.theme.palette.text.secondary,
                          fontSize: '20px',
                          marginBottom: '4px',
                        }} />
                      )}
                      <Typography
                        sx={{
                          color: activeDrawer === 'logs' ? this.theme.palette.primary.main : this.theme.palette.text.primary,
                          fontSize: '12px',
                          fontWeight: 'bold',
                          writingMode: 'vertical-rl',
                          textOrientation: 'mixed',
                          userSelect: 'none',
                          letterSpacing: '0.5px',
                          textAlign: 'center',
                        }}
                      >
                        LOGS
                      </Typography>
                    </Box>

                    {/* Input/Output Option */}
                    <Box
                      sx={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        cursor: 'pointer',
                        padding: '8px 4px',
                        borderRadius: '4px',
                        backgroundColor: activeDrawer === 'io' && drawerOpen ? ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.2') :
                          activeDrawer === 'io' ? ConfigurationDataColors.Instance.hoverColor : transparentColor,
                        border: activeDrawer === 'io' ? `1px solid ${this.theme.palette.primary.main}` : `1px solid ${transparentColor}`,
                        minHeight: '60px',
                        width: '40px',
                        '&:hover': {
                          backgroundColor: activeDrawer === 'io' ? ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.15') : ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.05'),
                        },
                      }}
                      onClick={() => this.toggleDrawer('io')}
                    >
                      {activeDrawer === 'io' && drawerOpen ? (
                        <ChevronRight sx={{
                          color: this.theme.palette.primary.main,
                          fontSize: '20px',
                          marginBottom: '4px',
                        }} />
                      ) : (
                        <ChevronLeft sx={{
                          color: activeDrawer === 'io' ? this.theme.palette.primary.main : this.theme.palette.text.secondary,
                          fontSize: '20px',
                          marginBottom: '4px',
                        }} />
                      )}
                      <Typography
                        sx={{
                          color: activeDrawer === 'io' ? this.theme.palette.primary.main : this.theme.palette.text.primary,
                          fontSize: '12px',
                          fontWeight: 'bold',
                          writingMode: 'vertical-rl',
                          textOrientation: 'mixed',
                          userSelect: 'none',
                          letterSpacing: '0.5px',
                          textAlign: 'center',
                        }}
                      >
                        I/O
                      </Typography>
                    </Box>

                    {/* SignalR Messages Option */}
                    <Box
                      sx={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        cursor: 'pointer',
                        padding: '8px 4px',
                        borderRadius: '4px',
                        backgroundColor: activeDrawer === 'signalr' && drawerOpen ? ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.2') :
                          activeDrawer === 'signalr' ? ConfigurationDataColors.Instance.hoverColor : transparentColor,
                        border: activeDrawer === 'signalr' ? `1px solid ${this.theme.palette.primary.main}` : `1px solid ${transparentColor}`,
                        minHeight: '60px',
                        width: '40px',
                        '&:hover': {
                          backgroundColor: activeDrawer === 'signalr' ? ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.15') : ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.05'),
                        },
                      }}
                      onClick={() => this.toggleDrawer('signalr')}
                    >
                      {activeDrawer === 'signalr' && drawerOpen ? (
                        <ChevronRight sx={{
                          color: this.theme.palette.primary.main,
                          fontSize: '20px',
                          marginBottom: '4px',
                        }} />
                      ) : (
                        <ChevronLeft sx={{
                          color: activeDrawer === 'signalr' ? this.theme.palette.primary.main : this.theme.palette.text.secondary,
                          fontSize: '20px',
                          marginBottom: '4px',
                        }} />
                      )}
                      <Typography
                        sx={{
                          color: activeDrawer === 'signalr' ? this.theme.palette.primary.main : this.theme.palette.text.primary,
                          fontSize: '12px',
                          fontWeight: 'bold',
                          writingMode: 'vertical-rl',
                          textOrientation: 'mixed',
                          userSelect: 'none',
                          letterSpacing: '0.5px',
                          textAlign: 'center',
                        }}
                      >
                        MESSAGES
                      </Typography>
                    </Box>
                  </Box>
                )}
              </Box>

              {/* Right Sidebar - Always visible, fills remaining space */}
              <Box sx={{ flex: 1, minWidth: 0 }}>
                <RightSidebar />
              </Box>

              {/* Floating Jog Controls Window */}
              {configState.isJogWindowOpen && (
                <JogControlsWindow onClose={this.toggleJogWindow} />
              )}

              {/* Floating 3D Viewer Window */}
              {configState.isViewerWindowOpen && (
                <ViewerWindow onClose={this.toggleViewerWindow} />
              )}

              {/* Full Screen Setup Editor Modal */}
              {isPLCEditorOpen && (
                <Box
                  sx={{
                    position: 'fixed',
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    backgroundColor: 'background.default',
                    zIndex: this.theme.zIndex.modal,
                  }}
                >
                  <PLCEditorApp onClose={this.closePLCEditor} />
                </Box>
              )}
            </Box>
          );
        }}
      />
    );
  }
}

