import {
  Alert,
  AlertTitle,
  Box,
  Collapse,
  Dialog,
  DialogContent,
  DialogTitle,
  Grid,
  IconButton,
  Paper,
  Slider,
  Switch,
  ToggleButton,
  ToggleButtonGroup,
  Typography
} from '@mui/material';
import React, { useCallback, useRef, useState } from 'react';
import { SystemIcons } from '../../SystemIcons';
import { SimulatorView } from '../../data/Common/SimulatorView';
import { ViewStyle } from '../../data/Common/ViewStyle';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { MachineData } from '../../data/Machine/MachineData';
import { RotaryAxis } from '../../data/Machine/RotaryAxis';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { StateManager } from '../../utils/statemanager/StateManager';

interface ViewerSettingsDialogProps {
  open: boolean;
  onClose: () => void;
  simulatorView: SimulatorView;
  isHardcodedSettings?: boolean; // True if using hardcoded settings vs configuration settings
}

interface ViewStyleGroup {
  title: string;
  properties: Array<{
    key: keyof SimulatorView;
    label: string;
  }>;
}

const viewStyleGroups: ViewStyleGroup[] = [
  {
    title: 'Machine Components',
    properties: [
      { key: 'base', label: 'Machine Base' },
      { key: 'bed', label: 'Machine Bed' },
      { key: 'gantry', label: 'Gantry' },
      { key: 'spindle', label: 'Spindle' },
      { key: 'tool', label: 'Tool' },
      { key: 'atc', label: 'ATC' },
      { key: 'drillHead', label: 'Drill Head' },
      { key: 'laser', label: 'Laser' },
      { key: 'laserPointer', label: 'Laser Pointer' }
    ]
  },
  {
    title: 'Work Area & Equipment',
    properties: [
      { key: 'spoilBoard', label: 'Spoil Board' },
      { key: 'material', label: 'Material' },
      { key: 'clamps', label: 'Clamps' },
      { key: 'verticalTable', label: 'Vertical Table' },
      { key: 'rotary', label: 'Rotary Axis' }
    ]
  }
];

const booleanProperties = [
  { key: 'workHome' as keyof SimulatorView, label: 'Work Home Position' },
  { key: 'toolpaths' as keyof SimulatorView, label: 'Toolpaths' },
  { key: 'dryRunToolpaths' as keyof SimulatorView, label: 'Dry Run Toolpaths' },
  { key: 'softLimits' as keyof SimulatorView, label: 'Soft Limits' },
  { key: 'machineZero' as keyof SimulatorView, label: 'Machine Zero' },
  { key: 'machineHome' as keyof SimulatorView, label: 'Machine Home' }
];

// Mapping from ViewStyle properties to ConfigurationData transparency properties
const transparencyMapping: Record<string, string> = {
  'base': 'baseTransparency',
  'bed': 'bedTransparency',
  'gantry': 'gantryTransparency',
  'spindle': 'spindleTransparency',
  'spoilBoard': 'spoilboardTransparency',
  'material': 'materialTransparency',
  'clamps': 'clampTransparency',
  'verticalTable': 'verticalTableTransparency',
  'atc': 'atcTransparency',
  'rotary': 'rotaryTransparency',
  'tool': 'toolTransparency',
  'laser': 'laserTransparency',
  'laserPointer': 'laserPointerTransparency',
  'drillHead': 'drillHeadTransparency',
  // Note: Components without transparency mappings won't show edit buttons
};

export function ViewerSettingsDialog({
  open,
  onClose,
  simulatorView,
  isHardcodedSettings = false
}: ViewerSettingsDialogProps) {
  const config = ConfigurationData.Instance; const colors = ConfigurationDataColors.Instance; const machineData = MachineData.Instance;

  // State for tracking which transparency editors are open
  const [openTransparencyEditors, setOpenTransparencyEditors] = useState<Set<string>>(new Set());

  // Toggle transparency editor for a specific property
  const toggleTransparencyEditor = useCallback((propertyKey: string) => {
    setOpenTransparencyEditors(prev => {
      const newSet = new Set(prev);
      if (newSet.has(propertyKey)) {
        newSet.delete(propertyKey);
      } else {
        newSet.add(propertyKey);
      }
      return newSet;
    });
  }, []);

  // Get transparency value for a property
  const getTransparencyValue = useCallback((propertyKey: string): number => {
    const transparencyProperty = transparencyMapping[propertyKey];
    if (transparencyProperty && transparencyProperty in config) {
      return (config as any)[transparencyProperty];
    }
    return 0.15; // Default transparency
  }, [config]);

  // Set transparency value for a property
  const setTransparencyValue = useCallback((propertyKey: string, value: number) => {
    const transparencyProperty = transparencyMapping[propertyKey];
    if (transparencyProperty && transparencyProperty in config) {
      (config as any)[transparencyProperty] = value;
      StateManager.propertyChanged(config, transparencyProperty);
    }
  }, [config]);

  // Filter properties based on machine capabilities
  const getFilteredProperties = (properties: Array<{ key: keyof SimulatorView; label: string; }>) => {
    return properties.filter(({ key }) => {
      switch (key) {
        case 'rotary':
          return machineData.rotaryAxis !== RotaryAxis.None;
        case 'verticalTable':
          return machineData.hasVerticalTable;
        case 'laser':
          return machineData.hasLaser;
        case 'laserPointer':
          return machineData.hasLaserPointer;
        case 'drillHead':
          return machineData.hasDrillHead;
        case 'atc':
          return machineData.hasATC;
        default:
          return true; // Show all other properties (tool is always available)
      }
    });
  };

  // Dragging state  
  const [isDragging, setIsDragging] = useState(false);
  const [position, setPosition] = useState(() => {
    // Position dialog on right side of screen with some margin
    const rightPosition = window.innerWidth - 820; // 800px dialog width + 20px margin
    return { x: rightPosition, y: 100 };
  });
  const dragStartRef = useRef({ x: 0, y: 0 });

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    if (e.target === e.currentTarget || (e.target as HTMLElement).tagName === 'H6') {
      setIsDragging(true);
      dragStartRef.current = { x: e.clientX - position.x, y: e.clientY - position.y };
      e.preventDefault();
    }
  }, [position]);

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (isDragging) {
      setPosition({
        x: e.clientX - dragStartRef.current.x,
        y: e.clientY - dragStartRef.current.y
      });
    }
  }, [isDragging]);

  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
  }, []);

  React.useEffect(() => {
    if (isDragging) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
      return () => {
        document.removeEventListener('mousemove', handleMouseMove);
        document.removeEventListener('mouseup', handleMouseUp);
      };
    }
  }, [isDragging, handleMouseMove, handleMouseUp]);

  const handleViewStyleChange = useCallback((property: keyof SimulatorView, value: ViewStyle) => {
    // Set the new value
    (simulatorView as any)[property] = value;

    // Notify state manager of the change
    StateManager.propertyChanged(simulatorView, property);
  }, [simulatorView]);

  const handleBooleanChange = useCallback((property: keyof SimulatorView, value: boolean) => {
    (simulatorView as any)[property] = value;
    StateManager.propertyChanged(simulatorView, property);
  }, [simulatorView]);

  const renderViewStyleGroup = (group: ViewStyleGroup) => {
    const filteredProperties = getFilteredProperties(group.properties);

    return (
      <Grid item xs={6} key={group.title}>
        <Paper
          elevation={1}
          sx={{ p: 2, backgroundColor: colors.lightBackgroundColor, height: '100%' }}
        >
          <Typography variant="h6" gutterBottom sx={{ color: colors.darkTextColor, fontSize: '1rem' }}>
            {group.title}
          </Typography>
          {filteredProperties.map(({ key, label }) => {
            const currentValue = simulatorView[key] as ViewStyle;
            const isTransparent = currentValue === ViewStyle.SemiTransparent;
            const hasTransparencyEditor = transparencyMapping[key] !== undefined;
            const isEditorOpen = openTransparencyEditors.has(key);

            return (
              <Box key={key} sx={{ mb: 1.5 }}>
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 0.5 }}>
                  <Typography variant="body2" sx={{ color: colors.darkTextColor, fontSize: '0.8rem' }}>
                    {label}
                  </Typography>
                </Box>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <ToggleButtonGroup
                    value={currentValue}
                    exclusive
                    onChange={(_, value) => value && handleViewStyleChange(key, value)}
                    size="small"
                    sx={{
                      '& .MuiToggleButton-root': {
                        color: colors.darkTextColor,
                        borderColor: colors.borderColor,
                        fontSize: '0.7rem',
                        minWidth: '45px',
                        padding: '2px 4px',
                        '&.Mui-selected': {
                          backgroundColor: colors.primaryColor,
                          color: colors.lightTextColor
                        }
                      }
                    }}
                  >
                    <ToggleButton value={ViewStyle.Show}>Show</ToggleButton>
                    <ToggleButton value={ViewStyle.Hide}>Hide</ToggleButton>
                    <ToggleButton value={ViewStyle.SemiTransparent}>Transparent</ToggleButton>
                    <ToggleButton value={ViewStyle.Wireframe}>Wireframe</ToggleButton>
                  </ToggleButtonGroup>
                  {isTransparent && hasTransparencyEditor && (
                    <IconButton
                      size="small"
                      onClick={() => toggleTransparencyEditor(key)}
                      sx={{
                        color: isEditorOpen ? colors.lightTextColor : colors.mutedTextColor,
                        backgroundColor: isEditorOpen ? colors.primaryColor : `${colors.lightTextColor}00`,
                        padding: '4px',
                        minWidth: '24px',
                        width: '24px',
                        height: '24px',
                        border: `1px solid ${isEditorOpen ? colors.primaryColor : colors.borderColor}`,
                        borderRadius: '4px',
                        transition: 'all 0.2s ease',
                        '&:hover': {
                          color: isEditorOpen ? colors.lightTextColor : colors.primaryColor,
                          backgroundColor: isEditorOpen ? colors.primaryColor : colors.lightOverlay,
                          borderColor: colors.primaryColor,
                          transform: 'scale(1.05)'
                        },
                        '& svg': {
                          fontSize: '16px'
                        }
                      }}
                      title={isEditorOpen ? 'Hide transparency editor' : 'Show transparency editor'}
                    >
                      {SystemIcons.edit}
                    </IconButton>
                  )}
                </Box>              {/* Transparency Slider */}
                <Collapse in={isTransparent && hasTransparencyEditor && isEditorOpen}>
                  <Box sx={{ mt: 1, px: 1 }}>
                    <ObserveState
                      listenTo={config}
                      properties={[transparencyMapping[key]]}
                      control={() => (
                        <>
                          <Typography variant="caption" sx={{ color: colors.mutedTextColor, fontSize: '0.75rem' }}>
                            Transparency Level: {Math.round(getTransparencyValue(key) * 100)}%
                          </Typography>
                          <Slider
                            value={getTransparencyValue(key)} // Direct transparency value (not inverted)
                            onChange={(_, value) => setTransparencyValue(key, value as number)}
                            min={0}
                            max={1}
                            step={0.05}
                            size="small"
                            sx={{
                              color: colors.primaryColor,
                              '& .MuiSlider-thumb': {
                                backgroundColor: colors.primaryColor,
                              },
                              '& .MuiSlider-track': {
                                backgroundColor: colors.primaryColor,
                              },
                              '& .MuiSlider-rail': {
                                backgroundColor: colors.borderColor,
                              }
                            }}
                          />
                        </>
                      )}
                    />
                  </Box>
                </Collapse>
              </Box>
            );
          })}

          {/* Add boolean toggles at the bottom of Machine Components group */}
          {group.title === 'Machine Components' && (
            <>
              <Typography variant="h6" gutterBottom sx={{ color: colors.darkTextColor, fontSize: '1rem', mt: 2 }}>
                Display Options
              </Typography>
              {booleanProperties.map(({ key, label }) => (
                <Box
                  key={key}
                  sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    minHeight: '32px',
                    mb: 1
                  }}
                >
                  <Typography sx={{ color: colors.darkTextColor, fontSize: '0.8rem' }}>
                    {label}
                  </Typography>
                  <Switch
                    checked={simulatorView[key] as boolean}
                    onChange={(e) => handleBooleanChange(key, e.target.checked)}
                    size="small"
                    sx={{
                      '& .MuiSwitch-switchBase.Mui-checked': {
                        color: colors.primaryColor,
                      },
                      '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': {
                        backgroundColor: colors.primaryColor,
                      },
                    }}
                  />
                </Box>
              ))}
            </>
          )}
        </Paper>
      </Grid>
    );
  };

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="lg"
      fullWidth={false}
      disableEnforceFocus={true}
      hideBackdrop={true}
      PaperProps={{
        sx: {
          position: 'fixed',
          left: position.x,
          top: position.y,
          margin: 0,
          maxHeight: '80vh',
          width: '800px',
          backgroundColor: colors.lightBackgroundColor,
          color: colors.darkTextColor,
          borderColor: colors.borderColor,
          cursor: isDragging ? 'grabbing' : 'default'
        }
      }}
    >
      <DialogTitle
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          backgroundColor: colors.primaryColor,
          color: colors.lightTextColor,
          cursor: 'grab',
          userSelect: 'none',
          '&:active': {
            cursor: 'grabbing'
          }
        }}
        onMouseDown={handleMouseDown}
      >
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          {SystemIcons.viewerSettings}
          <Typography variant="h6">3D Viewer Settings</Typography>
        </Box>
        <IconButton
          onClick={onClose}
          sx={{ color: colors.lightTextColor }}
        >
          {SystemIcons.close}
        </IconButton>
      </DialogTitle>

      <DialogContent sx={{ p: 3 }}>
        <ObserveState
          listenTo={simulatorView}
          control={() => (
            <>
              {isHardcodedSettings && (
                <Alert
                  severity="warning"
                  sx={{ mb: 3, backgroundColor: colors.lightBackgroundColor }}
                >
                  <AlertTitle>Temporary Settings</AlertTitle>
                  This view does not remember changes. They will be reset when you use this view again.
                </Alert>
              )}

              {/* ViewStyle Settings in Two Columns */}
              <Grid container spacing={2}>
                {viewStyleGroups.map(renderViewStyleGroup)}
              </Grid>
            </>
          )}
        />
      </DialogContent>
    </Dialog>
  );
}
