import React from 'react';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataElement } from '../data/DataElement';
import { Declaration } from '../data/Declaration';
import { IPLCElement, PLCRenderMode, PLCValidationIssue } from '../data/IPLCElement';
import { PLCProgramType, PLCSerializationHelper, PLCUtilities } from '../data/PLCUtilities';
import { AssignmentPredicate } from '../predicates/AssignmentPredicate';
import { BasePLCStatement } from './BasePLCStatement';

/**
 * Statement for assigning a value using an assignment predicate
 */
export class AssignmentStatement extends BasePLCStatement {
    private _assignmentPredicate: AssignmentPredicate | undefined;

    constructor() {
        super();
        // Initialize with a new assignment predicate
        this._assignmentPredicate = new AssignmentPredicate();
        this._assignmentPredicate.setParentElement(this);

        // Set up cache invalidation listener
        PLCUtilities.setupCacheInvalidationListener(this);
    }

    /**
     * Get the assignment predicate
     */
    public get assignmentPredicate(): AssignmentPredicate | undefined {
        return this._assignmentPredicate;
    }

    /**
     * Set the assignment predicate
     */
    public set assignmentPredicate(value: AssignmentPredicate | undefined) {
        this._assignmentPredicate = value;
        if (this._assignmentPredicate) {
            this._assignmentPredicate.setParentElement(this);
        }
        StateManager.propertyChanged(this, 'assignmentPredicate');
    }

    /**
     * Get a short, single-line description for display in tree views
     * Delegates to the assignment predicate
     * @returns A human-readable summary of the assignment
     */
    public getShortDescription(): string {
        if (!this._assignmentPredicate) {
            return 'Assignment (not configured)';
        }
        return this._assignmentPredicate.getShortDescription();
    }

    /**
     * Override setParentElement to cascade to assignment predicate
     */
    public setParentElement(parent: IPLCElement | undefined): void {
        super.setParentElement(parent);
        // Cascade to child predicate
        if (this._assignmentPredicate) {
            this._assignmentPredicate.setParentElement(this);
        }
    }

    /**
     * Render the statement (delegates to predicate)
     * @param mode Optional rendering mode (Edit, ReadOnly, or Disabled)
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        // Determine effective mode:
        // - If parent says Disabled or ReadOnly, use that (propagate down)
        // - Otherwise, if this statement is disabled, use Disabled mode
        let effectiveMode = mode;
        if (mode === PLCRenderMode.Edit && !this._enabled) {
            effectiveMode = PLCRenderMode.Disabled;
        }

        if (!this._assignmentPredicate) {
            return null;
        }

        // Wrap in a container with disabled styling if needed
        const content = this._assignmentPredicate.render(effectiveMode, targetProgramType);

        if (effectiveMode === PLCRenderMode.Disabled) {
            return (
                <div style={{
                    textDecoration: 'line-through',
                    textDecorationLine: 'line-through',
                    opacity: 0.6
                }}>
                    {content}
                </div>
            );
        }

        return content;
    }

    /**
     * Validate the statement
     */
    public validate(): string | undefined {
        if (!this._assignmentPredicate) {
            return 'Assignment requires a predicate';
        }
        return this._assignmentPredicate.validate();
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): any {
        const baseData = PLCSerializationHelper.getStorageData(this, ['_assignmentPredicate']);
        return {
            type: 'AssignmentStatement',
            ...baseData,
            assignmentPredicate: this._assignmentPredicate?.toJSON()
        };
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        if (data.assignmentPredicate) {
            this._assignmentPredicate = new AssignmentPredicate();
            this._assignmentPredicate.fromJSON(data.assignmentPredicate);
            this._assignmentPredicate.setParentElement(this);
        }
    }

    /**
     * Clone the statement
     */
    public clone(): AssignmentStatement {
        const cloned = new AssignmentStatement();
        if (this._assignmentPredicate) {
            cloned.assignmentPredicate = this._assignmentPredicate.clone();
        }
        return cloned;
    }

    /**
     * Get declarations used by this statement (delegates to predicate)
     */
    public getUsedDeclarations(): Declaration[] {
        if (!this._assignmentPredicate) {
            return [];
        }
        return this._assignmentPredicate.getUsedDeclarations();
    }

    /**
     * Get declarations added by this statement (delegates to predicate)
     */
    public getAddedDeclarations(): Declaration[] {
        if (!this._assignmentPredicate) {
            return [];
        }
        const declarations = this._assignmentPredicate.getAddedDeclarations();
        return declarations;
    }

    /**
     * Get PLC logic code (wraps predicate with IF 1==1 THEN)
     */
    public getPLCLogic(): string[] {
        if (this.isDisabled(PLCRenderMode.Edit, PLCProgramType.System)) {
            return [];
        }
        if (!this._assignmentPredicate) {
            return [];
        }

        const logic: string[] = [];

        // 1. Collect pre-logic (for memory-bit assignments using helper bits)
        const preLogic = this._assignmentPredicate.getPrePLCLogic();
        if (preLogic.length > 0) {
            logic.push(...preLogic);
        }

        // 2. Main logic
        const predicateLogic = this._assignmentPredicate.getPLCLogic();
        if (predicateLogic.length === 0) {
            return [];
        }

        // Get comment from predicate
        const comment = this._assignmentPredicate.getComment();
        const commentPart = comment ? `    ; ${comment}` : '';

        // Wrap with IF 1==1 THEN to make it an unconditional assignment
        logic.push(`IF 1==1 THEN ${predicateLogic[0]}${commentPart}`);

        // 3. Collect post-logic (for memory-bit assignments using helper bits)
        const secondaryLogic = this._assignmentPredicate.getSecondaryPLCLogic();
        if (secondaryLogic.length > 0) {
            logic.push(...secondaryLogic);
        }

        return logic;
    }

    /**
     * Get validation issues (delegates to predicate)
     */
    public getValidationIssues(): PLCValidationIssue[] {
        // Disabled elements cannot be invalid
        if (this.isDisabled(PLCRenderMode.Edit, PLCProgramType.System)) {
            return [];
        }

        if (!this._assignmentPredicate) {
            return [new PLCValidationIssue(this, 'Assignment requires a predicate')];
        }
        return this._assignmentPredicate.getValidationIssues();
    }

    /**
     * Get all data elements used by this statement
     * @returns Array of all DataElement instances in this statement
     */
    public override getDataElements(): DataElement[] {
        if (!this._assignmentPredicate) {
            return [];
        }
        return this._assignmentPredicate.getDataElements();
    }
}
