import { IStorable } from '../../common/IStorable';
import { StateManager } from '../../utils/statemanager/StateManager';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { ViewStyle } from './ViewStyle';

/**
 * Simulator view configuration and state
 * Direct conversion from C# SimulatorView class
 */
export class SimulatorView implements IStorable {
  // View identification
  private _name: string = 'default';

  // Camera properties - stored as spherical coordinates relative to target
  // These are optional and will be computed on first use if undefined
  private _cameraDistance?: number; // Distance from target
  private _cameraPolarAngle?: number; // Elevation angle (0 = top, PI = bottom)
  private _cameraAzimuthalAngle?: number; // Rotation around vertical (0 = front)
  private _zoomFactor: number = 1.0;

  // View visibility settings
  private _workHome: boolean = true;
  private _toolpaths: boolean = true;
  private _dryRunToolpaths: boolean = false;
  private _softLimits: boolean = true;
  private _machineZero: boolean = false;
  private _machineHome: boolean = false;
  private _material: ViewStyle = ViewStyle.Show;
  private _gantry: ViewStyle = ViewStyle.Show;
  private _base: ViewStyle = ViewStyle.Show;
  private _bed: ViewStyle = ViewStyle.Show;
  private _railing: ViewStyle = ViewStyle.Show;
  private _spindle: ViewStyle = ViewStyle.Show;
  private _workPiece: ViewStyle = ViewStyle.Show;
  private _spoilBoard: ViewStyle = ViewStyle.Show;
  private _clamps: ViewStyle = ViewStyle.Show;
  private _tool: ViewStyle = ViewStyle.Show;
  private _rotary: ViewStyle = ViewStyle.Show;
  private _verticalTable: ViewStyle = ViewStyle.Show;
  private _laser: ViewStyle = ViewStyle.Show;
  private _laserPointer: ViewStyle = ViewStyle.Show;
  private _drillHead: ViewStyle = ViewStyle.Show;
  private _atc: ViewStyle = ViewStyle.Show;

  public get name(): string {
    return this._name;
  }

  public set name(value: string) {
    this._name = value;
    StateManager.propertyChanged(this, 'name');
  }

  public get cameraDistance(): number | undefined {
    return this._cameraDistance;
  }

  public set cameraDistance(value: number | undefined) {
    this._cameraDistance = value;
    StateManager.propertyChanged(this, 'cameraDistance');
  }

  public get cameraPolarAngle(): number | undefined {
    return this._cameraPolarAngle;
  }

  public set cameraPolarAngle(value: number | undefined) {
    this._cameraPolarAngle = value;
    StateManager.propertyChanged(this, 'cameraPolarAngle');
  }

  public get cameraAzimuthalAngle(): number | undefined {
    return this._cameraAzimuthalAngle;
  }

  public set cameraAzimuthalAngle(value: number | undefined) {
    this._cameraAzimuthalAngle = value;
    StateManager.propertyChanged(this, 'cameraAzimuthalAngle');
  }

  // Legacy properties for backward compatibility - computed from spherical coordinates
  public get cameraPosition(): { x: number; y: number; z: number } {
    // This is a computed property - not stored, derived from spherical coordinates
    // For now, return a default until we have a target to compute from
    return { x: 10, y: 10, z: 10 };
  }

  public set cameraPosition(value: { x: number; y: number; z: number }) {
    // Legacy setter - ignored, use spherical coordinates instead
    // This is here for backward compatibility only
  }

  public get cameraTarget(): { x: number; y: number; z: number } {
    // Legacy property - not used in new system
    return { x: 0, y: 0, z: 0 };
  }

  public set cameraTarget(value: { x: number; y: number; z: number }) {
    // Legacy setter - ignored
  }

  public get zoomFactor(): number {
    return this._zoomFactor;
  }

  public set zoomFactor(value: number) {
    this._zoomFactor = value;
    StateManager.propertyChanged(this, 'zoomFactor');
  }

  public get workHome(): boolean {
    return this._workHome;
  }

  public set workHome(value: boolean) {
    this._workHome = value;
    StateManager.propertyChanged(this, 'workHome');
  }

  public get toolpaths(): boolean {
    return this._toolpaths;
  }

  public set toolpaths(value: boolean) {
    this._toolpaths = value;
    StateManager.propertyChanged(this, 'toolpaths');
  }

  public get dryRunToolpaths(): boolean {
    return this._dryRunToolpaths;
  }

  public set dryRunToolpaths(value: boolean) {
    this._dryRunToolpaths = value;
    StateManager.propertyChanged(this, 'dryRunToolpaths');
  }

  public get softLimits(): boolean {
    return this._softLimits;
  }

  public set softLimits(value: boolean) {
    this._softLimits = value;
    StateManager.propertyChanged(this, 'softLimits');
  }

  public get machineZero(): boolean {
    return this._machineZero;
  }

  public set machineZero(value: boolean) {
    this._machineZero = value;
    StateManager.propertyChanged(this, 'machineZero');
  }

  public get machineHome(): boolean {
    return this._machineHome;
  }

  public set machineHome(value: boolean) {
    this._machineHome = value;
    StateManager.propertyChanged(this, 'machineHome');
  }

  public get material(): ViewStyle {
    return this._material;
  }

  public set material(value: ViewStyle) {
    this._material = value;
    StateManager.propertyChanged(this, 'material');
  }

  public get gantry(): ViewStyle {
    return this._gantry;
  }

  public set gantry(value: ViewStyle) {
    this._gantry = value;
    StateManager.propertyChanged(this, 'gantry');
  }

  public get base(): ViewStyle {
    return this._base;
  }

  public set base(value: ViewStyle) {
    this._base = value;
    StateManager.propertyChanged(this, 'base');
  }

  public get bed(): ViewStyle {
    return this._bed;
  }

  public set bed(value: ViewStyle) {
    this._bed = value;
    StateManager.propertyChanged(this, 'bed');
  }

  public get railing(): ViewStyle {
    return this._railing;
  }

  public set railing(value: ViewStyle) {
    this._railing = value;
    StateManager.propertyChanged(this, 'railing');
  }

  public get spindle(): ViewStyle {
    return this._spindle;
  }

  public set spindle(value: ViewStyle) {
    this._spindle = value;
    StateManager.propertyChanged(this, 'spindle');
  }

  public get workPiece(): ViewStyle {
    return this._workPiece;
  }

  public set workPiece(value: ViewStyle) {
    this._workPiece = value;
    StateManager.propertyChanged(this, 'workPiece');
  }

  public get spoilBoard(): ViewStyle {
    return this._spoilBoard;
  }

  public set spoilBoard(value: ViewStyle) {
    this._spoilBoard = value;
    StateManager.propertyChanged(this, 'spoilBoard');
  }

  public get clamps(): ViewStyle {
    return this._clamps;
  }

  public set clamps(value: ViewStyle) {
    this._clamps = value;
    StateManager.propertyChanged(this, 'clamps');
  }

  public get tool(): ViewStyle {
    return this._tool;
  }

  public set tool(value: ViewStyle) {
    this._tool = value;
    StateManager.propertyChanged(this, 'tool');
  }

  public get rotary(): ViewStyle {
    return this._rotary;
  }

  public set rotary(value: ViewStyle) {
    this._rotary = value;
    StateManager.propertyChanged(this, 'rotary');
  }

  public get verticalTable(): ViewStyle {
    return this._verticalTable;
  }

  public set verticalTable(value: ViewStyle) {
    this._verticalTable = value;
    StateManager.propertyChanged(this, 'verticalTable');
  }

  public get laser(): ViewStyle {
    return this._laser;
  }

  public set laser(value: ViewStyle) {
    this._laser = value;
    StateManager.propertyChanged(this, 'laser');
  }

  public get laserPointer(): ViewStyle {
    return this._laserPointer;
  }

  public set laserPointer(value: ViewStyle) {
    this._laserPointer = value;
    StateManager.propertyChanged(this, 'laserPointer');
  }

  public get drillHead(): ViewStyle {
    return this._drillHead;
  }

  public set drillHead(value: ViewStyle) {
    this._drillHead = value;
    StateManager.propertyChanged(this, 'drillHead');
  }

  public get atc(): ViewStyle {
    return this._atc;
  }

  public set atc(value: ViewStyle) {
    this._atc = value;
    StateManager.propertyChanged(this, 'atc');
  }

  /**
   * Copy camera and visibility settings from another SimulatorView
   * Used when loading saved view settings
   * @param other The SimulatorView to copy settings from
   */
  public copySettingsFrom(other: SimulatorView): void {
    // Copy camera settings (but NOT cameraDistance - it's computed)
    this.cameraPolarAngle = other.cameraPolarAngle;
    this.cameraAzimuthalAngle = other.cameraAzimuthalAngle;
    this.zoomFactor = other.zoomFactor;

    // Copy visibility settings
    this.workHome = other.workHome;
    this.toolpaths = other.toolpaths;
    this.dryRunToolpaths = other.dryRunToolpaths;
    this.softLimits = other.softLimits;
    this.machineZero = other.machineZero;
    this.machineHome = other.machineHome;
    this.material = other.material;
    this.gantry = other.gantry;
    this.base = other.base;
    this.bed = other.bed;
    this.railing = other.railing;
    this.spindle = other.spindle;
    this.workPiece = other.workPiece;
    this.spoilBoard = other.spoilBoard;
    this.clamps = other.clamps;
    this.tool = other.tool;
    this.rotary = other.rotary;
    this.verticalTable = other.verticalTable;
    this.laser = other.laser;
    this.laserPointer = other.laserPointer;
    this.drillHead = other.drillHead;
    this.atc = other.atc;
  }

  /**
   * IStorable implementation - serialize to JSON using generic DataUtilities approach
   */
  public toJSON(): object {
    // Exclude cameraDistance - it should be computed dynamically from bounding box
    // Only store zoom, angles, and target mode
    // StateManager observers automatically excluded by DataUtilities
    return DataUtilities.getStorageData(this, ['_cameraDistance', 'cameraDistance']);
  }

  /**
   * IStorable implementation - deserialize from JSON using generic DataUtilities approach
   */
  public fromJSON(data: any): void {
    if (!data) return;

    // Use DataUtilities to load data generically
    // This will automatically use setters (which trigger StateManager notifications)
    // StateManager observers automatically excluded by DataUtilities
    DataUtilities.loadStorageData(this, data, ['_cameraDistance', 'cameraDistance']);

    // Explicitly set cameraDistance to undefined to ensure it's recomputed from bounding box
    this._cameraDistance = undefined;
  }
}
