import { CNCOffset } from '../CNCOffset';
import { CNCPoint } from '../CNCPoint';
import { MachineStateData } from '../MachineStateData';
import { BoxPoints } from './BoxPoints';
import { CoordinateType } from './CoordinateType';

/**
 * Represents a rectangular box with position and dimensions
 */
export class Box {
  public origin: CNCPoint;
  public width: number;
  public height: number;
  public length: number;  // 3D depth dimension
  public boxPoints: BoxPoints;  // 8 corner points for 3D box

  constructor(origin: CNCPoint = new CNCPoint(0, 0, 0, CoordinateType.MachineZero), width: number = 0, length: number = 0, height: number = 0, boxPoints?: BoxPoints) {
    this.origin = origin;
    this.width = width;
    this.height = height;
    this.length = length;

    // If boxPoints not provided, compute them from origin and dimensions
    if (boxPoints) {
      this.boxPoints = boxPoints;
    } else {
      this.boxPoints = Box.computeBoxPoints(origin, width, length, height);
    }
  }

  /**
   * Compute the 8 corner points of a box from origin and dimensions
   */
  static computeBoxPoints(
    origin: CNCPoint,
    width: number,
    length: number,
    height: number
  ): BoxPoints {
    return {
      frontLeftLower: new CNCPoint(origin.x, origin.y, origin.z, origin.coordinateType),
      frontRightLower: new CNCPoint(origin.x + width, origin.y, origin.z, origin.coordinateType),
      rearRightLower: new CNCPoint(origin.x + width, origin.y + length, origin.z, origin.coordinateType),
      rearLeftLower: new CNCPoint(origin.x, origin.y + length, origin.z, origin.coordinateType),
      frontLeftUpper: new CNCPoint(origin.x, origin.y, origin.z + height, origin.coordinateType),
      frontRightUpper: new CNCPoint(origin.x + width, origin.y, origin.z + height, origin.coordinateType),
      rearRightUpper: new CNCPoint(origin.x + width, origin.y + length, origin.z + height, origin.coordinateType),
      rearLeftUpper: new CNCPoint(origin.x, origin.y + length, origin.z + height, origin.coordinateType)
    };
  }

  /**
   * Gets the right edge of the box
   */
  get right(): number {
    return this.origin.x + this.width;
  }

  /**
   * Gets the bottom edge of the box (Y dimension)
   */
  get bottom(): number {
    return this.origin.y + this.length;
  }

  /**
   * Gets the center X coordinate
   */
  get centerX(): number {
    return this.origin.x + this.width / 2;
  }

  /**
   * Gets the center Y coordinate
   */
  get centerY(): number {
    return this.origin.y + this.length / 2;
  }

  /**
   * Gets the X coordinate of the origin
   */
  get x(): number {
    return this.origin.x;
  }

  /**
   * Gets the Y coordinate of the origin
   */
  get y(): number {
    return this.origin.y;
  }

  /**
   * Gets the Z coordinate of the origin
   */
  get z(): number {
    return this.origin.z;
  }

  /**
   * Check if a point is inside the box
   */
  contains(x: number, y: number): boolean {
    return x >= this.x && x <= this.right && y >= this.y && y <= this.bottom;
  }

  /**
   * Check if this box intersects with another box
   */
  intersects(other: Box): boolean {
    return !(other.x > this.right ||
      other.right < this.x ||
      other.y > this.bottom ||
      other.bottom < this.y);
  }

  /**
   * Create a copy of this box
   */
  clone(): Box {
    return new Box(this.origin, this.width, this.length, this.height, this.boxPoints);
  }

  /**
   * Returns a new Box with all points converted to MachineZero coordinates
   * This ensures consistent coordinate system for collision detection
   * Inlined here to avoid circular dependency (CoordinateUtil imports Box).
   */
  toMachineZero(): Box {
    const toMZ = (point: CNCPoint): CNCPoint => {
      if (point.coordinateType === CoordinateType.MachineZero) {
        return new CNCPoint(point.x, point.y, point.z, CoordinateType.MachineZero);
      }
      if (point.coordinateType === CoordinateType.WorkZero) {
        const wz = MachineStateData.Instance.currentWorkZero;
        const offset = new CNCOffset(wz.x, wz.y, wz.z);
        const converted = CNCPoint.addOffset(point, offset);
        return new CNCPoint(converted.x, converted.y, converted.z, CoordinateType.MachineZero);
      }
      throw new Error(`Box.toMachineZero: unsupported coordinate type '${point.coordinateType}'. Use CoordinateUtil.toMachineZero for complex conversions.`);
    };

    return new Box(
      toMZ(this.origin),
      this.width,
      this.length,
      this.height,
      {
        frontLeftLower: toMZ(this.boxPoints.frontLeftLower),
        frontRightLower: toMZ(this.boxPoints.frontRightLower),
        frontRightUpper: toMZ(this.boxPoints.frontRightUpper),
        frontLeftUpper: toMZ(this.boxPoints.frontLeftUpper),
        rearLeftLower: toMZ(this.boxPoints.rearLeftLower),
        rearRightLower: toMZ(this.boxPoints.rearRightLower),
        rearRightUpper: toMZ(this.boxPoints.rearRightUpper),
        rearLeftUpper: toMZ(this.boxPoints.rearLeftUpper)
      }
    );
  }
}
