import { BoardType } from '../data/Machine/BoardType';

/**
 * Centroid board I/O layout constants
 * Acorn  base board: pins 1-8   (gap 9-32,  expansion boards start at 33, 16 pins each)
 * Acorn6 base board: pins 1-16  (gap 17-64, expansion boards start at 65, 16 pins each)
 * Each expansion board adds 16 I/O pins
 */
const ACORN_BASE_END = 8;
const ACORN_EXPANSION_START = 33;
const ACORN6_BASE_END = 16;
const ACORN6_EXPANSION_START = 65;
const PINS_PER_EXPANSION_BOARD = 16;

/**
 * Compute the full list of available I/O pin numbers for the given board type
 * and number of installed expansion boards.
 *
 * Acorn:
 *   base          → 1-8
 *   + 1 exp board → 33-48   (gap: 9-32)
 *   + 2 exp boards→ 33-64
 *   ...
 *
 * Acorn6:
 *   base          → 1-16
 *   + 1 exp board → 65-80   (gap: 17-64)
 *   ...
 *
 * All other board types return only the base range (1-8).
 */
export function getAvailableIONumbers(
    boardType: BoardType,
    expansionBoardCount: number
): number[] {
    const isAcorn6 = boardType === BoardType.Acorn6;
    const baseEnd = isAcorn6 ? ACORN6_BASE_END : ACORN_BASE_END;
    const expansionStart = isAcorn6 ? ACORN6_EXPANSION_START : ACORN_EXPANSION_START;

    const numbers: number[] = [];

    // Base board pins
    for (let i = 1; i <= baseEnd; i++) {
        numbers.push(i);
    }

    // Expansion board pins
    const count = Math.max(0, Math.floor(expansionBoardCount));
    for (let board = 0; board < count; board++) {
        const start = expansionStart + board * PINS_PER_EXPANSION_BOARD;
        for (let pin = start; pin < start + PINS_PER_EXPANSION_BOARD; pin++) {
            numbers.push(pin);
        }
    }

    return numbers;
}
