import { Machine } from '../machine/Machine';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';
import { SingletonRegistry } from '../utils/SingletonRegistry';
import { StateManager } from '../utils/statemanager/StateManager';
import { DataUtilities } from '../utils/storage/DataUtilities';
import { CNCOffset } from './CNCOffset';
import { CNCPoint } from './CNCPoint';
import { CoordinateType } from './Common/CoordinateType';
import { Fixture, FixtureLibrary } from './Common/FixtureLibrary';
import { SaveableDataBase } from './Common/SaveableDataBase';
import { ConfigurationState } from './ConfigurationState';
import { DataFileConstants } from './DataFileConstants';

/**
 * Constants for default simulator view names
 */
export const DEFAULT_VIEW_NAMES = {
  DEFAULT: 'default',
  TOP_WORKPIECE: 'topWorkpiece',
  COMPACT: 'compact',
  GCODE: 'gcode',
  CLAMP_EDITOR: 'clampEditor',
  MATERIAL_EDITOR: 'materialEditor',
  CURRENT: 'current',
  JOB_VIEW: 'jobView'
} as const;

/**
 * Machine state data structure
 * Direct conversion from C# MachineStateData class
 * Implemented as singleton pattern
 */
export class MachineStateData extends SaveableDataBase {
  /**
   * Filename for saving/loading machine state data
   */
  protected get filename(): string {
    return DataFileConstants.MACHINE_STATE;
  }

  // Session tracking for tool measurements
  private _sessionNumber: number = 0; // Increments each time machine is homed

  // Spoil board dimensions
  private _spoilBoardWidth: number = 48;
  private _spoilBoardYLength: number = 96;
  private _spoilBoardHeight: number = 0.75;
  private _spoilboardPosition: CNCOffset = new CNCOffset(1, 1, 0);

  // MIGRATION COMPLETE: currentMachinePoint moved to ConfigurationState (runtime-only)
  // All references updated to use ConfigurationState.Instance.currentMachinePoint

  // Current work zero home point (in machine coordinates)
  // This is the active work zero that the machine uses for coordinate transformations
  private _currentWorkZeroHome: CNCPoint = new CNCPoint(1, 1, -4, CoordinateType.MachineZero);

  // Fixture and tool info
  private _currentFixtureNumber: string = "G54";
  private _currentFixtureSaved: boolean = false;
  private _currentToolNumber: number = 1; // Default to tool 1 for testing

  // Machine state - Jobs stored by ID (fetched from job storage)
  private _currentJobId?: string = undefined; // ID of current job (fetch from storage)
  private _lastJobId?: string = undefined; // ID of last job (fetch from storage)

  // Rotary axis state
  private _rotaryInstalled: boolean = false;

  // Getter and setter methods with StateManager property change notifications

  // Session tracking
  public get sessionNumber(): number {
    return this._sessionNumber;
  }

  public set sessionNumber(value: number) {
    this._sessionNumber = value;
    StateManager.propertyChanged(this, 'sessionNumber');
  }

  /**
   * Increment session number when machine is homed
   */
  public incrementSessionNumber(): void {
    this._sessionNumber++;
    StateManager.propertyChanged(this, 'sessionNumber');
  }

  // Spoil board dimensions
  public get spoilBoardWidth(): number {
    return this._spoilBoardWidth;
  }

  public set spoilBoardWidth(value: number) {
    this._spoilBoardWidth = value;
    StateManager.propertyChanged(this, 'spoilBoardWidth');
  }

  public get spoilBoardYLength(): number {
    return this._spoilBoardYLength;
  }

  public set spoilBoardYLength(value: number) {
    this._spoilBoardYLength = value;
    StateManager.propertyChanged(this, 'spoilBoardYLength');
  }

  public get spoilBoardHeight(): number {
    return this._spoilBoardHeight;
  }

  public set spoilBoardHeight(value: number) {
    this._spoilBoardHeight = value;
    StateManager.propertyChanged(this, 'spoilBoardHeight');
  }

  public get spoilboardPosition(): CNCOffset {
    // Ensure we always return a CNCOffset, even for old data
    if (!this._spoilboardPosition) {
      this._spoilboardPosition = new CNCOffset(0, 0, 0);
    }
    return this._spoilboardPosition;
  }

  public get spoilboardX(): number {
    return this.spoilboardPosition.x;
  }

  public set spoilboardX(value: number) {
    this.spoilboardPosition.x = value;
    StateManager.propertyChanged(this, 'spoilboardX');
  }

  public get spoilboardY(): number {
    return this.spoilboardPosition.y;
  }

  public set spoilboardY(value: number) {
    this.spoilboardPosition.y = value;
    StateManager.propertyChanged(this, 'spoilboardY');
  }

  // Work coordinate system
  public get currentWorkZero(): CNCPoint {
    return this._currentWorkZeroHome;
  }

  public set currentWorkZero(value: CNCPoint) {
    this._currentWorkZeroHome.x = value.x;
    this._currentWorkZeroHome.y = value.y;
    this._currentWorkZeroHome.z = value.z;
    StateManager.propertyChanged(this, 'currentWorkZero');

    // Update API fixture point when work zero changes
    this.updateAPIFixturePoint();
  }

  // Fixture and tool info
  public get currentFixtureNumber(): string {
    return this._currentFixtureNumber;
  }

  public set currentFixtureNumber(value: string) {
    this._currentFixtureNumber = value;
    StateManager.propertyChanged(this, 'currentFixtureNumber');
  }

  /**
   * Set work zero from a fixture (copy fixture values to currentWorkZeroHome)
   * @param fixture The fixture to copy values from
   * @param useZ If true, copy X, Y, and Z. If false, copy only X and Y (preserve current Z)
   */
  public setWorkZeroFromFixture(fixture: Fixture, useZ: boolean = true): void {
    this._currentWorkZeroHome.x = fixture.xOffset;
    this._currentWorkZeroHome.y = fixture.yOffset;
    if (useZ) {
      this._currentWorkZeroHome.z = fixture.zOffset;
    }

    // Update fixture number to show which preset was loaded
    this._currentFixtureNumber = fixture.fixtureNumber;

    StateManager.propertyChanged(this, 'currentWorkZero');
    StateManager.propertyChanged(this, 'currentFixtureNumber');

    // Update API fixture point when work zero changes
    this.updateAPIFixturePoint();
  }

  /**
   * Check if current work zero matches any fixture (XY only)
   * @returns Fixture that matches current work zero XY coordinates, or null if custom
   */
  public getMatchingFixture(): Fixture | null {
    const tolerance = 0.0001;
    return FixtureLibrary.Instance.fixtures.find(f =>
      !f.isComputed &&
      Math.abs(f.xOffset - this._currentWorkZeroHome.x) < tolerance &&
      Math.abs(f.yOffset - this._currentWorkZeroHome.y) < tolerance
    ) || null;
  }

  /**
   * Check if current work zero is custom (doesn't match any fixture XY)
   * @returns true if work zero XY doesn't match any fixture
   */
  public isWorkZeroCustom(): boolean {
    return this.getMatchingFixture() === null;
  }

  public get currentFixtureSaved(): boolean {
    return this._currentFixtureSaved;
  }

  public set currentFixtureSaved(value: boolean) {
    this._currentFixtureSaved = value;
    StateManager.propertyChanged(this, 'currentFixtureSaved');
  }

  public get currentToolNumber(): number {
    return this._currentToolNumber;
  }

  public set currentToolNumber(value: number) {
    this._currentToolNumber = value;
    StateManager.propertyChanged(this, 'currentToolNumber');
    // Also notify that current work point changed (tool offsets affect displayed position)
    StateManager.propertyChanged(this, 'currentWorkPoint');
    StateManager.propertyChanged(ConfigurationState.Instance, 'currentMachinePoint');

    // Call API to update fixture point on the machine (tool offsets affect fixture calculation)
    this.updateAPIFixturePoint();
  }

  // Machine state - Job IDs (persisted)
  public get currentJobId(): string | undefined {
    return this._currentJobId;
  }

  public set currentJobId(value: string | undefined) {
    this._currentJobId = value;
    StateManager.propertyChanged(this, 'currentJobId');
  }

  public get lastJobId(): string | undefined {
    return this._lastJobId;
  }

  public set lastJobId(value: string | undefined) {
    this._lastJobId = value;
    StateManager.propertyChanged(this, 'lastJobId');
  }

  // Rotary axis state getters/setters
  public get rotaryInstalled(): boolean {
    return this._rotaryInstalled;
  }

  public set rotaryInstalled(value: boolean) {
    this._rotaryInstalled = value;
    StateManager.propertyChanged(this, 'rotaryInstalled');
  }

  constructor() {
    super();

    // Register this singleton - will throw if a duplicate is created
    SingletonRegistry.MachineStateData = this;

    // All initialization is done inline above
    // Register listeners on sub-objects
    this.registerSubObjectListeners();

    // Note: setupAutoSave() will be called after instance creation to avoid constructor issues
  }

  /**
   * Register listeners on sub-objects to trigger MachineStateData change notifications
   * This ensures that when sub-object properties change, the parent MachineStateData is notified
   */
  protected registerSubObjectListeners(): void {
    // Register listener for spoilboardPosition CNCOffset
    StateManager.addObserver(this._spoilboardPosition, () => {
      StateManager.propertyChanged(this, 'spoilboardPosition');
    }, [], 'MachineStateData-SpoilboardPosition');

    // NOTE: currentMachinePoint is now in ConfigurationState and manages its own notifications
    // No need to register listener here since getter delegates to ConfigurationState.Instance.currentMachinePoint

    // Register listener for currentWorkZeroHome CNCPoint
    StateManager.addObserver(this._currentWorkZeroHome, () => {
      StateManager.propertyChanged(this, 'currentWorkZero');
      // Update API fixture point when work zero changes
      this.updateAPIFixturePoint();
    }, [], 'MachineStateData-CurrentWorkZeroHome');

    // Note: SimulatorViewData is no longer stored here - now managed by ViewSettings
    // Note: proposedSpindlePosition is in ConfigurationState (transient UI state, not saved)
    // Note: proposedJob, testJob, currentJobCache, lastJobCache are in ConfigurationState (runtime-only)
    // Note: Jobs are complex objects that manage their own listeners
  }

  /**
   * Unregister listeners on sub-objects before they are replaced during fromJSON
   */
  protected unregisterSubObjectListeners(): void {
    StateManager.removeObserverByName(this._spoilboardPosition, 'MachineStateData-SpoilboardPosition');
    // NOTE: currentMachinePoint is now in ConfigurationState - no listener to remove here
    StateManager.removeObserverByName(this._currentWorkZeroHome, 'MachineStateData-CurrentWorkZeroHome');
  }

  /**
   * Serialize to JSON - handle CNCPoint and Job sub-objects explicitly
   */
  public toJSON(): any {
    const baseData = DataUtilities.getStorageData(this, ['_instance', '_currentWorkZeroHome', '_spoilboardPosition']); // Exclude sub-objects and runtime-only properties

    // Handle sub-objects explicitly with proper serialization
    // NOTE: _simulatorViewDatas is excluded - now managed by ViewSettings
    // NOTE: proposedSpindlePosition is in ConfigurationState (transient UI state)
    // NOTE: proposedJob, testJob, currentJobCache, lastJobCache are in ConfigurationState (runtime-only)
    // NOTE: _currentMachinePoint is in ConfigurationState (runtime-only, synced from machine controller)
    return {
      ...baseData,
      _currentWorkZeroHome: this._currentWorkZeroHome.toJSON(),
      _spoilboardPosition: this._spoilboardPosition.toJSON(),
      _currentJobId: this._currentJobId || null, // Store only ID (job is in job storage)
      _lastJobId: this._lastJobId || null, // Store only ID (job is in job storage)
    };
  }

  /**
   * Load from JSON - handle CNCPoint and Job sub-objects explicitly
   */
  public fromJSON(data: any): void {
    // Unregister old listeners before replacing objects
    this.unregisterSubObjectListeners();

    // Load basic properties automatically
    DataUtilities.loadStorageData(this, data, ['_instance', '_currentWorkZeroHome', '_spoilboardPosition']); // Exclude sub-objects that need special handling

    // NOTE: _currentMachinePoint is now runtime-only state in ConfigurationState (synced from machine controller)
    // Old saved values for _currentMachinePoint are ignored for backward compatibility

    // Load current work zero home (new format)
    if (data._currentWorkZeroHome) {
      this._currentWorkZeroHome.fromJSON(data._currentWorkZeroHome);
    }
    // NOTE: Old _currentFixture data is ignored - no migration

    // Handle CNCOffset sub-objects explicitly
    if (data._spoilboardPosition) {
      this._spoilboardPosition.fromJSON(data._spoilboardPosition);
    }

    // NOTE: _simulatorViewDatas is no longer stored here - now managed by ViewSettings

    // Load job IDs (jobs will be fetched from job storage on demand)
    this._currentJobId = data._currentJobId || data._currentJob?.id; // Support old format
    this._lastJobId = data._lastJobId || data._lastJob?.id; // Support old format

    // Clear job caches in ConfigurationState (will be loaded on demand)
    ConfigurationState.Instance.currentJobCache = undefined;
    ConfigurationState.Instance.lastJobCache = undefined;

    // Handle old proposedJob data for backward compatibility (but don't load it)
    // proposedJob is now runtime-only in ConfigurationState, should not persist

    // Support old format: if full job data exists, migrate to storage
    // WORKAROUND: Dynamic require to avoid circular dependency (Job imports MachineStateData)
    if (data._currentJob && !this._currentJobId) {
      const { Job } = require('./Job');
      const job = new Job();
      job.fromJSON(data._currentJob);
      ConfigurationState.Instance.currentJob = job; // This will store to job storage and update _currentJobId
    }
    if (data._lastJob && !this._lastJobId) {
      const { Job } = require('./Job');
      const job = new Job();
      job.fromJSON(data._lastJob);
      ConfigurationState.Instance.lastJob = job; // This will store to job storage and update _lastJobId
    }

    // Re-register listeners on new objects
    this.registerSubObjectListeners();
  }

  /**
   * Get the singleton instance
   */
  public static get Instance(): MachineStateData {
    if (!SingletonRegistry.MachineStateData) {
      // Constructor will register with SingletonRegistry and throw if duplicate
      const instance = new MachineStateData();
      // Setup auto-save after instance is fully created
      instance.setupAutoSave();
      // Initialize connection state asynchronously
      instance.initializeConnectionState();
    }
    return SingletonRegistry.MachineStateData!;
  }

  /**
   * Initialize connection state by checking machine connection
   */
  private async initializeConnectionState(): Promise<void> {
    try {
      const machine = Machine.getInstance();
      const isConnected = await machine.system.IsConnectedToServer();
      ConfigurationState.Instance.isConnected = isConnected;
    } catch (error) {
      // If we can't check connection, assume disconnected
      // But in simulator mode, always consider connected
      if (MachineInterfaceManager.Instance.isUsingSimulator()) {
        ConfigurationState.Instance.isConnected = true;
      } else {
        ConfigurationState.Instance.isConnected = false;
      }
    }
  }

  /**
   * Call the API to update the fixture point on the machine
   */
  private updateAPIFixturePoint(): void {
    // Use async IIFE to call the API method
    (async () => {
      try {
        await Machine.getInstance().movement.SetCurrentFixturePoint();
      } catch (error) {
        // Silently fail - errors are already logged by the movement implementation
      }
    })();
  }
}
