import {
  Input as InputIcon,
  Output as OutputIcon,
  RestartAlt as ResetIcon
} from '@mui/icons-material';
import {
  Alert,
  Box,
  Button,
  CircularProgress,
  List,
  Paper,
  Typography
} from '@mui/material';
import { Component } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { IOStateData } from '../../data/IOStateData';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { Machine } from '../../machine/Machine';
import { LogCategory, Logger } from '../../utils/Logger';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { InputItem } from './InputItem';
import { OutputItem } from './OutputItem';

interface InputOutputDrawerProps {
  onViewChange?: (view: string) => void;
}

interface InputOutputDrawerState {
  loading: boolean;
  error: string | null;
}

export class InputOutputDrawer extends Component<InputOutputDrawerProps, InputOutputDrawerState> {

  constructor(props: InputOutputDrawerProps) {
    super(props);
    this.state = {
      loading: false,
      error: null
    };
  }

  private handleOutputToggle = async (outputNumber: number) => {
    // Get current state and toggle to opposite
    const output = IOStateData.Instance.getOutputByNumber(outputNumber);
    if (!output) {
      Logger.Instance.logError(LogCategory.UserInterface, `Output ${outputNumber} not found`);
      return;
    }

    const newState = !output.isActive;

    // In simulator mode, state updates immediately
    // In Centroid mode, state updates when events are received
    const machine = Machine.getInstance();
    await machine.io.SetOutputState(outputNumber, newState);
  }

  private handleResetAllOutputs = async () => {
    try {
      const machine = Machine.getInstance();
      if (!machine) {
        throw new Error('Machine instance not available');
      }

      const outputs = IOStateData.Instance.outputs;
      const forcedOutputs = outputs.filter(output => output.isForced);

      if (forcedOutputs.length === 0) {
        return;
      }


      // Reset all forced outputs
      for (const output of forcedOutputs) {
        await machine.io.ResetOutput(output.number);
      }

      // Refetch forced state from the machine
      const outputNumbers = IOStateData.Instance.outputs.map(o => o.number);
      const forcedOutputsState = await machine.io.GetForcedOutputs(outputNumbers);
      IOStateData.Instance.updateForcedOutputs(forcedOutputsState);

    } catch (error) {
      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to reset all outputs:', error);
      UserMessageQueue.Instance.addMessage('❌ Failed to reset outputs');
    }
  }

  render() {
    const { loading, error } = this.state;

    return (
      <>
        <ObserveState
          key="input-output-drawer"
          listenTo={IOStateData.Instance}
          properties={['inputs', 'outputs', 'isInitialized']}
          control={() => {
            const config = ConfigurationData.Instance;
            const colors = ConfigurationDataColors.Instance;
            const ioState = IOStateData.Instance;

            // Defensive check: ensure inputs and outputs are arrays, then sort by number
            const inputs = Array.isArray(ioState.inputs)
              ? [...ioState.inputs].sort((a, b) => a.number - b.number)
              : [];
            const outputs = Array.isArray(ioState.outputs)
              ? [...ioState.outputs].sort((a, b) => a.number - b.number)
              : [];

            return (
              <Box
                sx={{
                  height: '100%',
                  display: 'flex',
                  flexDirection: 'column',
                  backgroundColor: colors.lightBackgroundColor
                }}
              >
                {/* Error Display */}
                {error && (
                  <Alert severity="error" sx={{ m: 1 }}>
                    {error}
                  </Alert>
                )}

                {/* Loading Indicator */}
                {loading && (
                  <Box sx={{ display: 'flex', justifyContent: 'center', p: 2 }}>
                    <CircularProgress size={24} />
                  </Box>
                )}

                {/* Scrollable Content */}
                <Box sx={{ flex: 1, overflow: 'auto' }}>
                  {/* Inputs Section */}
                  {inputs.length > 0 && (
                    <Paper sx={{ m: 1, overflow: 'hidden' }} variant="outlined">
                      <Box sx={{
                        p: 1.5,
                        backgroundColor: colors.lightBackgroundColor,
                        borderBottom: `1px solid ${colors.secondaryBorderColor}`
                      }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                          <InputIcon sx={{ color: colors.primaryColor, fontSize: 18 }} />
                          <Typography variant="subtitle2" sx={{ fontWeight: 'bold', fontSize: '0.85rem' }}>
                            Inputs ({inputs.length})
                          </Typography>
                        </Box>
                      </Box>

                      <List sx={{ py: 0 }}>
                        {inputs.map((input) => (
                          <InputItem
                            key={`input-${input.number}`}
                            input={input}
                          />
                        ))}
                      </List>
                    </Paper>
                  )}

                  {/* Outputs Section */}
                  {outputs.length > 0 && (
                    <Paper sx={{ m: 1, overflow: 'hidden' }} variant="outlined">
                      <Box sx={{
                        p: 1.5,
                        backgroundColor: colors.lightBackgroundColor,
                        borderBottom: `1px solid ${colors.secondaryBorderColor}`
                      }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                            <OutputIcon sx={{ color: colors.primaryColor, fontSize: 18 }} />
                            <Typography variant="subtitle2" sx={{ fontWeight: 'bold', fontSize: '0.85rem' }}>
                              Outputs ({outputs.length})
                            </Typography>
                          </Box>
                          <Button
                            size="small"
                            startIcon={<ResetIcon sx={{ fontSize: 14 }} />}
                            onClick={this.handleResetAllOutputs}
                            sx={{
                              fontSize: '0.7rem',
                              textTransform: 'none',
                              minWidth: 'auto',
                              py: 0.25,
                              px: 1
                            }}
                          >
                            Reset All
                          </Button>
                        </Box>
                      </Box>

                      <List sx={{ py: 0 }}>
                        {outputs.map((output) => (
                          <OutputItem
                            key={`output-${output.number}`}
                            output={output}
                            onToggle={this.handleOutputToggle}
                          />
                        ))}
                      </List>
                    </Paper>
                  )}

                  {/* No I/O configured message */}
                  {inputs.length === 0 && outputs.length === 0 && (
                    <Box sx={{ p: 3, textAlign: 'center' }}>
                      <Typography variant="body2" sx={{ color: colors.mutedTextColor }}>
                        No inputs or outputs configured
                      </Typography>
                    </Box>
                  )}
                </Box>
              </Box>
            );
          }}
        />
      </>
    );
  }
}