import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataElement } from './DataElement';
import { DataType, Declaration, Visibility, formatDeclarationName } from './Declaration';
import { DeclarationScope, IPLCSource, PLCUtilities } from './PLCUtilities';

/**
 * Controller for DataElementPickerDialog
 * Manages all dialog state using StateManager pattern
 */
export class DataElementPickerDialogController {
    private _dataElement: DataElement;
    private _program: IPLCSource | undefined;

    // UI State
    private _tabIndex: number = 0;
    private _searchText: string = '';
    private _scope: DeclarationScope = DeclarationScope.All;

    // Mode: 'pick' = selecting new, 'edit' = editing user-defined, 'display' = viewing system/picked
    private _mode: 'pick' | 'edit' | 'display' = 'pick';

    // Working declaration (for edit/display modes)
    private _workingDeclaration: Declaration | undefined;

    // Edit fields (bound to UI controls)
    private _editName: string = '';
    private _editDisplayName: string = '';
    private _editDescription: string = '';
    private _editDataType: DataType = DataType.MemoryBit;
    private _editVisibility: Visibility = Visibility.Visible;
    private _editCategory: string[] = [];
    private _editIsSetText: string = 'Set';
    private _editIsResetText: string = 'Reset';

    // Saved values for cancel operation (only used in edit mode)
    private _savedIsSetText: string = 'Set';
    private _savedIsResetText: string = 'Reset';

    constructor(dataElement: DataElement) {
        this._dataElement = dataElement;
        this._program = dataElement.getPLCProgram();

        // Initialize state from dataElement
        this.initializeFromDataElement();
    }

    /**
     * Initialize controller state from the data element
     */
    private initializeFromDataElement(): void {
        const hasExistingDeclaration = this._dataElement.isDefinition || this._dataElement.isReference;
        const isUserDefined = this._dataElement.declaration && !this._dataElement.declaration.isSystem;

        // Determine mode
        if (!hasExistingDeclaration) {
            this._mode = 'pick';
            this._tabIndex = 0; // Start on Existing tab
        } else if (isUserDefined) {
            this._mode = 'edit';
            this._tabIndex = 1; // Show Define tab
        } else {
            this._mode = 'display';
            this._tabIndex = 0; // Show Existing tab with read-only view
        }

        // Load working declaration
        if (hasExistingDeclaration) {
            const declarationName = this._dataElement.declarationName || this._dataElement.declaration?.name;
            if (declarationName && this._program) {
                this._workingDeclaration = PLCUtilities.getDeclarationByName(this._program, declarationName);
            }

            // If not found in program but we have local declaration, use it
            if (!this._workingDeclaration && this._dataElement.declaration) {
                this._workingDeclaration = this._dataElement.declaration;
            }
        }

        // Initialize edit fields from working declaration or defaults
        if (this._workingDeclaration) {
            this._editName = this._workingDeclaration.name;
            this._editDisplayName = this._workingDeclaration.displayName || '';
            this._editDescription = this._workingDeclaration.description;
            this._editDataType = this._workingDeclaration.dataType;
            this._editVisibility = this._workingDeclaration.visibility;
            this._editCategory = [...this._workingDeclaration.category];
            this._editIsSetText = this._workingDeclaration.isSetText;
            this._editIsResetText = this._workingDeclaration.isResetText;
            // Save original values for cancel
            this._savedIsSetText = this._workingDeclaration.isSetText;
            this._savedIsResetText = this._workingDeclaration.isResetText;
        } else {
            // Default values for new declaration
            this._editName = '';
            this._editDisplayName = '';
            this._editDescription = '';
            this._editDataType = DataType.MemoryBit;
            this._editVisibility = Visibility.Visible;
            this._editCategory = ['* User Defined'];
            this._editIsSetText = 'Set';
            this._editIsResetText = 'Reset';
        }
    }

    // ===== Getters/Setters for UI State =====

    public get dataElement(): DataElement {
        return this._dataElement;
    }

    public get program(): IPLCSource | undefined {
        return this._program;
    }

    public get tabIndex(): number {
        return this._tabIndex;
    }

    public set tabIndex(value: number) {
        this._tabIndex = value;
        StateManager.propertyChanged(this, 'tabIndex');
    }

    public get searchText(): string {
        return this._searchText;
    }

    public set searchText(value: string) {
        this._searchText = value;
        StateManager.propertyChanged(this, 'searchText');
    }

    public get scope(): DeclarationScope {
        return this._scope;
    }

    public set scope(value: DeclarationScope) {
        this._scope = value;
        StateManager.propertyChanged(this, 'scope');
    }

    public get mode(): 'pick' | 'edit' | 'display' {
        return this._mode;
    }

    public get workingDeclaration(): Declaration | undefined {
        return this._workingDeclaration;
    }

    // ===== Getters/Setters for Edit Fields =====

    public get editName(): string {
        return this._editName;
    }

    public set editName(value: string) {
        this._editName = value;
        StateManager.propertyChanged(this, 'editName');
    }

    public get editDisplayName(): string {
        return this._editDisplayName;
    }

    public set editDisplayName(value: string) {
        this._editDisplayName = value;
        StateManager.propertyChanged(this, 'editDisplayName');
    }

    public get editDescription(): string {
        return this._editDescription;
    }

    public set editDescription(value: string) {
        this._editDescription = value;
        StateManager.propertyChanged(this, 'editDescription');
    }

    public get editDataType(): DataType {
        return this._editDataType;
    }

    public set editDataType(value: DataType) {
        const oldType = this._editDataType;
        this._editDataType = value;

        // If data type changed and we have a name, update the suffix
        if (oldType !== value && this._editName.trim()) {
            this._editName = formatDeclarationName(this._editName, value);
            StateManager.propertyChanged(this, 'editName');
        }

        StateManager.propertyChanged(this, 'editDataType');
    }

    public get editVisibility(): Visibility {
        return this._editVisibility;
    }

    public set editVisibility(value: Visibility) {
        this._editVisibility = value;
        StateManager.propertyChanged(this, 'editVisibility');
    }

    public get editCategory(): string[] {
        return this._editCategory;
    }

    public set editCategory(value: string[]) {
        this._editCategory = value;
        StateManager.propertyChanged(this, 'editCategory');
    }

    public get editIsSetText(): string {
        return this._editIsSetText;
    }

    public set editIsSetText(value: string) {
        this._editIsSetText = value;
        // In edit mode, directly modify the working declaration
        if (this._mode === 'edit' && this._workingDeclaration) {
            this._workingDeclaration.isSetText = value;
        }
        StateManager.propertyChanged(this, 'editIsSetText');
    }

    public get editIsResetText(): string {
        return this._editIsResetText;
    }

    public set editIsResetText(value: string) {
        this._editIsResetText = value;
        // In edit mode, directly modify the working declaration
        if (this._mode === 'edit' && this._workingDeclaration) {
            this._workingDeclaration.isResetText = value;
        }
        StateManager.propertyChanged(this, 'editIsResetText');
    }

    // ===== Actions =====

    /**
     * Select an existing declaration from the list
     */
    public selectDeclaration(declaration: Declaration): void {
        this._workingDeclaration = declaration;
        StateManager.propertyChanged(this, 'workingDeclaration');
    }

    /**
     * Switch to define mode for creating a new declaration
     */
    public startDefineNew(): void {
        this._mode = 'edit';
        this._tabIndex = 1; // Switch to Define tab

        // Reset edit fields
        this._editName = '';
        this._editDisplayName = '';
        this._editDescription = '';
        this._editDataType = DataType.MemoryBit;
        this._editVisibility = Visibility.Visible;
        this._editCategory = ['* User Defined'];
        this._editIsSetText = 'Set';
        this._editIsResetText = 'Reset';
        this._workingDeclaration = undefined;

        StateManager.propertyChanged(this, 'mode');
        StateManager.propertyChanged(this, 'tabIndex');
        StateManager.propertyChanged(this, 'editName');
        StateManager.propertyChanged(this, 'editDisplayName');
        StateManager.propertyChanged(this, 'editDescription');
        StateManager.propertyChanged(this, 'editDataType');
        StateManager.propertyChanged(this, 'editVisibility');
        StateManager.propertyChanged(this, 'editCategory');
        StateManager.propertyChanged(this, 'editIsSetText');
        StateManager.propertyChanged(this, 'editIsResetText');
        StateManager.propertyChanged(this, 'workingDeclaration');
    }

    /**
     * Switch back to pick mode to select another declaration
     */
    public returnToPick(): void {
        this._mode = 'pick';
        this._tabIndex = 0; // Switch to Pick Existing tab
        this._searchText = '';
        this._workingDeclaration = undefined;

        StateManager.propertyChanged(this, 'mode');
        StateManager.propertyChanged(this, 'tabIndex');
        StateManager.propertyChanged(this, 'searchText');
        StateManager.propertyChanged(this, 'workingDeclaration');
    }

    /**
     * Validate the current state
     */
    public isValid(): boolean {
        // For pick mode on Define New tab (tabIndex 1), validate edit fields
        if (this._mode === 'pick' && this._tabIndex === 1) {
            return this._editName.trim().length > 0;
        }

        // For pick mode on Pick Existing tab, must have selected declaration
        if (this._mode === 'pick') {
            return this._workingDeclaration !== undefined;
        }

        // For edit mode, must have valid name
        if (this._mode === 'edit') {
            return this._editName.trim().length > 0;
        }

        // Display mode is always valid (read-only)
        return true;
    }

    /**
     * Apply changes to the data element
     * This is called when the user confirms the dialog
     */
    public apply(): void {
        if (this._mode === 'pick' && this._workingDeclaration) {
            // User picked an existing declaration - set reference
            this._dataElement.declarationName = this._workingDeclaration.name;
            this._dataElement.declaration = undefined; // Clear local declaration

        } else if (this._mode === 'edit' || (this._mode === 'pick' && this._tabIndex === 1 && this._editName.trim())) {
            // User defined/edited a declaration - create/update local declaration
            // This handles both explicit edit mode AND being on the Define New tab (tabIndex 1) with a name entered
            // Format name with proper suffix based on data type
            const formattedName = formatDeclarationName(this._editName.trim(), this._editDataType);

            // In edit mode, update the existing declaration instead of creating a new one
            if (this._mode === 'edit' && this._workingDeclaration) {
                this._workingDeclaration.name = formattedName;
                this._workingDeclaration.displayName = this._editDisplayName.trim() || undefined;
                this._workingDeclaration.description = this._editDescription.trim();
                this._workingDeclaration.dataType = this._editDataType;
                this._workingDeclaration.visibility = this._editVisibility;
                this._workingDeclaration.category = [...this._editCategory];
                this._workingDeclaration.isSetText = this._editIsSetText;
                this._workingDeclaration.isResetText = this._editIsResetText;

                // Update the data element's declaration reference if name changed
                // This ensures the statement uses the new name
                if (this._dataElement.declaration) {
                    this._dataElement.declaration = this._workingDeclaration;
                } else if (this._dataElement.declarationName) {
                    this._dataElement.declarationName = formattedName;
                }
            } else {
                // Creating new declaration (Define New tab)
                const declaration = new Declaration(formattedName);
                declaration.displayName = this._editDisplayName.trim() || undefined;
                declaration.description = this._editDescription.trim();
                declaration.dataType = this._editDataType;
                declaration.visibility = this._editVisibility;
                declaration.category = [...this._editCategory];
                declaration.isSetText = this._editIsSetText;
                declaration.isResetText = this._editIsResetText;

                // Set as definition
                this._dataElement.declaration = declaration;
                this._dataElement.declarationName = undefined; // Clear reference name
            }
        }

        // Display mode doesn't change anything - it's read-only
    }

    /**
     * Cancel editing and restore original values
     */
    public cancel(): void {
        // Restore original values in edit mode
        if (this._mode === 'edit' && this._workingDeclaration) {
            this._workingDeclaration.isSetText = this._savedIsSetText;
            this._workingDeclaration.isResetText = this._savedIsResetText;
        }
    }

    /**
     * Get available declarations based on current filters
     */
    public getFilteredDeclarations(): Declaration[] {
        if (!this._program) return [];

        let declarations = PLCUtilities.searchDeclarations(
            this._program,
            this._searchText,
            {
                scope: this._scope,
                scopeContext: this._dataElement.getParentElement(),
                includeHidden: false
            }
        );

        return declarations;
    }
}
