import { IStorable } from '../../common/IStorable';
import { StateManager } from '../../utils/statemanager/StateManager';
import { DataUtilities } from '../../utils/storage/DataUtilities';

/**
 * ATC Structural Dimensions class
 */



export class ATCStructure implements IStorable {
    private _postWidth: number = 2;
    private _postLength: number = 2;
    private _barHeight: number = 2;
    private _barWidth: number = 3;
    private _barLength: number = 54;
    private _postOffsetFromRails: number = 2;

    public get postWidth(): number { return this._postWidth; }
    public set postWidth(value: number) {
        this._postWidth = value;
        StateManager.propertyChanged(this, 'postWidth');
    }

    public get postLength(): number { return this._postLength; }
    public set postLength(value: number) {
        this._postLength = value;
        StateManager.propertyChanged(this, 'postLength');
    }

    public get barHeight(): number { return this._barHeight; }
    public set barHeight(value: number) {
        this._barHeight = value;
        StateManager.propertyChanged(this, 'barHeight');
    }

    public get barWidth(): number { return this._barWidth; }
    public set barWidth(value: number) {
        this._barWidth = value;
        StateManager.propertyChanged(this, 'barWidth');
    }

    public get barLength(): number { return this._barLength; }
    public set barLength(value: number) {
        this._barLength = value;
        StateManager.propertyChanged(this, 'barLength');
    }

    public get postOffsetFromRails(): number { return this._postOffsetFromRails; }
    public set postOffsetFromRails(value: number) {
        this._postOffsetFromRails = value;
        StateManager.propertyChanged(this, 'postOffsetFromRails');
    }

    public toJSON(): object {
        return DataUtilities.getStorageData(this);
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}
