import { CNCPoint } from '../CNCPoint';

/**
 * Represents a plane defined by 4 points in 3D space
 * Used for intersection calculations and collision detection
 */
export class Plane {
  public point1: CNCPoint;
  public point2: CNCPoint;
  public point3: CNCPoint;
  public point4: CNCPoint;

  constructor(
    point1: CNCPoint,
    point2: CNCPoint,
    point3: CNCPoint,
    point4: CNCPoint
  ) {
    this.point1 = point1;
    this.point2 = point2;
    this.point3 = point3;
    this.point4 = point4;
  }

  /**
   * Create a plane from 3 points (4th point calculated for completeness)
   */
  static fromThreePoints(
    point1: CNCPoint,
    point2: CNCPoint,
    point3: CNCPoint
  ): Plane {
    // Calculate 4th point to complete the plane (assuming rectangular plane)
    const point4 = new CNCPoint(
      point1.x + (point3.x - point2.x),
      point1.y + (point3.y - point2.y),
      point1.z + (point3.z - point2.z),
      point1.coordinateType
    );
    
    return new Plane(point1, point2, point3, point4);
  }
}
