import {
  Home as HomeIcon,
  OpenWith as JogIcon,
  FlashOn as LaserIcon,
  School as LearningIcon,
  Terminal as MDIIcon,
  Memory as PLCIcon,
  PlayArrow as RunIcon,
  Settings as SettingsIcon,
  Rotate90DegreesCcw as TurningIcon,
  ThreeDRotation as Viewer3DIcon,
} from '@mui/icons-material';
import {
  Box,
  Chip,
  IconButton,
  ListItemButton,
  Tooltip,
  Typography,
} from '@mui/material';
import React, { useState } from 'react';
import { SetupChecklistLibrary } from '../../data/Checklist/SetupChecklistLibrary';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineInterfaceManager } from '../../utils/MachineInterfaceManager';
import { ObserveMultiState } from '../../utils/statemanager/ObserveMultiState';

interface LeftNavigationProps {
  selectedView: string;
  onViewChange: (view: string) => void;
  onJogClick?: () => void;
  onViewerClick?: () => void;
}

interface NavigationItem {
  id: string;
  label: string;
  icon: React.ComponentType;
  showCondition?: (config: ConfigurationData) => boolean;
}

const navigationItems: NavigationItem[] = [
  { id: 'home', label: 'Home', icon: HomeIcon },
  { id: 'milling', label: 'Run', icon: RunIcon },
  { id: 'learning', label: 'Learning', icon: LearningIcon, showCondition: (config) => config.showLearningFeature },
  { id: 'mdi', label: 'MDI', icon: MDIIcon },
  { id: 'turning', label: 'Turning', icon: TurningIcon, showCondition: (config) => config.showTurningFeature },
  { id: 'laser', label: 'Laser', icon: LaserIcon, showCondition: (config) => config.showLaserFeature },
  { id: 'settings', label: 'Data', icon: SettingsIcon },
  { id: 'plc', label: 'Setup', icon: PLCIcon },
];

export function LeftNavigation({ selectedView, onViewChange, onJogClick, onViewerClick }: LeftNavigationProps) {
  const [config] = useState(() => ConfigurationData.Instance);
  const [colors] = useState(() => ConfigurationDataColors.Instance);
  const [checklistLibrary] = useState(() => SetupChecklistLibrary.Instance);

  return (
    <ObserveMultiState
      key="left-navigation"
      listenTo={[config, checklistLibrary]}
      control={() => {
        // Filter navigation items based on feature flags
        const visibleItems = navigationItems.filter(item =>
          !item.showCondition || item.showCondition(config)
        );

        // Get incomplete checklist count
        const incompleteCount = checklistLibrary.incompleteItems.length;

        return (
          <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
            {/* Navigation Items */}
            <Box sx={{ flexGrow: 1, p: 1 }}>
              {visibleItems.map((item) => {
                const IconComponent = item.icon;
                const isSelected = selectedView === item.id;

                return (
                  <Box key={item.id} sx={{ mb: 1 }}>
                    <ListItemButton
                      selected={isSelected}
                      onClick={() => {
                        if (item.id === 'milling') {
                          // WORKAROUND: Dynamic property for component communication
                          // _millingTriggerRun is set by Milling component to reset workflow
                          const trigger = (ConfigurationState.Instance as any)._millingTriggerRun;
                          if (trigger) trigger();
                        }
                        onViewChange(item.id);
                      }}
                      sx={{
                        width: 75,
                        height: 75,
                        borderRadius: 1,
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        justifyContent: 'center',
                        bgcolor: isSelected ? `${colors.darkTextColor}05` : `${colors.lightTextColor}00`,
                        border: isSelected ? '1px solid' : `1px solid ${colors.lightTextColor}00`,
                        borderColor: isSelected ? colors.secondaryColor : `${colors.lightTextColor}00`,
                        color: isSelected ? colors.secondaryColor : 'text.primary',
                        '&:hover': {
                          bgcolor: isSelected ? `${colors.darkTextColor}0A` : 'action.hover',
                          borderColor: isSelected ? colors.primaryColor : `${colors.lightTextColor}00`,
                        },
                        '&.Mui-selected': {
                          bgcolor: `${colors.darkTextColor}05`,
                          border: '1px solid',
                          borderColor: colors.secondaryColor,
                          color: colors.secondaryColor,
                          '&:hover': {
                            bgcolor: `${colors.darkTextColor}0A`,
                            borderColor: colors.primaryColor,
                          },
                        },
                      }}
                    >
                      <Box sx={{ position: 'relative', fontSize: 28, mb: 0.5 }}>
                        <IconComponent />
                        {item.id === 'plc' && incompleteCount > 0 && (
                          <Box
                            sx={{
                              position: 'absolute',
                              top: -4,
                              right: -4,
                              bgcolor: colors.errorColor,
                              color: colors.lightTextColor,
                              borderRadius: '50%',
                              minWidth: 20,
                              height: 20,
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'center',
                              fontSize: '0.7rem',
                              fontWeight: 'bold',
                              px: 0.5,
                            }}
                          >
                            {incompleteCount}
                          </Box>
                        )}
                      </Box>
                      <Typography variant="caption" sx={{ fontSize: '0.65rem', textAlign: 'center' }}>
                        {item.label}
                      </Typography>
                    </ListItemButton>
                  </Box>
                );
              })}
            </Box>

            {/* Simulator Mode Indicator */}
            {MachineInterfaceManager.Instance.isUsingSimulator() && (
              <Box sx={{ px: 1, pb: 1 }}>
                <Chip
                  label="Simulator"
                  size="small"
                  sx={{
                    width: 75,
                    bgcolor: 'warning.main',
                    color: 'warning.contrastText',
                    fontWeight: 'bold',
                    fontSize: '0.6rem',
                    height: 20,
                    borderRadius: 1,
                  }}
                />
              </Box>
            )}

            {/* Jog Controls Button at Bottom */}
            {onJogClick && (
              <Box sx={{ p: 1, borderTop: '1px solid', borderColor: 'divider' }}>
                <Tooltip title="Jog Controls" placement="right">
                  <IconButton
                    onClick={onJogClick}
                    sx={{
                      width: 75,
                      height: 75,
                      borderRadius: 1,
                      border: `1px solid ${colors.lightTextColor}00`,
                      '&:hover': {
                        bgcolor: 'action.hover',
                        borderColor: 'primary.main',
                      },
                    }}
                  >
                    <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                      <Box sx={{ fontSize: 28, mb: 0.5 }}>
                        <JogIcon />
                      </Box>
                      <Typography variant="caption" sx={{ fontSize: '0.65rem', textAlign: 'center' }}>
                        Jog
                      </Typography>
                    </Box>
                  </IconButton>
                </Tooltip>
              </Box>
            )}

            {/* 3D Viewer Button */}
            {onViewerClick && (
              <Box sx={{ p: 1 }}>
                <Tooltip title="3D Viewer" placement="right">
                  <IconButton
                    onClick={onViewerClick}
                    sx={{
                      width: 75,
                      height: 75,
                      borderRadius: 1,
                      border: `1px solid ${colors.lightTextColor}00`,
                      '&:hover': {
                        bgcolor: 'action.hover',
                        borderColor: 'primary.main',
                      },
                    }}
                  >
                    <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                      <Box sx={{ fontSize: 28, mb: 0.5 }}>
                        <Viewer3DIcon />
                      </Box>
                      <Typography variant="caption" sx={{ fontSize: '0.65rem', textAlign: 'center' }}>
                        3D View
                      </Typography>
                    </Box>
                  </IconButton>
                </Tooltip>
              </Box>
            )}
          </Box>
        );
      }}
    />
  );
}