import { ToggleButton, ToggleButtonGroup, Tooltip } from '@mui/material';
import React, { useEffect } from 'react';
import { CNCPoint } from '../../data/CNCPoint';
import { CoordinateType } from '../../data/Common/CoordinateType';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineData } from '../../data/Machine/MachineData';
import { MachineStateData } from '../../data/MachineStateData';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { JogDirection, Machine } from '../../machine/Machine';
import { ActionBus } from '../../utils/actions/ActionBus';
import { MoveAction, MoveType } from '../../utils/actions/MoveAction';
import { CoordinateUtil } from '../../utils/CoordinateUtil';
import { JogRenewalManager } from '../../utils/JogRenewalManager';
import { LogCategory, Logger } from '../../utils/Logger';
import { ObserveMultiProperties } from '../../utils/statemanager/ObserveMultiProperties';
import { AxisCoordinateDisplay } from './AxisCoordinateDisplay';
import { SafeModeControl } from './SafeModeControl';

export function JogControls() {
  // Get singletons directly
  const machineState = MachineStateData.Instance;
  const configState = ConfigurationState.Instance;

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      // Stop any ongoing jog movement and cleanup renewal timers
      JogRenewalManager.Instance.cleanup();
    };
  }, []);

  const handleJogStart = async (direction: JogDirection) => {
    try {
      // Use JogRenewalManager to handle jog with automatic renewal
      await JogRenewalManager.Instance.startJog(direction);
    } catch (error) {
      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to start jog:', error);
      UserMessageQueue.Instance.addMessage('❌ Failed to start jog movement');
    }
  };

  const handleJogStop = () => {
    // Stop all jog movements using renewal manager
    JogRenewalManager.Instance.stopAll();
  };

  // Removed unused getCoordinateTextColor function - not used by AxisCoordinateDisplay component
  // Removed unused handleSetWorkZero function - work zero setting is handled by AxisCoordinateDisplay component
  // Removed unused handleGoToPosition function - go to position is handled by AxisCoordinateDisplay component
  // Removed unused handleCoordinateChange function - coordinate changes are handled by AxisCoordinateDisplay component
  // Removed unused getCoordinateValue function - coordinate display is handled by AxisCoordinateDisplay component
  // Removed unused getButtonType function - button type logic is handled by AxisCoordinateDisplay component

  const containerStyle: React.CSSProperties = {
    display: 'flex',
    flexDirection: 'column',
    gap: '5px',
    padding: '20px',
    minWidth: '625px', // Add minimum width to ensure buttons have room
    fontFamily: 'Arial, sans-serif'
  };

  const leftSideStyle: React.CSSProperties = {
    flex: 1,
    maxWidth: 'calc(50% - 50px)' // Reduced by 50px to bring divider closer to buttons
  };

  const rightSideStyle: React.CSSProperties = {
    flex: 1, // Allow it to take remaining space
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center' // Center content horizontally
  };

  // Removed unused coordinateRowStyle - row styling is handled by AxisCoordinateDisplay component

  const jogButtonStyle: React.CSSProperties = {
    backgroundColor: ConfigurationDataColors.Instance.primaryColor,
    color: ConfigurationDataColors.Instance.lightTextColor,
    border: 'none', // Remove border
    borderRadius: '5px', // Increased from 4px (20%)
    padding: '13px', // Increased from 11px (20%)
    cursor: 'pointer',
    fontSize: '25px', // Increased from 21px (20%)
    fontWeight: 'bold', // Keep bold but not extreme
    width: '56px', // Increased from 47px (20%)
    height: '56px', // Increased from 47px (20%)
    zIndex: 20 // Ensure buttons are on top
  };

  const jogContainerStyle: React.CSSProperties = {
    display: 'flex',
    gap: '10px', // Reduced from 20px
    alignItems: 'center'
  };

  const xyJogStyle: React.CSSProperties = {
    position: 'relative',
    width: '190px', // Increased from 158px (20%)
    height: '190px', // Increased from 158px (20%)
    backgroundColor: ConfigurationDataColors.Instance.primaryColor, // Same color as buttons
    borderRadius: '13px' // Increased from 11px (20%)
  };

  const zJogStyle: React.CSSProperties = {
    display: 'flex',
    flexDirection: 'column',
    gap: '13px', // Increased from 11px (20%)
    alignItems: 'center'
  };

  return (
    <>
      <style>
        {`
          .custom-range-slider::-webkit-slider-thumb {
            appearance: none;
            width: 16px;
            height: 16px;
            background: ${ConfigurationDataColors.Instance.primaryColor};
            border-radius: 50%;
            cursor: pointer;
            border: 2px solid ${ConfigurationDataColors.Instance.lightTextColor};
            box-shadow: 0 2px 4px ${ConfigurationDataColors.Instance.shadowColor};
          }
          
          .custom-range-slider::-webkit-slider-track {
            appearance: none;
            height: 4px;
            background: linear-gradient(to right, ${ConfigurationDataColors.Instance.primaryColor} 0%, ${ConfigurationDataColors.Instance.primaryColor} var(--slider-progress, 0%), ${ConfigurationDataColors.Instance.borderColor} var(--slider-progress, 0%), ${ConfigurationDataColors.Instance.borderColor} 100%);
            border-radius: 2px;
          }
          
          .custom-range-slider::-moz-range-thumb {
            width: 16px;
            height: 16px;
            background: ${ConfigurationDataColors.Instance.primaryColor};
            border-radius: 50%;
            cursor: pointer;
            border: 2px solid ${ConfigurationDataColors.Instance.lightTextColor};
            box-shadow: 0 2px 4px ${ConfigurationDataColors.Instance.shadowColor};
          }
          
          .custom-range-slider::-moz-range-track {
            height: 4px;
            background: ${ConfigurationDataColors.Instance.borderColor};
            border-radius: 2px;
          }
        `}
      </style>
      <ObserveMultiProperties
        key="jog-controls-observers"
        listenTo={[
          {
            object: machineState,
            properties: ['currentWorkZero', 'currentFixtureNumber']
          },
          {
            object: ConfigurationState.Instance,
            properties: ['proposedSpindlePosition', 'currentMachinePoint']
          }
        ]}
        control={() => (
          <div style={containerStyle}>
            {/* Main content section - 50/50 split */}
            <div style={{ display: 'flex', gap: '5px' }}>
              {/* Left side - Coordinates with individual Set/Go buttons */}
              <div style={leftSideStyle}>

                {/* Coordinates Display using AxisCoordinateDisplay component */}
                <div style={{ marginBottom: '16px' }}>
                  <AxisCoordinateDisplay
                    axes={['X', 'Y', 'Z']}
                    showButtons={true}
                    showCoordinateTypeToggle={true}
                    inputWidth="120px"
                    labelFontSize="0.875rem"
                    valueFontSize="1rem"
                    buttonWidth="60px"
                    buttonHeight="40px"
                    gap={0.5}
                    axisGap={1}
                    instanceKey="jog-controls-axis-display"
                  />
                </div>
              </div>

              {/* Vertical separator bar */}
              <div style={{
                width: '1px',
                backgroundColor: ConfigurationDataColors.Instance.borderColor,
                margin: '0 8px',
                minHeight: '200px',
                alignSelf: 'stretch',
                zIndex: 10,
                position: 'relative'
              }}></div>

              {/* Right side - Jog Controls */}
              <div style={rightSideStyle}>
                <div style={jogContainerStyle}>
                  {/* XY Movement - 8 directions */}
                  <div style={xyJogStyle}>
                    {/* Center point - Go to Work Home button */}
                    <button
                      onClick={() => {
                        // Go to work home (0,0,0) - create work coordinate point with offsets and convert to machine coordinates
                        const workHomePosition = new CNCPoint(0, 0, 0, CoordinateType.WorkZeroWithOffsets);
                        const machinePosition = CoordinateUtil.toMachineZero(workHomePosition);
                        const moveAction = MoveAction.fromCNCPoint(machinePosition, MoveType.Coordinates);
                        ActionBus.Instance.addAction(moveAction);
                      }}
                      style={{
                        position: 'absolute',
                        top: '50%',
                        left: '50%',
                        transform: 'translate(-50%, -50%)',
                        width: '31px', // Increased from 26px (20%)
                        height: '31px', // Increased from 26px (20%)
                        backgroundColor: ConfigurationDataColors.Instance.successColor,
                        color: ConfigurationDataColors.Instance.lightTextColor,
                        border: 'none',
                        borderRadius: '50%',
                        cursor: 'pointer',
                        fontSize: '13px', // Increased from 11px (20%)
                        fontWeight: 'bold'
                      }}
                      title="Go to Work Home (0,0,0)"
                    >
                      H
                    </button>

                    {/* 8 directional buttons */}
                    {/* North */}
                    <button
                      onMouseDown={() => handleJogStart(JogDirection.YPlus)}
                      onMouseUp={handleJogStop}
                      onMouseLeave={handleJogStop}
                      style={{ ...jogButtonStyle, position: 'absolute', top: '0', left: '50%', transform: 'translateX(-50%)' }}
                    >
                      ▲
                    </button>

                    {/* Northeast */}
                    <button
                      onMouseDown={() => handleJogStart(JogDirection.XPlusYPlus)}
                      onMouseUp={handleJogStop}
                      onMouseLeave={handleJogStop}
                      style={{ ...jogButtonStyle, position: 'absolute', top: '13px', right: '13px' }}
                    >
                      ⬈
                    </button>

                    {/* East */}
                    <button
                      onMouseDown={() => handleJogStart(JogDirection.XPlus)}
                      onMouseUp={handleJogStop}
                      onMouseLeave={handleJogStop}
                      style={{ ...jogButtonStyle, position: 'absolute', right: '0', top: '50%', transform: 'translateY(-50%)' }}
                    >
                      ▶
                    </button>

                    {/* Southeast */}
                    <button
                      onMouseDown={() => handleJogStart(JogDirection.XPlusYMinus)}
                      onMouseUp={handleJogStop}
                      onMouseLeave={handleJogStop}
                      style={{ ...jogButtonStyle, position: 'absolute', bottom: '13px', right: '13px' }}
                    >
                      ⬊
                    </button>

                    {/* South */}
                    <button
                      onMouseDown={() => handleJogStart(JogDirection.YMinus)}
                      onMouseUp={handleJogStop}
                      onMouseLeave={handleJogStop}
                      style={{ ...jogButtonStyle, position: 'absolute', bottom: '0', left: '50%', transform: 'translateX(-50%)' }}
                    >
                      ▼
                    </button>

                    {/* Southwest */}
                    <button
                      onMouseDown={() => handleJogStart(JogDirection.XMinusYMinus)}
                      onMouseUp={handleJogStop}
                      onMouseLeave={handleJogStop}
                      style={{ ...jogButtonStyle, position: 'absolute', bottom: '13px', left: '13px' }}
                    >
                      ⬋
                    </button>

                    {/* West */}
                    <button
                      onMouseDown={() => handleJogStart(JogDirection.XMinus)}
                      onMouseUp={handleJogStop}
                      onMouseLeave={handleJogStop}
                      style={{ ...jogButtonStyle, position: 'absolute', left: '0', top: '50%', transform: 'translateY(-50%)' }}
                    >
                      ◀
                    </button>

                    {/* Northwest */}
                    <button
                      onMouseDown={() => handleJogStart(JogDirection.XMinusYPlus)}
                      onMouseUp={handleJogStop}
                      onMouseLeave={handleJogStop}
                      style={{ ...jogButtonStyle, position: 'absolute', top: '13px', left: '13px' }}
                    >
                      ⬉
                    </button>
                  </div>

                  {/* Z Movement */}
                  <div style={zJogStyle}>
                    <button
                      onMouseDown={() => handleJogStart(JogDirection.ZPlus)}
                      onMouseUp={handleJogStop}
                      onMouseLeave={handleJogStop}
                      style={jogButtonStyle}
                    >
                      ▲
                    </button>
                    <button
                      onMouseDown={() => handleJogStart(JogDirection.ZMinus)}
                      onMouseUp={handleJogStop}
                      onMouseLeave={handleJogStop}
                      style={jogButtonStyle}
                    >
                      ▼
                    </button>
                  </div>
                </div>
              </div>
            </div> {/* Close main content section */}

            {/* Speed and Mode Controls - Full Width Below Everything */}
            <ObserveMultiProperties
              key="jog-mode-controls-full-width"
              listenTo={[
                { object: configState, properties: ['jogContinuousMode', 'jogFastMode', 'jogIncrementSpeed'] },
                { object: MachineData.Instance, properties: ['linearJogIncrement'] }
              ]}
              control={() => (
                <div style={{
                  marginTop: '16px',
                  paddingTop: '16px',
                  borderTop: `1px solid ${ConfigurationDataColors.Instance.borderColor}`,
                  display: 'flex',
                  gap: '16px',
                  justifyContent: 'center',
                  alignItems: 'center'
                }}>
                  {/* Speed Increment Buttons */}
                  <ToggleButtonGroup
                    value={configState.jogIncrementSpeed}
                    exclusive
                    onChange={async (e, value) => {
                      if (value !== null) {
                        try {
                          configState.jogIncrementSpeed = value;
                          await Machine.getInstance().movement.SetJogIncrementSpeed(value);
                        } catch (error) {
                          Logger.Instance.logError(LogCategory.UserInterface, 'Failed to set jog increment speed:', error);
                          UserMessageQueue.Instance.addMessage('❌ Failed to set jog speed');
                        }
                      }
                    }}
                    size="small"
                    sx={{
                      '& .MuiToggleButton-root.Mui-selected': {
                        backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                        color: ConfigurationDataColors.Instance.lightTextColor,
                        '&:hover': {
                          backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                          opacity: 0.9
                        }
                      }
                    }}
                  >
                    <ToggleButton value={'X1'} sx={{ minWidth: '60px', fontWeight: 'bold', fontSize: '0.75rem', padding: '4px 8px' }}>
                      {parseFloat(ConfigurationData.Instance.jogIncrement1x.toFixed(4))}
                    </ToggleButton>
                    <ToggleButton value={'X10'} sx={{ minWidth: '60px', fontWeight: 'bold', fontSize: '0.75rem', padding: '4px 8px' }}>
                      {parseFloat((ConfigurationData.Instance.jogIncrement1x * 10).toFixed(3))}
                    </ToggleButton>
                    <ToggleButton value={'X100'} sx={{ minWidth: '60px', fontWeight: 'bold', fontSize: '0.75rem', padding: '4px 8px' }}>
                      {parseFloat((ConfigurationData.Instance.jogIncrement1x * 100).toFixed(2))}
                    </ToggleButton>
                  </ToggleButtonGroup>

                  {/* Continuous/Incremental Toggle Button */}
                  <Tooltip title={configState.jogContinuousMode ? 'Click to switch to Incremental Mode' : 'Click to switch to Continuous Mode'} arrow>
                    <ToggleButton
                      value="continuous"
                      selected={configState.jogContinuousMode}
                      onChange={async () => {
                        try {
                          const newMode = !configState.jogContinuousMode;
                          configState.jogContinuousMode = newMode;
                          await Machine.getInstance().movement.SetContinuousJog(newMode);
                        } catch (error) {
                          Logger.Instance.logError(LogCategory.UserInterface, 'Failed to set continuous jog mode:', error);
                          UserMessageQueue.Instance.addMessage('❌ Failed to set jog mode');
                        }
                      }}
                      sx={{
                        minWidth: '90px',
                        fontWeight: 'bold',
                        fontSize: '0.75rem',
                        padding: '4px 8px',
                        backgroundColor: configState.jogContinuousMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                        color: ConfigurationDataColors.Instance.lightTextColor,
                        border: 'none',
                        '&:hover': {
                          backgroundColor: configState.jogContinuousMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                          opacity: 0.85
                        },
                        '&.Mui-selected': {
                          backgroundColor: configState.jogContinuousMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                          color: ConfigurationDataColors.Instance.lightTextColor,
                          '&:hover': {
                            backgroundColor: configState.jogContinuousMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                            opacity: 0.85
                          }
                        }
                      }}
                    >
                      {configState.jogContinuousMode ? 'Continuous' : 'Incremental'}
                    </ToggleButton>
                  </Tooltip>

                  {/* Fast/Slow Jog Toggle Button */}
                  <Tooltip title={configState.jogFastMode ? 'Click to switch to Slow Jog' : 'Click to switch to Fast Jog'} arrow>
                    <ToggleButton
                      value="fast"
                      selected={configState.jogFastMode}
                      onChange={async () => {
                        try {
                          const newMode = !configState.jogFastMode;
                          configState.jogFastMode = newMode;
                          await Machine.getInstance().movement.SetFastJog(newMode);
                        } catch (error) {
                          Logger.Instance.logError(LogCategory.UserInterface, 'Failed to set fast jog mode:', error);
                          UserMessageQueue.Instance.addMessage('❌ Failed to set fast jog speed');
                        }
                      }}
                      sx={{
                        minWidth: '60px',
                        fontWeight: 'bold',
                        fontSize: '0.75rem',
                        padding: '4px 8px',
                        backgroundColor: configState.jogFastMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                        color: ConfigurationDataColors.Instance.lightTextColor,
                        border: 'none',
                        '&:hover': {
                          backgroundColor: configState.jogFastMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                          opacity: 0.85
                        },
                        '&.Mui-selected': {
                          backgroundColor: configState.jogFastMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                          color: ConfigurationDataColors.Instance.lightTextColor,
                          '&:hover': {
                            backgroundColor: configState.jogFastMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                            opacity: 0.85
                          }
                        }
                      }}
                    >
                      {configState.jogFastMode ? 'Fast' : 'Slow'}
                    </ToggleButton>
                  </Tooltip>
                </div>
              )}
            />

            {/* Safe Mode section */}
            <div style={{ marginTop: '8px', paddingTop: '8px', borderTop: `1px solid ${ConfigurationDataColors.Instance.borderColor}` }}>
              <SafeModeControl variant="compact" />
            </div>
          </div>
        )}
      />
    </>
  );
}
