import { CNCPoint } from '../data/CNCPoint';
import { CoordinateType } from '../data/Common/CoordinateType';
import { ConfigurationData } from '../data/ConfigurationData';
import { ConfigurationState, JogIncrementSpeed } from '../data/ConfigurationState';
import { AxisType } from '../data/Machine/AxisType';
import { MachineData } from '../data/Machine/MachineData';
import { ICNCMovement, MovementCoordinateType } from '../machine/ICNCMovement';
import { IOEvent } from '../machine/IOEvent';
import { JogDirection } from '../machine/JogDirection';
import { JogSpeed } from '../machine/JogSpeed';
import { MoveDirection } from '../machine/MoveDirection';
import { MoveStrategy } from '../machine/MoveStrategy';
import { MoveType } from '../machine/MoveType';
import { CNCMovementApi } from '../services/src/apis/CNCMovementApi';
import { CNCUIApi } from '../services/src/apis/CNCUIApi';
import { MachinePoint } from '../services/src/models';
import { JogIncrementSpeed as ApiJogIncrementSpeed } from '../services/src/models/JogIncrementSpeed';
import { CoordinateUtil } from '../utils/CoordinateUtil';
import { LogCategory, Logger } from '../utils/Logger';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';
import { CentroidCNCProgram } from './CentroidCNCProgram';
import { CentroidCNCSystem } from './CentroidCNCSystem';

export class CentroidCNCMovement implements ICNCMovement {
  private readonly api: CNCMovementApi;
  private readonly uiApi: CNCUIApi;
  private readonly program: CentroidCNCProgram;
  private readonly system: CentroidCNCSystem;
  private moveType: MoveType = MoveType.Absolute;
  private feedRateFactor: number = 1.0;
  private isJogging: boolean = false;
  private currentJogDirection: JogDirection | null = null;
  private currentJogSpeed: JogSpeed | null = null;
  private isContinuousJog: boolean = false;

  constructor() {
    const config = MachineInterfaceManager.Instance.getServiceConfiguration();
    this.api = new CNCMovementApi(config || undefined);
    this.uiApi = new CNCUIApi(config || undefined);
    this.program = new CentroidCNCProgram();
    this.system = new CentroidCNCSystem();
  }

  async SetMoveType(moveType: MoveType): Promise<void> {
    // Store move type locally - it will be applied in G-code commands (G90/G91)
    this.moveType = moveType;
  }

  async GetMoveType(): Promise<MoveType> {
    try {
      const response = await this.api.apiCNCMovementGetMoveTypeGet();
      const apiMoveType = (response as any).data;
      return apiMoveType === 0 ? MoveType.Absolute : MoveType.Relative;
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to get move type:', error);
      return this.moveType; // Return cached value on error
    }
  }

  async GetCurrentPosition(): Promise<CNCPoint> {
    try {
      const response = await this.api.apiCNCMovementGetCurrentPositionGet();
      const machinePoint = (response as any).data;
      if (machinePoint) {
        return new CNCPoint(
          machinePoint.x || 0,
          machinePoint.y || 0,
          machinePoint.z || 0,
          CoordinateType.MachineHome
        );
      }
      // If machinePoint is null/undefined, log and return current cached position
      Logger.Instance.logError(LogCategory.DataManager, 'GetCurrentPosition returned null/undefined data - using cached position');
      // Return current cached position from ConfigurationState instead of (0,0,0)
      return ConfigurationState.Instance.currentMachinePoint;
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to get current position:', error);
      throw error;
    }
  }

  async MoveTo(point: CNCPoint, coordinateType: MovementCoordinateType, xySpeed?: number, zSpeed?: number, strategy?: MoveStrategy): Promise<void> {
    try {
      const gcode: string[] = [];

      // Convert point to appropriate coordinate system
      if (coordinateType === MovementCoordinateType.WorkZero) {
        point = CoordinateUtil.toWorkZeroWithOffsets(point);
      } else {
        point = CoordinateUtil.toMachineHome(point);
      }

      // Determine speeds from ConfigurationData if not provided
      const config = ConfigurationData.Instance;
      const configState = ConfigurationState.Instance;
      const isFastJog = configState.jogFastMode;

      // Get current position to determine Z direction
      const currentPos = ConfigurationState.Instance.currentMachinePoint;
      const isZMovingUp = currentPos && point.z > currentPos.z;

      // Calculate speeds based on fast/slow mode and axis
      const calculatedXYSpeed = xySpeed ?? (isFastJog ? config.fastJogXY : config.slowJogXY);
      const calculatedZSpeed = zSpeed ?? (() => {
        if (isFastJog) {
          return isZMovingUp ? config.fastJogZPlus : config.fastJogZMinus;
        } else {
          return config.slowJogZ;
        }
      })();

      const isMachineCoordinates = coordinateType === MovementCoordinateType.Machine;

      if (isMachineCoordinates) {
        // G53 - Machine coordinates (one shot, must be on same line as command)
        // G53 is rapid positioning (G0) and requires absolute positioning
        // Movement rate overridden using L word
        if (strategy === MoveStrategy.ZSeparate) {
          // Move Z first, then XY
          gcode.push(`G53 G0 Z${point.z.toFixed(4)} L${calculatedZSpeed.toFixed(1)}`);
          gcode.push(`G53 G0 X${point.x.toFixed(4)} Y${point.y.toFixed(4)} L${calculatedXYSpeed.toFixed(1)}`);
        } else {
          // Direct move (all axes together)
          gcode.push(`G53 G0 X${point.x.toFixed(4)} Y${point.y.toFixed(4)} Z${point.z.toFixed(4)} L${calculatedXYSpeed.toFixed(1)}`);
        }
      } else {
        // Work coordinates (G54) - use G1 with F parameter for controlled feed rate
        gcode.push('G54'); // Work coordinates (relative to work zero/fixture)
        gcode.push(this.moveType === MoveType.Absolute ? 'G90' : 'G91');

        if (strategy === MoveStrategy.ZSeparate) {
          // Move Z first, then XY
          gcode.push(`G1 Z${point.z.toFixed(4)} F${calculatedZSpeed.toFixed(1)}`);
          gcode.push(`G1 X${point.x.toFixed(4)} Y${point.y.toFixed(4)} F${calculatedXYSpeed.toFixed(1)}`);
        } else {
          // Direct move (all axes together)
          gcode.push(`G1 X${point.x.toFixed(4)} Y${point.y.toFixed(4)} Z${point.z.toFixed(4)} F${calculatedXYSpeed.toFixed(1)}`);
        }
      }

      await this.program.RunGCode(gcode, true);

      // Clear proposed spindle position since move is complete
      // Note: currentMachinePoint will be updated via SignalR DRO events
      ConfigurationState.Instance.proposedSpindlePosition = null;
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to move to position:', error);
      throw error;
    }
  }

  async MoveToUntil(point: CNCPoint, coordinateType: MovementCoordinateType, event: IOEvent, xySpeed?: number, zSpeed?: number): Promise<void> {
    try {
      // Note: G-code doesn't directly support "move until IO event" in standard form
      // This would typically require custom M-codes or probe commands (G31)
      // For now, we'll use G31 (probe) which stops on contact
      const gcode: string[] = [];

      // Set coordinate system
      if (coordinateType === MovementCoordinateType.Machine) {
        gcode.push('G53');
      }

      // Set absolute positioning
      gcode.push('G90');

      // Use G31 (probe move) - stops on contact
      const feedRate = zSpeed || xySpeed || 100; // Default probe speed
      gcode.push(`G31 X${point.x.toFixed(4)} Y${point.y.toFixed(4)} Z${point.z.toFixed(4)} F${feedRate.toFixed(1)}`);

      await this.program.RunGCode(gcode, true);
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to move to position until event:', error);
      throw error;
    }
  }

  async MoveDirectionUntil(
    direction: MoveDirection,
    event: IOEvent,
    maxDistance?: number,
    speed?: number
  ): Promise<void> {
    try {
      // Build G-code for directional probing
      const gcode: string[] = [];
      gcode.push('G91'); // Relative positioning for directional move

      const distance = maxDistance || 100; // Default max distance if not specified
      const feedRate = speed || 100; // Default probe speed

      // Determine axis and direction
      let moveCmd = 'G31 ';
      switch (direction) {
        case MoveDirection.XPositive:
          moveCmd += `X${distance.toFixed(4)}`;
          break;
        case MoveDirection.XNegative:
          moveCmd += `X${(-distance).toFixed(4)}`;
          break;
        case MoveDirection.YPositive:
          moveCmd += `Y${distance.toFixed(4)}`;
          break;
        case MoveDirection.YNegative:
          moveCmd += `Y${(-distance).toFixed(4)}`;
          break;
        case MoveDirection.ZPositive:
          moveCmd += `Z${distance.toFixed(4)}`;
          break;
        case MoveDirection.ZNegative:
          moveCmd += `Z${(-distance).toFixed(4)}`;
          break;
      }
      moveCmd += ` F${feedRate.toFixed(1)}`;
      gcode.push(moveCmd);
      gcode.push('G90'); // Return to absolute positioning

      await this.program.RunGCode(gcode, true);
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to move direction until event:', error);
      throw error;
    }
  }

  async SetCurrentFixturePoint(): Promise<void> {
    try {
      // Use CoordinateUtil to calculate API fixture offset from current work zero
      let apiPoint = CoordinateUtil.toAPIFixtureOffset();

      apiPoint = CoordinateUtil.toMachineHome(apiPoint);

      const machinePoint: MachinePoint = {
        x: apiPoint.x,
        y: apiPoint.y,
        z: apiPoint.z
        // CNCPoint doesn't have 'a' property, omitting rotational axis for now
      };

      await this.api.apiCNCMovementSetFixturePointPost({ machinePoint });
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to set fixture point:', error);
      throw error;
    }
  }

  async AdjustFeedRate(factor: number): Promise<void> {
    try {
      this.feedRateFactor = factor;
      await this.api.apiCNCMovementSetFeedRateOverridePost({ body: factor });
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to adjust feed rate:', error);
      throw error;
    }
  }

  async GetCurrentFeedRateFactor(): Promise<number> {
    try {
      const response = await this.api.apiCNCMovementGetFeedRateOverrideGet();
      this.feedRateFactor = response || 1.0;
      return this.feedRateFactor;
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to get feed rate factor:', error);
      return this.feedRateFactor; // Return cached value on error
    }
  }

  async ResetFeedRateFactor(): Promise<void> {
    try {
      await this.api.apiCNCMovementResetFeedRateOverridePost();
      this.feedRateFactor = 1.0;
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to reset feed rate factor:', error);
      throw error;
    }
  }

  /**
   * Maps a logical axis type (X, Y, Z, A) to its physical axis number (1-6)
   * by looking up the axis configuration in MachineData
   * @param logicalAxis The logical axis type to look up
   * @returns The physical axis number (1-6), or null if not configured
   */
  private getPhysicalAxisNumber(logicalAxis: AxisType): number | null {
    const machineData = MachineData.Instance;
    const axisConfig = machineData.axisConfigurations.find(
      config => config.axisType === logicalAxis
    );

    if (!axisConfig) {
      Logger.Instance.logError(
        LogCategory.DataManager,
        `No axis configuration found for logical axis: ${logicalAxis}`
      );
      return null;
    }

    return axisConfig.axisNumber;
  }

  async StartJog(direction: JogDirection): Promise<void> {
    try {
      // Get current jog settings from ConfigurationState
      const config = ConfigurationState.Instance;
      const continuous = config.jogContinuousMode;
      const willRenew = continuous; // Renewal pattern for continuous jog

      this.isJogging = true;
      this.currentJogDirection = direction;
      this.isContinuousJog = continuous;

      // Handle diagonal jog directions by calling two axis jogs
      if (direction === JogDirection.XPlusYPlus ||
        direction === JogDirection.XPlusYMinus ||
        direction === JogDirection.XMinusYPlus ||
        direction === JogDirection.XMinusYMinus) {

        // Determine X and Y directions
        const xPlus = direction === JogDirection.XPlusYPlus || direction === JogDirection.XPlusYMinus;
        const yPlus = direction === JogDirection.XPlusYPlus || direction === JogDirection.XMinusYPlus;

        // Get physical axis numbers for X and Y
        const xAxisNumber = this.getPhysicalAxisNumber(AxisType.X);
        const yAxisNumber = this.getPhysicalAxisNumber(AxisType.Y);

        if (xAxisNumber === null || yAxisNumber === null) {
          throw new Error('Cannot jog diagonal - X or Y axis not configured');
        }

        // Start both axes simultaneously
        await Promise.all([
          this.startSingleAxisJog(xAxisNumber, xPlus, willRenew),
          this.startSingleAxisJog(yAxisNumber, yPlus, willRenew)
        ]);

        return;
      }

      // Single-axis jog - determine logical axis type and direction
      let logicalAxis: AxisType;
      let isPlus: boolean;

      switch (direction) {
        case JogDirection.XPlus:
          logicalAxis = AxisType.X;
          isPlus = true;
          break;
        case JogDirection.XMinus:
          logicalAxis = AxisType.X;
          isPlus = false;
          break;
        case JogDirection.YPlus:
          logicalAxis = AxisType.Y;
          isPlus = true;
          break;
        case JogDirection.YMinus:
          logicalAxis = AxisType.Y;
          isPlus = false;
          break;
        case JogDirection.ZPlus:
          logicalAxis = AxisType.Z;
          isPlus = true;
          break;
        case JogDirection.ZMinus:
          logicalAxis = AxisType.Z;
          isPlus = false;
          break;
        case JogDirection.APlus:
          logicalAxis = AxisType.A;
          isPlus = true;
          break;
        case JogDirection.AMinus:
          logicalAxis = AxisType.A;
          isPlus = false;
          break;
        default:
          throw new Error(`Unknown jog direction: ${direction}`);
      }

      // Get physical axis number from configuration
      const physicalAxisNumber = this.getPhysicalAxisNumber(logicalAxis);

      if (physicalAxisNumber === null) {
        throw new Error(`Cannot jog - ${logicalAxis} axis not configured`);
      }

      // Start the jog on the physical axis
      await this.startSingleAxisJog(physicalAxisNumber, isPlus, willRenew);

    } catch (error) {
      this.isJogging = false;
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to start jog:', error);
      throw error;
    }
  }

  /**
   * Helper method to start jog on a single physical axis
   * @param axisNumber Physical axis number (1-4)
   * @param isPlus True for plus direction, false for minus
   * @param willRenew True if using renewal pattern (continuous jog)
   */
  private async startSingleAxisJog(axisNumber: number, isPlus: boolean, willRenew: boolean): Promise<void> {
    // Call appropriate API method based on axis number and direction
    switch (axisNumber) {
      case 1:
        if (isPlus) {
          await this.uiApi.apiCNCUIStartJogAxis1PlusPost({ willRenew });
        } else {
          await this.uiApi.apiCNCUIStartJogAxis1MinusPost({ willRenew });
        }
        break;
      case 2:
        if (isPlus) {
          await this.uiApi.apiCNCUIStartJogAxis2PlusPost({ willRenew });
        } else {
          await this.uiApi.apiCNCUIStartJogAxis2MinusPost({ willRenew });
        }
        break;
      case 3:
        if (isPlus) {
          await this.uiApi.apiCNCUIStartJogAxis3PlusPost({ willRenew });
        } else {
          await this.uiApi.apiCNCUIStartJogAxis3MinusPost({ willRenew });
        }
        break;
      case 4:
        if (isPlus) {
          await this.uiApi.apiCNCUIStartJogAxis4PlusPost({ willRenew });
        } else {
          await this.uiApi.apiCNCUIStartJogAxis4MinusPost({ willRenew });
        }
        break;
      default:
        throw new Error(`Unsupported physical axis number: ${axisNumber}`);
    }
  }

  async StopJog(): Promise<void> {
    try {
      if (!this.isJogging || !this.currentJogDirection) {
        // No jog in progress
        return;
      }

      // Handle diagonal jog directions
      if (this.currentJogDirection === JogDirection.XPlusYPlus ||
        this.currentJogDirection === JogDirection.XPlusYMinus ||
        this.currentJogDirection === JogDirection.XMinusYPlus ||
        this.currentJogDirection === JogDirection.XMinusYMinus) {

        // Determine X and Y directions
        const xPlus = this.currentJogDirection === JogDirection.XPlusYPlus ||
          this.currentJogDirection === JogDirection.XPlusYMinus;
        const yPlus = this.currentJogDirection === JogDirection.XPlusYPlus ||
          this.currentJogDirection === JogDirection.XMinusYPlus;

        // Get physical axis numbers for X and Y
        const xAxisNumber = this.getPhysicalAxisNumber(AxisType.X);
        const yAxisNumber = this.getPhysicalAxisNumber(AxisType.Y);

        if (xAxisNumber !== null && yAxisNumber !== null) {
          // Stop both axes simultaneously
          await Promise.all([
            this.stopSingleAxisJog(xAxisNumber, xPlus),
            this.stopSingleAxisJog(yAxisNumber, yPlus)
          ]);
        }

        this.isJogging = false;
        this.currentJogDirection = null;
        this.isContinuousJog = false;
        return;
      }

      // Single-axis jog - determine logical axis type and direction
      let logicalAxis: AxisType;
      let isPlus: boolean;

      switch (this.currentJogDirection) {
        case JogDirection.XPlus:
          logicalAxis = AxisType.X;
          isPlus = true;
          break;
        case JogDirection.XMinus:
          logicalAxis = AxisType.X;
          isPlus = false;
          break;
        case JogDirection.YPlus:
          logicalAxis = AxisType.Y;
          isPlus = true;
          break;
        case JogDirection.YMinus:
          logicalAxis = AxisType.Y;
          isPlus = false;
          break;
        case JogDirection.ZPlus:
          logicalAxis = AxisType.Z;
          isPlus = true;
          break;
        case JogDirection.ZMinus:
          logicalAxis = AxisType.Z;
          isPlus = false;
          break;
        case JogDirection.APlus:
          logicalAxis = AxisType.A;
          isPlus = true;
          break;
        case JogDirection.AMinus:
          logicalAxis = AxisType.A;
          isPlus = false;
          break;
        default:
          Logger.Instance.logError(
            LogCategory.DataManager,
            `Unknown jog direction in StopJog: ${this.currentJogDirection}`
          );
          return;
      }

      // Get physical axis number from configuration
      const physicalAxisNumber = this.getPhysicalAxisNumber(logicalAxis);

      if (physicalAxisNumber !== null) {
        // Stop the jog on the physical axis
        await this.stopSingleAxisJog(physicalAxisNumber, isPlus);
      }

      this.isJogging = false;
      this.currentJogDirection = null;
      this.isContinuousJog = false;
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to stop jog:', error);
      throw error;
    }
  }

  /**
   * Helper method to stop jog on a single physical axis
   * @param axisNumber Physical axis number (1-4)
   * @param isPlus True for plus direction, false for minus
   */
  private async stopSingleAxisJog(axisNumber: number, isPlus: boolean): Promise<void> {
    // Call appropriate API method based on axis number and direction
    switch (axisNumber) {
      case 1:
        if (isPlus) {
          await this.uiApi.apiCNCUIStopJogAxis1PlusPost();
        } else {
          await this.uiApi.apiCNCUIStopJogAxis1MinusPost();
        }
        break;
      case 2:
        if (isPlus) {
          await this.uiApi.apiCNCUIStopJogAxis2PlusPost();
        } else {
          await this.uiApi.apiCNCUIStopJogAxis2MinusPost();
        }
        break;
      case 3:
        if (isPlus) {
          await this.uiApi.apiCNCUIStopJogAxis3PlusPost();
        } else {
          await this.uiApi.apiCNCUIStopJogAxis3MinusPost();
        }
        break;
      case 4:
        if (isPlus) {
          await this.uiApi.apiCNCUIStopJogAxis4PlusPost();
        } else {
          await this.uiApi.apiCNCUIStopJogAxis4MinusPost();
        }
        break;
      default:
        Logger.Instance.logError(
          LogCategory.DataManager,
          `Unsupported physical axis number in stopSingleAxisJog: ${axisNumber}`
        );
    }
  }

  async KeepJogging(direction: JogDirection): Promise<void> {
    // For the renewal pattern, call StartJog again with willRenew=true
    // This resets the backend's 250ms timeout
    if (this.isJogging && this.isContinuousJog && this.currentJogDirection === direction) {
      await this.StartJog(direction);
    }
  }

  async SetContinuousJog(isContinuous: boolean): Promise<void> {
    try {
      // Get current state from ConfigurationState
      const currentState = ConfigurationState.Instance.jogContinuousMode;
      await this.uiApi.apiCNCUISetJogModePost({ isContinuous: !currentState });
      // ConfigurationState will be updated via SignalR ServerStatus
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to toggle continuous jog mode:', error);
      throw error;
    }
  }

  async SetFastJog(isFast: boolean): Promise<void> {
    try {
      // Get current state from ConfigurationState
      const currentState = ConfigurationState.Instance.jogFastMode;
      await this.uiApi.apiCNCUISetFastJogPost({ isFast: !currentState });
      // ConfigurationState will be updated via SignalR ServerStatus
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to toggle fast jog mode:', error);
      throw error;
    }
  }

  async SetJogIncrementSpeed(speed: JogIncrementSpeed): Promise<void> {
    try {
      // Convert ConfigurationState enum ('X1'/'X10'/'X100') to API enum (1/10/100)
      const apiSpeed = speed === JogIncrementSpeed.X1 ? ApiJogIncrementSpeed.NUMBER_1 :
        speed === JogIncrementSpeed.X10 ? ApiJogIncrementSpeed.NUMBER_10 :
          ApiJogIncrementSpeed.NUMBER_100;
      await this.uiApi.apiCNCUITriggerJogIncrementSpeedPost({ speed: apiSpeed });
      // ConfigurationState will be updated via SignalR ServerStatus
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to set jog increment speed:', error);
      throw error;
    }
  }



}