import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item for verifying machine features configuration.
 * This requires manual confirmation as we cannot programmatically verify
 * if the physical machine features match the configuration.
 */
export class MachineFeatureChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Machine Features',
            'Configure optional machine features and attachments (Vertical Table, ATC, Laser, Drill Head, etc.)'
        );
    }

    public needsManualConfirmation(): boolean {
        // User must manually confirm they've configured the correct features
        return true;
    }

    public completionCheck(): boolean {
        // We cannot automatically determine if features are configured correctly
        // The user must manually verify and confirm
        return true;
    }

    public clone(): SetupChecklistItem {
        const cloned = new MachineFeatureChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
